function ensureDemandRouteState() {
  if (!state) return structuredClone(DEMAND_ROUTE_DEFAULT);
  state.demandRoute =
    state.demandRoute || structuredClone(DEMAND_ROUTE_DEFAULT);
  state.demandRoute.steps = state.demandRoute.steps || {};
  state.demandRoute.groups = Array.isArray(state.demandRoute.groups)
    ? state.demandRoute.groups
    : [];
  DEMAND_ROUTE_STEPS.forEach((step) => {
    state.demandRoute.steps[step.key] = state.demandRoute.steps[step.key] || {};
    step.fields.forEach(([key]) => {
      state.demandRoute.steps[step.key][key] =
        state.demandRoute.steps[step.key][key] || "";
    });
  });
  return state.demandRoute;
}

function demandSearchEnabled(route) {
  return route.adSystem === "yandex" ||
    route.adSystem === "both" ||
    route.adSystem === "google" ||
    route.adSystem === "yandex_google"
    ? ((route.adSystem === "yandex" || route.adSystem === "both") &&
        /search|поиск/.test(route.yandexCampaignType || "")) ||
        ((route.adSystem === "google" || route.adSystem === "both") &&
          /search/.test(route.googleCampaignType || ""))
    : false;
}

function demandDisplayEnabled(route) {
  return (
    ((route.adSystem === "yandex" || route.adSystem === "both") &&
      /rsya|рся/.test(route.yandexCampaignType || "")) ||
    ((route.adSystem === "google" || route.adSystem === "both") &&
      /display/.test(route.googleCampaignType || ""))
  );
}

function demandSystemLabel(value) {
  return (
    { yandex: "Яндекс", google: "Google", both: "Яндекс + Google" }[value] ||
    "Яндекс"
  );
}

function demandCampaignTypeLabel(route) {
  const parts = [];
  if (route.adSystem === "yandex" || route.adSystem === "both")
    parts.push(
      "Яндекс: " +
        ({ search: "Поиск", rsya: "РСЯ", search_rsya: "Поиск + РСЯ" }[
          route.yandexCampaignType
        ] || "Поиск + РСЯ"),
    );
  if (route.adSystem === "google" || route.adSystem === "both")
    parts.push(
      "Google: " +
        ({
          search: "Search",
          display: "Display",
          search_display: "Search + Display",
        }[route.googleCampaignType] || "Search + Display"),
    );
  return parts.join(" · ");
}

function demandGroupHasSearchNeed(route, group) {
  return (
    demandSearchEnabled(route) &&
    /поиск|search|оба|поиск \+ рся|search \+ display|универс/.test(
      normalizeGateTitle(group.type || ""),
    )
  );
}

function demandGroupHasDisplayNeed(route, group) {
  return (
    demandDisplayEnabled(route) &&
    /рся|display|оба|поиск \+ рся|search \+ display|универс/.test(
      normalizeGateTitle(group.type || ""),
    )
  );
}

function demandChecks() {
  const route = ensureDemandRouteState();
  const issues = [];
  if (!String(route.promoted || "").trim())
    issues.push({
      level: "problem",
      text: "Нет «что продвигаем» — нельзя собирать семантику.",
    });
  if (!String(route.excluded || "").trim())
    issues.push({
      level: "needs_review",
      text: "Нет «что не продвигаем» — высокий риск мусорного спроса.",
    });
  if (!megaPlatformPageRefUrl(route.landingPageRefV1))
    issues.push({
      level: "problem",
      text: "Нет посадочной страницы для запуска.",
    });
  (route.groups || []).forEach((group, index) => {
    const name = group.name || `Группа ${index + 1}`;
    if (!String(group.intent || "").trim())
      issues.push({ level: "problem", text: `${name}: нет интента.` });
    if (!megaPlatformPageRefUrl(group.pageRefV1 || route.landingPageRefV1))
      issues.push({ level: "problem", text: `${name}: нет посадочной.` });
    if (
      demandGroupHasSearchNeed(route, group) &&
      !String(group.keywords || "").trim()
    )
      issues.push({
        level: "problem",
        text: `${name}: включён Поиск / Search, но нет ключевых фраз.`,
      });
    if (
      demandGroupHasDisplayNeed(route, group) &&
      !String(group.audience || "").trim()
    )
      issues.push({
        level: "problem",
        text: `${name}: включена РСЯ / Display, но нет аудитории.`,
      });
    if (!String(group.negatives || "").trim())
      issues.push({
        level: "needs_review",
        text: `${name}: нет минус-фраз / negatives.`,
      });
    if (!String(group.ad || "").trim())
      issues.push({ level: "in_progress", text: `${name}: нет объявления.` });
    const target = Number(
      String(route.targetCpa || "")
        .replace(/[^0-9.,]/g, "")
        .replace(",", "."),
    );
    const forecast = Number(
      String(group.forecastCpa || "")
        .replace(/[^0-9.,]/g, "")
        .replace(",", "."),
    );
    if (target && forecast && forecast > target)
      issues.push({
        level: "needs_review",
        text: `${name}: прогноз CPA выше нормы.`,
      });
  });
  return issues;
}

function getDemandRouteStatus() {
  const route = ensureDemandRouteState();
  if (
    !String(route.promoted || "").trim() &&
    !String(route.excluded || "").trim() &&
    !megaPlatformPageRefUrl(route.landingPageRefV1)
  )
    return "not_started";
  const issues = demandChecks();
  if (issues.some((i) => i.level === "problem")) return "problem";
  if (!(route.groups || []).length) return "in_progress";
  if (issues.some((i) => i.level === "needs_review")) return "needs_review";
  if (issues.some((i) => i.level === "in_progress")) return "in_progress";
  return "ready";
}

function getDemandProgressText() {
  const route = ensureDemandRouteState();
  const completed = DEMAND_ROUTE_STEPS.filter((step) =>
    step.fields.some(([key]) =>
      String(route.steps?.[step.key]?.[key] || "").trim(),
    ),
  ).length;
  const groups = (route.groups || []).length;
  return `${completed} из ${DEMAND_ROUTE_STEPS.length} шагов заполнено · ${groups} групп`;
}

function firstIncompleteDemandStepKey(route) {
  const found = DEMAND_ROUTE_STEPS.find(
    (step) =>
      !step.fields.some(([key]) =>
        String(route.steps?.[step.key]?.[key] || "").trim(),
      ),
  );
  return found?.key || "launch_package";
}

function demandInput(name, label, type = "text", placeholder = "") {
  const route = ensureDemandRouteState();
  const value = route[name] || "";
  const tag =
    type === "textarea"
      ? `<textarea data-demand-field="${escapeAttr(name)}" placeholder="${escapeAttr(placeholder)}">${escapeHtml(value)}</textarea>`
      : `<input data-demand-field="${escapeAttr(name)}" value="${escapeAttr(value)}" placeholder="${escapeAttr(placeholder)}" />`;
  return `<label class="demand-field"><span>${escapeHtml(label)}</span>${tag}</label>`;
}

