function exportCsv() {
  syncEvidenceTexts();
  const rows = [];
  rows.push([
    "gate",
    "block",
    "instruction",
    "status",
    "evidence",
    "pages",
    "notes",
    "source_row",
  ]);
  state.gates.forEach((g) => {
    g.cards.forEach((c) =>
      rows.push([
        g.title,
        c.title,
        c.instruction || "",
        STATUS_LABELS[c.status] || c.status,
        formatStructuredEvidencePlain(c, state),
        c.pages || "",
        c.notes || "",
        c.sourceRow || "",
      ]),
    );
  });
  appendGate5ExportRows(rows);
  const catalog = getEvidenceCatalog();
  if (catalog.length) {
    rows.push([]);
    rows.push(["SHARED_EVIDENCE"]);
    rows.push(["key", "title", "value", "used_in_blocks"]);
    catalog.forEach((item) =>
      rows.push([
        item.key,
        item.label,
        getEvidenceValue(item.key),
        item.cards.map((c) => c.title).join(" | "),
      ]),
    );
  }
  if (state.linkBank?.length) {
    rows.push([]);
    rows.push(["PROJECT_LINK_BANK"]);
    rows.push([
      "url",
      "availability",
      "indexation",
      "visibility",
      "errors",
      "comment",
      "source",
    ]);
    state.linkBank.forEach((link) => {
      const seo = link.seo || {};
      rows.push([
        megaPlatformLinkBankUrl(link, state),
        seoLabel("availability", seo.availability),
        seoLabel("indexation", seo.indexation),
        seoLabel("visibility", seo.visibility),
        seoLabel("errors", seo.errors),
        link.comment || "",
        toolNameByKey(link.source || ""),
      ]);
    });
  }
  if (state.tools?.length) {
    rows.push([]);
    rows.push(["PROJECT_TOOLS"]);
    rows.push(["group", "tool", "enabled"]);
    state.tools.forEach((tool) =>
      rows.push([tool.group, tool.name, tool.enabled ? "Включён" : "Отключён"]),
    );
  }
  if (state.metrics?.length) {
    rows.push([]);
    rows.push(["METRICS"]);
    rows.push([
      "date",
      "channel",
      "impressions",
      "clicks",
      "cost",
      "leads",
      "ctr",
      "cpa",
    ]);
    state.metrics.forEach((m) => {
      const ctr = m.impressions
        ? ((m.clicks / m.impressions) * 100).toFixed(2)
        : 0;
      const cpa = m.leads ? (m.cost / m.leads).toFixed(2) : 0;
      rows.push([
        m.date || "",
        m.channel || "",
        m.impressions || 0,
        m.clicks || 0,
        m.cost || 0,
        m.leads || 0,
        ctr,
        cpa,
      ]);
    });
  }
  downloadText("guru-export.csv", toCsv(rows));
}

