function toCsv(rows) {
  return rows
    .map((row) =>
      row
        .map((v) => {
          const s = String(v ?? "");
          return /[",\n;]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
        })
        .join(","),
    )
    .join("\n");
}

function downloadText(filename, text) {
  const blob = new Blob(["\ufeff" + text], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

function parseCsv(text) {
  const rows = [];
  let row = [];
  let cell = "";
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const next = text[i + 1];
    if (ch === '"' && inQuotes && next === '"') {
      cell += '"';
      i++;
      continue;
    }
    if (ch === '"') {
      inQuotes = !inQuotes;
      continue;
    }
    if (ch === "," && !inQuotes) {
      row.push(cell);
      cell = "";
      continue;
    }
    if ((ch === "\n" || ch === "\r") && !inQuotes) {
      if (ch === "\r" && next === "\n") i++;
      row.push(cell);
      rows.push(row);
      row = [];
      cell = "";
      continue;
    }
    cell += ch;
  }
  row.push(cell);
  rows.push(row);
  return rows.filter((r) => r.some((v) => String(v).trim() !== ""));
}

function importCsvFile(file) {
  const reader = new FileReader();
  reader.onload = () => {
    const rows = parseCsv(reader.result);
    if (!rows.length) return alert("CSV пустой.");
    const replace = confirm(
      "Заменить текущие карточки импортированным CSV? Нажмите “Отмена”, чтобы добавить отдельный импортированный Gate.",
    );
    const importedGate = {
      id: "gate-import-" + Date.now(),
      title: "Импорт CSV " + new Date().toLocaleDateString("ru-RU"),
      cards: rows.slice(1).map((r, idx) => ({
        id: "import-card-" + Date.now() + "-" + idx,
        title: r[0] || r[1] || "Без названия",
        instruction: r[1] || "",
        status: "not_started",
        evidence: r[3] || "",
        evidenceFields: extractEvidenceFields(r[3] || "").map((item) => ({
          key: item.key,
          label: item.label,
        })),
        pages: r[5] || "",
        notes: "",
        fields: {},
        sourceRow: idx + 2,
      })),
    };
    if (replace) state.gates = [importedGate];
    else state.gates.push(importedGate);
    initializeEvidenceStructure(state);
    activeView = "gate";
    activeGateId = importedGate.id;
    flashSaving();
    render();
  };
  reader.readAsText(file, "utf-8");
}

function importProjectCsvFile(file) {
  const reader = new FileReader();
  reader.onload = () => {
    const rows = parseCsv(reader.result);
    if (!rows.length) return alert("CSV пустой.");
    if (
      !confirm(
        "Импортировать весь проект из CSV? Это заменит все текущие данные (Gates, ссылки, инструменты, метрики).",
      )
    )
      return;
    const STATUS_REVERSE = {};
    Object.entries(STATUS_LABELS).forEach(([k, v]) => (STATUS_REVERSE[v] = k));
    const gates = {};
    let section = "gates";
    let i = 0;
    if (rows[0] && rows[0][0] === "gate") i = 1;
    for (; i < rows.length; i++) {
      const r = rows[i];
      const first = (r[0] || "").trim();
      if (first === "SHARED_EVIDENCE") {
        section = "shared_evidence";
        i++;
        continue;
      }
      if (first === "PROJECT_LINK_BANK") {
        section = "link_bank";
        i++;
        continue;
      }
      if (first === "PROJECT_TOOLS") {
        section = "tools";
        i++;
        continue;
      }
      if (first === "METRICS") {
        section = "metrics";
        i++;
        continue;
      }
      if (!r.some((v) => String(v).trim())) continue;
      if (section === "gates") {
        const gateTitle = r[0] || "Импорт";
        if (!gates[gateTitle])
          gates[gateTitle] = {
            id: "gate-import-" + Date.now() + "-" + Object.keys(gates).length,
            title: gateTitle,
            cards: [],
          };
        gates[gateTitle].cards.push({
          id: "import-card-" + Date.now() + "-" + i,
          title: r[1] || "Без названия",
          instruction: r[2] || "",
          status: STATUS_REVERSE[r[3]] || "not_started",
          evidence: r[4] || "",
          evidenceFields: extractEvidenceFields(r[4] || "").map((item) => ({
            key: item.key,
            label: item.label,
          })),
          pages: r[5] || "",
          notes: r[6] || "",
          fields: {},
          sourceRow: r[7] || "",
        });
      } else if (section === "link_bank") {
        if (!state.linkBank) state.linkBank = [];
        state.linkBank.push({
          url: r[0] || "",
          seo: {
            availability: r[1] || "",
            indexation: r[2] || "",
            visibility: r[3] || "",
            errors: r[4] || "",
          },
          comment: r[5] || "",
          source: r[6] || "",
        });
      } else if (section === "tools") {
        if (!state.tools) state.tools = [];
        state.tools.push({
          group: r[0] || "",
          name: r[1] || "",
          enabled: r[2] === "Включён",
        });
      } else if (section === "metrics") {
        if (!state.metrics) state.metrics = [];
        state.metrics.push({
          date: r[0] || "",
          channel: r[1] || "",
          impressions: Number(r[2]) || 0,
          clicks: Number(r[3]) || 0,
          cost: Number(r[4]) || 0,
          leads: Number(r[5]) || 0,
        });
      }
    }
    const gateList = Object.values(gates);
    if (gateList.length) state.gates = gateList;
    initializeEvidenceStructure(state);
    activeView = "project";
    activeGateId = state.gates[0]?.id || null;
    flashSaving();
    render();
    alert("Проект успешно импортирован: " + state.gates.length + " Gates.");
  };
  reader.readAsText(file, "utf-8");
}

