function auditStatusOptions(value, type) {
  let options = [["", "Не проверено"]];
  if (type === "meta") {
    options = options.concat([
      ["ok", "Индексация разрешена"],
      ["closed", "Закрыта от индексации"],
      ["error", "Ошибка"],
    ]);
  } else if (type === "cwv") {
    options = options.concat([
      ["ok", "ОК"],
      ["improve", "Требует улучшения"],
      ["error", "Проблема"],
    ]);
  } else {
    options = options.concat([
      ["ok", "ОК"],
      ["improve", "Требует улучшения"],
      ["error", "Критичные ошибки"],
    ]);
  }
  return `<option value="" ${!value ? "selected" : ""}>${options[0][1]}</option>${options
    .slice(1)
    .map(
      ([key, label]) =>
        `<option value="${escapeAttr(key)}" ${value === key ? "selected" : ""}>${escapeHtml(label)}</option>`,
    )
    .join("")}`;
}

function auditStatusChip(value) {
  const label =
    value === "ok"
      ? "ОК"
      : value === "improve"
        ? "Требует улучшения"
        : value === "closed"
          ? "Закрыта"
          : value === "error"
            ? "Проблема"
            : "Не проверено";
  const cls =
    value === "ok"
      ? "ready"
      : value === "improve" || value === "closed"
        ? "needs_attention"
        : value === "error"
          ? "problem"
          : "not_started";
  return `<span class="status-pill status-${cls}">${escapeHtml(label)}</span>`;
}

const __guruPrevPageStructureStatusV20 = pageStructureStatus;
pageStructureStatus = function (row) {
  v20EnsurePageAuditFields(row);
  const url = megaPlatformAuditRowUrl(row);
  if (!url) return "not_started";
  if ([row.metaRobotsStatus, row.cwvStatus, row.imagesStatus].includes("error"))
    return "problem";
  if (
    [row.cwvStatus, row.imagesStatus, row.metaRobotsStatus].includes(
      "improve",
    ) ||
    row.metaRobotsStatus === "closed"
  )
    return "needs_attention";
  const checks = [
    Boolean(url),
    evaluateLength(row.h1, 10, 90).ok,
    evaluateLength(row.title, 20, 90).ok,
    evaluateLength(row.description, 50, 200).ok,
    row.metaRobotsStatus === "ok",
    row.cwvStatus === "ok",
    row.imagesStatus === "ok",
    Boolean(String(row.auditEvidence || "").trim()),
    row.ctaMode === "not_needed"
      ? true
      : Boolean(String(row.finalCta || "").trim()),
  ];
  const filled = checks.filter(Boolean).length;
  if (filled === checks.length) return "ready";
  return "in_progress";
};

