function genericRouteSectionsHtml(card, row, pageIndex) {
  const context = pageTemplateContext(card);
  const defs = ensurePageContextFields(row, context);
  const grouped = defs.reduce((acc, def) => {
    (acc[def.group] = acc[def.group] || []).push(def);
    return acc;
  }, {});
  const sections = Object.entries(grouped).map(([group, items], idx) =>
    routeSection(
      group,
      `<div class="route-section-grid">${items.map((def) => contextInputField(card, pageIndex, row, def.key, def.label, routeStandardForDef(def), def.type, def.type === "textarea" ? "full" : "")).join("")}</div>`,
      idx === 0,
    ),
  );
  sections.push(
    routeSection("SEO-сниппет", snippetRouteHtml(card, row, pageIndex)),
  );
  sections.push(
    routeSection("Финальный CTA", finalCtaRouteHtml(card, row, pageIndex)),
  );
  sections.push(
    routeSection(
      "Технический контроль",
      pageAuditControlsCompactHtml(card, row, pageIndex),
    ),
  );
  return sections.join("");
}

function routeStandardForDef(def) {
  if (/смысл|текст|проблем|оффер|доказ|кейс|шаг|карточ/i.test(def.label))
    return "Коротко, проверяемо, без общего текста.";
  if (/cta|кноп/i.test(def.label)) return "Конкретное действие пользователя.";
  if (/ссылка|адрес|карта/i.test(def.label)) return "URL или точное значение.";
  return "Заполнить только то, что нужно для этой страницы.";
}

