/* v0.23 — Юридико-доверительный контроль: cookie/footer компактно, согласия внутри страниц + сводка */
const V23_LEGAL_COOKIE_TITLE = "Cookie-баннер";
const V23_LEGAL_FOOTER_TITLE = "Футер: Политика + Реквизиты";
const V23_FORM_CONSENT_TITLE = "Согласие в формах";

function isV23CookieCard(card) {
  return (
    normalizeGateTitle(card?.title || "") ===
    normalizeGateTitle(V23_LEGAL_COOKIE_TITLE)
  );
}
function isV23FooterCard(card) {
  return (
    normalizeGateTitle(card?.title || "") ===
    normalizeGateTitle(V23_LEGAL_FOOTER_TITLE)
  );
}
function isV23FormConsentSummaryCard(card) {
  return (
    normalizeGateTitle(card?.title || "") ===
    normalizeGateTitle(V23_FORM_CONSENT_TITLE)
  );
}
function isV23LegalTrustCard(card) {
  return isV23CookieCard(card) || isV23FooterCard(card);
}

const __guruPrevGetGate1CardModeV23 = getGate1CardMode;
