function v23FormConsentSummaryStatus(card) {
  const rows = v23AllPageRowsForConsent().filter(
    (item) => megaPlatformAuditRowUrl(item.row) || item.row.hasForm,
  );
  if (!rows.length) return "not_started";
  if (
    rows.some(
      (item) =>
        item.row.hasForm === "yes" && item.row.formConsentStatus === "error",
    )
  )
    return "problem";
  const relevant = rows.filter((item) => item.row.hasForm === "yes");
  if (!relevant.length && rows.some((item) => item.row.hasForm === "no"))
    return "ready";
  if (
    relevant.length &&
    relevant.every(
      (item) =>
        item.row.formConsentStatus === "ok" &&
        String(item.row.formConsentEvidence || "").trim(),
    )
  )
    return "ready";
  return "in_progress";
}

