function g5SyncStructure(records) {
  const g5 = ensureGate5State();
  (records || []).forEach((r) => {
    const campaignId = g5RecordId(r.campaignId, r.campaignName, "camp");
    if (campaignId || r.campaignName)
      g5.setup.campaigns[campaignId] = {
        id: campaignId,
        name: r.campaignName || campaignId,
      };
    const groupId = r.groupId ? g5RecordId(r.groupId, r.groupName, "grp") : "";
    if (groupId)
      g5.setup.groups[groupId] = {
        id: groupId,
        campaignId,
        name: r.groupName || groupId,
        landing: r.landing || "",
      };
    const adId = r.adId ? g5RecordId(r.adId, r.adTitle, "ad") : "";
    if (adId)
      g5.setup.ads[adId] = {
        id: adId,
        campaignId,
        groupId,
        title: r.adTitle || adId,
        landing: r.landing || "",
      };
  });
}
function g5YandexRegisterChange(g5, campaign, change) {
  g5.iterationCounter = (g5.iterationCounter || 0) + 1;
  g5.iterations.push({
    id: makeId("g5-import-change"), number: g5.iterationCounter, createdAt: new Date().toISOString(),
    changeDate: new Date().toISOString().slice(0, 10), campaignId: campaign.id, campaignName: campaign.name,
    campaignType: campaign.type, level: change.level, before: change.before || "—", after: change.after || "—",
    reason: change.type, hypothesis: "", targetMetric: "", checkDate: "", changeStatus: "Зафиксировано",
    outcome: "Источник: импорт файла", source: "Импорт файла", groupId: change.groupId || "", element: change.element || "",
  });
}
function g5YandexDiff(previous, current) {
  if (!previous) return [{ level: "Кампания", type: "Добавлена кампания", after: `Импортирована структура: ${current.counts.groups} групп, ${current.counts.ads} объявлений, ${current.counts.phrases} фраз` }];
  const oldRows = previous.records || [];
  const byId = (rows, key) => new Map(rows.filter((row) => row[key]).map((row) => [row[key], row]));
  const diffs = [];
  [["groupId", "Группа", "Добавлена группа", "Удалена / отсутствует группа"], ["adId", "Объявление", "Добавлено объявление", "Удалено / отсутствует объявление"], ["phraseId", "Ключ", "Добавлена фраза", "Удалена / отсутствует фраза"]].forEach(([key, level, added, removed]) => {
    const oldMap = byId(oldRows, key), newMap = byId(current.records, key);
    newMap.forEach((row, id) => { if (!oldMap.has(id)) diffs.push({ level, type: added, after: id, groupId: row.groupId, element: id }); });
    oldMap.forEach((row, id) => { if (!newMap.has(id)) diffs.push({ level, type: removed, before: id, groupId: row.groupId, element: id }); });
  });
  const oldAds = byId(oldRows, "adId"), newAds = byId(current.records, "adId");
  newAds.forEach((row, id) => {
    const old = oldAds.get(id); if (!old) return;
    [["title1", "Изменён заголовок"], ["adText", "Изменён текст объявления"], ["landing", "Изменена посадочная"], ["region", "Изменён регион"]].forEach(([key, type]) => {
      if ((old[key] || "") !== (row[key] || "")) diffs.push({ level: "Объявление", type, before: old[key], after: row[key], groupId: row.groupId, element: id });
    });
  });
  const oldPhrases = byId(oldRows, "phraseId"), newPhrases = byId(current.records, "phraseId");
  newPhrases.forEach((row, id) => {
    const old = oldPhrases.get(id); if (!old) return;
    [["phraseStatus", "Изменён статус фразы"], ["groupNegatives", "Изменены минус-фразы"], ["region", "Изменён регион"]].forEach(([key, type]) => {
      if ((old[key] || "") !== (row[key] || "")) diffs.push({ level: "Ключ", type, before: old[key], after: row[key], groupId: row.groupId, element: id });
    });
  });
  return diffs;
}
function g5RepairYandexCampaignIdentity(g5, actualCabinetId) {
  const incorrect = g5.campaignRegistry.find((campaign) => String(campaign.cabinetId) === "1" && /яндекс/i.test(campaign.platform || ""));
  if (!incorrect) return false;
  const target = g5.campaignRegistry.find((campaign) => String(campaign.cabinetId) === String(actualCabinetId));
  const replaceInternalId = (collection) => (collection || []).forEach((item) => {
    if (item.campaignId === incorrect.id && target) item.campaignId = target.id;
  });
  if (target) {
    replaceInternalId(g5.periodSnapshots);
    replaceInternalId(g5.links);
    replaceInternalId(g5.iterations);
    replaceInternalId(g5.comparisons);
    replaceInternalId(g5.finalDecisions);
    g5.campaignRegistry = g5.campaignRegistry.filter((campaign) => campaign !== incorrect);
  } else {
    incorrect.cabinetId = String(actualCabinetId);
    incorrect.guruId = `GURU-${actualCabinetId}`;
    incorrect.name = incorrect.name === "Кампания 1" ? `Кампания ${actualCabinetId}` : incorrect.name;
  }
  const reassignExternal = (record) => {
    if (String(record?.campaignId) === "1") record.campaignId = String(actualCabinetId);
  };
  Object.values(g5.reports).forEach((records) => records.forEach(reassignExternal));
  Object.values(g5.setup.groups).forEach(reassignExternal);
  Object.values(g5.setup.ads).forEach(reassignExternal);
  Object.values(g5.setup.phrases || {}).forEach(reassignExternal);
  Object.values(g5.yandexDirect.groups).forEach(reassignExternal);
  Object.values(g5.yandexDirect.ads).forEach(reassignExternal);
  Object.values(g5.yandexDirect.phrases).forEach(reassignExternal);
  g5.yandexDirect.structureSnapshots.forEach(reassignExternal);
  if (g5.setup.campaigns["1"]) {
    const legacy = g5.setup.campaigns["1"];
    g5.setup.campaigns[String(actualCabinetId)] = { ...legacy, id: String(actualCabinetId) };
    delete g5.setup.campaigns["1"];
  }
  return true;
}
function g5ImportYandexStructure(payload) {
  const g5 = ensureGate5State();
  const yd = g5.yandexDirect;
  const importId = makeId("g5-yd-import");
  g5RepairYandexCampaignIdentity(g5, payload.campaign.id);
  const existing = g5.campaignRegistry.find((campaign) => campaign.cabinetId === payload.campaign.id);
  const now = new Date().toISOString();
  const campaign = existing || { id: makeId("g5-campaign"), guruId: `GURU-${payload.campaign.id}`, cabinetId: payload.campaign.id, createdAt: now };
  const previous = yd.structureSnapshots.filter((snapshot) => snapshot.campaignId === payload.campaign.id).slice(-1)[0];
  const unchanged = !!previous && previous.hash === payload.hash;
  Object.assign(campaign, { name: payload.campaign.name, platform: "Яндекс Директ", type: payload.campaign.type, currency: payload.campaign.currency, status: existing?.status || "Импортирована", firstImportAt: existing?.firstImportAt || now, lastImportAt: now, groupCount: payload.counts.groups, adCount: payload.counts.ads, phraseCount: payload.counts.phrases, landingCount: payload.counts.landings, regions: [...new Set(payload.records.map((row) => row.region).filter(Boolean))].join(", "), sourceFile: payload.fileName, campaignNegatives: payload.campaign.campaignNegatives, comment: existing?.comment || "" });
  if (existing) Object.assign(existing, campaign); else g5.campaignRegistry.push(campaign);
  g5.setup.campaigns[payload.campaign.id] = { id: payload.campaign.id, name: payload.campaign.name, type: payload.campaign.type, currency: payload.campaign.currency, platform: "Яндекс Директ" };
  payload.records.forEach((row) => {
    if (row.groupId) {
      const group = { id: row.groupId, campaignId: payload.campaign.id, name: row.groupName || row.groupId, number: row.groupNumber, landing: row.landing, region: row.region, negatives: row.groupNegatives, status: row.adStatus || row.phraseStatus || "", importedAt: now };
      yd.groups[row.groupId] = { ...yd.groups[row.groupId], ...group };
      g5.setup.groups[row.groupId] = group;
    }
    if (row.adId) {
      const ad = { id: row.adId, campaignId: payload.campaign.id, groupId: row.groupId, type: row.adType, title: row.title1, title2: row.title2, text: row.adText, landing: row.landing, displayUrl: row.displayUrl, fastLinks: row.fastLinks, clarifications: row.clarifications, image: row.image, creative: row.creative, status: row.adStatus, moderationStatus: row.moderationStatus, importedAt: now };
      yd.ads[row.adId] = { ...yd.ads[row.adId], ...ad };
      g5.setup.ads[row.adId] = ad;
    }
    if (row.phraseId || row.phrase) {
      const phraseId = row.phraseId || `${row.groupId}:${row.phrase}`;
      const phrase = { id: phraseId, campaignId: payload.campaign.id, groupId: row.groupId, adId: row.adId, phrase: row.phrase, negatives: row.phrase.match(/(?:-|!)[^\s]+/g)?.join(" ") || "", status: row.phraseStatus, region: row.region, landing: row.landing, importedAt: now };
      yd.phrases[phraseId] = { ...yd.phrases[phraseId], ...phrase };
      g5.setup.phrases[phraseId] = phrase;
    }
    if (row.landing) yd.landings[row.landing] = { id: row.landing, campaignId: payload.campaign.id, url: row.landing, importedAt: now };
    if (row.region) yd.regions[`${payload.campaign.id}:${row.region}`] = { id: `${payload.campaign.id}:${row.region}`, campaignId: payload.campaign.id, name: row.region, importedAt: now };
    if (row.groupNegatives) yd.negativePhrases[`${payload.campaign.id}:${row.groupId}`] = { id: `${payload.campaign.id}:${row.groupId}`, campaignId: payload.campaign.id, groupId: row.groupId, value: row.groupNegatives, importedAt: now };
  });
  Object.values(yd.groups).filter((group) => group.campaignId === payload.campaign.id).forEach((group) => {
    const related = payload.records.filter((row) => row.groupId === group.id);
    group.phraseCount = new Set(related.map((row) => row.phraseId || row.phrase).filter(Boolean)).size;
    group.adCount = new Set(related.map((row) => row.adId).filter(Boolean)).size;
    g5.setup.groups[group.id] = { ...g5.setup.groups[group.id], phraseCount: group.phraseCount, adCount: group.adCount };
  });
  const snapshot = { id: makeId("g5-structure"), importId, campaignId: payload.campaign.id, importedAt: now, sourceFile: payload.fileName, counts: payload.counts, activeAds: payload.records.filter((row) => /актив|показывается|on/i.test(row.adStatus || "")).map((row) => row.adId).filter(Boolean).filter((value, index, array) => array.indexOf(value) === index).length, activePhrases: payload.records.filter((row) => /актив|показывается|on/i.test(row.phraseStatus || "")).map((row) => row.phraseId || row.phrase).filter(Boolean).filter((value, index, array) => array.indexOf(value) === index).length, hash: payload.hash, records: payload.records, unchanged };
  yd.structureSnapshots.push(snapshot);
  yd.imports.push({ id: importId, importedAt: now, fileName: payload.fileName, type: payload.type, status: unchanged ? "Импорт выполнен, изменений нет" : "Импортирован", campaignId: payload.campaign.id, counts: payload.counts });
  g5.imports.yandexStructure = { type: "yandex_structure", uploadedAt: now, fileName: payload.fileName, rows: payload.counts.rows, uploads: yd.imports.filter((item) => item.type === "yandex_structure").map((item) => ({ fileName: item.fileName, uploadedAt: item.importedAt, rows: item.counts.rows })) };
  if (!unchanged) g5YandexDiff(previous, payload).forEach((change) => g5YandexRegisterChange(g5, campaign, change));
  g5YandexRegisterChange(g5, campaign, { level: "Кампания", type: "Импортирован файл структуры", after: `Импортирована структура кампании из файла ${payload.fileName}.` });
  return { unchanged, changes: unchanged ? 0 : g5YandexDiff(previous, payload).length };
}

function g5PayloadSnapshotDescriptors(payload) {
  if (!payload || !payload.type) return [];
  const dates = (payload.records || []).map((row) => String(row?.date || "").slice(0, 10)).filter(Boolean).sort();
  const periodStart = String(payload.periodStart || payload.meta?.from || dates[0] || "").slice(0, 10);
  const periodEnd = String(payload.periodEnd || payload.meta?.to || dates.at(-1) || "").slice(0, 10);
  if (!periodStart || !periodEnd) return [];
  const campaignIds = payload.campaignIds?.length
    ? payload.campaignIds
    : [...new Set((payload.records || []).map((row) => String(row?.campaignId || "").trim()).filter(Boolean))];
  return campaignIds.map((campaignId) => ({
    reportType: payload.type === "search_placement" ? "search_placement" : payload.type,
    campaignId: String(campaignId),
    periodStart,
    periodEnd,
  }));
}

function g5DuplicateSnapshots(payload) {
  const g5 = ensureGate5State();
  const descriptors = g5PayloadSnapshotDescriptors(payload);
  if (!descriptors.length) return [];
  return g5.periodSnapshots.filter((snapshot) => descriptors.some((descriptor) =>
    String(snapshot?.reportType || "") === descriptor.reportType
    && g5SnapshotCampaignKey(g5, snapshot) === descriptor.campaignId
    && String(snapshot?.periodStart || "").slice(0, 10) === descriptor.periodStart
    && String(snapshot?.periodEnd || snapshot?.date || "").slice(0, 10) === descriptor.periodEnd));
}

function g5ImportYandexReport(payload, duplicateMode = "skip") {
  const g5 = ensureGate5State();
  const key = payload.type;
  const importId = makeId("g5-yd-import");
  const campaignIds = [...new Set(payload.records.map((row) => String(row.campaignId || "")).filter((id) => /^\d{6,}$/.test(id)))];
  if (!campaignIds.length) throw new Error("ID кампании не найден. Импорт невозможен без ID кампании Яндекс Директа.");
  const duplicates = g5DuplicateSnapshots(payload);
  if (duplicates.length && duplicateMode !== "update") return { skipped: true, changes: 0 };
  if (duplicates.length) {
    const duplicateIds = new Set(duplicates.map((snapshot) => snapshot.id));
    g5.periodSnapshots = g5.periodSnapshots.filter((snapshot) => !duplicateIds.has(snapshot.id));
    const descriptors = g5PayloadSnapshotDescriptors(payload);
    g5.reports[key] = (g5.reports[key] || []).filter((record) => !descriptors.some((descriptor) =>
      String(record?.campaignId || "") === descriptor.campaignId
      && String(record?.date || "").slice(0, 10) >= descriptor.periodStart
      && String(record?.date || "").slice(0, 10) <= descriptor.periodEnd));
  }
  const rowKey = (row) => [row.date, row.campaignId, row.groupId, row.adId, row.query || "", row.conditionType || "", row.conditionName || ""].join("|");
  const merged = new Map((g5.reports[key] || []).map((row) => [rowKey(row), row]));
  payload.records.forEach((row) => merged.set(rowKey(row), { ...row, importId, sourceFile: payload.fileName }));
  g5.reports[key] = [...merged.values()];
  const now = new Date().toISOString();
  campaignIds.forEach((campaignId) => {
    const campaignRows = payload.records.filter((row) => String(row.campaignId) === campaignId);
    const sample = campaignRows[0];
    let campaign = g5.campaignRegistry.find((item) => String(item.cabinetId) === campaignId);
    if (!campaign) {
      campaign = { id: makeId("g5-campaign"), guruId: `GURU-${campaignId}`, cabinetId: campaignId, name: sample.campaignName || `Кампания ${campaignId}`, platform: "Яндекс Директ", type: "Не определён", objective: "Лид", status: "Импортирована", createdAt: now, firstImportAt: now };
      g5.campaignRegistry.push(campaign);
    }
    Object.assign(campaign, { name: sample.campaignName || campaign.name, platform: "Яндекс Директ", lastImportAt: now, sourceFile: payload.fileName });
    const total = campaignRows.reduce((sum, row) => ({ spend: sum.spend + g5Num(row.spend), impressions: sum.impressions + g5Num(row.impressions), clicks: sum.clicks + g5Num(row.clicks), conversions: sum.conversions + g5Num(row.conversions) }), { spend: 0, impressions: 0, clicks: 0, conversions: 0 });
    const periodStart = payload.meta?.from || sample.date;
    const periodEnd = payload.meta?.to || sample.date;
    if (periodStart && periodEnd) {
      g5.periodSnapshots.push({ id: makeId("g5-snapshot"), importId, createdAt: now, campaignId: campaign.id, periodStart, periodEnd, status: "Активна", reportType: key, source: payload.fileName, sourceLabel: payload.typeLabel, spend: total.spend, impressions: total.impressions, clicks: total.clicks, ctr: g5Div(total.clicks, total.impressions) * 100, leads: total.conversions, conversions: total.conversions, cr: g5Div(total.conversions, total.clicks) * 100, cpa: g5Div(total.spend, total.conversions), comment: "Создан автоматически" });
      g5YandexRegisterChange(g5, campaign, { level: "Кампания", type: "Создан новый снимок периода", after: `${periodStart} — ${periodEnd}; источник ${payload.fileName}` });
    } else {
      g5YandexRegisterChange(g5, campaign, { level: "Кампания", type: "Импорт без снимка периода", after: `Файл ${payload.fileName} импортирован, но снимок не создан: в отчёте нет отдельной даты или периода.` });
    }
    g5YandexRegisterChange(g5, campaign, { level: "Кампания", type: "Импорт статистики", after: periodStart && periodEnd ? `Импортирован отчёт «${payload.typeLabel}» за период ${periodStart} — ${periodEnd}. Источник: ${payload.fileName}` : `Импортирован отчёт «${payload.typeLabel}» без создания факт-периода. Источник: ${payload.fileName}` });
  });
  g5.imports[key] = { type: key, uploadedAt: now, fileName: payload.fileName, rows: g5.reports[key].length };
  const hasPeriod = g5PayloadSnapshotDescriptors(payload).length > 0;
  g5.yandexDirect.imports.push({ id: importId, importedAt: now, fileName: payload.fileName, type: key, typeLabel: payload.typeLabel, status: hasPeriod ? (duplicates.length ? "Обновлён" : "Импортирован") : "Импортирован без снимка: нет периода", counts: payload.counts });
  return { skipped: false, changes: campaignIds.length, withoutSnapshot: !hasPeriod };
}
