/*
  v1.1.1 — Gate 0 / Паспорт проекта → Продукт, сегмент и задача клиента
  Возвращаем простую паспортную точку: что продаём → кому продаём → ради какого результата.
*/
const PRODUCT_SEGMENT_GLOBAL_FIELDS = [
  {
    key: "whatSell",
    label: "Что продаём",
    hint: "продукт / услуга / направление",
    evidenceKey: "что_продаем",
    usedIn: "Gate 1 / Gate 3 / Gate 4",
    downstream: "оффер, семантика, юнит-экономика, кампании, календарь, отчёты",
  },
  {
    key: "targetSegment",
    label: "Кому продаём",
    hint: "основной сегмент / аудитория",
    evidenceKey: "кому_продаем",
    usedIn: "Gate 1 / Gate 3 / Gate 4",
    downstream: "ЦА, сегменты, персоны, рекламные группы, коллаборации",
  },
  {
    key: "clientResult",
    label: "Ради какого результата",
    hint: "какую задачу клиента решаем",
    evidenceKey: "ради_какого_результата",
    usedIn: "Gate 1 / Gate 3 / Gate 4",
    downstream: "JTBD, офер, лендинги, объявления, CTA",
  },
];

function isProductSegmentClientCard(card) {
  return card?.title === "Продукт, сегмент и задача клиента";
}

function readProductSegmentValue(field, workspace = state) {
  return (
    workspace?.project?.[field.key] ||
    workspace?.sharedEvidence?.[field.evidenceKey] ||
    ""
  );
}

function productSegmentPlain(workspace = state) {
  return PRODUCT_SEGMENT_GLOBAL_FIELDS.map(
    (field) => `${field.label}:\n${readProductSegmentValue(field, workspace)}`,
  ).join("\n\n");
}

function ensureProductSegmentGlobals(workspace = state) {
  if (!workspace) return;
  workspace.project = workspace.project || {};
  workspace.sharedEvidence = workspace.sharedEvidence || {};
  const card = (workspace.gates || [])
    .flatMap((g) => g.cards || [])
    .find(isProductSegmentClientCard);
  if (card) {
    card.instruction =
      "Инструменты: бриф, интервью, CRM, сайт, отдел продаж.\n\nБлок отвечает за понимание: что продаётся, кому продаётся и какую задачу клиента решает.\n\nНа выходе должно быть понятно: что продаём, кому и ради какого результата.";
    card.evidenceFields = PRODUCT_SEGMENT_GLOBAL_FIELDS.map((field) => ({
      key: field.evidenceKey,
      label: field.label,
    }));
  }
  PRODUCT_SEGMENT_GLOBAL_FIELDS.forEach((field) => {
    const fromProject = String(workspace.project[field.key] || "").trim();
    const fromShared = String(
      workspace.sharedEvidence[field.evidenceKey] || "",
    ).trim();
    const value = fromProject || fromShared;
    workspace.project[field.key] = value;
    workspace.sharedEvidence[field.evidenceKey] = value;
  });
  if (card) card.evidence = productSegmentPlain(workspace);
}

function productSegmentValue(field, workspace = state) {
  return readProductSegmentValue(field, workspace);
}

function productSegmentStatus(workspace = state) {
  const values = PRODUCT_SEGMENT_GLOBAL_FIELDS.map((field) =>
    String(productSegmentValue(field, workspace) || "").trim(),
  );
  const filled = values.filter(Boolean).length;
  if (!filled) return "not_started";
  if (filled === PRODUCT_SEGMENT_GLOBAL_FIELDS.length) return "ready";
  return "in_progress";
}

function productSegmentFieldsHtml(card) {
  ensureProductSegmentGlobals(state);
  return `<div class="product-segment-block">
    <div class="product-segment-formula"><span>Что продаём</span><span>кому продаём</span><span>ради какого результата</span><span>передать дальше</span></div>
    <div class="product-segment-grid">
      ${PRODUCT_SEGMENT_GLOBAL_FIELDS.map((field) => {
        const value = productSegmentValue(field, state);
        return `<label class="product-segment-field">
          <span class="product-segment-title">${escapeHtml(field.label)}</span>
          <input data-product-segment-field="${escapeAttr(field.key)}" value="${escapeAttr(value)}" placeholder="${escapeAttr(field.hint)}" />
          <span class="product-segment-hint">${escapeHtml(field.hint)}</span>
          <span class="product-segment-indicators">
            <span class="mini-indicator ${String(value).trim() ? "is-saved" : ""}">${String(value).trim() ? "Сохранено в проекте" : "Не заполнено"}</span>
            <span class="mini-indicator">Используется в ${escapeHtml(field.usedIn)}</span>
          </span>
          <span class="product-segment-downstream">Передаётся в: ${escapeHtml(field.downstream)}</span>
        </label>`;
      }).join("")}
    </div>
    <div class="product-segment-note">Эти три значения являются глобальными данными проекта. Изменение здесь обновляет связанные поля по системе.</div>
  </div>`;
}

function updateProductSegmentField(e) {
  const field = PRODUCT_SEGMENT_GLOBAL_FIELDS.find(
    (item) => item.key === e.target.dataset.productSegmentField,
  );
  if (!field || !state) return;
  ensureProductSegmentGlobals(state);
  const value = e.target.value;
  state.project[field.key] = value;
  state.sharedEvidence[field.evidenceKey] = value;
  const card = allCardsFromWorkspace(state).find(isProductSegmentClientCard);
  if (card) {
    card.evidence = productSegmentPlain(state);
    recalculateStatusForCard(card, state);
  }
  flashSaving();
}

