const __guruPrevRecalculateStatusForCardV11 = recalculateStatusForCard;
recalculateStatusForCard = function (card, workspace = state) {
  if (isProductSegmentClientCard(card)) {
    ensureProductSegmentGlobals(workspace);
    card.status = productSegmentStatus(workspace);
    return;
  }
  __guruPrevRecalculateStatusForCardV11(card, workspace);
};

