/* v1.1.11 — Gate 0 / Контрольная дата фиксации
   Блок фиксирует дату, объект и срез состояния проекта. Не задача на реализацию.
*/
const CONTROL_FIXATION_FIELDS_V1111 = [
  {
    key: "controlFixationDate",
    sharedKey: "control_fixation_date",
    label: "Дата фиксации",
    hint: "день, когда зафиксировали состояние проекта",
    type: "date",
  },
  {
    key: "controlFixationObject",
    sharedKey: "control_fixation_object",
    label: "Объект фиксации",
    hint: "сайт / Gate / блок / кампания / отчёт",
    type: "text",
  },
];

function isControlFixationCardV1111(card) {
  return card?.title === "Контрольная дата фиксации";
}

function controlFixationInstructionV1111() {
  return "Блок отвечает не за постановку задачи, а за фиксацию состояния проекта на конкретную дату.\n\nФормула: дата → объект → состояние → доказательство → статус.\n\nНа выходе должно быть понятно: на какую дату, какой объект и в каком состоянии зафиксирован для будущего сравнения до / после.";
}

function controlFixationReadV1111(field, workspace = state) {
  return (
    workspace?.project?.[field.key] ||
    workspace?.sharedEvidence?.[field.sharedKey] ||
    ""
  );
}

function controlFixationPlainV1111(workspace = state) {
  return CONTROL_FIXATION_FIELDS_V1111.map(
    (field) => `${field.label}:\n${controlFixationReadV1111(field, workspace)}`,
  ).join("\n\n");
}

function ensureControlFixationV1111(card, workspace = state) {
  if (!card || !workspace || !isControlFixationCardV1111(card)) return;
  workspace.project = workspace.project || {};
  workspace.sharedEvidence = workspace.sharedEvidence || {};
  card.instruction = controlFixationInstructionV1111();
  card.evidenceFields = CONTROL_FIXATION_FIELDS_V1111.map((field) => ({
    key: field.sharedKey,
    label: field.label,
  }));
  CONTROL_FIXATION_FIELDS_V1111.forEach((field) => {
    const value = String(
      workspace.project[field.key] ||
        workspace.sharedEvidence[field.sharedKey] ||
        "",
    ).trim();
    workspace.project[field.key] = value;
    workspace.sharedEvidence[field.sharedKey] = value;
  });
  card.evidence = controlFixationPlainV1111(workspace);
}

function controlFixationObjectLooksBrokenV1111(value = "") {
  const v = String(value || "")
    .trim()
    .toLowerCase();
  if (!v) return false;
  if (v.length < 3) return true;
  return ["-", "---", "нет", "не указано", "непонятно", "хз"].includes(v);
}

function controlFixationStatusV1111(card, workspace = state) {
  if (!isControlFixationCardV1111(card)) return card?.status || "not_started";
  const date = String(
    controlFixationReadV1111(CONTROL_FIXATION_FIELDS_V1111[0], workspace) || "",
  ).trim();
  const object = String(
    controlFixationReadV1111(CONTROL_FIXATION_FIELDS_V1111[1], workspace) || "",
  ).trim();
  if (!date) return "not_started";
  if (controlFixationObjectLooksBrokenV1111(object)) return "problem";
  if (date && object) return "ready";
  return "in_progress";
}

function controlFixationFieldsHtmlV1111(card) {
  ensureControlFixationV1111(card, state);
  const status = controlFixationStatusV1111(card, state);
  const fieldHtml = (field) => {
    const value = controlFixationReadV1111(field, state);
    const type = field.type === "date" ? "date" : "text";
    return `<label class="control-date-field">
      <span class="control-date-title">${escapeHtml(field.label)}</span>
      <span class="control-date-hint">${escapeHtml(field.hint)}</span>
      <input type="${type}" data-control-fixation-key="${escapeAttr(field.key)}" value="${escapeAttr(value)}" placeholder="${escapeAttr(field.hint)}" />
    </label>`;
  };
  return `<div class="control-date-v1111">
    <div class="control-date-head">
      <div>
        <div class="control-date-orient">Зафиксируйте состояние проекта на конкретную дату, чтобы потом сравнить изменения.</div>
      </div>
      <span class="status-pill status-${escapeAttr(status)}">${escapeHtml(STATUS_LABELS[status] || status)}</span>
    </div>
    <div class="control-date-grid">
      ${CONTROL_FIXATION_FIELDS_V1111.map((field) => fieldHtml(field)).join("")}
    </div>
  </div>`;
}

function updateControlFixationInputV1111(e) {
  const field = CONTROL_FIXATION_FIELDS_V1111.find(
    (item) => item.key === e.target.dataset.controlFixationKey,
  );
  if (!field || !state) return;
  state.project = state.project || {};
  state.sharedEvidence = state.sharedEvidence || {};
  const value = e.target.value;
  state.project[field.key] = value;
  state.sharedEvidence[field.sharedKey] = value;
  const card = allCardsFromWorkspace(state).find(isControlFixationCardV1111);
  if (card) {
    ensureControlFixationV1111(card, state);
    card.status = controlFixationStatusV1111(card, state);
  }
  flashSaving();
}

const __guruPrevPrepareSystemCardsV1111 = prepareSystemCards;
prepareSystemCards = function (workspace) {
  __guruPrevPrepareSystemCardsV1111(workspace);
  (workspace?.gates || [])
    .flatMap((g) => g.cards || [])
    .forEach((card) => {
      if (isControlFixationCardV1111(card))
        ensureControlFixationV1111(card, workspace);
    });
};

const __guruPrevRecalculateStatusForCardV1111 = recalculateStatusForCard;
recalculateStatusForCard = function (card, workspace = state) {
  if (isControlFixationCardV1111(card)) {
    ensureControlFixationV1111(card, workspace);
    card.status = controlFixationStatusV1111(card, workspace);
    return;
  }
  __guruPrevRecalculateStatusForCardV1111(card, workspace);
};

const __guruPrevTextValuesForStatusV1111 = textValuesForStatus;
textValuesForStatus = function (card, workspace = state) {
  if (isControlFixationCardV1111(card))
    return CONTROL_FIXATION_FIELDS_V1111.map((field) =>
      controlFixationReadV1111(field, workspace),
    );
  return __guruPrevTextValuesForStatusV1111(card, workspace);
};

const __guruPrevFormatStructuredEvidencePlainV1111 =
  formatStructuredEvidencePlain;
formatStructuredEvidencePlain = function (card, workspace = state) {
  if (isControlFixationCardV1111(card))
    return controlFixationPlainV1111(workspace);
  return __guruPrevFormatStructuredEvidencePlainV1111(card, workspace);
};

const __guruPrevCardUserFieldsHtmlV1111 = cardUserFieldsHtml;
cardUserFieldsHtml = function (c) {
  if (isControlFixationCardV1111(c))
    return `<div class="field-row control-date-row"><span>${escapeHtml(c.title)}</span>${controlFixationFieldsHtmlV1111(c)}</div>`;
  return __guruPrevCardUserFieldsHtmlV1111(c);
};

const __guruPrevBindCardInputsV1111 = bindCardInputs;
bindCardInputs = function () {
  __guruPrevBindCardInputsV1111();
  document.querySelectorAll("[data-control-fixation-key]").forEach((input) => {
    input.addEventListener("input", updateControlFixationInputV1111);
    input.addEventListener("change", updateControlFixationInputV1111);
  });
};

/* v1.2.0 — Gate 0 vertical layout */
const __guruPrevRenderGateTableV120 = renderGateTable;
/* Gate 0 визуально разделён на «Компания» и «Продукт / Услуга». Диагностика
   имеет по одной физической карточке в конце каждого раздела; остальные
   карточки вне списков сохраняют исходный относительный порядок. */
const GATE0_COMPANY_SECTION_TITLES = [
  "Проект: базовые сведения",
  "Цель проекта и ограничения",
  "Сегментация · Компания",
  "Позиционирование · Компания",
  "Оффер и CTA · Компания",
  "Текущее состояние маркетинговой системы · Компания",
  "Диагностика точки отсчёта · Компания",
];
const GATE0_PRODUCT_SECTION_TITLES = [
  "Продукт, сегмент и задача клиента",
  "Проверь — у каждого продукта должна быть своя посадочная",
  "Текущие результаты",
  "Диагностика точки отсчёта · Продукт/Услуга",
];
function gate0CardHtml(c) {
  const isOpen = state._gate0Open[c.id] === true;
  return `<details class="gate0-card" data-card-row="${c.id}" ${isOpen ? "open" : ""}>
    <summary class="gate0-card-head">
      <div class="gate0-card-title">${escapeHtml(c.title)}</div>
      <span class="gate0-card-status status-${c.status}" data-gate0-jump-missing="${escapeAttr(c.id)}" role="button" tabindex="0" title="Перейти к незаполненному полю">${STATUS_LABELS[c.status] || c.status}</span>
    </summary>
    ${instructionToggleHtml(c)}
    <div class="gate0-card-body">${cardUserFieldsHtml(c)}</div>
  </details>`;
}
function gate0SectionHeadingHtml(title, desc, sectionKey = "") {
  if (!sectionKey) {
    const normalized = String(title || "").toLowerCase().replace(/[\s/\\\-–—·]/g, "");
    if (normalized === "компания") sectionKey = "company";
    if (normalized === "продуктуслуга") sectionKey = "product";
  }
  if (!sectionKey)
    return `<div class="gate0-section-heading"><div class="gate0-section-heading-title">${escapeHtml(title)}</div>${desc ? `<div class="gate0-section-heading-desc">${escapeHtml(desc)}</div>` : ""}</div>`;
  const expanded = activeGateId === "gate-0"
    ? state?._gate0SectionsOpen?.[sectionKey] !== false
    : state?.ui?.gateScopeOpenV526?.[activeGateId]?.[sectionKey] !== false;
  const titleHtml = `<button type="button" class="gate0-section-toggle" data-gate0-section-toggle="${escapeAttr(sectionKey)}" aria-expanded="${expanded}" title="${expanded ? "Свернуть все блоки раздела" : "Развернуть все блоки раздела"}"><span class="gate0-section-heading-title">${escapeHtml(title)}</span><span class="gate0-section-toggle-icon" aria-hidden="true">⌄</span></button>`;
  return `<div class="gate0-section-heading" data-gate0-section-heading="${escapeAttr(sectionKey)}">${titleHtml}${desc ? `<div class="gate0-section-heading-desc">${escapeHtml(desc)}</div>` : ""}</div>`;
}

function gate0SetSectionOpen(sectionKey, open, updateCards = false) {
  const heading = els.contentArea.querySelector(`[data-gate0-section-heading="${sectionKey}"]`);
  if (!heading) return;
  const button = heading.querySelector("[data-gate0-section-toggle]");
  button.setAttribute("aria-expanded", String(open));
  button.title = open ? "Свернуть все блоки раздела" : "Развернуть все блоки раздела";
  let node = heading.nextElementSibling;
  while (node && !node.matches("[data-gate0-section-heading]")) {
    node.classList.toggle("gate0-section-content-hidden", !open);
    if (updateCards) {
      const cards = node.matches("details.gate0-card")
        ? [node] : [...node.querySelectorAll("details.gate0-card")];
      cards.forEach((card) => {
        card._guruRenderedOpen = open;
        card.open = open;
        state._gate0Open[card.dataset.cardRow] = open;
      });
    }
    node = node.nextElementSibling;
  }
}

function gate0RevealSectionForNode(node) {
  const hiddenItem = node?.closest?.(".gate0-section-content-hidden");
  if (!hiddenItem || !els.contentArea.contains(hiddenItem)) return;
  let heading = hiddenItem.previousElementSibling;
  while (heading && !heading.matches("[data-gate0-section-heading]"))
    heading = heading.previousElementSibling;
  const sectionKey = heading?.dataset.gate0SectionHeading;
  if (!sectionKey) return;
  gate0SetSectionOpen(sectionKey, true);
  if (activeGateId === "gate-0") state._gate0SectionsOpen[sectionKey] = true;
  else guruGateScopeOpenStateV526()[sectionKey] = true;
  guruScheduleUiPreferenceSave();
}
renderGateTable = function (gate, cards) {
  if (gate && gate.id === "gate-0") {
    // Для показа Gate 0 нужны статусы только карточек этого гейта. Пересчёт всех
    // Gate здесь раньше добавлял сотни миллисекунд к каждому открытию.
    gate.cards.forEach((card) => recalculateStatusForCard(card, state));
    guruV350NormalizeCompanyStrategyCardOrder(state);
    state._gate0Open = state._gate0Open || {};
    state._gate0SectionsOpen = state._gate0SectionsOpen || {};
    const visible = cards.filter((c) => !isOfferPsychCard(c) && !c._merged);
    const companyCards = visible.filter(
      (c) =>
        GATE0_COMPANY_SECTION_TITLES.includes(c.title) ||
        guruV349IsCompanyBrandPurposeCard(c) ||
        guruV351IsCompanyKeywordFoundationCard(c) ||
        gate0DiagnosticScope(c) === "company",
    );
    const productCards = visible.filter(
      (c) =>
        GATE0_PRODUCT_SECTION_TITLES.includes(c.title) ||
        gate0DiagnosticScope(c) === "product",
    );
    const restCards = visible.filter(
      (c) =>
        !GATE0_COMPANY_SECTION_TITLES.includes(c.title) &&
        !GATE0_PRODUCT_SECTION_TITLES.includes(c.title) &&
        !guruV349IsCompanyBrandPurposeCard(c) &&
        !guruV351IsCompanyKeywordFoundationCard(c) &&
        !gate0DiagnosticScope(c),
    );
    const productCardsHtml = productCards
      .map((c) =>
        c.id === "gate0-landing-check-v215"
          ? gate0ProductLandingCheckHtml(c)
          : gate0CardHtml(c),
      )
      .join("");
    els.contentArea.innerHTML = `<div class="gate0-vertical">
          ${companyCards.length ? gate0SectionHeadingHtml("Компания", "Проект целиком: сведения, цель, платформа, инфраструктура, каналы — без привязки к конкретному продукту.", "company") : ""}
      ${companyCards.length ? guruStrategicFoundationCompanyHtmlV310(state) : ""}
      ${companyCards.map(gate0CardHtml).join("")}
          ${productCards.length ? gate0SectionHeadingHtml("Продукт / Услуга", "Один селектор «категория → позиция» ниже управляет всеми блоками этого раздела.", "product") : ""}
      ${productCards.length ? guruV194ProductSelectHtml("product_segment_client_task") : ""}
      ${productCardsHtml}
      ${restCards.map(gate0CardHtml).join("")}
    </div>`;
    document.querySelectorAll("details.gate0-card").forEach((el) => {
      el._guruRenderedOpen = el.open;
      el.addEventListener("toggle", () => {
        if (el._guruRenderedOpen === el.open) return;
        el._guruRenderedOpen = el.open;
        state._gate0Open = state._gate0Open || {};
        state._gate0Open[el.dataset.cardRow] = el.open;
        guruScheduleUiPreferenceSave();
      });
    });
    ["company", "product"].forEach((sectionKey) => {
      gate0SetSectionOpen(sectionKey, state._gate0SectionsOpen[sectionKey] !== false);
    });
    els.contentArea.querySelectorAll("[data-gate0-section-toggle]").forEach((button) => {
      button.addEventListener("click", () => {
        const sectionKey = button.dataset.gate0SectionToggle;
        const open = button.getAttribute("aria-expanded") !== "true";
        gate0SetSectionOpen(sectionKey, open, true);
        state._gate0SectionsOpen[sectionKey] = open;
        guruScheduleUiPreferenceSave();
      });
    });
    bindCardInputs();
    bindGate0StatusJump();
    bindGate0DiagnosticStages();
    renderGateNav();
    return;
  }
  __guruPrevRenderGateTableV120(gate, cards);
};

function gate0FirstEmptyField(section) {
  const selector = [
    "[data-v116-key]",
    "[data-v116-multi]",
    "[data-guru-product-jtbd]",
    "input:not([type=hidden]):not([type=checkbox]):not([type=radio])",
    "textarea",
    "select",
  ].join(",");
  return [...section.querySelectorAll(selector)].find((field) => {
    if (field.disabled || field.readOnly || field.closest("[hidden]")) return false;
    return !String(field.value || "").trim();
  });
}

function gate0JumpToMissingField(cardId) {
  const escapedId = typeof CSS?.escape === "function" ? CSS.escape(cardId) : cardId;
  const section = document.querySelector(`.gate0-card[data-card-row="${escapedId}"]`);
  if (!section) return;
  gate0RevealSectionForNode(section);
  section.open = true;
  state._gate0Open = state._gate0Open || {};
  state._gate0Open[cardId] = true;
  const field = gate0FirstEmptyField(section);
  const target = field || section.querySelector(".gate0-card-body") || section;
  target.scrollIntoView({ behavior: "smooth", block: "center" });
  if (field) setTimeout(() => field.focus({ preventScroll: true }), 350);
}

function bindGate0StatusJump() {
  document.querySelectorAll("[data-gate0-jump-missing]").forEach((badge) => {
    if (badge.dataset.gate0JumpBound) return;
    badge.dataset.gate0JumpBound = "true";
    const jump = (event) => {
      event.preventDefault();
      event.stopPropagation();
      gate0JumpToMissingField(badge.dataset.gate0JumpMissing);
    };
    badge.addEventListener("click", jump);
    badge.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") jump(event);
    });
  });
}

function gate0RefreshStatuses(options = {}) {
  const refreshSummary = options.refreshSummary === true;
  const gate = state?.gates?.find((g) => g.id === "gate-0");
  if (gate && options.statusesReady !== true)
    gate.cards.forEach((c) => recalculateStatusForCard(c, state));
  document.querySelectorAll(".gate0-card[data-card-row]").forEach((section) => {
    const card = findCard(section.dataset.cardRow);
    if (!card) return;
    const badge = section.querySelector(".gate0-card-status");
    if (badge) {
      badge.className = "gate0-card-status status-" + card.status;
      badge.textContent = STATUS_LABELS[card.status] || card.status;
      badge.dataset.gate0JumpMissing = card.id;
    }
    if (refreshSummary && isStartupSummaryCard(card)) {
      const body = section.querySelector(".gate0-card-body");
      if (body)
        body.innerHTML = `<div class="field-row">${gate0SummaryHtml(card)}</div>`;
      bindGate0DiagnosticStages();
    }
  });
  bindGate0StatusJump();
}

const __guruPrevFlashSavingV120 = flashSaving;
flashSaving = function () {
  __guruPrevFlashSavingV120();
  if (activeGateId === "gate-0") gate0RefreshStatuses();
};

function autosizeTextarea(el) {
  el.style.height = "auto";
  el.style.height = el.scrollHeight + "px";
}

const __guruPrevBindCardInputsV120 = bindCardInputs;
bindCardInputs = function () {
  __guruPrevBindCardInputsV120();
  document.querySelectorAll("[data-cr-meta-card-id]").forEach((input) => {
    input.addEventListener("input", updateCurrentResultMeta);
    input.addEventListener("change", updateCurrentResultMeta);
  });
  document.querySelectorAll(".passport-v116-autosize").forEach((ta) => {
    autosizeTextarea(ta);
    ta.addEventListener("input", () => autosizeTextarea(ta));
  });
  document.querySelectorAll("[data-v116-multi]").forEach((ta) => {
    ta.addEventListener("input", function () {
      const key = this.dataset.v116Multi;
      const idx = Number(this.dataset.v116MultiIdx);
      state.project[key] = state.project[key] || [];
      state.project[key][idx] = this.value;
      this.classList.toggle("is-filled", !!this.value.trim());
      this.classList.toggle("is-empty", !this.value.trim());
      autosizeTextarea(this);
      flashSaving();
    });
  });
  document.querySelectorAll("[data-v116-multi-add]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const key = btn.dataset.v116MultiAdd;
      state.project[key] = state.project[key] || [];
      state.project[key].push("");
      flashSaving();
      renderGate();
    });
  });
  document.querySelectorAll("[data-v116-multi-remove]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const key = btn.dataset.v116MultiRemove;
      const idx = Number(btn.dataset.v116MultiIdx);
      state.project[key] = state.project[key] || [];
      state.project[key].splice(idx, 1);
      flashSaving();
      renderGate();
    });
  });
};

/* v1.2.0 — Диагностика точки отсчёта: воронка 5A */
function diagToolIssueText(name, status, labels = {}) {
  const s = String(status || "");
  if (s === "implemented" || s === "active") return "";
  if (s === "in_progress") return `${name} — в работе`;
  if (s === "planned") return `${name} — планируется`;
  if (s === "not_implemented") return `${name} — не реализовано`;
  if (s === "inactive") return `${name} — не используется`;
  if (!s) return `${name} — статус не указан`;
  return `${name} — ${labels[s] || "не готово"}`;
}

function diagChannelTitle(c) {
  return [c.platform, c.type].filter(Boolean).join(" / ");
}

/* v2.1.5 — Действие 4: источник строки «Оффер и CTA «Категория»» в
   диагностике. Раньше смотрел только в старый словарь project.offersV2
   по имени категории (offersV2.productOffers[categoryName]) — он почти
   всегда пуст, если оффер/CTA заполнены на уровне позиции внутри
   категории через единый селектор (guruV194). Теперь сначала проверяются
   реальные данные позиций этой категории (guruV194Resolve по offers —
   там же лежит и CTA каждой записи), и только если их нет — старый
   словарь как было. Вид и логика самой диагностики (сколько элементов,
   как считается %) не меняются — меняется только то, откуда берётся
   готовность одного конкретного пункта. */
function gate0DiagnosticOfferCanonStatus(categoryName, legacyItem) {
  const category = guruV185ProductByName(categoryName, state);
  if (category) {
    const items = guruV194Products(state).filter((item) =>
      megaPlatformProductCategoryIds(item, state).includes(category.id));
    const probes = items.length ? items : [{ id: "", categoryId: category.id }];
    let hasComplete = false;
    let hasPartial = false;
    probes.forEach((probe) => {
      guruV194Resolve("offers", probe, state).records.forEach((record) => {
        const parts = guruV194OfferParts(record);
        if (guruV194OfferIsComplete(parts)) hasComplete = true;
        else if (guruV194OfferCoreIsComplete(parts) || guruV185Text(parts.cta) || guruV185Text(record.value)) hasPartial = true;
      });
    });
    if (hasComplete) return "works";
    if (hasPartial) return "needs_improvement";
  }
  if (v121ProductOfferReady(legacyItem)) return "works";
  if (v121HasText(legacyItem.offer) || v121HasText(legacyItem.cta)) return "needs_improvement";
  return "missing";
}

// Позиция диагностики: name + статус элемента → единый статус, тон и текст.
// Процент и статус этапа всегда выводятся из этих же элементов: нельзя
// получить «100%» для пункта, который отмечен как «Отсутствует».
function diag5AItem(name, status) {
  const canon = guruCanonStatus(status);
  const tone =
    canon === "works" || canon === "not_needed"
      ? "ok"
      : canon === "needs_improvement"
        ? "warn"
        : "bad";
  const label = canon ? guruStatusLabel(canon) : "статус не указан";
  return { status: canon, tone, text: `${name} — ${label}` };
}

function diagStageMetrics(items = []) {
  const total = items.length || 1;
  const score = items.reduce((sum, item) => {
    if (item.status === "works" || item.status === "not_needed") return sum + 1;
    if (item.status === "needs_improvement") return sum + 0.5;
    return sum;
  }, 0);
  const statuses = items.map((item) => item.status).filter(Boolean);
  const hasStartedWork = statuses.some(
    (value) =>
      value === "works" ||
      value === "not_needed" ||
      value === "needs_improvement" ||
      value === "broken",
  );
  let status = "not_started";
  if (statuses.length && statuses.every((value) => value === "works" || value === "not_needed")) {
    status = "ready";
  } else if (hasStartedWork && statuses.includes("broken")) {
    status = "problem";
  } else if (hasStartedWork) {
    status = "in_progress";
  }
  return { pct: Math.round((score / total) * 100), status };
}

function diag5AStageV348(key, name, label, desc, items = []) {
  return { key, name, label, desc, items, ...diagStageMetrics(items) };
}

function diag5AContentStatusV348(values = []) {
  const normalized = values.map(guruV185Text);
  const filled = normalized.filter(Boolean).length;
  if (!filled) return "missing";
  return filled === normalized.length ? "works" : "needs_improvement";
}

function diag5APositioningItemsV348(product, workspace = state) {
  const records = guruV194ExactRecords(
    "positioning",
    "product",
    product,
    workspace,
  );
  if (!records.length)
    return [diag5AItem("Позиционирование", "missing")];
  return records.map((record, index) => {
    const parts = guruV194PositioningParts(record);
    return diag5AItem(
      records.length > 1 ? `Позиционирование №${index + 1}` : "Позиционирование",
      diag5AContentStatusV348([
        parts.category,
        parts.key_difference,
        parts.basis,
        record.value,
      ]),
    );
  });
}

function diag5AOfferItemsV348(product, workspace = state) {
  const records = guruV194ExactRecords(
    "offers",
    "product",
    product,
    workspace,
  );
  if (!records.length) return [diag5AItem("Оффер + CTA", "missing")];
  return records.map((record, index) => {
    const parts = guruV194OfferParts(record);
    const status = guruV194OfferIsComplete(parts)
      ? "works"
      : [record.value, parts.rational, parts.irrational, parts.social, parts.cta]
            .some(guruV185Text)
        ? "needs_improvement"
        : "missing";
    return diag5AItem(
      records.length > 1 ? `Оффер + CTA №${index + 1}` : "Оффер + CTA",
      status,
    );
  });
}

function gate0LandingRecordReadV348(product, workspace = state) {
  const bindingId = gate0PositionBindingKey(product, workspace);
  return bindingId
    ? workspace?.project?.productBindingsV185?.[bindingId]?.landing || {}
    : {};
}

function diag5ALandingStatusV348(product, workspace = state) {
  const landing = gate0LandingRecordReadV348(product, workspace);
  const status = guruCanonStatus(landing.status);
  const hasUrl = Boolean(megaPlatformProductUrl(product, workspace));
  if (!status && !hasUrl) return "missing";
  if (status === "broken" || status === "missing") return status;
  if (status === "not_needed") return status;
  if (status === "works" && hasUrl) return "works";
  return "needs_improvement";
}

function diag5ACurrentResultsItemsV348(card) {
  const rows = card ? ensureCurrentResults(card) : [];
  const meta = card?.currentResultsMeta || {};
  return [
    diag5AItem(
      "Период фиксации результатов",
      guruV185Text(meta.period) ? "works" : "missing",
    ),
    ...rows.map((row) =>
      diag5AItem(
        row.label || row.key,
        guruV185Text(row.value) ? "works" : "missing",
      ),
    ),
  ];
}

function diag5AScopeModelV348(workspace = state, productId = null) {
  const gate0 = workspace?.gates?.find((gate) => gate.id === "gate-0");
  const mega = gate0?.cards?.find((card) => isMegaMarketingCard(card));
  const currentResultsCard = gate0?.cards?.find((card) =>
    isCurrentResultsCard(card),
  );
  const marketing = mega?.megaMarketing || {};
  const platform = marketing.platformV2 || {};
  const fundamental = platform.fundamental || [];
  const fundamentalItem = (label, matcher) => {
    const row = fundamental.find((item) => matcher.test(String(item?.name || "")));
    return diag5AItem(label, row?.status || "missing");
  };

  const companyStages = [
    diag5AStageV348(
      "company:channels",
      "Каналы",
      "Компания",
      "Все текущие каналы и рекламные материалы",
      (marketing.channels || []).map((channel) =>
        diag5AItem(
          diagChannelTitle(channel) || channel.channel || channel.name || "Канал",
          channel.status,
        ),
      ),
    ),
    diag5AStageV348(
      "company:infrastructure",
      "Инфраструктура",
      "Компания",
      "Аналитика, цели, CRM, UTM и обработка лидов",
      (marketing.infra || []).map((item) =>
        diag5AItem(item.name || "Инструмент", item.status),
      ),
    ),
    diag5AStageV348(
      "company:fundamental",
      "Базовые элементы сайта",
      "Компания",
      "Форма заявки / корзина, блоки доверия и контакты",
      [
        fundamentalItem("Форма заявки / корзина", /Форма/i),
        fundamentalItem("Блоки доверия", /Блоки доверия/i),
        fundamentalItem("Контакты", /Контакты/i),
      ],
    ),
  ];

  const allProducts = guruV194Products(workspace);
  const products = productId === null
    ? allProducts
    : allProducts.filter((product) => product.id === productId);
  const resultsPositionId = guruV185Text(
    currentResultsCard?.currentResultsMeta?.positionId,
  );
  const resultsProduct = allProducts.find(
    (product) => product.id === resultsPositionId,
  );
  const productGroups = products.map((product) => {
    const stages = [
      diag5AStageV348(
        `product:${product.id}:positioning-landing`,
        "Позиционирование и посадочная",
        "Продукт / Услуга",
        "Точные данные выбранного продукта без наследования",
        [
          ...diag5APositioningItemsV348(product, workspace),
          diag5AItem(
            "Посадочная страница",
            diag5ALandingStatusV348(product, workspace),
          ),
        ],
      ),
      diag5AStageV348(
        `product:${product.id}:offers`,
        "Офферы и CTA",
        "Продукт / Услуга",
        "Каждый оффер относится только к этому product_id",
        diag5AOfferItemsV348(product, workspace),
      ),
    ];
    if (resultsProduct?.id === product.id) {
      stages.push(
        diag5AStageV348(
          `product:${product.id}:results`,
          "Текущие результаты",
          "Продукт / Услуга",
          "Срез, привязанный через currentResultsMeta.positionId",
          diag5ACurrentResultsItemsV348(currentResultsCard),
        ),
      );
    }
    return { product, stages };
  });

  const hasUnassignedResults = Boolean(
    currentResultsCard &&
      (!resultsProduct || !resultsPositionId),
  );
  const unassignedStages = hasUnassignedResults
    ? [
        diag5AStageV348(
          "product:unassigned-results",
          "Текущие результаты",
          "Не назначено продукту",
          "Привязка допускается только по currentResultsMeta.positionId",
          [diag5AItem("Продукт результатов не назначен", "missing")],
        ),
      ]
    : [];

  return { companyStages, productGroups, unassignedStages };
}

function diag5AStages(workspace = state, scope = "") {
  const model = diag5AScopeModelV348(
    workspace,
    scope === "company" ? "" : null,
  );
  if (scope === "company") return model.companyStages;
  if (scope === "product")
    return [
      ...model.productGroups.flatMap((group) => group.stages),
      ...model.unassignedStages,
    ];
  return [
    ...model.companyStages,
    ...model.productGroups.flatMap((group) => group.stages),
    ...model.unassignedStages,
  ];
}

function diag5ASelectedProductGroupV350(workspace = state, model = null) {
  const selectedProduct = guruV194SelectedProduct(workspace);
  if (!selectedProduct) return null;
  const source = model || diag5AScopeModelV348(workspace, selectedProduct.id);
  return source.productGroups.find(
    (group) => group.product.id === selectedProduct.id,
  ) || null;
}

function diag5ALight(pct) {
  if (pct >= 80) return '<span class="diag-dot diag-green"></span>';
  if (pct >= 40) return '<span class="diag-dot diag-yellow"></span>';
  return '<span class="diag-dot diag-red"></span>';
}

function diag5AItemsHtml(items = []) {
  if (!items.length)
    return '<div class="diag-ok">Нет данных для диагностики — заполните блоки Gate 0</div>';
  const groups = [
    ["ok", "Реализовано"],
    ["warn", "В работе / планируется"],
    ["bad", "Не реализовано"],
  ];
  return groups
    .map(([tone, title]) => {
      const list = items.filter((i) => i.tone === tone);
      if (!list.length) return "";
      return `<div class="diag-group diag-group-${tone}">
        <div class="diag-group-title">${title}</div>
        <ul class="diag-issues diag-issues-${tone}">${list.map((i) => `<li>${escapeHtml(i.text)}</li>`).join("")}</ul>
      </div>`;
    })
    .join("");
}

function gate0DiagnosticOpenStages() {
  if (!state) return {};
  state.ui = state.ui || {};
  state.ui.gate0Diagnostics = state.ui.gate0Diagnostics || { openStages: {} };
  state.ui.gate0Diagnostics.openStages =
    state.ui.gate0Diagnostics.openStages || {};
  return state.ui.gate0Diagnostics.openStages;
}

function bindGate0DiagnosticStages() {
  document.querySelectorAll("[data-gate0-diagnostic-stage]").forEach((stage) => {
    if (stage.dataset.gate0DiagnosticBound) return;
    stage.dataset.gate0DiagnosticBound = "true";
    // Вставка <details open> через innerHTML сама генерирует toggle. Это не
    // действие пользователя: запоминаем отрендеренное состояние и игнорируем
    // первый служебный event, иначе один рендер создаёт десятки saveState().
    stage._guruDiagnosticRenderedOpen = stage.open;
    stage.addEventListener("toggle", () => {
      if (stage._guruDiagnosticRenderedOpen === stage.open) return;
      stage._guruDiagnosticRenderedOpen = stage.open;
      gate0DiagnosticOpenStages()[stage.dataset.gate0DiagnosticStage] = stage.open;
      guruScheduleUiPreferenceSave();
    });
  });
}

function diag5AStageHtmlV348(stage, openStages) {
  const light = diag5ALight(stage.pct);
  const tone = stage.pct >= 80 ? "green" : stage.pct >= 40 ? "yellow" : "red";
  const storageKey = stage.key || stage.name;
  const isOpen = Object.prototype.hasOwnProperty.call(openStages, storageKey)
    ? openStages[storageKey]
    : false;
  return `<details class="diag-stage diag-stage-${tone}" data-gate0-diagnostic-stage="${escapeAttr(storageKey)}" ${isOpen ? "open" : ""}>
    <summary class="diag-stage-head">
      <span class="diag-light">${light}</span>
      <div class="diag-stage-info">
        <div class="diag-stage-name">${escapeHtml(stage.name)} · ${escapeHtml(stage.label)}</div>
        <div class="diag-stage-desc">${escapeHtml(stage.desc)}</div>
      </div>
      <div class="diag-stage-bar-wrap">
        <span class="status-pill status-${escapeAttr(stage.status)}">${escapeHtml(STATUS_LABELS[stage.status] || stage.status)}</span>
        <div class="gate0-summary-bar"><div class="gate0-summary-fill" style="width:${stage.pct}%"></div></div>
        <span class="gate0-summary-pct">${stage.pct}%</span>
      </div>
    </summary>
    ${diag5AItemsHtml(stage.items)}
  </details>`;
}

function diag5AScopeStatusV348(stages = []) {
  return diagStageMetrics(stages.flatMap((stage) => stage.items || []));
}

function diag5AScopeHeadingHtmlV348(title, desc, stages) {
  const metrics = diag5AScopeStatusV348(stages);
  return `<div class="diag-scope-head-v348">
    <div><h4>${escapeHtml(title)}</h4><p>${escapeHtml(desc)}</p></div>
    <span class="status-pill status-${escapeAttr(metrics.status)}">${escapeHtml(STATUS_LABELS[metrics.status] || metrics.status)} · ${metrics.pct}%</span>
  </div>`;
}

function gate0SummaryHtml(card = null) {
  const scope = gate0DiagnosticScope(card);
  const selectedProduct = scope === "product"
    ? guruV194SelectedProduct(state)
    : null;
  const model = diag5AScopeModelV348(
    state,
    scope === "company"
      ? ""
      : scope === "product"
        ? selectedProduct?.id || ""
        : null,
  );
  const openStages = gate0DiagnosticOpenStages();
  const companyHtml = `<section class="diag-scope-v348" data-gate0-diagnostic-scope="company">
    ${diag5AScopeHeadingHtmlV348(
      "Компания",
      "Каналы, инфраструктура и базовые элементы сайта на уровне проекта.",
      model.companyStages,
    )}
    <div class="diag-scope-stages-v348">${model.companyStages
      .map((stage) => diag5AStageHtmlV348(stage, openStages))
      .join("")}</div>
  </section>`;
  const selectedProductGroup = scope === "product"
    ? diag5ASelectedProductGroupV350(state, model)
    : null;
  const selectedProductStages = selectedProductGroup?.stages || [];
  const productsHtml = selectedProductGroup
    ? `<section class="diag-product-v348" data-gate0-diagnostic-product-id="${escapeAttr(selectedProductGroup.product.id)}">
        ${diag5AScopeHeadingHtmlV348(selectedProductGroup.product.name, "Данные только этого product_id.", selectedProductStages)}
        <div class="diag-scope-stages-v348">${selectedProductStages
          .map((stage) => diag5AStageHtmlV348(stage, openStages))
          .join("")}</div>
      </section>`
    : '<div class="diag-ok">Выберите категорию и продукт, чтобы выполнить продуктовую диагностику.</div>';
  const productHtml = `<section class="diag-scope-v348" data-gate0-diagnostic-scope="product">
    ${diag5AScopeHeadingHtmlV348(
      "Продукт / Услуга",
      "Позиционирование, офферы, посадочные и точно привязанные текущие результаты.",
      selectedProductStages,
    )}
    <div class="diag-products-v348">${productsHtml}</div>
  </section>`;

  if (scope === "company") return `<div class="diag-5a">${companyHtml}</div>`;
  if (scope === "product") return `<div class="diag-5a">${productHtml}</div>`;
  return `<div class="diag-5a">${companyHtml}${productHtml}</div>`;
}

const __guruPrevCardUserFieldsHtmlV120Summary = cardUserFieldsHtml;
cardUserFieldsHtml = function (c) {
  if (isStartupSummaryCard(c))
    return `<div class="field-row">${gate0SummaryHtml(c)}</div>`;
  return __guruPrevCardUserFieldsHtmlV120Summary(c);
};

const __guruPrevRecalcStatusV120Summary = recalculateStatusForCard;
recalculateStatusForCard = function (card, workspace = state) {
  if (isStartupSummaryCard(card)) {
    const scope = gate0DiagnosticScope(card);
    const selectedProductGroup = scope === "product"
      ? diag5ASelectedProductGroupV350(workspace)
      : null;
    const stages = scope === "product"
      ? selectedProductGroup?.stages || []
      : diag5AStages(workspace, scope);
    const statuses = stages.map((stage) => stage.status);
    if (!statuses.length || statuses.every((status) => status === "not_started")) {
      card.status = "not_started";
    } else if (statuses.every((status) => status === "ready")) {
      card.status = "ready";
    } else if (statuses.includes("problem")) {
      card.status = "problem";
    } else {
      card.status = "in_progress";
    }
    return;
  }
  __guruPrevRecalcStatusV120Summary(card, workspace);
};

