const MEGA_TOOL_STATUSES = GURU_STATUS_OPTIONS;
const MEGA_CHANNEL_STATUSES = GURU_STATUS_OPTIONS;

function isMegaMarketingCard(card) {
  return (
    card?.id === "card-7" ||
    card?.title === "Текущее состояние маркетинговой системы · Компания" ||
    card?.title === "Текущее состояние маркетинговой системы" ||
    card?.title === "Текущее состояние сайта"
  );
}

function ensureMegaMarketing(card, workspace = state) {
  if (!card || !isMegaMarketingCard(card)) return;
  if (!card.megaMarketing) {
    card.megaMarketing = { platform: [], infra: [], channels: [] };
    const gate = workspace?.gates?.find((g) => g.id === "gate-0");
    if (gate) {
      const oldSite = gate.cards.find(
        (c) =>
          c.title === "Текущее состояние сайта" ||
          c.title === "Текущее состояние маркетинговой системы" ||
          c.title === "Текущее состояние маркетинговой системы · Компания",
      );
      const oldInfra = gate.cards.find(
        (c) => c.title === "Текущая инфраструктура маркетинга",
      );
      const oldChannels = gate.cards.find(
        (c) => c.title === "Текущие каналы и рекламные материалы",
      );
      if (oldSite?.toolItems?.length) {
        card.megaMarketing.platform = oldSite.toolItems.map((i) => ({
          name: i.name,
          status: i.status || "",
          comment: i.comment || "",
        }));
        console.log(
          "Mega migration: platform from toolItems",
          card.megaMarketing.platform.length,
        );
      }
      if (oldInfra?.toolItems?.length) {
        card.megaMarketing.infra = oldInfra.toolItems.map((i) => ({
          name: i.name,
          status: i.status || "",
          comment: i.comment || "",
        }));
        console.log(
          "Mega migration: infra from toolItems",
          card.megaMarketing.infra.length,
        );
      }
      if (oldChannels?.channelItems?.length) {
        card.megaMarketing.channels = oldChannels.channelItems.map((i) => ({
          ...i,
        }));
        console.log(
          "Mega migration: channels from channelItems",
          card.megaMarketing.channels.length,
        );
      }
    }
  }
  const m = card.megaMarketing;
  if (!m.platformV2) {
    m.platformV2 = { fundamental: [], landings: {}, extra: [] };
    if (m.platform?.length) {
      const oldMap = new Map(m.platform.map((i) => [i.name, i]));
      m.platformV2.fundamental = MEGA_PLATFORM_FUNDAMENTAL.map((name) => {
        const mapped = Object.entries(MEGA_PLATFORM_OLD_MAP).find(
          ([, v]) => v === name,
        );
        const old = mapped ? oldMap.get(mapped[0]) : oldMap.get(name);
        return {
          name,
          status: old?.status || "",
          url: old?.url || "",
          comment: old?.comment || "",
        };
      });
      console.log(
        "Platform v2 migration: fundamental",
        m.platformV2.fundamental.filter((r) => r.status).length + " with data",
      );
    }
  }
  m.platformV2.fundamental = Array.isArray(m.platformV2.fundamental)
    ? m.platformV2.fundamental : [];
  const unknownFundamental = m.platformV2.fundamental.filter((row) =>
    !MEGA_PLATFORM_FUNDAMENTAL.includes(row.name));
  if (unknownFundamental.length && !m.platformV2.legacyFundamentalRowsV1)
    m.platformV2.legacyFundamentalRowsV1 = structuredClone(unknownFundamental);
  const prevFund = new Map(m.platformV2.fundamental.map((r) => [r.name, r]));
  m.platformV2.fundamental = MEGA_PLATFORM_FUNDAMENTAL.map((name) => {
    const old = prevFund.get(name) || {};
    return {
      name,
      status: old.status || "",
      url: old.url || "",
      comment: old.comment || "",
    };
  });
  m.platformV2.landings = m.platformV2.landings || {};
  m.platformV2.extra = Array.isArray(m.platformV2.extra) ? m.platformV2.extra : [];
  m.platformV2.extra.forEach((row) => {
    if (row.group !== "commercial") return;
    if (!row.pageTypeV1) row.pageTypeV1 = "landing";
    if (!Object.hasOwn(row, "targetV1")) row.targetV1 = null;
    row.manualV2 = true;
  });
  // Старые строки остаются в сохранённом проекте для совместимости других
  // разделов; в новом представлении они больше не являются полями ввода.
  const priorLegal = Array.isArray(m.platformV2.legal) ? m.platformV2.legal : [];
  const unknownLegal = priorLegal.filter((row) =>
    !MEGA_PLATFORM_LEGAL_PAGES.includes(row.name));
  if (unknownLegal.length && !m.platformV2.legacyLegalRowsV1)
    m.platformV2.legacyLegalRowsV1 = structuredClone(unknownLegal);
  const legalPrevious = new Map(priorLegal.map((row) => [row.name, row]));
  const footerLegal = workspace?.gates?.find((gate) => gate.id === "gate-1")?.cards
    ?.find((item) => item.id === "card-site-footer-v497")?.siteChromeV497 || {};
  m.platformV2.legal = MEGA_PLATFORM_LEGAL_PAGES.map((name) => {
    const names = [name, ...(MEGA_PLATFORM_LEGAL_ALIASES[name] || [])];
    const legacyRows = [
      ...names.map((label) => legalPrevious.get(label)),
      ...names.map((label) => m.platformV2.extra.find((row) => row.name === label)),
      ...(name === "Политика конфиденциальности"
        ? [m.platformV2.fundamental.find((row) => row.name === name)] : []),
    ].filter(Boolean);
    const footer = name === "Публичная оферта"
      ? { status: footerLegal.offerStatus === "ready" ? "works" : "", url: footerLegal.offerUrl || "" }
      : name === "Условия возврата"
        ? { status: footerLegal.returnStatus === "ready" ? "works" : "", url: footerLegal.returnUrl || "" }
        : {};
    const old = legalPrevious.get(name) || Object.fromEntries(["status", "url", "comment"].map((field) =>
      [field, legacyRows.map((row) => row[field]).find(Boolean) || footer[field] || ""]));
    return { name, status: old.status || "", url: old.url || "", comment: old.comment || "" };
  });
  if (!m.platformV2.onOrder) {
    const old = m.platformV2.extra.find((row) => row.name === "На заказ") || {};
    m.platformV2.onOrder = { status: old.status || "", url: old.url || "", comment: old.comment || "" };
  }
  // Sync infra with v2 config, migrate old data
  const prevInfra = new Map(m.infra.map((r) => [r.name, r]));
  const infraCustom = m.infra.filter((r) => r._custom);
  m.infra = MEGA_INFRA_DEFAULTS_V2.map((cfg) => {
    let old = prevInfra.get(cfg.name);
    if (!old) {
      const mappedOldName = Object.entries(MEGA_INFRA_OLD_MAP).find(
        ([, v]) => v === cfg.name,
      );
      if (mappedOldName) old = prevInfra.get(mappedOldName[0]);
    }
    return {
      name: cfg.name,
      hint: cfg.hint,
      group: cfg.group,
      status: old?.status || "",
      comment: old?.comment || "",
    };
  });
  infraCustom.forEach((r) => m.infra.push(r));

  // Sync channels with config, preserve old data by platform+type key
  const prevCh = new Map(m.channels.map((r) => [r.platform + "|" + r.type, r]));
  const chCustom = m.channels.filter((r) => r._custom);
  m.channels = MEGA_CHANNEL_DEFAULTS.map((cfg) => {
    const old = prevCh.get(cfg.platform + "|" + cfg.type);
    return {
      ...cfg,
      materials: old?.materials || cfg.materials,
      status: old?.status || "",
    };
  });
  chCustom.forEach((r) => m.channels.push(r));

  return m;
}

