// URL pages belong to Platform. Presence of a key (including an empty string)
// means migration must never restore a value the user deliberately cleared.
const MEGA_PLATFORM_FIXED_URLS = Object.freeze({
  "card-21": "home", "card-22-hub": "catalog", "card-27": "contacts",
  "card-28": "delivery", "card-26": "about", "card-25": "blog",
  "card-29": "privacy", "card-30": "not_found", "card-31": "thank_you",
});
const MEGA_PLATFORM_LEGAL_KEYS = Object.freeze({
  "Реквизиты компании": "company_details",
  "Политика конфиденциальности": "privacy",
  "Согласие на обработку данных": "data_consent",
  "Публичная оферта": "offer",
  "Условия возврата": "returns",
});
const MEGA_PLATFORM_OLD_FIXED_KEYS = Object.freeze({
  "Главная страница": "home", "Страница продукта / услуги / каталог": "catalog",
  "Контакты (телефон, адрес, мессенджер)": "contacts",
  "Страница доставки и оплаты": "delivery", "О нас / история бренда": "about",
  "Блог": "blog", "На заказ": "on_order",
  ...MEGA_PLATFORM_LEGAL_KEYS,
});

function megaPlatformUrlStore(workspace = state) {
  const card = workspace?.gates?.find((gate) => gate.id === "gate-0")?.cards
    ?.find(isMegaMarketingCard);
  if (!card) return null;
  card.megaMarketing = card.megaMarketing || { platform: [], infra: [], channels: [] };
  card.megaMarketing.platformV2 = card.megaMarketing.platformV2 ||
    { fundamental: [], landings: {}, extra: [] };
  const platform = card.megaMarketing.platformV2;
  platform.urlsV1 = platform.urlsV1 && typeof platform.urlsV1 === "object"
    ? platform.urlsV1 : {};
  for (const group of ["fixed", "categories", "products", "custom"])
    platform.urlsV1[group] = platform.urlsV1[group] &&
      typeof platform.urlsV1[group] === "object" ? platform.urlsV1[group] : {};
  return platform.urlsV1;
}

function megaPlatformUrl(group, id, workspace = state) {
  if (!id) return "";
  const store = megaPlatformUrlStore(workspace);
  if (group === "categories" && store?.missingCategoryGeneratedIds?.includes(id)) return "";
  if (group === "categories" && id === store?.onOrderCategoryId)
    return String(store.fixed.on_order || "");
  return String(store?.[group]?.[id] || "");
}

function megaPlatformSetUrl(group, id, value, workspace = state) {
  if (!id) return false;
  const store = megaPlatformUrlStore(workspace);
  if (group === "categories" && store?.missingCategoryGeneratedIds?.includes(id)) return false;
  if (!store?.[group]) return false;
  if (group === "categories" && id === store.onOrderCategoryId) {
    store.fixed.on_order = String(value ?? "").trim();
    return true;
  }
  store[group][id] = String(value ?? "").trim();
  return true;
}

function megaPlatformAuditUrlKey(card, row) {
  if (card?.id === "card-32")
    return row?.id ? ["custom", `audit:${row.id}`] : null;
  if (card?.id === "card-25" && card.pageRows?.indexOf(row) > 0)
    return row?.id ? ["custom", `audit:${row.id}`] : null;
  if (card?.id === "card-22")
    return row?.categoryId ? ["categories", String(row.categoryId)] : null;
  if (card?.id === "card-23" || card?.id === "card-24")
    return row?.catalogItemIdV189 ? ["products", String(row.catalogItemIdV189)] : null;
  const fixed = MEGA_PLATFORM_FIXED_URLS[card?.id];
  return fixed ? ["fixed", fixed] : null;
}

function megaPlatformAuditUrl(card, row, workspace = state) {
  const key = megaPlatformAuditUrlKey(card, row);
  return key ? megaPlatformUrl(...key, workspace) : "";
}

function megaPlatformAuditRowUrl(row, workspace = state) {
  const card = workspace?.gates?.find((gate) => gate.id === "gate-1")?.cards
    ?.find((item) => item.pageRows?.includes(row));
  const key = megaPlatformAuditUrlKey(card, row);
  return key ? megaPlatformUrl(...key, workspace) : String(row?.url || "").trim();
}

function megaPlatformProductUrl(product, workspace = state) {
  const matches = typeof product === "string"
    ? guruV194Products(workspace).filter((item) => item.id === product || item.name === product)
    : [];
  const id = typeof product === "string"
    ? matches.length === 1 ? matches[0].id : ""
    : String(product?.id || "");
  return megaPlatformUrl("products", id, workspace);
}

function megaPlatformAllPages(workspace = state) {
  const store = megaPlatformUrlStore(workspace);
  if (!store) return [];
  const labels = {
    home: "Главная страница", catalog: "Каталог (Хаб)", contacts: "Контакты",
    delivery: "Доставка и оплата", about: "О нас / история бренда",
    blog: "Блог", on_order: "На заказ", not_found: "Страница 404",
    thank_you: "Страница «Спасибо»",
    ...Object.fromEntries(Object.entries(MEGA_PLATFORM_LEGAL_KEYS)
      .map(([label, key]) => [key, label])),
  };
  const rows = Object.entries(labels).map(([id, name]) => ({
    name, url: store.fixed[id] || "", group: "fixed", id,
  }));
  (workspace.project?.productRegistryV185 || []).forEach((item) => {
    if (!item.id || item.id === store.onOrderCategoryId ||
        !item.manualOriginV2 && (store.missingCategoryIds?.includes(item.name) ||
          store.missingCategoryGeneratedIds?.includes(item.id))) return;
    rows.push({ name: item.name, url: megaPlatformUrl("categories", item.id, workspace),
      group: "categories", id: item.id });
  });
  (workspace.project?.catalogItemsV189 || []).forEach((item) => {
    if (!item.id || !String(item.name || "").trim()) return;
    rows.push({ name: item.name, url: store.products[item.id] || "",
      group: "products", id: item.id });
  });
  for (const cardId of ["card-25", "card-32"]) {
    const card = workspace.gates?.find((gate) => gate.id === "gate-1")?.cards
      ?.find((item) => item.id === cardId);
    (card?.pageRows || []).forEach((row, index) => {
      if (cardId === "card-25" && index === 0 || !row.id) return;
      rows.push({ name: String(row.name || (cardId === "card-32" ? "Лендинг" : "Статья блога")),
        url: store.custom[`audit:${row.id}`] || "", group: "custom", id: `audit:${row.id}` });
    });
  }
  const platform = workspace.gates?.find((gate) => gate.id === "gate-0")?.cards
    ?.find(isMegaMarketingCard)?.megaMarketing?.platformV2;
  (platform?.extra || []).forEach((item) => {
    if (!item.id || item.promotedV2 || MEGA_PLATFORM_HIDDEN_EXTRA.has(item.name)) return;
    rows.push({ name: item.name, url: store.custom[item.id] || "",
      group: "custom", id: item.id });
  });
  return rows;
}

function megaPlatformCanonicalPageRefV2(ref, workspace = state) {
  if (ref?.group !== "custom" || !ref.id) return ref;
  const platform = workspace?.gates?.find((gate) => gate.id === "gate-0")?.cards
    ?.find(isMegaMarketingCard)?.megaMarketing?.platformV2;
  const origin = (platform?.extra || []).find((row) => row?.id === ref.id);
  const promoted = origin?.promotedV2;
  if (!promoted?.id || !["category", "product"].includes(promoted.kind)) return ref;
  const group = promoted.kind === "category" ? "categories" : "products";
  const entries = promoted.kind === "category"
    ? workspace?.project?.productRegistryV185 : workspace?.project?.catalogItemsV189;
  if (!Array.isArray(entries) || !entries.some((entry) =>
      entry?.id === promoted.id && entry.manualOriginV2 === origin.id))
    return ref;
  if (group === "categories" &&
      megaPlatformUrlStore(workspace)?.onOrderCategoryId === promoted.id)
    return { group: "fixed", id: "on_order" };
  return { group, id: promoted.id };
}

function megaPlatformPageRefUrl(ref, workspace = state) {
  const canonical = megaPlatformCanonicalPageRefV2(ref, workspace);
  return canonical?.group && canonical?.id
    ? megaPlatformUrl(canonical.group, canonical.id, workspace) : "";
}

function megaPlatformPageRefForUrl(raw, workspace = state) {
  const url = String(raw || "").trim();
  if (!url) return null;
  const matches = megaPlatformAllPages(workspace).filter((page) => page.url === url);
  const store = megaPlatformUrlStore(workspace);
  const unique = new Map(matches.map((page) => {
    const alias = page.group === "categories" && page.id === store?.onOrderCategoryId;
    const group = alias ? "fixed" : page.group;
    const id = alias ? "on_order" : page.id;
    return [`${group}:${id}`, { group, id }];
  }));
  return unique.size === 1 ? [...unique.values()][0] : null;
}

function megaPlatformPageChoiceHtml(ref, attrs, label = "Посадочная") {
  const canonical = megaPlatformCanonicalPageRefV2(ref, state);
  const selected = canonical?.group && canonical?.id
    ? `${canonical.group}:${canonical.id}` : "";
  const url = megaPlatformPageRefUrl(ref, state);
  return `<label class="g1-field"><span>${escapeHtml(label)} · из Платформы</span>
    <select class="g1-input" data-mega-platform-page-ref ${attrs}>
      <option value="">Страница не выбрана</option>${megaPlatformAllPages(state).map((page) =>
        `<option value="${escapeAttr(`${page.group}:${page.id}`)}" ${selected === `${page.group}:${page.id}` ? "selected" : ""}>${escapeHtml(page.name)}</option>`).join("")}
    </select><span class="mega-platform-source-value">${escapeHtml(url || "URL не указан")}</span></label>`;
}

document.addEventListener("change", (event) => {
  const select = event.target?.closest?.("select[data-mega-platform-page-ref]");
  if (!select) return;
  const kind = select.dataset.megaPlatformRefKind;
  const section = state.demandV130?.[select.dataset.megaPlatformPrefix];
  const step = section?.steps?.[select.dataset.megaPlatformStep];
  const search = kind === "search-sitelink"
    ? ensureGate4SearchBuild(select.dataset.g4sbProduct) : null;
  const draft = search ? g4sbV437DraftFromTarget(search, select) : null;
  const checkCard = kind === "gate1-check"
    ? findCard(select.dataset.megaPlatformCard) : null;
  const check = checkCard?.[select.dataset.megaPlatformCheck];
  const row = kind === "demand-step" ? step
    : kind === "demand-sitelink" ? step?.sitelinkRows?.[Number(select.dataset.megaPlatformRow)]
      : kind === "demand-route" ? state.demandRoute
      : kind === "demand-group" ? state.demandRoute?.groups?.[Number(select.dataset.megaPlatformIndex)]
      : kind === "link-bank" ? state.linkBank?.[Number(select.dataset.megaPlatformIndex)]
      : kind === "gate1-check" ? check
      : kind === "search-sitelink" ? draft?.sitelinkRows?.[Number(select.dataset.megaPlatformRow)]
      : kind === "g4-implementation" ? select.dataset.megaPlatformId
        ? state.gate4?.implementations?.find((item) => item.id === select.dataset.megaPlatformId)
        : state.gate4?.implementations?.[Number(select.dataset.megaPlatformIndex)]
        : null;
  if (!row) return;
  const colon = select.value.indexOf(":");
  const ref = colon < 0 ? null : {
    group: select.value.slice(0, colon), id: select.value.slice(colon + 1),
  };
  if (kind === "demand-step" || kind === "demand-route") row.landingPageRefV1 = ref;
  else row.pageRefV1 = ref;
  if (checkCard) recalculateStatusForCard(checkCard);
  flashSaving();
  if (kind === "link-bank") renderLinkBank();
  else renderGate();
});

function megaPlatformMigrateUrls(workspace, categoriesWithoutStableId = []) {
  const store = megaPlatformUrlStore(workspace);
  if (!store) return;
  store.missingCategoryIds = [...new Set([
    ...categoriesWithoutStableId,
    ...(workspace.project?.productRegistryV185 || [])
      .filter((item) => !String(item?.id || "").trim())
      .map((item) => String(item?.name || "Без названия")),
  ])];
  store.missingCategoryGeneratedIds = [...new Set([
    ...(store.missingCategoryGeneratedIds || []),
    ...(workspace.project?.productRegistryV185 || [])
      .filter((item) => categoriesWithoutStableId.includes(item?.name) && item?.id)
      .map((item) => String(item.id)),
  ])];
  const candidates = new Map();
  const unmappedLegacyUrls = [];
  const add = (group, id, value, source) => {
    const url = typeof value === "string" ? value.trim() : "";
    if (!id || !url) return;
    if (group === "categories") {
      const category = (workspace.project?.productRegistryV185 || [])
        .find((item) => String(item.id) === String(id));
      if (!category || store.missingCategoryIds.includes(category.name) ||
          store.missingCategoryGeneratedIds?.includes(category.id)) {
        unmappedLegacyUrls.push({ source, url,
          reason: "У категории нет подтверждённого стабильного ID" });
        return;
      }
    }
    if (group === "products" &&
        !(workspace.project?.catalogItemsV189 || [])
          .some((item) => String(item.id) === String(id))) {
      unmappedLegacyUrls.push({ source, url, reason: "Нет product_id в каталоге" });
      return;
    }
    const key = `${group}:${id}`;
    if (!candidates.has(key)) candidates.set(key, []);
    candidates.get(key).push({ source, url });
  };
  const marketingCard = workspace.gates.find((gate) => gate.id === "gate-0")
    ?.cards.find(isMegaMarketingCard);
  const marketing = marketingCard?.megaMarketing || {};
  const platform = marketing.platformV2 || {};
  for (const row of [
    ...(Array.isArray(platform.legacyLegalRowsV1) ? platform.legacyLegalRowsV1 : []),
    ...(Array.isArray(platform.legacyFundamentalRowsV1) ? platform.legacyFundamentalRowsV1 : []),
  ].filter(Boolean)) {
    const canonicalLegal = Object.entries(MEGA_PLATFORM_LEGAL_ALIASES)
      .find(([name, aliases]) => name === row.name || aliases.includes(row.name))?.[0];
    const fixed = MEGA_PLATFORM_OLD_FIXED_KEYS[row.name] ||
      MEGA_PLATFORM_LEGAL_KEYS[canonicalLegal];
    if (fixed) add("fixed", fixed, row.url, `platformV2.legacy.${row.name}`);
    else if (typeof row.url === "string" && row.url.trim())
      unmappedLegacyUrls.push({ source: `platformV2.legacy.${row.name}`,
        url: row.url.trim(), reason: "Нет системного ключа страницы" });
  }
  (platform.extra || []).forEach((row) => {
    if (row.promotedV2 || MEGA_PLATFORM_HIDDEN_EXTRA.has(row.name)) return;
    row.id = row.id || makeId("platform-page");
    add("custom", row.id, row.url, `platformV2.extra.${row.id}.url`);
  });
  const gate1 = workspace.gates.find((gate) => gate.id === "gate-1");
  const homeSource = workspace.project?.website || gate1?.cards
    .find((card) => card.id === "card-21")?.pageRows?.[0]?.url || "";
  let projectHost = "";
  try {
    const address = /^https?:\/\//i.test(homeSource) ? homeSource : `https://${homeSource}`;
    projectHost = new URL(address).hostname;
  } catch (_) { /* No confirmed project domain. */ }
  const auditEvidenceUrl = (value) => {
    const url = typeof value === "string" ? value.trim() : "";
    if (!url || !projectHost || /\s/.test(url)) return "";
    if (url.startsWith("/") && !url.startsWith("//")) return url;
    try {
      return new URL(/^https?:\/\//i.test(url) ? url : `https://${url}`).hostname === projectHost
        ? url : "";
    } catch (_) { return ""; }
  };
  (gate1?.cards || []).forEach((card) => {
    (card.pageRows || []).forEach((row, index) => {
      let key = card.id === "card-22" && store.missingCategoryIds.includes(row.name)
        ? null : megaPlatformAuditUrlKey(card, row);
      if (key?.[0] === "categories" &&
          !(workspace.project?.productRegistryV185 || []).some((item) => String(item.id) === key[1]))
        key = null;
      if (key?.[0] === "products" &&
          !(workspace.project?.catalogItemsV189 || []).some((item) => String(item.id) === key[1]))
        key = null;
      if (!key) {
        if (typeof row.url === "string" && row.url.trim())
          unmappedLegacyUrls.push({ source: `${card.id}.pageRows[${index}].url`,
            url: row.url.trim(), reason: "У страницы нет стабильной связи с ключом Платформы" });
        return;
      }
      add(...key, row.url, `${card.id}.pageRows[${index}].url`);
      add(...key, row.pageUrl, `${card.id}.pageRows[${index}].pageUrl`);
      add(...key, row.contextFields?.pageUrl, `${card.id}.pageRows[${index}].contextFields.pageUrl`);
    });
    const fixed = MEGA_PLATFORM_FIXED_URLS[card.id];
    if (fixed && (card.pageRows || []).length <= 1) {
      add("fixed", fixed, auditEvidenceUrl(card.legacyEvidenceBeforePlatformV1),
        `${card.id}.legacyEvidenceBeforePlatformV1`);
      add("fixed", fixed, auditEvidenceUrl(card.evidence), `${card.id}.evidence`);
      add("fixed", fixed, auditEvidenceUrl(card.fields?.url), `${card.id}.fields.url`);
      add("fixed", fixed, auditEvidenceUrl(card.fields?.pageUrl), `${card.id}.fields.pageUrl`);
    }
  });
  const footer = gate1?.cards.find((card) => card.id === "card-site-footer-v497")?.siteChromeV497 || {};
  add("fixed", "offer", footer.offerUrl, "siteChromeV497.offerUrl");
  add("fixed", "returns", footer.returnUrl, "siteChromeV497.returnUrl");
  (platform.legal || []).forEach((row) => add("fixed", MEGA_PLATFORM_LEGAL_KEYS[row.name], row.url,
    `platformV2.legal.${row.name}`));
  add("fixed", "on_order", platform.onOrder?.url, "platformV2.onOrder.url");
  const onOrderProposal = guruSiteChromeProposalV499(workspace)
    .find((item) => item.key === "on_order");
  add("fixed", "on_order", onOrderProposal?.url, "guruSiteChromeProposalV499.on_order");
  const onOrderCategory = (workspace.project?.productRegistryV185 || [])
    .find((item) => String(item?.name || "").trim().toLocaleLowerCase("ru-RU") === "на заказ");
  if (onOrderCategory?.id && !categoriesWithoutStableId.includes(onOrderCategory.name))
    store.onOrderCategoryId = String(onOrderCategory.id);
  const onOrderAudit = gate1?.cards.find((card) => card.id === "card-22")?.pageRows
    ?.find((row) => row.categoryId === onOrderCategory?.id);
  add("fixed", "on_order", onOrderAudit?.url, "card-22.На заказ.url");
  [...(platform.fundamental || []), ...(platform.extra || [])].forEach((row) =>
    add("fixed", MEGA_PLATFORM_OLD_FIXED_KEYS[row.name], row.url, `platformV2.${row.name}`));
  [...(marketing.platform || []), ...(marketingCard?.toolItems || [])].forEach((row) => {
    const name = MEGA_PLATFORM_OLD_MAP[row.name] || row.name;
    add("fixed", MEGA_PLATFORM_OLD_FIXED_KEYS[name], row.url,
      `megaMarketing.platform.${row.name}`);
  });
  add("fixed", "home", workspace.project?.website, "project.website");
  add("fixed", "home", workspace.project?.websiteUrl, "project.websiteUrl");
  add("fixed", "home", workspace.project?.website_url, "project.website_url");
  (gate1?.cards || []).forEach((card) => add("fixed", "home",
    card.robotsYandex?.siteUrl, `${card.id}.robotsYandex.siteUrl`));
  const categories = Array.isArray(workspace.project?.productRegistryV185)
    ? workspace.project.productRegistryV185 : [];
  const products = Array.isArray(workspace.project?.catalogItemsV189)
    ? workspace.project.catalogItemsV189 : [];
  store.missingCategoryIds = [...new Set([
    ...categoriesWithoutStableId,
    ...categories.filter((item) => !String(item?.id || "").trim())
      .map((item) => String(item?.name || "Без названия")),
  ])];
  categories.forEach((category) => {
    if (store.missingCategoryIds.includes(category.name)) return;
    add("categories", category.id, category.url,
      `productRegistryV185.${category.id}.url`);
  });
  products.forEach((product) => {
    add("products", product.id, product.url, `catalogItemsV189.${product.id}.url`);
    add("products", product.id, product.landing?.url, `catalogItemsV189.${product.id}.landing.url`);
    const legacy = platform.landings?.[product.name];
    add("products", product.id, legacy?.url, `platformV2.landings.${product.name}.url`);
  });
  for (const [sourceId, record] of Object.entries(workspace.gate4Rsya || {})) {
    const product = products.find((item) => item.id === sourceId);
    for (const group of record?.groups || []) {
      const productId = group.product_id || product?.id;
      if (!products.some((item) => item.id === productId)) {
        for (const value of [group.landing, ...(group.ads || []).flatMap((ad) =>
          [ad.landing, ad.ctaUrl])])
          if (typeof value === "string" && value.trim())
            unmappedLegacyUrls.push({ source: `gate4Rsya.${sourceId}.${group.id}`,
              url: value.trim(), reason: "Нет product_id" });
        continue;
      }
      add("products", productId, group.landing, `gate4Rsya.${sourceId}.${group.id}.landing`);
      for (const ad of group.ads || []) {
        add("products", productId, ad.landing, `gate4Rsya.${sourceId}.${group.id}.${ad.id}.landing`);
        add("products", productId, ad.ctaUrl, `gate4Rsya.${sourceId}.${group.id}.${ad.id}.ctaUrl`);
      }
    }
  }
  for (const [sourceId, campaign] of Object.entries(workspace.gate4Production?.campaigns || {})) {
    const product = products.find((item) => item.id === campaign?.productId ||
      item.id === campaign?.product_id);
    if (product) add("products", product.id, campaign?.landing,
      `gate4Production.campaigns.${sourceId}.landing`);
    else if (typeof campaign?.landing === "string" && campaign.landing.trim())
      unmappedLegacyUrls.push({ source: `gate4Production.campaigns.${sourceId}.landing`,
        url: campaign.landing.trim(), reason: "Нет product_id" });
  }
  const bindings = workspace.project?.productBindingsV185 || {};
  for (const category of categories) {
    if (store.missingCategoryIds.includes(category.name)) continue;
    add("categories", category.id, bindings[category.id]?.landing?.url,
      `productBindingsV185.${category.id}.landing.url`);
    add("categories", category.id, bindings[category.id]?.productProfile?.fields?.url,
      `productBindingsV185.${category.id}.productProfile.fields.url`);
  }
  for (const product of products)
    add("products", product.id, bindings[product.id]?.landing?.url,
      `productBindingsV185.${product.id}.landing.url`);
  (workspace.project?.gate0ScopedValuesV194 || []).forEach((record) => {
    const field = String(record?.field || "").trim().toLowerCase();
    if (!/url|landing|page/.test(field) || typeof record?.value !== "string" ||
        !record.value.trim()) return;
    const fixed = {
      website: "home", website_url: "home", home_url: "home", site_url: "home",
      catalog_url: "catalog", contacts_url: "contacts", delivery_url: "delivery",
      privacy_url: "privacy", about_url: "about", blog_url: "blog",
      thank_you_url: "thank_you", not_found_url: "not_found",
    }[field];
    const group = record.product_id ? "products" : record.category_id ? "categories"
      : fixed ? "fixed" : "";
    const id = record.product_id || record.category_id || fixed;
    const source = `gate0ScopedValuesV194.${record.id || record.field}`;
    if (group && id) add(group, id, record.value, source);
    else unmappedLegacyUrls.push({ source, url: record.value.trim() });
  });
  for (const card of gate1?.cards || []) {
    const robots = card.robotsV130;
    for (const row of [...(robots?.yandex?.urlResults || []),
      ...(robots?.yandex?.serviceResults || []),
      ...(robots?.legacyUrlResultsV1 || []),
      ...(robots?.legacyServiceResultsV1 || []),
      ...(robots?.google?.urlResults || [])]) {
      const matchingPages = [...(gate1?.cards || [])].flatMap((pageCard) =>
        (pageCard.pageRows || []).map((pageRow) => ({ pageCard, pageRow })))
        .filter(({ pageRow }) => pageRow.url && pageRow.url === row.url);
      const byUrl = matchingPages.length === 1 ? matchingPages[0] : null;
      let key = byUrl && megaPlatformAuditUrlKey(byUrl.pageCard, byUrl.pageRow);
      if (!key) {
        const name = String(row.type || "").trim().toLocaleLowerCase("ru-RU");
        const fixed = Object.entries({
          "главная страница": "home", "каталог (хаб)": "catalog",
          "контакты": "contacts", "доставка и оплата": "delivery",
          "политика конфиденциальности": "privacy", "о нас / история бренда": "about",
          "блог": "blog", "на заказ": "on_order",
        }).find(([label]) => label === name)?.[1];
        if (fixed) key = ["fixed", fixed];
      }
      if (key) add(...key, row.url, `robotsV130.${card.id}.${row.type || "urlResults"}`);
      else if (typeof row.url === "string" && row.url.trim())
        unmappedLegacyUrls.push({ source: `robotsV130.${card.id}.${row.type || "urlResults"}`,
          url: row.url.trim(), reason: "Нет стабильной связи со страницей Платформы" });
    }
  }
  const gate2 = workspace.gates?.find((gate) => gate.id === "gate-2");
  for (const card of gate2?.cards || [])
    for (const [index, row] of (card.fields?.metrikaQualityV360?.perProduct || []).entries())
      add("fixed", "thank_you", row?.thankYouUrl,
        `gate2.${card.id}.perProduct[${index}].thankYouUrl`);
  const conflicts = [];
  if (store.onOrderCategoryId) {
    const aliasKey = `categories:${store.onOrderCategoryId}`;
    const aliasCandidates = candidates.get(aliasKey) || [];
    aliasCandidates.forEach((entry) => add("fixed", "on_order", entry.url, entry.source));
    candidates.delete(aliasKey);
    if (!Object.hasOwn(store.fixed, "on_order") &&
        Object.hasOwn(store.categories, store.onOrderCategoryId))
      store.fixed.on_order = store.categories[store.onOrderCategoryId];
  }
  for (const [key, entries] of candidates) {
    const colon = key.indexOf(":");
    const group = key.slice(0, colon);
    const id = key.slice(colon + 1);
    if (!Object.hasOwn(store[group], id)) store[group][id] = entries[0].url;
    if (new Set(entries.map((entry) => entry.url)).size > 1)
      conflicts.push({ key, selected: store[group][id], candidates: entries });
  }
  store.migrationConflicts = conflicts;
  store.unmappedLegacyUrls = unmappedLegacyUrls;
  const unresolvedReferences = [];
  for (const [index, link] of (workspace.linkBank || []).entries()) {
    if (link.pageRefV1 || !String(link.url || "").trim()) continue;
    const ref = megaPlatformPageRefForUrl(link.url, workspace);
    if (ref) link.pageRefV1 = ref;
    else unresolvedReferences.push({ source: `linkBank[${index}].url`, url: link.url });
  }
  for (const [sourceId, record] of Object.entries(workspace.gate4Rsya || {})) {
    for (const group of record?.groups || []) {
      for (const ad of group.ads || []) {
        for (const link of ad.sitelinks || []) {
          if (link.pageRefV1 || !String(link.url || "").trim()) continue;
          const ref = megaPlatformPageRefForUrl(link.url, workspace);
          if (ref) link.pageRefV1 = ref;
          else unresolvedReferences.push({ source: `gate4Rsya.${sourceId}.${group.id}.${ad.id}.sitelinks.${link.id}`, url: link.url });
        }
      }
    }
    const promotion = record?.campaign?.promotion;
    if (promotion?.url && !promotion.pageRefV1) {
      const ref = megaPlatformPageRefForUrl(promotion.url, workspace);
      if (ref) promotion.pageRefV1 = ref;
      else unresolvedReferences.push({ source: `gate4Rsya.${sourceId}.campaign.promotion.url`, url: promotion.url });
    }
  }
  for (const card of gate2?.cards || []) {
    for (const [collection, field] of [["pageChecks", "url"],
      ["callRoutes", "landingUrl"], ["emailRoutes", "landingUrl"]]) {
      for (const [index, check] of (card.fields?.metrikaQualityV360?.[collection] || []).entries()) {
        if (check.pageRefV1 || !String(check[field] || "").trim()) continue;
        const ref = megaPlatformPageRefForUrl(check[field], workspace);
        if (ref) check.pageRefV1 = ref;
        else unresolvedReferences.push({ source: `gate2.${card.id}.${collection}[${index}].${field}`, url: check[field] });
      }
    }
  }
  for (const card of gate1?.cards || []) {
    for (const [kind, record] of [["serverResponse", card.serverResponse],
      ["legalTrust", card.legalTrust], ["cookieV130", card.cookieV130],
      ["footerV130", card.footerV130]]) {
      if (!record || record.pageRefV1 || !String(record.url || "").trim()) continue;
      const ref = megaPlatformPageRefForUrl(record.url, workspace);
      if (ref) record.pageRefV1 = ref;
      else unresolvedReferences.push({ source: `gate1.${card.id}.${kind}.url`, url: record.url });
    }
  }
  const route = workspace.demandRoute;
  if (route?.landing && !route.landingPageRefV1) {
    const ref = megaPlatformPageRefForUrl(route.landing, workspace);
    if (ref) route.landingPageRefV1 = ref;
    else unresolvedReferences.push({ source: "demandRoute.landing", url: route.landing });
  }
  for (const [index, group] of (route?.groups || []).entries()) {
    if (group.pageRefV1 || !String(group.landing || "").trim()) continue;
    const ref = megaPlatformPageRefForUrl(group.landing, workspace);
    if (ref) group.pageRefV1 = ref;
    else unresolvedReferences.push({
      source: `demandRoute.groups[${index}].landing`, url: group.landing,
    });
  }
  for (const [prefix, section] of Object.entries(workspace.demandV130 || {})) {
    for (const [stepKey, step] of Object.entries(section?.steps || {})) {
      if (typeof step?.landing === "string" && step.landing.trim() &&
          !step.landingPageRefV1) {
        const ref = megaPlatformPageRefForUrl(step.landing, workspace);
        if (ref) step.landingPageRefV1 = ref;
        else unresolvedReferences.push({ source: `demandV130.${prefix}.${stepKey}.landing`, url: step.landing });
      }
      for (const [index, row] of (step?.sitelinkRows || []).entries()) {
        if (row.pageRefV1 || !String(row.t3col2 || "").trim()) continue;
        const ref = megaPlatformPageRefForUrl(row.t3col2, workspace);
        if (ref) row.pageRefV1 = ref;
        else unresolvedReferences.push({ source: `demandV130.${prefix}.${stepKey}.sitelinkRows[${index}].t3col2`, url: row.t3col2 });
      }
    }
  }
  for (const [index, item] of (workspace.gate4?.implementations || []).entries()) {
    if (item.pageRefV1 || !String(item.landing || "").trim()) continue;
    const ref = megaPlatformPageRefForUrl(item.landing, workspace);
    if (ref) item.pageRefV1 = ref;
    else unresolvedReferences.push({ source: `gate4.implementations[${index}].landing`, url: item.landing });
  }
  for (const [productKey, build] of Object.entries(workspace.gate4SearchBuild || {})) {
    const collections = [
      ["sitelinkRows", build.sitelinkRows],
      ...(build.groupRows || []).map((group, index) =>
        [`groupRows[${index}].sitelinkRows`, group.sitelinkRows]),
      ["clusterDraft.sitelinkRows", build.clusterDraft?.sitelinkRows],
      ...Object.entries(build.jtbdDraftsV388 || {}).map(([key, draft]) =>
        [`jtbdDraftsV388.${key}.sitelinkRows`, draft?.sitelinkRows]),
    ];
    for (const [path, rows] of collections) {
      for (const [index, row] of (Array.isArray(rows) ? rows : []).entries()) {
        if (row.pageRefV1 || !String(row.sl2 || "").trim()) continue;
        const ref = megaPlatformPageRefForUrl(row.sl2, workspace);
        if (ref) row.pageRefV1 = ref;
        else unresolvedReferences.push({
          source: `gate4SearchBuild.${productKey}.${path}[${index}].sl2`, url: row.sl2,
        });
      }
    }
  }
  store.unresolvedReferences = unresolvedReferences;
  store.migratedAt = store.migratedAt || new Date().toISOString();
}

function megaPlatformAuditRow(name, sourceCardId, rows) {
  return {
    name,
    urls: rows.map((row) => String(row.url || "").trim()).filter(Boolean),
    sourceFound: Boolean(rows.length),
    sourceCardId,
    sourceText: rows.length > 1 ? "Карточки аудита" : "Карточка аудита",
  };
}

function megaPlatformAutoRows(workspace = state) {
  const cards = workspace?.gates?.find((gate) => gate.id === "gate-1")?.cards || [];
  const card = (id) => cards.find((item) => item.id === id);
  const row = (id, name) => ({
    ...megaPlatformAuditRow(name, id, card(id)?.pageRows || []),
    urlGroup: "fixed", urlId: MEGA_PLATFORM_FIXED_URLS[id],
    sourceFound: Boolean(card(id)),
  });
  const categoryAuditRows = card("card-22")?.pageRows || [];
  const missingCategoryIds = megaPlatformUrlStore(workspace)?.missingCategoryIds || [];
  const missingGeneratedIds = megaPlatformUrlStore(workspace)?.missingCategoryGeneratedIds || [];
  const categories = guruV185Registry(workspace).map((category) => {
    const audit = categoryAuditRows.find((item) => String(item.categoryId || "") === String(category.id));
    return {
      name: category.name,
      urlGroup: "categories", urlId: !category.manualOriginV2 &&
        (missingCategoryIds.includes(category.name) ||
          missingGeneratedIds.includes(category.id)) ? "" : category.id,
      urls: audit?.url?.trim() ? [audit.url.trim()] : [],
      sourceFound: Boolean(audit),
      sourceCategoryId: category.id,
      sourceText: "Что продаём · категория",
    };
  });
  const productAuditRows = [
    ...(card("card-24")?.pageRows || []),
    ...(card("card-23")?.pageRows || []),
  ];
  const productPages = guruV189CatalogItems(workspace).map((product) => {
    const audit = productAuditRows.find((item) =>
      String(item.catalogItemIdV189 || "") === String(product.id));
    return {
      name: product.name,
      urlGroup: "products", urlId: product.id,
      urls: audit?.url?.trim() ? [audit.url.trim()] : [],
      sourceFound: Boolean(audit),
      sourceCategoryId: megaPlatformProductCategoryId(product, workspace) || "__uncategorized__",
      sourceProductId: product.id,
      sourceText: "Что продаём · позиция",
      manualOriginV2: product.manualOriginV2 || "",
    };
  });
  const auditExtraRows = ["card-25", "card-32"].flatMap((cardId) =>
    (card(cardId)?.pageRows || []).flatMap((audit, index) => {
      if (cardId === "card-25" && index === 0 || !audit.id) return [];
      return [{ name: audit.name || (cardId === "card-32" ? "Лендинг" : "Статья блога"),
        urlGroup: "custom", urlId: `audit:${audit.id}`, sourceCardId: cardId,
        sourceText: "Карточка аудита", sourceFound: true }];
    }));
  return {
    required: [row("card-21", "Главная страница"), row("card-22-hub", "Каталог (Хаб)"),
      ...categories, ...productPages, row("card-27", "Контакты"), row("card-28", "Доставка и оплата")],
    conversion: [row("card-26", "О нас / история бренда"), row("card-25", "Блог")],
    supplemental: [row("card-30", "Страница 404"), row("card-31", "Страница «Спасибо»"),
      ...auditExtraRows],
  };
}

