  const draft = megaPlatformProductPickerDraft;
  if (!pick || !draft || draft.categoryId !== pick.dataset.megaPlatformPickIn) return;
  if (pick.checked) draft.selectedIds.add(pick.dataset.megaPlatformPickProduct);
  else draft.selectedIds.delete(pick.dataset.megaPlatformPickProduct);
