/* ================================================================
   v1.3.0 — Robots.txt: доступ поисковых роботов (v2 redesign)
   ================================================================ */

const ROBOTS_V2_RESULT_OPTIONS = [
  "",
  "Разрешено",
  "Запрещено",
  "Не требуется",
  "Требует внимания",
];
const ROBOTS_V2_YANDEX_INSTRUCTION =
  "Суть:\nПроверить, что Яндекс может обходить важные страницы сайта и robots.txt не содержит ошибок.\n\nИсточник URL:\nСтраницы автоматически читаются из Gate 0 → Точка отсчёта и распределяются на важные и служебные.\n\nИдеал:\n0 ошибок, важные страницы разрешены, служебные URL обработаны корректно.";

function robotsV130Gate0UrlKey(value) {
  const url = String(value || "").trim();
  if (!url) return "";
  return url.replace(/\/+$/, "").toLowerCase() || "/";
}

function robotsV130IsServicePage(name, url) {
  const rawUrl = String(url || "").trim().toLowerCase();
  let pathname = rawUrl;
  try {
    pathname = new URL(rawUrl, "https://guru.local").pathname.toLowerCase();
  } catch (_error) {}
  // Фактический публичный URL важнее неоднозначного названия строки в Gate 0.
  // Например, строка «Форма заявки / корзина» может вести на обычные Контакты.
  if (/(^|\/)(contacts?|kontakty|kontakti|контакты)(\/|$)/i.test(pathname))
    return false;
  return /служеб|корзин|cart|checkout|личн.*кабинет|login|account|политик|privacy|cookie|404|thank|спасибо|поиск|search|фильтр|filter|admin|wp-admin|успешн.*заказ/i.test(
    `${name || ""} ${url || ""}`,
  );
}

function robotsV130WorkspaceOwnsCard(workspace, card) {
  return Boolean(
    workspace?.gates?.some((gate) =>
      Array.isArray(gate?.cards) && gate.cards.includes(card),
    ),
  );
}

function robotsV130Gate0Pages(workspace = state) {
  const candidates = megaPlatformAllPages(workspace);

  const seen = new Set();
  const important = [];
  const service = [];
  candidates.forEach((candidate) => {
    const url = String(candidate.url || "").trim();
    const key = robotsV130Gate0UrlKey(url);
    if (!key || seen.has(key)) return;
    seen.add(key);
    const isService = robotsV130IsServicePage(candidate.name, url);
    (isService ? service : important).push({
      url,
      type: candidate.name,
      expect: isService ? "Закрыто от обхода или индексирования" : "Разрешено",
    });
  });
  return { important, service };
}

function robotsV130MergeResults(sourceRows, previousRows, withComment = false) {
  const previous = new Map(
    (Array.isArray(previousRows) ? previousRows : []).map((row) => [
      robotsV130Gate0UrlKey(row?.url),
      row,
    ]),
  );
  return sourceRows.map((row) => {
    const saved = previous.get(robotsV130Gate0UrlKey(row.url)) || {};
    return {
      ...row,
      result: saved.result || "",
      ...(withComment ? { comment: saved.comment || "" } : {}),
    };
  });
}

function ensureRobotsV130(card, workspace = state) {
  if (!card) return;
  card.title = "Robots.txt: доступ поисковых роботов";
  card.instruction =
    "Проверяем, что поисковые роботы видят важные страницы сайта, а служебные URL не мешают обходу и индексации.";
  const old = card.robotsUnified || {};
  card.robotsV130 = card.robotsV130 || {
    url: old.url || "",
    domain: "",
    source: "",
    yandex: {
      enabled: "yes",
      errors: "",
      sitemap: "",
      source: "",
      urlResults: [],
      serviceResults: [],
    },
    summary: {
      robotsOpen: "",
      errorsStatus: "",
      importantStatus: "",
      serviceStatus: "",
      sitemapStatus: "",
      conclusion: "",
    },
  };
  const f = card.robotsV130;
  f.yandex = f.yandex || {};
  if (!Array.isArray(f.yandex.sitemaps)) {
    const legacyStatus = {
      yes: "ok",
      no: "error",
      attention: "pending",
    }[f.yandex.sitemap] || "";
    f.yandex.sitemaps = [{ url: "", status: legacyStatus }];
  }
  if (!f.yandex.sitemaps.length)
    f.yandex.sitemaps.push({ url: "", status: "" });
  if (Object.hasOwn(f.yandex, "sitemap")) delete f.yandex.sitemap;
  if (Object.hasOwn(f.yandex, "importantOk")) delete f.yandex.importantOk;
  if (Object.hasOwn(f.yandex, "serviceOk")) delete f.yandex.serviceOk;
  if (Object.hasOwn(f, "google")) delete f.google;
  if (card.robotsUnified?.systems && Object.hasOwn(card.robotsUnified.systems, "google"))
    delete card.robotsUnified.systems.google;
  f.summary = f.summary || {};
  // prepareSystemCards может нормализовать ещё не активированный workspace.
  // В этот момент глобальный state равен null или другому проекту: не строим
  // проекцию по чужим данным и не стираем сохранённые построчные результаты.
  if (!robotsV130WorkspaceOwnsCard(workspace, card)) return f;
  if (!megaPlatformUrlStore(workspace)?.migratedAt) return f;
  if (!Object.hasOwn(f, "legacyUrlResultsV1"))
    f.legacyUrlResultsV1 = structuredClone(f.yandex.urlResults || []);
  if (!Object.hasOwn(f, "legacyServiceResultsV1"))
    f.legacyServiceResultsV1 = structuredClone(f.yandex.serviceResults || []);
  const gate0Pages = robotsV130Gate0Pages(workspace);
  const previousResults = [
    ...(Array.isArray(f.yandex.urlResults) ? f.yandex.urlResults : []),
    ...(Array.isArray(f.yandex.serviceResults) ? f.yandex.serviceResults : []),
  ];
  f.yandex.urlResults = robotsV130MergeResults(
    gate0Pages.important,
    previousResults,
  );
  f.yandex.serviceResults = robotsV130MergeResults(
    gate0Pages.service,
    previousResults,
    true,
  );
  return f;
}

function rv2Select(name, value, options, attrs = "") {
  return `<select ${attrs} class="g1-input ${value ? "is-filled" : "is-empty"}">${options
    .map((o) => {
      const v = Array.isArray(o) ? o[0] : o;
      const l = Array.isArray(o) ? o[1] : o || "—";
      return `<option value="${escapeAttr(v)}" ${value === v ? "selected" : ""}>${escapeHtml(l)}</option>`;
    })
    .join("")}</select>`;
}

function rv2Input(value, placeholder, attrs = "") {
  const filled = String(value || "").trim();
  return `<input class="g1-input ${filled ? "is-filled" : "is-empty"}" ${attrs} value="${escapeAttr(value || "")}" placeholder="${escapeAttr(placeholder)}" />`;
}

function robotsV130FieldsHtml(card) {
  const f = ensureRobotsV130(card);
  const yEnabled = f.yandex.enabled !== "no";

  const topHtml = `<div class="rv2-section">
    <label class="g1-field"><span>URL robots.txt${g0HintBtnHtml("audit_url")}</span>${rv2Input(f.url, "https://site.ru/robots.txt", 'data-rv2="url"')}</label>
    <label class="g1-field"><span>Основной домен${g0HintBtnHtml("audit_domain")}</span>${rv2Input(f.domain, "https://site.ru", 'data-rv2="domain"')}</label>
  </div>`;

  const yUrlTable = `<table class="cr-table rv2-url-table"><thead><tr><th>URL</th><th>Тип</th><th>Ожидаем</th><th>Результат</th></tr></thead>
    <tbody>${f.yandex.urlResults
      .map(
        (
          r,
          i,
        ) => `<tr><td class="cr-label">${escapeHtml(r.url)}</td><td>${escapeHtml(r.type)}</td><td>${escapeHtml(r.expect)}</td>
    <td>${rv2Select("", r.result, ROBOTS_V2_RESULT_OPTIONS, `data-rv2-sys="yandex" data-rv2-table="url" data-rv2-idx="${i}"`)}</td></tr>`,
      )
      .join("") || '<tr><td colspan="4" class="rv2-source-empty">Добавьте URL важных страниц в Gate 0 → Точка отсчёта.</td></tr>'}</tbody></table>`;

  const yServiceTable = `<table class="cr-table rv2-url-table"><thead><tr><th>URL</th><th>Тип</th><th>Ожидаем</th><th>Результат</th><th>Комментарий (необязательно)</th></tr></thead>
    <tbody>${f.yandex.serviceResults
      .map(
        (
          r,
          i,
        ) => `<tr><td class="cr-label">${escapeHtml(r.url)}</td><td>${escapeHtml(r.type)}</td><td>${escapeHtml(r.expect)}</td>
    <td>${rv2Select("", r.result, ROBOTS_V2_RESULT_OPTIONS, `data-rv2-sys="yandex" data-rv2-table="service" data-rv2-idx="${i}"`)}</td>
    <td>${rv2Input(r.comment, "—", `data-rv2-sys="yandex" data-rv2-table="service-comment" data-rv2-idx="${i}"`)}</td></tr>`,
      )
      .join("") || '<tr><td colspan="5" class="rv2-source-empty">Добавьте URL служебных страниц в Gate 0 → Точка отсчёта.</td></tr>'}</tbody></table>`;

  const ySitemapRows = f.yandex.sitemaps
    .map((row, index) => `<div class="rv2-sitemap-row" data-rv2-sitemap-row="${index}">
      <input class="g1-input ${String(row.url || "").trim() ? "is-filled" : "is-empty"}" data-rv2-sitemap-field="url" data-rv2-sitemap-idx="${index}" value="${escapeAttr(row.url || "")}" placeholder="https://site.ru/sitemap.xml" aria-label="URL Sitemap ${index + 1}" />
      ${rv2Select("", row.status || "", ["", ["ok", "OK"], ["error", "Ошибка"], ["pending", "Ожидание"]], `data-rv2-sitemap-field="status" data-rv2-sitemap-idx="${index}" aria-label="Статус Sitemap ${index + 1}"`)}
      <button type="button" class="small-btn rv2-sitemap-remove" data-rv2-sitemap-remove="${index}" aria-label="Удалить Sitemap ${index + 1}" ${f.yandex.sitemaps.length === 1 ? "disabled" : ""}>×</button>
    </div>`)
    .join("");

  const ySitemapsHtml = `<div class="g1-field rv2-sitemap-list" data-rv2-sitemap-list>
    <span>Sitemap в robots.txt</span>
    <div class="rv2-sitemap-rows">${ySitemapRows}</div>
    <button type="button" class="small-btn add-inline-btn rv2-sitemap-add" data-rv2-sitemap-add>+ Добавить Sitemap</button>
  </div>`;

  const yandexHtml = `<div class="rv2-system-card">
    <div class="rv2-system-head"><div><b>Яндекс</b> <span class="rv2-service">Яндекс Вебмастер</span></div>
      <label class="rv2-toggle"><span>Проверка:</span>${rv2Select(
        "",
        f.yandex.enabled || "yes",
        [
          ["yes", "Да"],
          ["no", "Нет"],
        ],
        'data-rv2-sys="yandex" data-rv2-field="enabled"',
      )}</label></div>
    ${
      yEnabled
        ? `<div class="rv2-system-body">
      <details class="instruction-toggle"><summary>Показать инструкцию</summary><div class="instruction-text">${escapeHtml(ROBOTS_V2_YANDEX_INSTRUCTION)}</div></details>
      <div class="rv2-fields">
        <label class="g1-field"><span>Ошибки robots.txt</span>${rv2Select("", f.yandex.errors, ["", ["0", "0 ошибок"], ["errors", "Есть ошибки"]], 'data-rv2-sys="yandex" data-rv2-field="errors"')}</label>
        ${ySitemapsHtml}
        <div class="rv2-url-heading" data-rv2-url-heading="important">Важные URL разрешены</div>
        <div class="rv2-url-title" data-rv2-url-title="important"><span>Проверка важных URL</span><button type="button" class="small-btn" data-rv2-copy-urls="important" ${f.yandex.urlResults.length ? "" : "disabled"}>Копировать все ссылки · ${f.yandex.urlResults.length}</button></div>
        ${yUrlTable}
        <div class="rv2-url-heading" data-rv2-url-heading="service">Служебные URL обработаны</div>
        <div class="rv2-url-title" data-rv2-url-title="service"><span>Проверка служебных URL</span><button type="button" class="small-btn" data-rv2-copy-urls="service" ${f.yandex.serviceResults.length ? "" : "disabled"}>Копировать все ссылки · ${f.yandex.serviceResults.length}</button></div>
        ${yServiceTable}
      </div>
    </div>`
        : '<div class="rv2-disabled">Проверка отключена</div>'
    }</div>`;

  const summaryHtml = `<div class="rv2-summary">
    <div class="rv2-summary-title">Итог проверки robots.txt</div>
    <div class="rv2-fields">
      <label class="g1-field"><span>robots.txt открыт</span>${rv2Select("", f.summary.robotsOpen, ["", ["yes", "Да"], ["no", "Нет"]], 'data-rv2-sum="robotsOpen"')}</label>
      <label class="g1-field"><span>Ошибки файла</span>${rv2Select("", f.summary.errorsStatus, ["", ["0", "0"], ["errors", "Есть ошибки"]], 'data-rv2-sum="errorsStatus"')}</label>
      <label class="g1-field"><span>Важные страницы</span>${rv2Select("", f.summary.importantStatus, ["", ["ok", "Разрешены"], ["partial", "Частично"], ["blocked", "Заблокированы"]], 'data-rv2-sum="importantStatus"')}</label>
      <label class="g1-field"><span>Служебные URL</span>${rv2Select("", f.summary.serviceStatus, ["", ["ok", "Обработаны"], ["partial", "Частично"], ["attention", "Требуют внимания"]], 'data-rv2-sum="serviceStatus"')}</label>
      <label class="g1-field"><span>Sitemap</span>${rv2Select("", f.summary.sitemapStatus, ["", ["yes", "Указан"], ["no", "Не указан"], ["attention", "Требует внимания"]], 'data-rv2-sum="sitemapStatus"')}</label>
      <label class="g1-field"><span>Финальный вывод</span>${rv2Input(f.summary.conclusion, "что исправить или можно идти дальше", 'data-rv2-sum="conclusion"')}</label>
    </div>
  </div>`;

  return `<div class="rv2-block">
    ${topHtml}
    <div class="rv2-systems" style="grid-template-columns:1fr;">${yandexHtml}</div>
  </div>`;
}

function robotsV130CardStatus(card, workspace = state) {
  const f = ensureRobotsV130(card, workspace);
  if (!String(f.url || "").trim()) return "not_started";
  const yEnabled = f.yandex.enabled !== "no";
  if (!yEnabled) return "not_required";

  function sysStatus(sys, enabled) {
    if (!enabled) return "skip";
    const sitemapRows = Array.isArray(sys.sitemaps) ? sys.sitemaps : [];
    const importantRows = Array.isArray(sys.urlResults) ? sys.urlResults : [];
    const serviceRows = Array.isArray(sys.serviceResults) ? sys.serviceResults : [];
    if (
      sys.errors === "errors" ||
      sitemapRows.some((row) => row.status === "error") ||
      importantRows.some((row) => row.result === "Запрещено") ||
      serviceRows.some((row) => row.result === "Разрешено")
    ) return "problem";
    if (
      !sys.errors ||
      !sitemapRows.length ||
      sitemapRows.some((row) => !String(row.url || "").trim() || !row.status) ||
      !importantRows.length ||
      importantRows.some((row) => !row.result) ||
      serviceRows.some((row) => !row.result)
    ) return "empty";
    if (
      sitemapRows.some((row) => row.status === "pending") ||
      importantRows.some((row) => ["Не требуется", "Требует внимания"].includes(row.result)) ||
      serviceRows.some((row) => row.result === "Требует внимания")
    )
      return "attention";
    return "done";
  }
  const ySt = sysStatus(f.yandex, yEnabled);
  if (ySt === "problem") return "problem";
  if (ySt === "empty") return "in_progress";
  if (ySt === "attention") return "needs_review";
  if (ySt === "done" || ySt === "skip") return "ready";
  return "in_progress";
}

let gate1DurableSaveFrame = null;
let gate1DurableSaveTimer = null;

function gate1ScheduleDurablePersist() {
  // Помечаем вкладку грязной сразу: beforeunload успеет сохранить данные даже
  // если пользователь обновит страницу раньше следующего кадра.
  if (typeof _guruTabDirty !== "undefined") _guruTabDirty = true;
  if (gate1DurableSaveFrame !== null || gate1DurableSaveTimer !== null)
    return;
  const persistAfterPaint = () => {
    gate1DurableSaveFrame = null;
    gate1DurableSaveTimer = setTimeout(() => {
      gate1DurableSaveTimer = null;
      guruPersistStateFast({ durable: true, quiet: true, cloud: false });
    }, 0);
  };
  if (typeof requestAnimationFrame === "function")
    gate1DurableSaveFrame = requestAnimationFrame(persistAfterPaint);
  else persistAfterPaint();
}

function robotsV130ScheduleDurablePersist() {
  gate1ScheduleDurablePersist();
}

const __g1PrevGetCardModeV130 = getGate1CardMode;
getGate1CardMode = function (card) {
  if (isRobotsUnifiedCard(card)) return "robots_v130";
  return __g1PrevGetCardModeV130(card);
};

const __g1PrevEnsureTypedV130 = ensureGate1TypedData;
ensureGate1TypedData = function (card) {
  if (isRobotsUnifiedCard(card)) {
    ensureRobotsV130(card);
    return;
  }
  return __g1PrevEnsureTypedV130(card);
};

const __g1PrevTypedFieldsV130 = gate1TypedFieldsHtml;
gate1TypedFieldsHtml = function (card) {
  if (getGate1CardMode(card) === "robots_v130")
    return robotsV130FieldsHtml(card);
  return __g1PrevTypedFieldsV130(card);
};

const __g1PrevRecalcV130 = recalculateStatusForCard;
recalculateStatusForCard = function (card, workspace = state) {
  if (isRobotsUnifiedCard(card)) {
    card.status = robotsV130CardStatus(card, workspace);
    return;
  }
  return __g1PrevRecalcV130(card, workspace);
};

function updateRobotsV2(target) {
  const card = allCardsFromWorkspace(state).find(isRobotsUnifiedCard);
  if (!card) return;
  const f = ensureRobotsV130(card);
  const sys = target.dataset.rv2Sys;
  const field = target.dataset.rv2Field;
  const table = target.dataset.rv2Table;
  const sum = target.dataset.rv2Sum;
  const sitemapField = target.dataset.rv2SitemapField;
  const idx = Number(target.dataset.rv2Idx);
  const sitemapIdx = Number(target.dataset.rv2SitemapIdx);
  if (sys && sys !== "yandex") return;
  if (sitemapField && Number.isInteger(sitemapIdx) && f.yandex.sitemaps[sitemapIdx]) {
    f.yandex.sitemaps[sitemapIdx][sitemapField] = target.value;
  } else if (target.dataset.rv2) {
    f[target.dataset.rv2] = target.value;
    if (target.dataset.rv2 === "url")
      addOrUpdateProjectLink(target.value, {
        comment: "robots.txt",
        source: "Robots.txt",
      });
  } else if (sum) {
    f.summary[sum] = target.value;
  } else if (sys && table === "url") {
    f[sys].urlResults[idx].result = target.value;
  } else if (sys && table === "service") {
    f[sys].serviceResults[idx].result = target.value;
  } else if (sys && table === "service-comment") {
    f[sys].serviceResults[idx].comment = target.value;
  } else if (sys && field) {
    f[sys][field] = target.value;
  }
  recalculateStatusForCard(card);
  // Сохранение большого workspace выполняется после ближайшей отрисовки:
  // нативный select закрывается без задержки, а beforeunload остаётся страховкой.
  robotsV130ScheduleDurablePersist();
  flashSaving();
  if (target.tagName === "SELECT" && field === "enabled") renderGate();
  else g1PointUpdateBadge(card, { nav: false });
}

document.addEventListener("input", (e) => {
  if (
    e.target?.dataset &&
    (e.target.dataset.rv2 ||
      e.target.dataset.rv2SitemapField ||
      e.target.dataset.rv2Sys ||
      e.target.dataset.rv2Sum) &&
    e.target.tagName !== "SELECT"
  )
    updateRobotsV2(e.target);
});
document.addEventListener("change", (e) => {
  if (
    e.target?.dataset &&
    (e.target.dataset.rv2 ||
      e.target.dataset.rv2SitemapField ||
      e.target.dataset.rv2Sys ||
      e.target.dataset.rv2Sum ||
      e.target.dataset.rv2Table)
  )
    updateRobotsV2(e.target);
});

async function robotsV130CopyText(text) {
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(text);
    return;
  }
  const textarea = document.createElement("textarea");
  textarea.value = text;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.opacity = "0";
  document.body.appendChild(textarea);
  textarea.select();
  const copied = document.execCommand("copy");
  textarea.remove();
  if (!copied) throw new Error("Clipboard copy failed");
}

document.addEventListener("click", async (e) => {
  const copy = e.target.closest?.("[data-rv2-copy-urls]");
  const add = e.target.closest?.("[data-rv2-sitemap-add]");
  const remove = e.target.closest?.("[data-rv2-sitemap-remove]");
  if (!copy && !add && !remove) return;
  const card = allCardsFromWorkspace(state).find(isRobotsUnifiedCard);
  if (!card) return;
  const f = ensureRobotsV130(card);
  if (copy) {
    const rows = copy.dataset.rv2CopyUrls === "service"
      ? f.yandex.serviceResults
      : f.yandex.urlResults;
    const urls = rows.map((row) => String(row?.url || "").trim()).filter(Boolean);
    if (!urls.length) return;
    const initial = copy.textContent;
    try {
      await robotsV130CopyText(urls.join("\n"));
      copy.textContent = `Скопировано · ${urls.length}`;
    } catch (_error) {
      copy.textContent = "Не удалось скопировать";
    }
    setTimeout(() => {
      if (copy.isConnected) copy.textContent = initial;
    }, 1600);
    return;
  } else if (add) {
    f.yandex.sitemaps.push({ url: "", status: "" });
  } else {
    const index = Number(remove.dataset.rv2SitemapRemove);
    if (Number.isInteger(index) && f.yandex.sitemaps.length > 1)
      f.yandex.sitemaps.splice(index, 1);
  }
  recalculateStatusForCard(card);
  flashSaving();
  renderGate();
});

/* ================================================================
   v1.3.0 — Sitemap.xml: карта важных страниц (редизайн)
   ================================================================ */

const SITEMAP_V130_STATUSES = GURU_STATUS_OPTIONS;

const SITEMAP_V130_YESNO = [
  ["", "—"],
  ["yes", "Да"],
  ["no", "Нет"],
  ["not_checked", "Не проверено"],
];
const SITEMAP_V130_LASTMOD = [
  ["", "—"],
  ["fresh", "Свежий"],
  ["stale", "Устарел"],
  ["missing", "Отсутствует"],
  ["not_required", "Не требуется"],
];
const SITEMAP_V130_TECH = [
  ["", "—"],
  ["no", "Нет"],
  ["problem", "Есть проблема"],
];

const SITEMAP_V130_INSTRUCTION = `Суть:\nSitemap содержит важные индексируемые страницы, не содержит мусор, файл валиден.\nИдеал: файл доступен, XML корректен, lastmod актуален, технических URL нет, расхождение с индексом < 20%.\n\nИнструкция:\n1. Открыть URL Sitemap → проверить: файл отдаётся 200, XML валиден, URL ведут на нужные страницы.\n2. Яндекс Вебмастер → Индексирование → Файлы Sitemap → проверить статус и сравнить «URL в Sitemap» со «Страницами в поиске».\n3. Расхождение > 20% → проверить причины (новые страницы, каноникалы, закрытые от индексации).`;

function ensureSitemapV130(card) {
  if (!card) return;
  card.title = "Sitemap.xml: карта важных страниц";
  card.instruction = SITEMAP_V130_INSTRUCTION;
  const old = card.sitemapUnified || {};
  card.sitemapV130 = card.sitemapV130 || {
    url: old.url || "",
    fileAccessible: "",
    xmlValid: "",
    urlCount: "",
    lastmod: "",
    techUrls: "",
    inRobots: "",
    yandex: {
      status: old.systems?.yandex?.enabled
        ? old.systems.yandex.status === "ok"
          ? "checked"
          : old.systems.yandex.status === "issue"
            ? "problem"
            : ""
        : "",
      webmasterStatus: "",
      pagesInSitemap: "",
      pagesInSearch: "",
      divergence: "",
      evidence: old.systems?.yandex?.evidence || "",
      comment: "",
    },
  };
  card.sitemapV130.yandex = card.sitemapV130.yandex || {
    status: "",
    webmasterStatus: "",
    pagesInSitemap: "",
    pagesInSearch: "",
    divergence: "",
    evidence: "",
    comment: "",
  };
  if (Object.hasOwn(card.sitemapV130, "google")) delete card.sitemapV130.google;
  if (card.sitemapUnified?.systems && Object.hasOwn(card.sitemapUnified.systems, "google"))
    delete card.sitemapUnified.systems.google;
  return card.sitemapV130;
}

function smV130Select(dataAttr, name, label, value, options) {
  return `<label class="g1-field"><span>${escapeHtml(label)}</span><select class="g1-input is-filled" data-sm-v130-field="${escapeAttr(name)}" ${dataAttr}>${options.map(([v, l]) => `<option value="${escapeAttr(v)}" ${value === v ? "selected" : ""}>${escapeHtml(l)}</option>`).join("")}</select></label>`;
}

function smV130Input(name, label, value, placeholder, dataAttr) {
  const filled = String(value || "").trim();
  return `<label class="g1-field"><span>${escapeHtml(label)}</span><textarea class="g1-input ${filled ? "is-filled" : "is-empty"}" data-sm-v130-field="${escapeAttr(name)}" ${dataAttr || ""} rows="1" placeholder="${escapeAttr(placeholder)}">${escapeHtml(value || "")}</textarea></label>`;
}

function smV130DivergenceHint(value) {
  const n = parseFloat(value);
  if (isNaN(n)) return "";
  if (n <= 20)
    return '<span style="color:#16a34a;font-size:11px;font-weight:700">допустимо</span>';
  if (n <= 50)
    return '<span style="color:#f59e0b;font-size:11px;font-weight:700">требует проверки</span>';
  return '<span style="color:#dc2626;font-size:11px;font-weight:700">вероятная проблема</span>';
}

function smV130SystemHtml(key, data) {
  const label = "Яндекс";
  const service = "Яндекс Вебмастер";
  const statusCanon = guruCanonStatus(data.status);
  const showFields = statusCanon === "missing" || statusCanon === "works" || statusCanon === "broken";
  const sysAttr = `data-sm-v130-system="${escapeAttr(key)}"`;
  const pill = !statusCanon
    ? '<span class="result-pill result-neutral">Не выбран</span>'
    : statusCanon === "not_needed"
      ? '<span class="result-pill result-neutral">Не требуется</span>'
      : statusCanon === "missing"
        ? '<span class="result-pill result-bad" style="background:#fff3d6;color:#8a5a00">Отсутствует</span>'
        : statusCanon === "works"
          ? '<span class="result-pill result-ok">Работает</span>'
          : '<span class="result-pill result-bad">' + escapeHtml(guruStatusLabel(data.status)) + '</span>';

  const statusSelect = `<label class="g1-field"><span>Статус</span><select class="g1-input is-filled" data-sm-v130-field="status" ${sysAttr}>${guruStatusOptionsHtml(data.status)}</select></label>`;

  if (!showFields) {
    return `<div class="g1-card" style="border-radius:16px;">
      <div class="g1-card-header-static" style="padding:16px 16px;border-bottom:none;">
        <span class="g1-card-title" style="font-size:14px;">${escapeHtml(label)} <span style="font-weight:600;color:var(--muted);font-size:12px;">${escapeHtml(service)}</span></span>
        ${pill}
      </div>
      <div style="padding:0 16px 16px;">
        <select class="g1-input ${data.status ? "is-filled" : "is-empty"}" data-sm-v130-field="status" ${sysAttr}>${guruStatusOptionsHtml(data.status)}</select>
      </div>
    </div>`;
  }

  const divHint = smV130DivergenceHint(data.divergence);
  const yandexFields = `
    ${smV130Input("webmasterStatus", "Статус в Яндекс Вебмастере", data.webmasterStatus, "обработан / ошибка / ожидание", sysAttr)}
    ${smV130Input("pagesInSitemap", "Страниц в Sitemap", data.pagesInSitemap, "число", sysAttr)}
    ${smV130Input("pagesInSearch", "Страниц в поиске", data.pagesInSearch, "число", sysAttr)}
    <label class="g1-field"><span>Расхождение, % ${divHint}</span><input class="g1-input ${String(data.divergence || "").trim() ? "is-filled" : "is-empty"}" data-sm-v130-field="divergence" ${sysAttr} value="${escapeAttr(data.divergence || "")}" placeholder="0–100" /></label>
  `;

  return `<div class="g1-card" style="border-radius:16px;">
    <div class="g1-card-header-static" style="padding:16px 16px;">
      <span class="g1-card-title" style="font-size:14px;">${escapeHtml(label)} <span style="font-weight:600;color:var(--muted);font-size:12px;">${escapeHtml(service)}</span></span>
      ${pill}
    </div>
    <div style="padding:16px 16px;display:flex;flex-direction:column;gap:12px;">
      ${statusSelect}
      ${yandexFields}
      ${smV130Input("evidence", "Доказательство", data.evidence, `ссылка на ${service}, скрин или отчёт`, sysAttr)}
      ${guruStatusIsBad(data.status) ? smV130Input("comment", "Комментарий (необязательно)", data.comment, "что именно не так", sysAttr) : ""}
    </div>
  </div>`;
}

function sitemapV130FieldsHtml(card) {
  const f = ensureSitemapV130(card);
  const urlFilled = String(f.url || "").trim();
  return `<div style="display:flex;flex-direction:column;gap:12px;">
    ${smV130Input("url", "URL Sitemap.xml", f.url, "https://site.ru/sitemap.xml", "").replace("URL Sitemap.xml</span>", "URL Sitemap.xml" + g0HintBtnHtml("audit_url") + "</span>")}
    <div class="g1-card" style="border-radius:16px;">
      <div class="g1-card-header-static" style="padding:16px 16px;">
        <span class="g1-card-title" style="font-size:14px;">Проверка файла</span>
      </div>
      <div style="padding:16px 16px;display:flex;flex-direction:column;gap:12px;">
        ${smV130Select("", "fileAccessible", "Файл доступен", f.fileAccessible, SITEMAP_V130_YESNO)}
        ${smV130Select("", "xmlValid", "XML корректный", f.xmlValid, SITEMAP_V130_YESNO)}
        ${smV130Input("urlCount", "Количество URL в файле", f.urlCount, "число", "")}
        ${smV130Select("", "lastmod", "<lastmod>", f.lastmod, SITEMAP_V130_LASTMOD)}
        ${smV130Select("", "techUrls", "Технические URL", f.techUrls, SITEMAP_V130_TECH)}
        ${smV130Select("", "inRobots", "Sitemap указан в robots.txt", f.inRobots, SITEMAP_V130_YESNO)}
      </div>
    </div>
    ${smV130SystemHtml("yandex", f.yandex)}
  </div>`;
}

function sitemapV130CardStatus(card) {
  const f = ensureSitemapV130(card);
  const url = String(f.url || "").trim();
  if (!url) return "not_started";
  const ys = guruCanonStatus(f.yandex.status);
  if (!ys) return "in_progress";
  if (ys === "not_needed" || ys === "broken") return "problem";
  if (
    f.techUrls === "problem" ||
    f.xmlValid === "no" ||
    f.fileAccessible === "no"
  )
    return "problem";
  if (f.lastmod === "stale") return "problem";
  if (ys === "works") return "ready";
  if (ys === "missing") return "in_progress";
  return "in_progress";
}

