gate1TypedFieldsHtml = function (card) {
  if (getGate1CardMode(card) === "redirect_v130")
    return redirectV130FieldsHtml(card);
  return __g1RdrPrevTypedFields(card);
};

const __g1RdrPrevRecalc = recalculateStatusForCard;
recalculateStatusForCard = function (card, workspace = state) {
  if (isServerResponseCard(card)) {
    card.status = redirectV130CardStatus(card);
    return;
  }
  return __g1RdrPrevRecalc(card, workspace);
};

function redirectV130RefreshCard(card) {
  const node = document.querySelector(`[data-card="${CSS.escape(card.id)}"]`);
  const fields = node?.querySelector(":scope > .g1-card-body > .card-fields");
  if (fields) fields.innerHTML = cardUserFieldsHtml(card);
  g1PointUpdateBadge(card, { nav: false });
  if (typeof gate1SeoGuidanceInjectV307 === "function")
    gate1SeoGuidanceInjectV307();
}

function updateRedirectV130(target, commit = false) {
  const card = allCardsFromWorkspace(state).find(isServerResponseCard);
  if (!card) return;
  const f = ensureRedirectV130(card);
  const field = target.dataset.rdrV130Field;
  const col = target.dataset.rdrV130Col;
  const idx = target.dataset.rdrV130Index;
  if (field) {
    f[field] = target.value;
    if (field === "domain") {
      const domain = redirectV130NormalizeDomain(f.domain);
      if (commit) f.domain = domain;
      f.rows = redirectV130BuildRows(domain, f.rows);
    }
  } else if (col && idx !== undefined) {
    const row = f.rows[Number(idx)];
    if (row && ["code", "result"].includes(col)) row[col] = target.value;
  }
  recalculateStatusForCard(card);
  gate1ScheduleDurablePersist();
  flashSaving();
  if (commit) redirectV130RefreshCard(card);
  else g1PointUpdateBadge(card, { nav: false });
}

document.addEventListener("input", (e) => {
  if (
    (e.target?.dataset?.rdrV130Field || e.target?.dataset?.rdrV130Col) &&
    e.target.tagName !== "SELECT"
  )
    updateRedirectV130(e.target, false);
});
document.addEventListener("change", (e) => {
  if (e.target?.dataset?.rdrV130Field || e.target?.dataset?.rdrV130Col)
    updateRedirectV130(e.target, true);
});

/* v1.3.0 — скрыть блок «Изображения SEO META in 1 CLICK» */
