/* v1.3.0 — убрать дубликат "Финальный CTA" */
const __g1PrevRouteSections = v22RouteSectionsHtml;
v22RouteSectionsHtml = function (card, row, pageIndex) {
  const template = v22TemplateForCard(card);
  const sections = [...(template.sections || [])];
  const isCategoryPage = card?.id === "card-22" || card?.id === "card-22-hub";
  const hasCta = sections.some(
    (s) => /final.?cta/i.test(s.key) || /Финальный CTA/i.test(s.title),
  );
  const statuses = sections.map((section) => v22SectionStatus(row, section));
  let firstOpen = statuses.findIndex((status) => status !== "ready");
  const html = sections
    .map((section, index) =>
      v22RouteSectionHtml(
        card,
        row,
        pageIndex,
        section,
        !isCategoryPage && index === firstOpen,
      ),
    )
    .join("");
  const seoOpen =
    !isCategoryPage &&
    firstOpen === -1 &&
    (!v22IsFilled(row.title) || !v22IsFilled(row.description));
  const ctaOpen =
    !hasCta &&
    firstOpen === -1 &&
    row.ctaMode !== "not_needed" &&
    !v22IsFilled(row.finalCta) &&
    !seoOpen;
  return (
    html +
    v22SeoSnippetSection(card, row, pageIndex, seoOpen) +
    v22TechnicalControlHtml(card, row, pageIndex)
  );
};

