const FOOTER_V130_STATUS3 = [
  ["", "—"],
  ["yes", "Есть"],
  ["no", "Нет"],
  ["not_required", "Не требуется"],
];
const FOOTER_V130_YESNO = [
  ["", "—"],
  ["yes", "Да"],
  ["no", "Нет"],
];
