const G2_CHECK_OPTIONS = GURU_STATUS_OPTIONS;

function ensureGate2Structure(gate) {
  if (!gate || gate.id !== "gate-2") return;
  if (gate.title === "2. Инструментирование - ДО трафика")
    gate.title = "2. Готовность к трафику";
  gate.cards.forEach((c) => {
    const stripped = String(c.title || "").replace(/^tilda\s*\/\s*сайт,\s*/i, "");
    if (stripped !== c.title) {
      c.title = stripped.charAt(0).toUpperCase() + stripped.slice(1);
    }
  });
  const existingIds = new Set(gate.cards.map((c) => c.id));
  G2_NEW_CARDS.forEach((nc) => {
    if (!existingIds.has(nc.id)) {
      gate.cards.push({
        id: nc.id,
        title: nc.title,
        instruction: nc.instruction,
        status: "not_started",
        evidence: "",
        pages: "",
        notes: "",
        fields: {},
      });
    }
  });
}

function getGate2AccordionState() {
  ensureUiState(state);
  if (!state.ui.gate2Accordion)
    state.ui.gate2Accordion = { sections: {}, cards: {} };
  return state.ui.gate2Accordion;
}

function g2SectionKeyForCardV271(card) {
  const newCardDef = G2_NEW_CARDS.find((item) => item.id === card?.id);
  if (newCardDef?.section) return newCardDef.section;
  const title = String(card?.title || "");
  const section = G2_SECTIONS.find((item) => {
    item.match.lastIndex = 0;
    return item.match.test(title);
  });
  return section?.key || "other";
}

function g2GetSections(gate, visibleIds) {
  ensureGate2Structure(gate);
  const isHeader = (c) => /^\s*\d+\.\s+/.test(c.title || "");
  const contentCards = gate.cards.filter(
    (c) => !isHeader(c) && visibleIds.has(c.id),
  );
  const sections = G2_SECTIONS.map((def) => ({ ...def, cards: [] }));
  const other = {
    key: "other",
    title: "Прочее",
    cards: [],
  };
  contentCards.forEach((card) => {
    const sectionKey = g2SectionKeyForCardV271(card);
    const sec = sections.find((item) => item.key === sectionKey);
    if (sec) sec.cards.push(card);
    else other.cards.push(card);
  });
  if (other.cards.length) sections.push(other);
  return sections.filter((s) => s.cards.length);
}

function g2ParseOrient(instruction) {
  if (!instruction) return "";
  const m = instruction.match(/Суть:\s*\n?(.*?)(?:\n\n|\nОтвечает|$)/s);
  return m ? m[1].trim() : "";
}

function g2ParseStandard(instruction) {
  if (!instruction) return "";
  const m = instruction.match(/Инструкция:\s*\n?(.*?)$/s);
  return m ? m[1].trim() : "";
}

function g2EnsureFields(card) {
  if (!card.fields) card.fields = {};
  if (card.fields.g2Check === undefined) card.fields.g2Check = "";
  if (card.fields.g2Source === undefined)
    card.fields.g2Source = card.evidence || "";
  return card.fields;
}

function g2CardStatus(card) {
  const f = g2EnsureFields(card);
  const check = f.g2Check || "";
  if (guruStatusIsOk(check)) return "ready";
  if (guruStatusIsBad(check)) return "problem";
  if (check) return "in_progress";
  return "not_started";
}

function g2SectionStatus(cards) {
  if (!cards.length) return "not_started";
  const statuses = cards.map(g2CardStatus);
  if (statuses.every((s) => s === "ready")) return "ready";
  if (statuses.some((s) => s === "problem")) return "problem";
  if (statuses.some((s) => s !== "not_started")) return "in_progress";
  return "not_started";
}

function g2SectionProgress(cards) {
  const ready = cards.filter((c) => g2CardStatus(c) === "ready").length;
  return `${ready} из ${cards.length} готово`;
}

function g2Gate0PlatformV2() {
  const gate0 = state?.gates?.find((g) => g.id === "gate-0");
  const card = gate0?.cards?.find(isMegaMarketingCard);
  if (card) ensureMegaMarketing(card, state);
  return card?.megaMarketing?.platformV2 || { landings: {} };
}

function g2ProductContextRows() {
  const products = pv130ProductsFromGate0();
  const maps = pv140EnsureProductMaps();
  const units = ensureUnitV130().items || [];
  const offers = v121EnsureOffers(state);
  const pv2 = g2Gate0PlatformV2();

  return products.map((product) => {
    const map = maps.find((row) => String(row.product || "").trim() === product) || {};
    const unit = units.find(
      (item) =>
        String(item.productKey || item.name || "").trim() === product,
    ) || {};
    const productOffer = offers.productOffers?.[product] || {};
    const landing = pv2.landings?.[product] || {};
    return {
      product,
      offer: map.finalOffer || map.initialOffer || productOffer.offer || "",
      segment: map.demandSegments || state.project?.targetSegment || "",
      jtbd: map.jtbd || "",
      queries: map.keywords || map.mainQueries || "",
      cta: productOffer.cta || state.project?.primaryTargetAction || "",
      cpa: unit.steps?.adLimits?.allowedCpa || "",
      cpl: unit.steps?.adLimits?.allowedCpl || "",
      landingUrl: megaPlatformProductUrl(product, state),
      landingStatus: landing.status || "",
    };
  });
}

function g2ShortValue(value) {
  const text = String(value || "").trim();
  return text ? escapeHtml(text) : '<span class="g2-muted">—</span>';
}

function g2LaunchContextHtml() {
  const rows = g2ProductContextRows();
  if (!rows.length) return "";
  return `<section class="g1-section g2-launch-context">
    <div class="g1-section-header g2-open-header">
      <span class="g1-section-left">
        <span class="g1-section-title">Контекст запуска из Gate 0 / 1</span>
        <span class="g1-section-progress">${rows.length} продуктов</span>
      </span>
    </div>
    <div class="g2-product-context-list">
      ${rows
        .map(
          (row, index) => `<article class="g2-product-context-row">
        <div class="g2-product-main">
          <span class="g2-product-index">Продукт ${index + 1}</span>
          <strong>${escapeHtml(row.product)}</strong>
        </div>
        <div class="g2-context-cell"><span>Оффер</span><b>${g2ShortValue(row.offer)}</b></div>
        <div class="g2-context-cell"><span>Сегмент / JTBD</span><b>${g2ShortValue(row.jtbd || row.segment)}</b></div>
        <div class="g2-context-cell"><span>Запросы</span><b>${g2ShortValue(row.queries)}</b></div>
        <div class="g2-context-cell"><span>CTA</span><b>${g2ShortValue(row.cta)}</b></div>
        <div class="g2-context-cell"><span>CPA / CPL</span><b>${g2ShortValue([row.cpa && "CPA " + row.cpa, row.cpl && "CPL " + row.cpl].filter(Boolean).join(" / "))}</b></div>
        <div class="g2-context-cell"><span>Посадочная</span><b>${g2ShortValue(row.landingUrl || row.landingStatus)}</b></div>
      </article>`,
        )
        .join("")}
    </div>
  </section>`;
}

function g2CardHtml(card) {
  const status = g2CardStatus(card);

  return `<article class="g2-check-row" data-card="${escapeAttr(card.id)}">
    <div class="g2-check-title">
      <span>${escapeHtml(card.title)}</span>
      <span class="status-pill status-${status}">${escapeHtml(STATUS_LABELS[status] || status)}</span>
    </div>
  </article>`;
}

function renderGate2Redesign(gate, cards) {
  ensureGate2Structure(gate);
  const sections = g2GetSections(gate, new Set(cards.map((c) => c.id)));

  els.contentArea.innerHTML = `<div class="g1-redesign">
    ${sections
      .map((section) => {
        const innerCards = section.cards;
        const status = g2SectionStatus(innerCards);
        const progressText = g2SectionProgress(innerCards);
        return `<section class="g1-section is-open g2-open-section">
        <div class="g1-section-header g2-open-header">
          <span class="g1-section-left">
            <span class="g1-section-title">${escapeHtml(section.title)}</span>
            <span class="g1-section-progress">${escapeHtml(progressText)}</span>
          </span>
          <span class="status-pill status-${status}">${escapeHtml(STATUS_LABELS[status] || status)}</span>
        </div>
        <div class="g1-section-body g2-section-body">
          ${innerCards.length ? innerCards.map((card) => g2CardHtml(card)).join("") : '<div class="g1-empty">Нет блоков в этой секции.</div>'}
        </div>
      </section>`;
      })
      .join("")}
  </div>`;

  bindGate2Events();
  bindCardInputs();
  renderGateNav();
}

function bindGate2Events() {
  document.querySelectorAll("[data-g2-toggle-section]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const acc = getGate2AccordionState();
      const key = btn.dataset.g2ToggleSection;
      const section = btn.closest(".g2-open-section");
      const body = section?.querySelector(":scope > .g2-section-body");
      if (!section || !body || !key) return;
      const open = btn.getAttribute("aria-expanded") !== "true";
      acc.sections[key] = open;
      section.classList.toggle("is-open", open);
      btn.setAttribute("aria-expanded", String(open));
      body.hidden = !open;
      guruScheduleUiPreferenceSave();
    });
  });
  document.querySelectorAll("[data-g2-toggle-card]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const acc = getGate2AccordionState();
      const cardId = btn.dataset.g2ToggleCard;
      acc.cards[cardId] = !acc.cards[cardId];
      saveState();
      renderGate();
    });
  });
}

function g2PointUpdateBadge(card) {
  if (!card) return;
  const status = g2CardStatus(card);
  const cardEl = document.querySelector(`[data-card="${CSS.escape(card.id)}"]`);
  const pill = cardEl?.querySelector(".status-pill");
  if (pill) {
    pill.className = `status-pill status-${status}`;
    pill.textContent = STATUS_LABELS[status] || status;
  }
  const sectionEl = cardEl?.closest(".g1-section");
  if (sectionEl) {
    const sectionCards = Array.from(sectionEl.querySelectorAll("[data-card]"))
      .map((el) => findCard(el.dataset.card))
      .filter(Boolean);
    const sStatus = g2SectionStatus(sectionCards);
    const sPill = sectionEl.querySelector(".g1-section-header .status-pill");
    if (sPill) {
      sPill.className = `status-pill status-${sStatus}`;
      sPill.textContent = STATUS_LABELS[sStatus] || sStatus;
    }
    const sProgress = sectionEl.querySelector(".g1-section-progress");
    if (sProgress) sProgress.textContent = g2SectionProgress(sectionCards);
  }
  renderGateNav();
}

function updateGate2Field(target) {
  const cardId = target.dataset.g2CardId;
  const field = target.dataset.g2Field;
  if (!cardId || !field) return;
  const card = findCard(cardId);
  if (!card) return;
  const f = g2EnsureFields(card);
  if (field === "notes") card.notes = target.value;
  else if (field === "source") f.g2Source = target.value;
  else if (field === "check") f.g2Check = target.value;
  else if (field === "extra") {
    if (!Array.isArray(f.g2ExtraNotes)) f.g2ExtraNotes = [];
    f.g2ExtraNotes[Number(target.dataset.g2Extra) || 0] = target.value;
  }
  if (target.tagName !== "SELECT" && (field === "notes" || field === "extra")) {
    target.classList.remove("is-filled", "is-empty");
    target.classList.add("is-optional");
  } else if (target.tagName !== "SELECT") {
    const cls = String(target.value || "").trim() ? "is-filled" : "is-empty";
    target.classList.remove("is-filled", "is-empty", "is-optional");
    target.classList.add(cls);
  }
  recalculateStatusForCard(card);
  flashSaving();
  if (target.tagName === "SELECT") renderGate();
  else g2PointUpdateBadge(card);
}

document.addEventListener("input", (e) => {
  if (e.target?.dataset?.g2CardId && e.target.tagName !== "SELECT")
    updateGate2Field(e.target);
});
document.addEventListener("change", (e) => {
  if (e.target?.dataset?.g2CardId) updateGate2Field(e.target);
});

const __guruPrevRenderGateTableV140 = renderGateTable;
renderGateTable = function (gate, cards) {
  if (gate?.id === "gate-2") {
    renderGate2Redesign(gate, cards);
    return;
  }
  if (gate?.id === "gate-3") {
    renderGate3Redesign(gate, cards);
    return;
  }
  __guruPrevRenderGateTableV140(gate, cards);
};

