function readGate0Value(key) {
  if (!state) return "";
  const p = state.project || {};
  const se = state.sharedEvidence || {};
  const map = {
    product: () => guruV185CategoryNames(state)[0] || "",
    audience: () => p.targetSegment || se["кому_продаем"] || "",
    client_result: () => p.clientResult || se["ради_какого_результата"] || "",
    geo: () => p.geography || "",
    project_name: () => p.name || "",
    website: () => megaPlatformUrl("fixed", "home", state),
    niche: () => p.niche || "",
    rational_coverage: () =>
      p.offerRationalCoverage || se["offer_rational_coverage"] || "",
    irrational_driver: () =>
      p.offerIrrationalDriver || se["offer_irrational_driver"] || "",
    social_mechanism: () =>
      p.offerSocialMechanism || se["offer_social_mechanism"] || "",
    positioning: () =>
      p.positioningStatement || se["positioning_statement"] || "",
    usp: () => p.usp || se["positioning_usp"] || "",
    main_keywords: () =>
      p.searchMainKeywords || se["search_main_keywords"] || "",
    priority_clusters: () =>
      p.searchPriorityClusters || se["search_priority_clusters"] || "",
    brand_queries: () =>
      p.searchBrandQueries || se["search_brand_queries"] || "",
    irrelevant_queries: () =>
      p.searchIrrelevantQueries || se["search_irrelevant_queries"] || "",
    current_offers: () => p.currentOffers || se["current_offers"] || "",
    current_ctas: () => p.currentCtas || se["current_ctas"] || "",
    primary_target_action: () =>
      p.primaryTargetAction || se["primary_target_action"] || "",
    services_list: () => guruV185CategoryNames(state).join("\n"),
  };
  return (map[key] ? map[key]() : "").trim();
}

