/* v1.3.0 — autosize для ВСЕХ textarea на странице */
function guruAutosizeNewTextareas(root) {
  if (!root || (root.nodeType !== 1 && root.nodeType !== 11)) return;
  const textareas = root.matches?.("textarea")
    ? [root]
    : root.querySelectorAll?.("textarea:not([data-autosized])") || [];
  textareas.forEach((ta) => {
    if (ta.dataset.autosized) return;
    ta.dataset.autosized = "1";
    ta.rows = 1;
    ta.style.height = "auto";
    ta.style.height = ta.scrollHeight + "px";
  });
}

document.addEventListener("input", (e) => {
  if (e.target.tagName === "TEXTAREA") {
    e.target.style.height = "auto";
    e.target.style.height = e.target.scrollHeight + "px";
  }
});
const guruTextareaRoot = document.getElementById("contentArea") || document.body;
guruAutosizeNewTextareas(guruTextareaRoot);
new MutationObserver((mutations) => {
  mutations.forEach((mutation) => {
    mutation.addedNodes.forEach(guruAutosizeNewTextareas);
  });
}).observe(guruTextareaRoot, {
  childList: true,
  subtree: true,
});

