function resolveContextG0Hint(key) {
  if (CONTEXT_FIELD_G0_HINTS[key]) return CONTEXT_FIELD_G0_HINTS[key];
  if (
    key.endsWith("_button") ||
    key.endsWith("Button") ||
    key.endsWith("Cta") ||
    key.endsWith("_cta")
  )
    return "page_cta";
  if (key.endsWith("_alt") && key.includes("cta")) return "page_cta";
  return null;
}

