/* v1.3.0 — toggle collapse for card subblocks (persisted in state) */
function g1CollapseKey(header) {
  if (header?.dataset?.g1CollapseKey) return header.dataset.g1CollapseKey;
  const spans = header.querySelectorAll("span");
  return Array.from(spans)
    .map((s) => s.textContent.trim())
    .join("|")
    .substring(0, 100);
}
function g1CollapsedSet() {
  if (!state) return new Set();
  state.g1Collapsed = state.g1Collapsed || [];
  return new Set(state.g1Collapsed);
}
function g1SaveCollapsed(set) {
  if (!state) return;
  state.g1Collapsed = [...set];
  guruScheduleUiPreferenceSave();
}
document.addEventListener("click", (e) => {
  const header = e.target.closest("[data-g1-collapse]");
  if (!header) return;
  if (e.target.closest("button, select, input, textarea, a, .danger-mini")) return;
  const card = header.closest(".g1-card-collapsible");
  if (!card) return;
  const key = g1CollapseKey(header);
  const set = g1CollapsedSet();
  const opening = card.classList.contains("is-collapsed");
  card.classList.toggle("is-collapsed", !opening);
  if (opening) set.delete(key);
  else set.add(key);
  state.ui = state.ui || {};
  state.ui.g1DisclosureOpenV512 = state.ui.g1DisclosureOpenV512 || {};
  state.ui.g1DisclosureOpenV512[guruDisclosureKeyV512(card)] = opening;
  g1SaveCollapsed(set);
});

