/* ================================================================
   v1.5.0 — Миграция: перенос производственного блока из Gate 1 в Gate 4
   Gate 1 = понять спрос. Gate 4 = создать рекламную сущность.
   ================================================================ */

// 1. Миграция данных: скопировать groups step из demandV130 в gate4Production
function migrateGate1ToGate4() {
  if (!state) return;
  if (state._gate4Migrated) return;
  const d = state.demandV130?.search?.steps?.groups;
  if (!d) {
    state._gate4Migrated = true;
    return;
  }
  state.gate4Production = state.gate4Production || {};
  state.gate4Production.semanticCore =
    state.gate4Production.semanticCore || d.semanticCore || "";
  state.gate4Production.groupRows = state.gate4Production.groupRows ||
    d.groupRows || [{}];
  state.gate4Production.adsRows =
    state.gate4Production.adsRows || d.adsRows || {};
  state.gate4Production.sitelinkRows = state.gate4Production.sitelinkRows ||
    d.sitelinkRows || [{}];
  state.gate4Production.openSteps = state.gate4Production.openSteps || {};
  state._gate4Migrated = true;
  saveState();
}

// 2. Убрать блок "groups" из DEMAND_V130_SEARCH_STEPS
const __g1SearchStepsOriginal = DEMAND_V130_SEARCH_STEPS;
while (DEMAND_V130_SEARCH_STEPS.length > 0) DEMAND_V130_SEARCH_STEPS.pop();
__g1SearchStepsOriginal
  .filter((s) => s.key !== "groups")
  .forEach((s) => DEMAND_V130_SEARCH_STEPS.push(s));

// 3. Gate 4 рендер производственного блока
function ensureGate4Production() {
  if (!state) return {};
  migrateGate1ToGate4();
  state.gate4Production = state.gate4Production || {
    semanticCore: "",
    groupRows: [{}],
    adsRows: {},
    sitelinkRows: [{}],
    openSteps: {},
  };
  state.gate4Production.openSteps = state.gate4Production.openSteps || {};
  return state.gate4Production;
}

function g4NumFormat(value, suffix = "") {
  const n = Number(value || 0);
  if (!n) return "—";
  return Math.round(n).toLocaleString("ru") + suffix;
}

function g4FactMetric(value) {
  const text = String(value || "").trim();
  if (!text || text === "0") return "—";
  return escapeHtml(text);
}

function g4SearchCampaignPlanFromGate1() {
  const d = state.demandV130?.search || {};
  const rows = d.steps?.clusters?.clusterRows || [];
  let impressions = 0;
  let clicks = 0;
  let budget = 0;
  rows.forEach((row) => {
    impressions += dv130ParseNum(row.col3);
    clicks += dv130ParseNum(row.col4);
    budget += dv130ParseNum(row.col5);
  });
  const platformLabel =
    (DEMAND_V130_PLATFORMS_SEARCH.find(([value]) => value === d.platform) || [])[1] ||
    "";
  return {
    platform: platformLabel,
    clusters: rows.filter((row) =>
      Object.values(row || {}).some((value) => String(value || "").trim()),
    ).length,
    impressions,
    clicks,
    budget,
  };
}

function g4CurrentSearchMetricsFromGate1() {
  const card = allCardsFromWorkspace(state).find((item) => item?.title === "Текущие результаты");
  if (!card) return null;
  const rows = ensureCurrentResults(card);
  const byKey = new Map(rows.map((row) => [row.key, row]));
  const read = (key) => byKey.get(key)?.value || "";
  return {
    period: card.currentResultsMeta?.period || "",
    traffic: read("traffic"),
    impressions: read("impressions"),
    clicks: read("clicks"),
    leads: read("leads"),
    cost: read("cost"),
  };
}

