const G4SB_V398_EMPTY_STRATEGIC = "[не заполнено в Стратегической основе]";

function g4sbV398AdPromptPhraseList(productId, draft, includeZeroDemand = false) {
  const selected = new Set((draft.keywordRows || []).map((row) =>
    g4sbV128PhraseKey(row.kw)));
  const deleted = new Set((ensureGate4SearchBuild(productId).deletedBankPhrases || [])
    .map(g4sbV128PhraseKey));
  const seen = new Set();
  return g4sbV128SourcePhraseRows(productId, draft).flatMap((row) => {
    const key = g4sbV128PhraseKey(row.kw);
    if (!key || !selected.has(key) || deleted.has(key) || seen.has(key) ||
        (!includeZeroDemand && g4sbV392PhraseCost(row, null).status === "zero")) return [];
    seen.add(key);
    return [String(row.kw).trim()];
  });
}

function g4sbV398StrategicPromptFields(productId) {
  const product = g4sbV385ProductSource(productId).product;
  const fields = product ? guruStrategicFoundationModelV286(product).fields : {};
  const offerParts = [
    ["Оффер", fields.offer?.value],
    ["УТП", fields.usp?.value],
  ].filter(([, value]) => String(value || "").trim());
  const offer = offerParts.length
    ? offerParts.map(([label, value]) => `${label}: ${String(value).trim()}`).join("; ")
    : G4SB_V398_EMPTY_STRATEGIC;
  const positioning = String(fields.positioning?.value || "").trim() ||
    G4SB_V398_EMPTY_STRATEGIC;
  const landing = String(fields.landing?.value || "").trim() ||
    G4SB_V398_EMPTY_STRATEGIC;
  return { offer, positioning, landing };
}

function g4sbV398AdPrompt(productId, draft, jtbd) {
  const { offer, positioning, landing } = g4sbV398StrategicPromptFields(productId);
  const phrases = g4sbV398AdPromptPhraseList(productId, draft);
  return `Ты пишешь контент для ОДНОЙ группы комбинаторного объявления Яндекс.Директ (Поиск).

JTBD: ${String(jtbd || "").trim() || "[JTBD не выбран]"}
Ключевые фразы группы (формулировки заголовка бери максимально близко к ним - совпадающее слово Директ подсвечивает жирным, это поднимает CTR):${phrases.length ? `\n${phrases.map((phrase) => `- ${phrase}`).join("\n")}` : " [фразы группы не выбраны]"}
Оффер/УТП: ${offer}
Позиционирование: ${positioning}
Посадочная страница: ${landing}

Создай до 3 отдельных комбинаторных объявлений. Каждое объявление - связанная пара из одного заголовка и одного текста. Не перемешивай значения между объявлениями:

1. Объявление 1: заголовок 1 + текст 1.
2. Объявление 2: заголовок 2 + текст 2.
3. Объявление 3: заголовок 3 + текст 3.

Жёсткие ограничения по символам (считая пробелы и знаки препинания):

- Каждый заголовок: ≤56 символов, содержит ключевую фразу группы или её близкий вариант
- Каждый текст: ≤81 символ, оффер + призыв к действию

Правила:

- Без ЗАГЛАВНЫХ БУКВ и лишних восклицательных знаков - модерация Директа это режет
- Без слов, конфликтующих с позиционированием (например "дёшево/недорого" при премиум-сегменте)
- Не выдумывай цифры, сроки или гарантии, которых нет в оффере

Формат вывода, без пояснений сверху:
Объявление 1
Заголовок: ...
Текст: ...

Объявление 2
Заголовок: ...
Текст: ...

Объявление 3
Заголовок: ...
Текст: ...`;
}

