function updateProjectComparisonInput(target) {
  const model = ensureProjectComparison();
  if (!model) return false;
  if (target.dataset.projectComparisonCompetitor) {
    const competitor = model.competitors.find((item) => item.id === target.dataset.projectComparisonCompetitor);
    const field = target.dataset.projectComparisonCompetitorField;
    if (competitor && field === "name") competitor[field] = target.value;
    else return false;
  } else if (target.dataset.projectComparisonCriterion) {
    const criterion = model.criteria.find((item) => item.id === target.dataset.projectComparisonCriterion);
    if (!criterion || projectComparisonCoreDefinition(criterion)) return false;
    criterion.name = target.value;
  } else if (target.dataset.projectComparisonCell) {
    const criterion = model.criteria.find((item) => item.id === target.dataset.projectComparisonCell);
    const ownerId = target.dataset.projectComparisonOwner;
    const field = target.dataset.projectComparisonField;
    const criterionKey = criterion?.coreKey || projectComparisonCoreDefinition(criterion)?.key || "";
    const ownCompanyPrice =
      ownerId === PROJECT_COMPARISON_OWN_ID && criterionKey === "price";
    if (
      !criterion ||
      !ownerId ||
      (ownerId === PROJECT_COMPARISON_OWN_ID && !ownCompanyPrice) ||
      field !== "text"
    )
      return false;
    criterion.cells[ownerId] = projectComparisonCell(criterion, ownerId);
    criterion.cells[ownerId][field] = target.value;
  } else if (target.dataset.projectComparisonSummary) {
    const summaryKey = target.dataset.projectComparisonSummary;
    if (summaryKey === "differentiate" || !(summaryKey in model.summary))
      return false;
    model.summary[summaryKey] = target.value;
  } else return false;
  flashSaving();
  return true;
}

document.addEventListener("input", (event) => updateProjectComparisonInput(event.target));
document.addEventListener("change", (event) => updateProjectComparisonInput(event.target));

function updateProjectComparisonProductInput(target) {
  const productId = String(target?.dataset?.projectComparisonProductId || "").trim();
  if (!productId) return false;
  const entry = ensureProjectComparisonProduct(productId);
  if (!entry) return false;
  if (target.dataset.projectComparisonProductCompetitor) {
    const competitor = entry.competitors.find(
      (item) => item.id === target.dataset.projectComparisonProductCompetitor,
    );
    if (!competitor) return false;
    competitor.name = target.value;
  } else if (target.dataset.projectComparisonProductCell) {
    const criterion = entry.criteria.find(
      (item) => item.id === target.dataset.projectComparisonProductCell,
    );
    const ownerId = target.dataset.projectComparisonProductOwner;
    if (!criterion || !ownerId || ownerId === PROJECT_COMPARISON_OWN_ID)
      return false;
    criterion.cells[ownerId] = projectComparisonCell(criterion, ownerId);
    criterion.cells[ownerId].text = target.value;
  } else return false;
  flashSaving();
  projectComparisonRefreshProductStatusUi(productId);
  return true;
}

