/* ================================================================
   v2.3.219 — возврат группы в редактирование без полной перерисовки Gate 4.

   Редактор и зависимая сводка находятся внутри .g4-v166-coverage, поэтому
   пересобираем только этот фрагмент. Это сохраняет остальной DOM страницы,
   убирает длинную блокировку главного потока и не сдвигает viewport.
   ================================================================ */
function g4sbV448ReturnEditAnchor(product, jtbdId, button) {
  const card = button?.closest?.(".g4-v166-jtbd[data-g4sb-jtbd-id]");
  return {
    product,
    jtbdId,
    viewportTop: card?.getBoundingClientRect().top ?? null,
    scroller: guruStableScrollContainer(button),
  };
}

function g4sbV448RestoreReturnEditAnchor(anchor) {
  if (!anchor || anchor.viewportTop === null) return;
  const card = g4sbV418JtbdCard(anchor.product, anchor.jtbdId);
  if (!card) return;
  const delta = card.getBoundingClientRect().top - anchor.viewportTop;
  if (Math.abs(delta) < 0.5) return;
  const scroller = anchor.scroller;
  if (
    scroller === document.scrollingElement ||
    scroller === document.documentElement ||
    scroller === document.body
  ) {
    window.scrollBy({ top: delta, left: 0, behavior: "auto" });
  } else if (scroller?.isConnected) {
    scroller.scrollTop += delta;
  }
}

