function g4sbV448WithEditorReadCache(product, draft, callback) {
  const productKey = String(product || "");
  const originalProductSource = g4sbV385ProductSource;
  const originalProductSemantics = g4sbV385ProductSemantics;
  const originalDirectionJtbds = g4sbV166DirectionJtbds;
  const originalSourcePhraseRows = g4sbV128SourcePhraseRows;
  const originalJtbdPhraseRows = g4sbV386JtbdPhraseRows;
  const productSourceCache = new Map();
  const productSemanticsCache = new Map();
  const directionJtbdsCache = new Map();
  const sourcePhraseRowsCache = new Map();
  const jtbdPhraseRowsCache = new Map();
  const memo = (cache, key, read) => {
    if (!cache.has(key)) cache.set(key, read());
    return cache.get(key);
  };
  g4sbV385ProductSource = function (productId) {
    const key = String(productId || "");
    if (key !== productKey) return originalProductSource.apply(this, arguments);
    return memo(productSourceCache, key, () =>
      originalProductSource.apply(this, arguments));
  };
  g4sbV385ProductSemantics = function (productId) {
    const key = String(productId || "");
    if (key !== productKey) return originalProductSemantics.apply(this, arguments);
    return memo(productSemanticsCache, key, () =>
      originalProductSemantics.apply(this, arguments));
  };
  g4sbV166DirectionJtbds = function (productId) {
    const key = String(productId || "");
    if (key !== productKey) return originalDirectionJtbds.apply(this, arguments);
    return memo(directionJtbdsCache, key, () =>
      originalDirectionJtbds.apply(this, arguments));
  };
  g4sbV128SourcePhraseRows = function (productId, currentDraft) {
    if (String(productId || "") !== productKey || currentDraft !== draft)
      return originalSourcePhraseRows.apply(this, arguments);
    return memo(sourcePhraseRowsCache, currentDraft, () =>
      originalSourcePhraseRows.apply(this, arguments));
  };
  g4sbV386JtbdPhraseRows = function (productId, jtbdId) {
    if (String(productId || "") !== productKey)
      return originalJtbdPhraseRows.apply(this, arguments);
    const key = `${productKey}\u0000${String(jtbdId || "")}`;
    return memo(jtbdPhraseRowsCache, key, () =>
      originalJtbdPhraseRows.apply(this, arguments));
  };
  try {
    return callback();
  } finally {
    g4sbV385ProductSource = originalProductSource;
    g4sbV385ProductSemantics = originalProductSemantics;
    g4sbV166DirectionJtbds = originalDirectionJtbds;
    g4sbV128SourcePhraseRows = originalSourcePhraseRows;
    g4sbV386JtbdPhraseRows = originalJtbdPhraseRows;
  }
}

function g4sbV448RefreshLaunchPriorities(product, d, coverage) {
  const indexed = (d.groupRows || []).map((row, index) => ({ row, index }));
  const launch = g4sbV131LaunchPriorities(indexed);
  coverage.querySelectorAll("[data-g4sb-saved-group-id]").forEach((card) => {
    const index = indexed.findIndex(({ row }) =>
      g4sbV420GroupId(row) === String(card.dataset.g4sbSavedGroupId || ""));
    const priority = launch.priorities.get(index);
    const status = card.querySelector(".g4-v127-group-status");
    const current = status?.querySelector(".g4-v131-priority");
    if (!priority?.rank) {
      current?.remove();
      return;
    }
    const next = g4sbV445ElementFromHtml(
      `<span class="g4-v131-priority ${priority.rank === 1 ? "is-first" : ""}">Запуск №${priority.rank}</span>`,
    );
    if (current) current.replaceWith(next);
    else status?.prepend(next);
  });
  const duplicateSummary = coverage.querySelector(":scope > .g4-v403-duplicate-summary");
  const currentNote = coverage.querySelector(":scope > .g4-v131-launch-note");
  if (!launch.first) {
    currentNote?.remove();
    return;
  }
  const note = g4sbV445ElementFromHtml(
    `<div class="g4-v131-launch-note"><span>Приоритет запуска по прогнозу</span><strong>№1 — ${escapeHtml(launch.first.row.col0 || "Группа")}</strong><small>Прогноз ранжирует готовые группы, но не меняет выбранный JTBD.</small></div>`,
  );
  if (currentNote) currentNote.replaceWith(note);
  else duplicateSummary?.after(note);
}

function g4sbV448RefreshSearchCoverage(product, d, currentCoverage, jtbdId) {
  if (!currentCoverage?.isConnected || !jtbdId) return false;
  const card = [...currentCoverage.querySelectorAll(
    ".g4-v166-jtbd[data-g4sb-jtbd-id]",
  )].find((item) => item.dataset.g4sbProduct === product &&
    item.dataset.g4sbJtbdId === jtbdId);
  const draft = d.clusterDraft;
  if (!card || !draft?.open || draft.jtbdId !== jtbdId) return false;

  card.open = true;
  card.querySelector(".g4-v126-editor")?.remove();
  const groupId = String(draft.editingClusterId || "");
  const escapedGroupId = CSS.escape(groupId);
  card.querySelector(
    `[data-g4sb-saved-group-id="${escapedGroupId}"]`,
  )?.remove();
  const body = card.querySelector(":scope > .g4-v160-jtbd-body");
  const editor = g4sbV445ElementFromHtml(g4sbV166EditorHtml(product, d));
  if (!body || !editor) return false;
  body.append(editor);
  d._g4V1261EditorRenderedInline = true;

  const jtbd = g4sbV166DirectionJtbds(product).find((item) => item.key === jtbdId);
  const groups = (d.groupRows || []).map((row, index) => ({ row, index }))
    .filter(({ row }) => g4sbV166GroupJtbdKey(product, row) === jtbdId);
  const readiness = jtbd
    ? g4sbV166JtbdReadiness(product, d, jtbd, groups) : "in_progress";
  const readinessPill = card.querySelector("[data-g4sb-jtbd-readiness]");
  if (readinessPill) {
    readinessPill.dataset.g4sbJtbdReadiness = readiness;
    readinessPill.className = `status-pill status-${readiness}`;
    readinessPill.textContent = STATUS_LABELS[readiness] || readiness;
  }

  const duplicateCount = g4sbV403DuplicateCount(product, d);
  const duplicateSummary = currentCoverage.querySelector(
    ":scope > .g4-v403-duplicate-summary",
  );
  if (duplicateSummary) {
    duplicateSummary.dataset.g4sbProductDuplicateCount = String(duplicateCount);
    const label = duplicateSummary.querySelector("strong");
    if (label) label.textContent =
      `Дубли фраз продукта (включая черновики): ${duplicateCount}`;
  }
  const implemented = g4sbV166DirectionJtbds(product).filter((item) =>
    (d.groupRows || []).some((row) => g4sbGroupIsFixed(row) &&
      g4sbV166GroupJtbdKey(product, row) === item.key)).length;
  currentCoverage.dataset.g4V166ImplementedCount = String(implemented);
  g4sbV448RefreshLaunchPriorities(product, d, currentCoverage);

  const currentSummary = currentCoverage.querySelector("[data-g4sb-launch-summary]");
  const summary = g4sbV445ElementFromHtml(g4sbV405LaunchSummaryHtml(
    product, d, g4sbV407SavedDuplicateCount(product, d),
  ));
  if (currentSummary && summary) currentSummary.replaceWith(summary);

  guruApplyFieldStates(editor);
  guruAutosizeProgressively(editor);
  guruInvalidateGateViewCache();
  g4sbV448ScheduleLaunchRefresh(product, d);
  return true;
}

