const __g4V409PrevDeleteClusterUnit = g4sbDeleteClusterUnit;
g4sbDeleteClusterUnit = function (d, groupId) {
  const group = (d.groupRows || []).find((row) =>
    row.groupId === groupId || row.clusterId === groupId);
  if (group && g4sbGroupIsFixed(group)) return false;
  const jtbdId = d.clusterDraft?.jtbdId || group?.jtbdId || "";
  const removed = __g4V409PrevDeleteClusterUnit(d, groupId);
  if (removed && d.clusterDraft?.editingClusterId === groupId) {
    d.clusterDraft.open = false;
    if (jtbdId && d.jtbdDraftsV388) delete d.jtbdDraftsV388[jtbdId];
  }
  return removed;
};

const __g4V409PrevSaveClusterDraft = g4sbSaveClusterDraft;
g4sbSaveClusterDraft = function (product, d) {
  const jtbdId = d.clusterDraft?.jtbdId || "";
  const saved = __g4V409PrevSaveClusterDraft(product, d);
  if (!saved) return saved;
  const group = d.groupRows.find((row) =>
    row.clusterId === saved.id || row.groupId === saved.id);
  if (group) {
    group.isFixed = true;
    group.fixedAt = new Date().toISOString();
  }
  if (d.clusterDraft) d.clusterDraft.open = false;
  if (jtbdId && d.jtbdDraftsV388) delete d.jtbdDraftsV388[jtbdId];
  if (jtbdId && Array.isArray(d.openJtbdIdsV391))
    d.openJtbdIdsV391 = d.openJtbdIdsV391.filter((id) => id !== jtbdId);
  if (d.activeJtbdId === jtbdId) d.activeJtbdId = "";
  return saved;
};

const __g4V409PrevDuplicateCluster = g4sbDuplicateCluster;
g4sbDuplicateCluster = function (product, d, groupId) {
  const copy = __g4V409PrevDuplicateCluster(product, d, groupId);
  if (!copy) return copy;
  const copiedGroup = d.groupRows.find((row) =>
    row.groupId === copy.id || row.clusterId === copy.id);
  if (copiedGroup) {
    copiedGroup.isFixed = false;
    delete copiedGroup.fixedAt;
  }
  return copy;
};

g4RsyaSearchForecastHtmlV363 = function (product) {
  const build = state.gate4SearchBuild?.[normalizeAspectKey(product || "no_product")];
  const rows = (Array.isArray(build?.groupRows) ? build.groupRows : [])
    .filter(g4sbGroupIsFixed);
  const items = rows.map((row, index) => {
    try {
      const phraseCount = (Array.isArray(row.demandRows) ? row.demandRows : [])
        .filter((item) => g4RsyaTextV289(item?.kw)).length;
      const assessment = g4sbV140ForecastAssessment(
        structuredClone(row), phraseCount, structuredClone(build.settings || {}), "",
      );
      const scenarios = assessment.conversionScenarios
        .filter((item) => Number.isFinite(item.cpa) && item.cpa > 0);
      if (!scenarios.length || assessment.errors.length) return "";
      return `<li><strong>${escapeHtml(row.col0 || `Группа ${index + 1}`)}</strong> · ${scenarios.map((item) => `${escapeHtml(item.label)} ${Math.round(item.cpa).toLocaleString("ru-RU")} ₽`).join(" · ")}</li>`;
    } catch (_error) { return ""; }
  }).filter(Boolean);
  return `<details class="g4-rsya-reference-v363"><summary>Прогноз CPA Поиска · только для справки</summary>
    ${g4RsyaGuideV363("searchForecast")}
    ${items.length ? `<ul>${items.join("")}</ul>` : '<p class="g4-rsya-note-v289">У выбранного товара нет зафиксированного прогноза CPA Поиска.</p>'}
  </details>`;
};

const __g4V409PrevGateBlockStatuses = guruGateBlockStatuses;
guruGateBlockStatuses = function (gate) {
  if (gate?.id !== "gate-4") return __g4V409PrevGateBlockStatuses(gate);
  try {
    const campaigns = g4EnsureLaunchCampaigns();
    const products = g4LaunchProducts();
    const channels = g4LaunchChannels();
    const statuses = [];
    products.forEach((product) => {
      channels.forEach((channel) => {
        const campaign = campaigns[g4CampaignStateKey(product, channel.key)] || {};
        statuses.push(g4IsYandexSearchChannel(channel)
          ? g4sbCampaignStatus(product, campaign, ensureGate4SearchBuild(product))
          : g4CampaignStatus(campaign));
      });
    });
    return statuses.length ? statuses : __g4V409PrevGateBlockStatuses(gate);
  } catch (_error) {
    return __g4V409PrevGateBlockStatuses(gate);
  }
};

function g4sbRefreshGroupSaveControls(product, jtbdId) {
  const card = [...document.querySelectorAll(".g4-v166-jtbd[data-g4sb-jtbd-id]")]
    .find((item) => item.dataset.g4sbProduct === product && item.dataset.g4sbJtbdId === jtbdId);
  const button = card?.querySelector("[data-g4sb-draft-save]");
  const missing = card?.querySelector("[data-g4sb-save-missing]");
  if (!button || !missing) return;
  const d = ensureGate4SearchBuild(product);
  const draft = d.jtbdDraftsV388?.[jtbdId];
  if (!draft?.open) return;
  const assessment = g4sbGroupSaveAssessment(product, d, draft);
  button.disabled = !assessment.enabled;
  button.textContent = d.groupRows.some((row) =>
    draft.editingClusterId && (row.groupId === draft.editingClusterId || row.clusterId === draft.editingClusterId))
    ? "Сохранить изменения" : "Сохранить группу";
  missing.hidden = assessment.enabled;
  missing.textContent = assessment.missing.length
    ? `Не хватает: ${assessment.missing.join(", ")}`
    : assessment.errors.length ? `Проверьте: ${assessment.errors.join("; ")}` : "";
}

