// Текущие результаты всегда подписаны: продукт либо явный, либо видно,
// что назначение ещё требуется. Неподписанный «общий итог» больше не маскируется.
/* v2.1.6 — «Продукт результатов» переведён с уровня категории (v185
   registry, meta.productId) на уровень позиции (v194 каталог,
   meta.positionId) и следует единому селектору guruV194Ui. Старое поле
   meta.productId и его миграция guruV185MigrateCurrentResults не
   трогаются и не удаляются — они остаются источником для одноразового
   переноса: если категория содержала ровно одну фактическую позицию,
   назначение переносится на неё автоматически; если позиций несколько —
   назначение однозначно не восстановить, это отмечается пометкой, без
   потери исходных данных результатов (сами цифры result-строк от
   productId/positionId не зависят). */
function gate0CurrentResultsMigrateToPosition(card, workspace = state) {
  const meta = card.currentResultsMeta;
  if (!meta || (meta.positionId && guruV194Product(meta.positionId, workspace))) return;
  if (!meta.productId) return;
  const category = guruV185ProductById(meta.productId, workspace);
  if (!category) return;
  const items = guruV194Products(workspace).filter((item) =>
    megaPlatformProductCategoryIds(item, workspace).includes(category.id));
  if (items.length === 1) meta.positionId = items[0].id;
}

function gate0CurrentResultsLegacyNoteHtml(meta, workspace = state) {
  if (!meta.productId) return "";
  const category = guruV185ProductById(meta.productId, workspace);
  if (!category) return "";
  const items = guruV194Products(workspace).filter((item) =>
    megaPlatformProductCategoryIds(item, workspace).includes(category.id));
  if (items.length <= 1) return "";
  return `<div class="gate5-note" style="margin-bottom:12px;">Требует ручной разбивки: раньше результаты были привязаны к категории «${escapeHtml(category.name)}» (${items.length} позиций). Сейчас привязка следует общему выбору продукта в блоке «Продукт, сегмент и задача клиента» — сами данные результатов не менялись.</div>`;
}

const __guruV185PrevCurrentResultsHtml = currentResultsHtml;
currentResultsHtml = function (card) {
  guruV185MigrateCurrentResults(card, state);
  const meta = card.currentResultsMeta || (card.currentResultsMeta = { period: "", sources: "", productId: "" });
  gate0CurrentResultsMigrateToPosition(card, state);
  const sharedProduct = guruV194SelectedProduct(state);
  if (sharedProduct) meta.positionId = sharedProduct.id;
  const selected = guruV194Product(meta.positionId, state);
  const positions = guruV194Products(state);
  const scope = `<label class="cr-meta-field"><span class="cr-meta-label">Продукт результатов</span><select disabled title="Продукт определяется общим селектором раздела «Продукт / услуга»" data-cr-meta-card-id="${escapeAttr(card.id)}" data-cr-meta-field="positionId"><option value="">Не назначено — не считать общим итогом</option>${positions.map((product) => `<option value="${escapeAttr(product.id)}" ${product.id === meta.positionId ? "selected" : ""}>${escapeHtml(product.name)}</option>`).join("")}</select></label>`;
  let html = __guruV185PrevCurrentResultsHtml(card);
  html = html.replace('<div class="cr-meta">', `<div class="cr-meta">${scope}`);
  const legacyNote = gate0CurrentResultsLegacyNoteHtml(meta, state);
  if (legacyNote) html = `${legacyNote}${html}`;
  else if (!selected) html = `<div class="gate5-note" style="margin-bottom:12px;">Результаты не назначены продукту и не используются как общий итог проекта. Выберите продукт в блоке «Продукт, сегмент и задача клиента».</div>${html}`;
  return html;
};

const __guruV185PrevRecalculateStatusForCard = recalculateStatusForCard;
recalculateStatusForCard = function (card, workspace = state) {
  if (isCurrentResultsCard(card)) {
    const rows = ensureCurrentResults(card);
    guruV185MigrateCurrentResults(card, workspace);
    gate0CurrentResultsMigrateToPosition(card, workspace);
    const filled = rows.filter((row) => guruV185Text(row.value)).length;
    const assigned = Boolean(guruV194Product(card.currentResultsMeta?.positionId, workspace));
    card.status = !filled ? "not_started" : assigned ? "ready" : "in_progress";
    return;
  }
  __guruV185PrevRecalculateStatusForCard(card, workspace);
};

/* ================================================================
   v1.89.0 — Каталог «Что продаём»: позиция → тип → категория.
   Категории остаются направлениями проекта (на них уже завязаны JTBD,
   офферы и Gate 1), а товары и услуги становятся отдельными позициями,
   которые могут накапливаться в одной категории.
   ================================================================ */
const GURU_CATALOG_ITEMS_MIGRATION_V189 = "gate0-catalog-items-v189";

function guruV189CatalogItems(workspace = state) {
  if (!workspace?.project) return [];
  const project = workspace.project;
  const raw = Array.isArray(project.catalogItemsV189)
    ? project.catalogItemsV189
    : [];
  const allowedContinuums = new Set(GURU_PRODUCT_CONTINUUMS_V187.map(([key]) => key));
  project.catalogItemsV189 = raw.map((item) => ({
    ...item,
    id: guruV185Text(item?.id) || makeId("catalog-item"),
    name: guruV185Text(item?.name),
    continuum: allowedContinuums.has(item?.continuum) ? item.continuum : "",
    createdAt: item?.createdAt || new Date().toISOString(),
  }));
  return project.catalogItemsV189;
}

function guruV189CatalogItemById(itemId, workspace = state) {
  return guruV189CatalogItems(workspace).find((item) => item.id === itemId) || null;
}

function guruV189EnsureCatalog(workspace = state) {
  if (!workspace?.project) return [];
  const categories = guruV187EnsureProductCards(workspace);
  const items = guruV189CatalogItems(workspace);
  const migrateContinuum = !workspace.project.catalogContinuumMigratedV247;
  // Ранее позиции Gate 1 существовали лишь как read-only сводка. Привязываем
  // их к тем же строкам каталога, что и ручные товары/услуги: один UI, один
  // набор действий, без дублирования данных.
  guruV188PositionRows(workspace).forEach(({ card, row, index }) => {
    const migrated = Boolean(megaPlatformCategoryStore(workspace)?.orderedMigratedAt);
    if (row._guruCatalogExcludedV190 ||
        !row.catalogItemIdV189 && (migrated || !row.categoryId)) return;
    row.catalogItemIdV189 = guruV185Text(row.catalogItemIdV189) || makeId("catalog-item");
    const sourceKey = `gate1:${card.id}:${guruV185Text(row.id) || row.catalogItemIdV189 || index}`;
    const sourceName = guruV185Text(g1pcContentName(row, card));
    let item = items.find((entry) => entry?.source?.key === sourceKey ||
      entry.id === row.catalogItemIdV189);
    if (!item && migrated) return;
    if (!item) {
      item = {
        id: row.catalogItemIdV189,
        name: sourceName,
        continuum: guruV185Text(row.catalogContinuumV189),
        ...(!megaPlatformCategoryStore(workspace)?.migratedAt
          ? { categoryId: row.categoryId } : {}),
        createdAt: new Date().toISOString(),
        source: { kind: "gate1", key: sourceKey, cardId: card.id, rowId: row.id || "", rowIndex: index },
        _sourceName: sourceName,
      };
      items.push(item);
      return;
    }
    if (!item.source) item.source = { kind: "gate1", key: sourceKey, cardId: card.id, rowId: row.id || "", rowIndex: index };
    // After Platform migration the Gate 1 audit keeps its historical field,
    // but must not overwrite the canonical relation on every load.
    if (!megaPlatformCategoryStore(workspace)?.migratedAt)
      item.categoryId = row.categoryId;
    if (migrateContinuum && !item.continuum)
      item.continuum = guruV185Text(row.catalogContinuumV189);
    if (!megaPlatformCategoryStore(workspace)?.migratedAt &&
        (!guruV185Text(item.name) || item._sourceName === sourceName)) {
      item.name = sourceName;
      item._sourceName = sourceName;
    }
  });
  if (migrateContinuum)
    workspace.project.catalogContinuumMigratedV247 = new Date().toISOString();
  const log = (workspace.project._gate0ProductIdMigrationLog = Array.isArray(
    workspace.project._gate0ProductIdMigrationLog,
  ) ? workspace.project._gate0ProductIdMigrationLog : []);
  if (!log.some((entry) => entry.id === GURU_CATALOG_ITEMS_MIGRATION_V189)) {
    log.push({
      id: GURU_CATALOG_ITEMS_MIGRATION_V189,
      at: new Date().toISOString(),
      status: "completed",
      note: "Позиции Gate 1 перенесены в единый редактируемый каталог; ручные товары и услуги добавляются туда же.",
    });
  }
  return { categories, items };
}

function guruV189CreateCategory(name, workspace = state) {
  const value = guruV185Text(name);
  if (!value || !workspace?.project) return null;
  const existing = guruV185Registry(workspace).find(
    (item) => guruV185Text(item.name).toLocaleLowerCase("ru-RU") === value.toLocaleLowerCase("ru-RU"),
  );
  if (existing) return null;
  workspace.project.productRegistryV185 = Array.isArray(workspace.project.productRegistryV185)
    ? workspace.project.productRegistryV185
    : [];
  const category = {
    id: makeId("product"),
    name: value,
    legacyNames: [],
    createdAt: new Date().toISOString(),
  };
  workspace.project.productRegistryV185.push(category);
  const urlStore = megaPlatformUrlStore(workspace);
  if (urlStore && !urlStore.onOrderCategoryId &&
      value.toLocaleLowerCase("ru-RU") === "на заказ")
    urlStore.onOrderCategoryId = category.id;
  guruV187EnsureProductCards(workspace);
  return category;
}

function guruV189CategoryItems(categoryId, workspace = state) {
  return megaPlatformOrderedProductsInCategory(categoryId, guruV189CatalogItems(workspace).filter(
    (item) => megaPlatformProductCategoryIds(item, workspace).includes(categoryId) && guruV185Text(item.name),
  ), workspace);
}

function guruV189PositionCountLabel(total) {
  const tail = total % 100;
  const last = total % 10;
  const word = tail >= 11 && tail <= 14
    ? "позиций"
    : last === 1
      ? "позиция"
      : last >= 2 && last <= 4
        ? "позиции"
        : "позиций";
  return `${total} ${word}`;
}

function guruV189CategorySummaryHtml(category, index) {
  const total = guruV189CategoryItems(category.id).length;
  return `<div class="guru-catalog-category-summary ${total ? "has-items" : ""}">
    <span>${escapeHtml(category.name)}</span>
    <span>${total ? guruV189PositionCountLabel(total) : "Пока пусто"}</span>
  </div>`;
}

function guruV192ContinuumHelpHtml(continuum) {
  const explanation = GURU_PRODUCT_CONTINUUM_EXPLANATIONS_V192[continuum];
  if (!explanation) {
    return `<aside class="guru-catalog-continuum-help is-placeholder" aria-live="polite"><strong>Подсказка по варианту</strong><span>После выбора здесь появятся определение и пример.</span><small>Это поможет проверить, соответствует ли вариант продукту.</small></aside>`;
  }
  const label = GURU_PRODUCT_CONTINUUMS_V187.find(([value]) => value === continuum)?.[1] || "";
  return `<aside class="guru-catalog-continuum-help is-active" aria-live="polite"><strong>${escapeHtml(label)}</strong><span>${escapeHtml(explanation.definition)}</span><small><b>Пример:</b> ${escapeHtml(explanation.example)}</small></aside>`;
}

let guruV192ContinuumStatusTimer = null;

function guruV192SaveContinuumSmooth(itemElement) {
  // Этот путь намеренно не вызывает общий flashSaving(): тот пересчитывает
  // весь Gate 0 и навигацию синхронно с выбором в native-select.
  _guruTabDirty = true;
  els.saveStatus.textContent = "Сохраняю...";
  els.autosaveDot.style.background = "#d4b05f";
  if (_saveTimer) clearTimeout(_saveTimer);
  _saveTimer = setTimeout(() => {
    _saveTimer = null;
    guruAutosaveStateSmooth();
  }, GURU_AUTOSAVE_DELAY_MS);

  if (guruV192ContinuumStatusTimer) clearTimeout(guruV192ContinuumStatusTimer);
  guruV192ContinuumStatusTimer = setTimeout(() => {
    guruV192ContinuumStatusTimer = null;
    const refresh = () => {
      if (activeGateId !== "gate-0" || !itemElement?.isConnected) return;
      const section = itemElement.closest(".gate0-card[data-card-row]");
      const card = section ? findCard(section.dataset.cardRow) : null;
      if (card) {
        recalculateStatusForCard(card, state);
        const badge = section.querySelector(".gate0-card-status");
        if (badge) {
          badge.className = `gate0-card-status status-${card.status}`;
          badge.textContent = STATUS_LABELS[card.status] || card.status;
        }
      }
      renderGateNav();
    };
    if (typeof requestIdleCallback === "function") requestIdleCallback(refresh, { timeout: 1200 });
    else setTimeout(refresh, 0);
  }, 350);
}

function guruV189CatalogItemHtml(item, categories, groupId, groupIndex) {
  const canChooseType = Boolean(guruV185Text(item.name));
  // Категория относится к самой позиции, а не к её типу. Поэтому её можно
  // выбрать или создать сразу внутри конкретного продукта; тип остаётся
  // отдельным следующим шагом, но не блокирует управление категориями.
  const canChooseCategory = canChooseType;
  const visibleCategoryIds = canChooseCategory ? megaPlatformProductCategoryIds(item, state) : [];
  const visibleCategoryNames = visibleCategoryIds.map((id) =>
    categories.find((category) => category.id === id)?.name).filter(Boolean);
  const drag = guruDragRowHtml("catalogCategory", { key: groupId }, groupIndex);
  return `<article class="guru-catalog-item" ${drag.rowAttrs}>
    <div class="guru-catalog-item-toolbar">${drag.handle}<span>Перетащите, чтобы изменить порядок в категории</span></div>
    <label class="g1-field"><strong>Что продаём</strong>${item.name ? `<span class="mega-platform-source-value">${escapeHtml(item.name)}</span><small class="mega-platform-source-label">из Платформы</small>` : `<input class="passport-v116-input is-empty" data-guru-catalog-name="${escapeAttr(item.id)}" value="" placeholder="Название нового товара или услуги" /><small class="guru-catalog-duplicate-hint" data-guru-catalog-duplicate-hint hidden>Товар с таким названием уже есть</small>`}${item.source?.kind === "gate1" ? '<small class="guru-catalog-source">Из Gate 1</small>' : ""}</label>
    <label class="g1-field"><strong>Что это</strong><select class="passport-v116-input ${item.continuum ? "is-filled" : "is-empty"}" data-guru-catalog-continuum="${escapeAttr(item.id)}" ${canChooseType ? "" : "disabled"}><option value="">${canChooseType ? "Выберите вариант" : "Сначала укажите продукт"}</option>${GURU_PRODUCT_CONTINUUMS_V187.map(([value, label]) => `<option value="${escapeAttr(value)}" ${value === item.continuum ? "selected" : ""}>${escapeHtml(label)}</option>`).join("")}</select></label>
    ${guruV192ContinuumHelpHtml(item.continuum)}
    <label class="g1-field"><strong>Категории</strong><span class="mega-platform-source-value">${escapeHtml(visibleCategoryNames.join(", ") || "Без категории")}</span><small class="mega-platform-source-label">из Платформы</small></label>
    <button type="button" class="small-btn danger-mini" data-guru-catalog-remove="${escapeAttr(item.id)}" aria-label="Удалить из всей системы" title="Удалить из всей системы">×</button>
  </article>`;
}

function guruV193CatalogGroupHtml(group, categories, ui) {
  const isOpen = ui.openGroupsV512?.[group.id] === true;
  return `<details class="guru-catalog-category-group" data-guru-catalog-category-group="${escapeAttr(group.id)}" data-guru-catalog-rendered-open="${isOpen ? "1" : "0"}" ${isOpen ? "open" : ""}>
    <summary class="guru-catalog-category-group-head"><strong>${escapeHtml(group.name)}</strong><span>${guruV189PositionCountLabel(group.items.length)}</span><i aria-hidden="true">⌄</i></summary>
    <div class="guru-catalog-category-group-items">
      ${group.items.length
        ? group.items.map((item, index) => guruV189CatalogItemHtml(item, categories, group.id, index)).join("")
        : '<div class="guru-catalog-group-empty">В этой категории пока нет продуктов или услуг.</div>'}
    </div>
  </details>`;
}

function guruV193CatalogGroups(categories, items) {
  const groups = categories.map((category) => ({
    id: category.id,
    name: category.name,
    items: megaPlatformOrderedProductsInCategory(category.id,
      items.filter((item) => megaPlatformProductCategoryIds(item).includes(category.id))),
  }));
  const uncategorized = megaPlatformOrderedProductsInCategory("__uncategorized__",
    items.filter((item) => !megaPlatformProductCategoryIds(item).length));
  if (uncategorized.length) {
    groups.unshift({ id: "__uncategorized__", name: "Без категории", items: uncategorized });
  }
  return groups;
}

// Этот блок заменяет старую схему «сначала категория, потом ручной текст».
// Порядок ввода теперь соответствует реальной работе: позиция → тип → категория.
guruV187ProductCardsHtml = function () {
  const { categories, items } = guruV189EnsureCatalog(state);
  const ui = state.project.catalogUiV191 || {};
  const groups = guruV193CatalogGroups(categories, items);
  return `<div class="passport-v116-field-card v116-multi-field guru-catalog">
    <span class="passport-v116-field-title">Что продаём</span>
    <div class="guru-catalog-actions"><button type="button" class="small-btn" data-guru-catalog-add>+ Добавить продукт / услугу</button></div>
    ${ui.isCreatingCategory ? `<div class="guru-catalog-new-category-form"><input class="passport-v116-input" data-guru-catalog-category-name value="${escapeAttr(ui.categoryDraft || "")}" placeholder="Например: Авторская одежда" autocomplete="off" autofocus /><button type="button" class="small-btn" data-guru-catalog-category-create>Создать категорию</button><button type="button" class="small-btn" data-guru-catalog-category-cancel>Отмена</button><small class="guru-catalog-duplicate-hint" data-guru-catalog-category-duplicate-hint hidden>Категория с таким названием уже есть</small></div>` : ""}
    <div class="guru-catalog-list">
      ${groups.map((group) => guruV193CatalogGroupHtml(group, categories, ui)).join("") || '<div class="guru-catalog-empty">Добавьте первую позицию: товар, услугу или гибрид.</div>'}
    </div>
  </div>`;
};

document.addEventListener("toggle", (event) => {
  const group = event.target?.closest?.("[data-guru-catalog-category-group]");
  if (!group || event.target !== group) return;
  const renderedOpen = group.dataset.guruCatalogRenderedOpen === "1";
  if (group.open === renderedOpen) return;
  group.dataset.guruCatalogRenderedOpen = group.open ? "1" : "0";
  const ui = (state.project.catalogUiV191 = state.project.catalogUiV191 || {});
  ui.collapsedGroupsV193 = ui.collapsedGroupsV193 || {};
  ui.openGroupsV512 = ui.openGroupsV512 || {};
  ui.openGroupsV512[group.dataset.guruCatalogCategoryGroup] = group.open;
  if (group.open) delete ui.collapsedGroupsV193[group.dataset.guruCatalogCategoryGroup];
  else ui.collapsedGroupsV193[group.dataset.guruCatalogCategoryGroup] = true;
  guruScheduleUiPreferenceSave();
}, true);

const __guruV189PrevPrepareSystemCards = prepareSystemCards;
prepareSystemCards = function (workspace) {
  __guruV189PrevPrepareSystemCards(workspace);
  guruV189EnsureCatalog(workspace);
};

document.addEventListener("click", (event) => {
  const addButton = event.target?.closest?.("[data-guru-catalog-add]");
  const removeButton = event.target?.closest?.("[data-guru-catalog-remove]");
  if (!addButton && !removeButton) return;
  if (removeButton) {
    megaPlatformDeleteRequest("product", removeButton.dataset.guruCatalogRemove, state);
    return;
  }
  const items = guruV189CatalogItems(state);
  const item = { id: makeId("catalog-item"), name: "", continuum: "",
    createdAt: new Date().toISOString() };
  items.unshift(item);
  megaPlatformSetProductCategoryIds(item.id, [], state);
  const ui = (state.project.catalogUiV191 ||= {});
  if (ui.collapsedGroupsV193) delete ui.collapsedGroupsV193.__uncategorized__;
  flashSaving();
  guruInvalidateGateViewCache();
  renderGate();
  if (addButton) {
    setTimeout(() => document.querySelector(
      `[data-guru-catalog-name="${CSS.escape(item.id)}"]`)?.focus(), 0);
  }
}, true);

document.addEventListener("click", (event) => {
  const createButton = event.target?.closest?.("[data-guru-catalog-inline-category-create]");
  const cancelButton = event.target?.closest?.("[data-guru-catalog-inline-category-cancel]");
  if (!createButton && !cancelButton) return;
  const itemId = createButton?.dataset.guruCatalogInlineCategoryCreate || cancelButton?.dataset.guruCatalogInlineCategoryCancel;
  const item = guruV189CatalogItemById(itemId, state);
  if (!item) return;
  if (cancelButton) {
    delete item._categoryMode;
    delete item._categoryDraft;
  } else {
    const name = item._categoryDraft ?? document.querySelector(`[data-guru-catalog-inline-category-name="${CSS.escape(itemId)}"]`)?.value ?? "";
    const category = guruV189CreateCategory(name, state);
    if (!category) return;
    delete item._categoryMode;
    delete item._categoryDraft;
  }
  flashSaving();
  renderGate();
}, true);

// Черновик живёт в state, поэтому случайная системная перерисовка не стирает
// уже набранное название. На каждый символ DOM не пересобираем.
document.addEventListener("input", (event) => {
  const inlineInput = event.target?.closest?.("[data-guru-catalog-inline-category-name]");
  const categoryInput = event.target?.closest?.("[data-guru-catalog-category-name]");
  if (!inlineInput && !categoryInput) return;
  if (inlineInput) {
    const item = guruV189CatalogItemById(
      inlineInput.dataset.guruCatalogInlineCategoryName,
      state,
    );
    if (item) item._categoryDraft = inlineInput.value;
  }
  if (categoryInput) {
    const ui = (state.project.catalogUiV191 = state.project.catalogUiV191 || {});
    ui.categoryDraft = categoryInput.value;
    const hint = categoryInput.closest(".guru-catalog-new-category-form")
      ?.querySelector("[data-guru-catalog-category-duplicate-hint]");
    if (hint) hint.hidden = !megaPlatformDuplicateEntityName("category",
      categoryInput.value, "", state);
  }
}, true);

// Enter подтверждает форму, Escape отменяет её. Во время IME-композиции Enter
// принадлежит редактору ввода и не должен преждевременно создавать категорию.
document.addEventListener("keydown", (event) => {
  const inlineInput = event.target?.closest?.("[data-guru-catalog-inline-category-name]");
  const categoryInput = event.target?.closest?.("[data-guru-catalog-category-name]");
  if (!inlineInput && !categoryInput) return;
  if (event.isComposing || event.keyCode === 229) return;
  if (event.key !== "Enter" && event.key !== "Escape") return;
  event.preventDefault();
  const form = event.target.closest(
    ".guru-catalog-inline-category, .guru-catalog-new-category-form",
  );
  const action = event.key === "Enter"
    ? form?.querySelector(
      "[data-guru-catalog-inline-category-create], [data-guru-catalog-category-create]",
    )
    : form?.querySelector(
      "[data-guru-catalog-inline-category-cancel], [data-guru-catalog-category-cancel]",
    );
  action?.click();
}, true);

document.addEventListener("click", (event) => {
  const openButton = event.target?.closest?.("[data-guru-catalog-category-open]");
  const createButton = event.target?.closest?.("[data-guru-catalog-category-create]");
  const cancelButton = event.target?.closest?.("[data-guru-catalog-category-cancel]");
  if (!openButton && !createButton && !cancelButton) return;
  state.project.catalogUiV191 = state.project.catalogUiV191 || {};
  if (openButton) state.project.catalogUiV191.isCreatingCategory = true;
  if (cancelButton) {
    state.project.catalogUiV191.isCreatingCategory = false;
    delete state.project.catalogUiV191.categoryDraft;
  }
  if (createButton) {
    const name = state.project.catalogUiV191.categoryDraft ?? document.querySelector("[data-guru-catalog-category-name]")?.value ?? "";
    if (!guruV189CreateCategory(name, state)) {
      const hint = document.querySelector("[data-guru-catalog-category-duplicate-hint]");
      if (hint) hint.hidden = !megaPlatformDuplicateEntityName("category", name, "", state);
      return;
    }
    state.project.catalogUiV191.isCreatingCategory = false;
    delete state.project.catalogUiV191.categoryDraft;
  }
  flashSaving();
  renderGate();
}, true);

document.addEventListener("input", (event) => {
  const input = event.target?.closest?.("[data-guru-catalog-name]");
  if (!input) return;
  const item = guruV189CatalogItemById(input.dataset.guruCatalogName, state);
  if (!item) return;
  const itemElement = input.closest(".guru-catalog-item");
  const duplicate = megaPlatformDuplicateEntityName("product", input.value, item.id, state);
  const hint = itemElement?.querySelector("[data-guru-catalog-duplicate-hint]");
  if (hint) hint.hidden = !duplicate;
  if (duplicate) return;
  item.name = input.value;
  // Не ждём следующей перерисовки: после ввода названия сразу открываем
  // следующий шаг, чтобы сценарий «название → тип → категория» был плавным.
  const continuumControl = itemElement?.querySelector("[data-guru-catalog-continuum]");
  const categoryControl = itemElement?.querySelector("[data-guru-catalog-category]");
  const hasName = Boolean(guruV185Text(item.name));
  if (continuumControl) continuumControl.disabled = !hasName;
  if (categoryControl) categoryControl.disabled = !hasName;
  document.querySelectorAll(`[data-mega-platform-rename-product="${CSS.escape(item.id)}"]`)
    .forEach((other) => { other.value = item.name; });
  flashSaving();
}, true);

document.addEventListener("change", (event) => {
  const input = event.target?.closest?.("[data-guru-catalog-name]");
  if (!input || megaPlatformDuplicateEntityName("product", input.value,
      input.dataset.guruCatalogName, state)) return;
  guruInvalidateGateViewCache();
  renderGate();
}, true);

document.addEventListener("change", (event) => {
  const continuum = event.target?.closest?.("[data-guru-catalog-continuum]");
  const category = event.target?.closest?.("[data-guru-catalog-category]");
  const newCategory = event.target?.closest?.("[data-guru-catalog-new-category]");
  if (!continuum && !category && !newCategory) return;
  const itemId = continuum?.dataset.guruCatalogContinuum || category?.dataset.guruCatalogCategory || newCategory?.dataset.guruCatalogNewCategory;
  const item = guruV189CatalogItemById(itemId, state);
  if (!item) return;
  if (continuum) item.continuum = continuum.value;
  if (continuum && item.source?.kind === "gate1") {
    const card = g1pcFindCard(item.source.cardId);
    const row = (card?.pageRows || []).find((entry) => entry.id === item.source.rowId) || card?.pageRows?.[item.source.rowIndex];
    if (row) row.catalogContinuumV189 = continuum.value;
  }
  // Выбор типа не должен уничтожать открытый native-select полной
  // перерисовкой Gate. Обновляем только пояснение в текущей карточке.
  if (continuum) {
    continuum.classList.toggle("is-filled", Boolean(item.continuum));
    continuum.classList.toggle("is-empty", !item.continuum);
    const itemElement = continuum.closest(".guru-catalog-item");
    const currentHelp = itemElement?.querySelector(".guru-catalog-continuum-help");
    const nextHelp = document.createElement("div");
    nextHelp.innerHTML = guruV192ContinuumHelpHtml(item.continuum);
    const renderedHelp = nextHelp.firstElementChild;
    if (currentHelp && renderedHelp) {
      currentHelp.className = renderedHelp.className;
      currentHelp.innerHTML = renderedHelp.innerHTML;
    }
    guruV192SaveContinuumSmooth(itemElement);
    return;
  }
  if (category) {
    // Historical controls can remain in an imported DOM, but the relation is
    // edited only in Platform. A change here must never write a second copy.
    renderGate();
    return;
  }
  if (newCategory) {
    const created = guruV189CreateCategory(newCategory.value, state);
    if (!created) return;
    delete item._categoryMode;
  }
  flashSaving();
  renderGate();
}, true);

document.addEventListener("click", (event) => {
  const button = event.target?.closest?.("[data-guru-catalog-focus]");
  if (!button) return;
  const input = document.querySelector(`[data-guru-catalog-name="${CSS.escape(button.dataset.guruCatalogFocus)}"]`);
  input?.scrollIntoView({ behavior: "smooth", block: "center" });
  input?.focus({ preventScroll: true });
}, true);

/* Последний предохранитель плавного ввода для старых модулей.
   Некоторые обработчики исторически вызывают renderGate() прямо на input.
   Структурные действия (click/change) по-прежнему рендерятся сразу, а набор
   текста никогда не уничтожает и не пересобирает весь текущий Gate. */
const __guruSmoothInputPrevRenderGate = renderGate;
renderGate = function () {
  if (guruUserEditDispatchActive && guruUserEditEventType === "input") {
    flashSaving();
    return;
  }
  return __guruSmoothInputPrevRenderGate.apply(this, arguments);
};

const __guruSmoothInputPrevRenderGateNav = renderGateNav;
renderGateNav = function () {
  if (guruUserEditDispatchActive && guruUserEditEventType === "input") return;
  return __guruSmoothInputPrevRenderGateNav.apply(this, arguments);
};

const __guruSmoothInputPrevRecalculateAllStatuses = recalculateAllStatuses;
recalculateAllStatuses = function () {
  if (guruUserEditDispatchActive && guruUserEditEventType === "input") return;
  return __guruSmoothInputPrevRecalculateAllStatuses.apply(this, arguments);
};

/* ================================================================
   v1.94.0 — Gate 0: продукт как центральная сущность.

   catalogItemsV189 остаётся реестром продуктов, productRegistryV185 —
   реестром категорий. Связанные смыслы хранятся отдельно, по одной записи
   на значение. Старые productBindingsV185 и глобальные поля проекта не
   удаляются: ниже они поддерживаются как совместимая проекция для Gate 1–8.
   ================================================================ */
const GURU_GATE0_PRODUCT_SCOPE_MIGRATION_V194 = "gate0-product-scope-v194";
const GURU_GATE0_OFFER_CTA_MIGRATION_V197 = "gate0-offer-cta-v197";
const GURU_GATE0_SCOPE_FIELDS_V194 = [
  ["jtbd", "JTBD", "Когда…, я хочу…, чтобы…"],
  ["segments", "Сегментация · Продукт/Услуга", "Один сегмент в одной записи"],
  ["positioning", "Позиционирование · Продукт/Услуга", "Категория + отличие от конкурентов"],
  ["usp", "УТП", "Главное обещание выбора"],
  ["offers", "Оффер и CTA · Продукт/Услуга", "Один оффер с собственным CTA в одной записи"],
  ["keyword_foundation", "Фундамент ключевых слов · Продукт/Услуга", "Черновые поисковые формулировки из стратегии продукта"],
  ["cta", "CTA", "Архив самостоятельных CTA прежней структуры"],
];
// Company-only records share the stable scoped storage format, but must not
// enter the product field catalogue: product inheritance, the common-meta
// editor and legacy projections intentionally iterate only V194 above.
const GURU_GATE0_COMPANY_SCOPE_FIELDS_V347 = [
  ["company_offer", "Оффер и CTA · Компания", "Первый шаг к знакомству с брендом"],
  ["brand_purpose", "Цель бренда", "Функциональная, высшая и единая цель бренда"],
];
const GURU_GATE0_SCOPES_V194 = [
  ["product", "Только этот продукт"],
  ["category", "Вся категория"],
  ["project", "Весь проект"],
];
const GURU_GATE0_CONFIRMATION_V194 = [
  ["draft", "Черновик"],
  ["needs_confirmation", "Нужно подтвердить"],
  ["confirmed", "Подтверждено"],
];

const GURU_GATE0_KEYWORD_FOUNDATION_V247 = "gate0-keyword-foundation-v247";
const GURU_GATE0_KEYWORD_CSV_V248 = "gate0-keyword-csv-v248";
const GURU_GATE0_KEYWORD_SOURCE_FIELDS_V247 = [
  "jtbd",
  "segments",
  "positioning",
  "usp",
  "offers",
];

function guruV247KeywordText(keyword) {
  if (keyword && typeof keyword === "object" && !Array.isArray(keyword))
    return guruV185Text(keyword.value ?? keyword.text ?? keyword.keyword);
  return guruV185Text(keyword);
}

function guruV247KeywordEntry(keyword, defaults = {}) {
  const current = keyword && typeof keyword === "object" && !Array.isArray(keyword)
    ? keyword
    : {};
  const source = ["manual", "generated", "imported"].includes(current.source)
    ? current.source
    : ["generated", "imported"].includes(defaults.source) ? defaults.source : "manual";
  const status = ["draft", "confirmed"].includes(current.status)
    ? current.status
    : defaults.status === "draft" || source === "generated" || source === "imported"
      ? "draft"
      : "confirmed";
  return {
    ...current,
    id: guruV185Text(current.id) || makeId("gate0-keyword"),
    value: guruV247KeywordText(keyword),
    source,
    status,
  };
}

function guruV194ProjectId(workspace = state) {
  if (workspace === state && activeProjectId) return String(activeProjectId);
  return String(workspace?.project?.id || workspace?.project?.projectId || activeProjectId || "");
}

function guruV194Products(workspace = state) {
  return guruV189CatalogItems(workspace).filter((item) => guruV185Text(item.name))
    .map((item) => new Proxy(item, {
      get(target, key, receiver) {
        return key === "categoryId" ? megaPlatformProductCategoryId(target, workspace)
          : Reflect.get(target, key, receiver);
      },
      set(target, key, value, receiver) {
        if (key === "categoryId") return true;
        return Reflect.set(target, key, value, receiver);
      },
    }));
}

function guruV194Product(productId, workspace = state) {
  return guruV194Products(workspace).find((item) => item.id === productId) || null;
}

function guruV194Records(workspace = state) {
  if (!workspace?.project) return [];
  const project = workspace.project;
  const allowedFields = new Set([
    ...GURU_GATE0_SCOPE_FIELDS_V194,
    ...GURU_GATE0_COMPANY_SCOPE_FIELDS_V347,
  ].map(([key]) => key));
  const allowedScopes = new Set(GURU_GATE0_SCOPES_V194.map(([key]) => key));
  const allowedStatuses = new Set(GURU_GATE0_CONFIRMATION_V194.map(([key]) => key));
  const products = new Map(guruV194Products(workspace).map((item) => [item.id, item]));
  const raw = Array.isArray(project.gate0ScopedValuesV194)
    ? project.gate0ScopedValuesV194
    : [];
  project.gate0ScopedValuesV194 = raw
    .filter((record) => allowedFields.has(record?.field) && allowedScopes.has(record?.scope))
    .map((record) => {
      const product = record.product_id ? products.get(String(record.product_id)) : null;
      const scope = record.field === "keyword_foundation"
        ? record.scope === "project" ? "project" : "product"
        : GURU_GATE0_COMPANY_SCOPE_FIELDS_V347.some(
            ([field]) => field === record.field,
          )
          ? "project"
          : record.scope;
      const normalized = {
        ...record,
        id: guruV185Text(record.id) || makeId("gate0-value"),
        project_id: guruV194ProjectId(workspace),
        category_id: scope === "project" ? "" : guruV185Text(record.category_id),
        product_id: scope === "product" ? guruV185Text(record.product_id) : "",
        scope,
        value: String(record.value || ""),
        source:
          record.source && typeof record.source === "object"
            ? record.source
            : { type: "manual", label: guruV185Text(record.source) || "Введено вручную" },
        confirmation_status: allowedStatuses.has(record.confirmation_status)
          ? record.confirmation_status
          : "draft",
        created_at: record.created_at || new Date().toISOString(),
        updated_at: record.updated_at || record.created_at || new Date().toISOString(),
      };
      if (record.field === "keyword_foundation") {
        normalized.scope = scope;
        normalized.product_id = scope === "product"
          ? guruV185Text(record.product_id)
          : "";
        normalized.category_id = scope === "product"
          ? guruV185Text(record.category_id) : "";
        normalized.keywords = Array.isArray(record.keywords)
          ? record.keywords.map((keyword) => guruV247KeywordEntry(keyword, {
              source: "manual",
              status: "confirmed",
            }))
          : [];
      }
      return normalized;
    });
  // Product records retain historical category_id only as old data. Readers
  // see the live Platform relation without persisting another copy of it.
  return new Proxy(project.gate0ScopedValuesV194, {
    get(target, key, receiver) {
      const value = Reflect.get(target, key, receiver);
      if (!/^\d+$/.test(String(key)) || !value || value.scope !== "product" || !value.product_id)
        return value;
      return new Proxy(value, {
        get(record, field, recordReceiver) {
          return field === "category_id"
            ? megaPlatformProductCategoryId(record.product_id, workspace)
            : Reflect.get(record, field, recordReceiver);
        },
        set(record, field, next, recordReceiver) {
          if (field === "category_id") return true;
          return Reflect.set(record, field, next, recordReceiver);
        },
      });
    },
  });
}

function guruV194RecordLocation(scope, product) {
  return {
    project_id: guruV194ProjectId(state),
    category_id: scope === "category" ? guruV185Text(product?.categoryId) : "",
    product_id: scope === "product" ? guruV185Text(product?.id) : "",
    scope,
  };
}

function guruV194ExactRecords(field, scope, product, workspace = state) {
  return guruV194Records(workspace).filter((record) => {
    if (record.field !== field || record.scope !== scope) return false;
    if (scope === "project") return true;
    if (scope === "category") return Boolean(product?.categoryId) && record.category_id === product.categoryId;
    return Boolean(product?.id) && record.product_id === product.id;
  });
}

function guruV194Resolve(field, product, workspace = state) {
  if (!product) return { scope: "product", records: [] };
  const productRecords = guruV194ExactRecords(field, "product", product, workspace);
  // Keyword foundations are two explicitly isolated stores. A product must
  // never inherit the company project-scoped foundation.
  if (field === "keyword_foundation")
    return { scope: "product", records: productRecords };
  if (productRecords.length) return { scope: "product", records: productRecords };
  const categoryRecords = guruV194ExactRecords(field, "category", product, workspace);
  if (categoryRecords.length) return { scope: "category", records: categoryRecords };
  return {
    scope: "project",
    records: guruV194ExactRecords(field, "project", product, workspace),
  };
}

function guruV194AppendLegacy(field, value, scope, product, legacyPath, workspace = state) {
  const text = guruV185Text(value);
  if (!text) return;
  const location = {
    project_id: guruV194ProjectId(workspace),
    category_id: scope === "category" ? guruV185Text(product?.categoryId || product?.id) : "",
    product_id: scope === "product" ? guruV185Text(product?.id) : "",
    scope,
  };
  const exists = guruV194Records(workspace).some(
    (record) =>
      record.field === field &&
      record.scope === scope &&
      (scope === "product" || record.category_id === location.category_id) &&
      record.product_id === location.product_id &&
      guruV185Text(record.value) === text,
  );
  if (exists) return;
  guruV194Records(workspace).push({
    id: makeId("gate0-value"),
    ...location,
    field,
    value: text,
    source: { type: "migration", label: "Gate 0 · прежняя структура", legacy_path: legacyPath },
    confirmation_status: "needs_confirmation",
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  });
}

function guruV194Migrate(workspace = state) {
  if (!workspace?.project) return;
  const project = workspace.project;
  const log = (project._gate0ProductIdMigrationLog = Array.isArray(project._gate0ProductIdMigrationLog)
    ? project._gate0ProductIdMigrationLog
    : []);
  if (log.some((entry) => entry.id === GURU_GATE0_PRODUCT_SCOPE_MIGRATION_V194)) return;

  guruV194Records(workspace);
  guruV185Registry(workspace).forEach((category) => {
    const binding = guruV185Binding(category.id, workspace);
    const categoryRef = { id: "", categoryId: category.id };
    guruV194AppendLegacy("jtbd", binding.jtbd, "category", categoryRef, `productBindingsV185.${category.id}.jtbd`, workspace);
    (binding.audiences || []).forEach((item, index) =>
      guruV194AppendLegacy("segments", item?.text, "category", categoryRef, `productBindingsV185.${category.id}.audiences.${index}`, workspace));
    guruV194AppendLegacy("offers", binding.offer, "category", categoryRef, `productBindingsV185.${category.id}.offer`, workspace);
    guruV194AppendLegacy("cta", binding.cta, "category", categoryRef, `productBindingsV185.${category.id}.cta`, workspace);
  });

  guruV194AppendLegacy("positioning", project.positioningStatement || project.positioningStartFormula, "project", null, "project.positioningStatement", workspace);
  guruV194AppendLegacy("usp", project.usp, "project", null, "project.usp", workspace);
  guruV194AppendLegacy("offers", project.currentOffers || project.offer, "project", null, "project.currentOffers", workspace);
  guruV194AppendLegacy("cta", project.currentCtas || project.mainCta, "project", null, "project.currentCtas", workspace);
  log.push({
    id: GURU_GATE0_PRODUCT_SCOPE_MIGRATION_V194,
    at: new Date().toISOString(),
    status: "completed_needs_confirmation",
    records: guruV194Records(workspace).length,
    note: "Существующие JTBD, сегменты, позиционирование, УТП, офферы и CTA перенесены без удаления прежних связей.",
  });
}

function guruV194MigrateOfferCtas(workspace = state) {
  if (!workspace?.project) return;
  const project = workspace.project;
  const log = (project._gate0ProductIdMigrationLog = Array.isArray(project._gate0ProductIdMigrationLog)
    ? project._gate0ProductIdMigrationLog
    : []);
  if (log.some((entry) => entry.id === GURU_GATE0_OFFER_CTA_MIGRATION_V197)) return;

  const records = guruV194Records(workspace);
  const locationKey = (record) => [record.scope, record.category_id, record.product_id].join("|");
  const offersByLocation = new Map();
  records.filter((record) => record.field === "offers").forEach((record) => {
    const key = locationKey(record);
    const group = offersByLocation.get(key) || [];
    group.push(record);
    offersByLocation.set(key, group);
  });

  records.filter((record) => record.field === "cta" && guruV185Text(record.value)).forEach((ctaRecord) => {
    const key = locationKey(ctaRecord);
    const candidates = offersByLocation.get(key) || [];
    const target = candidates.find((offerRecord) => !guruV194OfferParts(offerRecord).cta);
    if (target) {
      const parts = guruV194OfferParts(target);
      if (!target.offer && !parts.legacy_value && guruV185Text(target.value)) parts.legacy_value = target.value;
      parts.cta = guruV185Text(ctaRecord.value);
      target.offer = parts;
      // Уже сохранённая формулировка оффера является пользовательским текстом:
      // при переносе legacy CTA не пересобираем и не заполняем её автоматически.
      target.updated_at = new Date().toISOString();
      return;
    }
    const offerRecord = {
      id: makeId("gate0-value"),
      project_id: ctaRecord.project_id,
      category_id: ctaRecord.category_id,
      product_id: ctaRecord.product_id,
      scope: ctaRecord.scope,
      field: "offers",
      value: guruV185Text(ctaRecord.value),
      offer: { rational: "", irrational: "", social: "", cta: guruV185Text(ctaRecord.value), legacy_value: "" },
      source: { ...(ctaRecord.source || {}), migrated_from_id: ctaRecord.id },
      confirmation_status: ctaRecord.confirmation_status,
      created_at: ctaRecord.created_at,
      updated_at: new Date().toISOString(),
    };
    records.push(offerRecord);
    candidates.push(offerRecord);
    offersByLocation.set(key, candidates);
  });
  log.push({
    id: GURU_GATE0_OFFER_CTA_MIGRATION_V197,
    at: new Date().toISOString(),
    status: "completed_preserved_legacy_ctas",
    note: "Самостоятельные CTA сохранены и добавлены в карточки офферов без удаления прежних записей.",
  });
}

function guruV194Values(field, product, workspace = state) {
  return guruV194Resolve(field, product, workspace).records
    .map((record) => guruV185Text(record.value))
    .filter(Boolean);
}

function guruV194SyncLegacy(workspace = state) {
  if (!workspace?.project) return;
  const project = workspace.project;
  const categories = guruV185Registry(workspace);
  const products = guruV194Products(workspace);
  const offers = v121EnsureOffers(workspace);
  project.productScopedOverridesV194 = project.productScopedOverridesV194 && typeof project.productScopedOverridesV194 === "object"
    ? project.productScopedOverridesV194
    : {};

  categories.forEach((category) => {
    const categoryRef = { id: "", categoryId: category.id };
    const binding = guruV185Binding(category.id, workspace);
    // Старый binding адресует всю категорию и не умеет выразить продуктовые
    // варианты. Поэтому в него проецируем только category → project, а
    // индивидуальные overrides оставляем в productScopedOverridesV194.
    const scopedRecords = (field) => {
      const exact = guruV194ExactRecords(field, "category", categoryRef, workspace);
      return exact.length
        ? exact
        : guruV194ExactRecords(field, "project", null, workspace);
    };
    const value = (field) => scopedRecords(field)
      .map((record) => guruV185Text(record.value)).filter(Boolean);
    const uniqueValues = (values) => [...new Set(values.filter(Boolean))];
    const jtbds = value("jtbd");
    const segments = value("segments");
    const categoryOffers = value("offers");
    const ctas = uniqueValues([
      ...scopedRecords("offers").map((record) => guruV194OfferParts(record).cta),
      ...value("cta"),
    ]);
    binding.jtbd = jtbds[0] || "";
    binding.audiences = segments.map((text) => ({ text, shared: true, source: "gate0ScopedValuesV194" }));
    binding.offer = categoryOffers.join("\n");
    binding.cta = ctas.join("\n");
    project.productMainJtbds = project.productMainJtbds || {};
    project.productMainJtbds[category.name] = guruV185Text(binding.jtbd);
    offers.productOffers[category.name] = {
      ...(offers.productOffers[category.name] || {}),
      productId: category.id,
      offer: guruV185Text(binding.offer),
      cta: guruV185Text(binding.cta),
    };
  });

  products.forEach((product) => {
    const previousOverrides = project.productScopedOverridesV194[product.id] || {};
    project.productScopedOverridesV194[product.id] = Object.fromEntries(
      GURU_GATE0_SCOPE_FIELDS_V194.map(([field]) => {
        const resolved = guruV194Resolve(field, product, workspace);
        return [field, {
          project_id: guruV194ProjectId(workspace),
          category_id: guruV185Text(previousOverrides[field]?.category_id),
          product_id: product.id,
          inherited_from_scope: resolved.scope,
          record_ids: resolved.records.map((record) => record.id),
          values: resolved.records.map((record) => record.value),
        }];
      }),
    );
  });

  const projectRecords = (field) => guruV194ExactRecords(field, "project", null, workspace);
  const projectValue = (field) => projectRecords(field)
    .map((record) => guruV185Text(record.value)).filter(Boolean);
  const positioning = projectValue("positioning");
  const usp = projectValue("usp");
  const projectOffers = projectValue("offers");
  const projectCtas = [...new Set([
    ...projectRecords("offers").map((record) => guruV194OfferParts(record).cta),
    ...projectValue("cta"),
  ].filter(Boolean))];
  project.positioningStatement = positioning.join("\n");
  project.usp = usp.join("\n");
  project.currentOffers = projectOffers.join("\n");
  project.offer = project.currentOffers;
  project.currentCtas = projectCtas.join("\n");
  project.mainCta = project.currentCtas;
  workspace.sharedEvidence = workspace.sharedEvidence || {};
  workspace.sharedEvidence.positioning_statement = project.positioningStatement;
  workspace.sharedEvidence.usp = project.usp;
  workspace.sharedEvidence.current_offers = project.currentOffers;
  workspace.sharedEvidence.current_ctas = project.currentCtas;
}

function guruV194Ensure(workspace = state) {
  if (!workspace?.project) return [];
  guruV189EnsureCatalog(workspace);
  guruV194Migrate(workspace);
  guruV194MigrateOfferCtas(workspace);
  guruV194Records(workspace);
  guruV194SyncLegacy(workspace);
  return guruV194Products(workspace);
}

/* ================================================================
   ПРАВИЛО (v2.1.6, после трёх независимых рассинхронов — Gate 3
   «Маршрут 5A», Gate 4 «Стратегическая основа», Gate 0 «Посадочная» и
   «Продукт результатов»): guruV194Ui — ЕДИНСТВЕННЫЙ выбор текущего
   продукта/услуги на весь проект (selectedCategoryId/selectedProductId,
   уровень ПОЗИЦИИ — конкретный item из guruV194Products, а не категория
   из guruV185Registry).

   Любой новый экран, которому нужно «для какого продукта показываем
   данные» — ОБЯЗАН читать guruV194SelectedProduct(state) / писать через
   guruV194Ui(state). Заводить для этого свой собственный
   selectedProductId (как раньше делали gate3ProductJourneyV210 и
   gate4ProductPickV210) — запрещено: это и есть причина всех трёх
   рассинхронов выше. Привязка к категории (guruV185Binding/registry)
   допустима только как ЯВНОЕ осознанное исключение с комментарием,
   объясняющим, почему для этого конкретного случая позиция не подходит
   (а не как случайное следствие использования более старого API). */
function guruV194Ui(workspace = state) {
  const project = workspace.project;
  project.gate0ScopeUiV194 = project.gate0ScopeUiV194 && typeof project.gate0ScopeUiV194 === "object"
    ? project.gate0ScopeUiV194
    : {};
  project.gate0ScopeUiV194.scopeByProductField = project.gate0ScopeUiV194.scopeByProductField || {};
  const products = guruV194Products(workspace);
  const categories = guruV185Registry(workspace);
  const uncategorizedId = "__uncategorized__";
  const categoryIds = new Set(categories.map((item) => item.id));
  if (products.some((item) => !megaPlatformProductCategoryIds(item, workspace).length))
    categoryIds.add(uncategorizedId);
  const currentProduct = products.find((item) => item.id === project.gate0ScopeUiV194.selectedProductId);
  if (!categoryIds.has(project.gate0ScopeUiV194.selectedCategoryId)) {
    project.gate0ScopeUiV194.selectedCategoryId = currentProduct
      ? megaPlatformProductCategoryIds(currentProduct, workspace)[0] || uncategorizedId
      : categories.find((category) => products.some((product) =>
          megaPlatformProductCategoryIds(product, workspace).includes(category.id)))?.id
        || (products.some((product) => !megaPlatformProductCategoryIds(product, workspace).length)
          ? uncategorizedId : categories[0]?.id || "");
  }
  const selectedCategoryId = project.gate0ScopeUiV194.selectedCategoryId;
  const categoryProducts = products.filter((item) =>
    selectedCategoryId === uncategorizedId
      ? !megaPlatformProductCategoryIds(item, workspace).length
      : megaPlatformProductCategoryIds(item, workspace).includes(selectedCategoryId));
  if (!categoryProducts.some((item) => item.id === project.gate0ScopeUiV194.selectedProductId))
    project.gate0ScopeUiV194.selectedProductId = categoryProducts[0]?.id || "";
  return project.gate0ScopeUiV194;
}

function guruV194SelectedProduct(workspace = state) {
  guruV194Ensure(workspace);
  return guruV194Product(guruV194Ui(workspace).selectedProductId, workspace);
}

