function guruV247KeywordNormalize(value) {
  return guruV185Text(value)
    .toLocaleLowerCase("ru-RU")
    .replace(/ё/g, "е")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim()
    .replace(/\s+/g, " ");
}

function guruV247KeywordTokens(value) {
  return (guruV185Text(value).toLocaleLowerCase("ru-RU").match(/[\p{L}\p{N}]+(?:[-‑–—][\p{L}\p{N}]+)*/gu) || [])
    .map((word) => word.replace(/ё/g, "е"))
    .filter((word) => (word.length > 1 || /^\d+$/.test(word)) && !GURU_GATE0_KEYWORD_STOP_WORDS_V247.has(word));
}

function guruV247KeywordFingerprint(value) {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `v1-${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function guruV247KeywordSourceSnapshot(product, workspace = state) {
  const fields = GURU_GATE0_KEYWORD_SOURCE_FIELDS_V247.map((field) => {
    const resolved = guruV194Resolve(field, product, workspace);
    const values = resolved.records.map((record) => guruV185Text(record.value)).filter(Boolean);
    return { field, values };
  });
  const canonical = fields
    .map(({ field, values }) => `${field}\u241f${values.join("\u241e")}`)
    .join("\u241d");
  return {
    fields,
    texts: fields.flatMap(({ values }) => values),
    fingerprint: guruV247KeywordFingerprint(canonical),
  };
}

function guruV247KeywordCandidates(
  snapshot,
  existingKeywords = [],
  limit = 15,
) {
  const existing = new Set(
    existingKeywords.map(guruV247KeywordText).map(guruV247KeywordNormalize).filter(Boolean),
  );
  const candidates = new Map();
  let order = 0;
  snapshot.fields.forEach(({ field, values }) => {
    values.forEach((text) => {
      const words = guruV247KeywordTokens(text);
      for (let size = 2; size <= 4; size += 1) {
        for (let index = 0; index <= words.length - size; index += 1) {
          const value = words.slice(index, index + size).join(" ");
          const key = guruV247KeywordNormalize(value);
          if (!key || existing.has(key)) continue;
          const current = candidates.get(key) || {
            value,
            size,
            order: order++,
            occurrences: 0,
            fields: new Set(),
          };
          current.occurrences += 1;
          current.fields.add(field);
          candidates.set(key, current);
        }
      }
    });
  });
  const ranked = [...candidates.values()]
    .sort((left, right) =>
      right.fields.size - left.fields.size ||
      right.occurrences - left.occurrences ||
      Math.abs(left.size - 3) - Math.abs(right.size - 3) ||
      left.order - right.order);
  const bounded = limit === null || limit === Infinity
    ? ranked
    : ranked.slice(0, Math.max(0, Number(limit) || 0));
  return bounded
    .map(({ value }) => value);
}

