function guruV248CsvCell(value) {
  const text = String(value ?? "");
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

function guruV248KeywordFoundationCsv(keywords = []) {
  const rows = [["phrase", "source", "status"]];
  keywords
    .map((keyword) => guruV247KeywordEntry(keyword))
    .filter((keyword) => guruV247KeywordText(keyword))
    .forEach((keyword) => rows.push([
      guruV247KeywordText(keyword),
      keyword.source,
      keyword.status,
    ]));
  return rows.map((row) => row.map(guruV248CsvCell).join(",")).join("\r\n");
}

function guruV248CsvDelimiter(text) {
  const firstLine = String(text || "").replace(/^\uFEFF/, "").split(/\r?\n/, 1)[0] || "";
  const counts = { ",": 0, ";": 0, "\t": 0 };
  let quoted = false;
  for (let index = 0; index < firstLine.length; index += 1) {
    const character = firstLine[index];
    if (character === '"' && quoted && firstLine[index + 1] === '"') {
      index += 1;
      continue;
    }
    if (character === '"') quoted = !quoted;
    else if (!quoted && Object.hasOwn(counts, character)) counts[character] += 1;
  }
  return Object.entries(counts).sort((left, right) => right[1] - left[1])[0]?.[1]
    ? Object.entries(counts).sort((left, right) => right[1] - left[1])[0][0]
    : ",";
}

function guruV248ParseCsvRows(text, delimiter = guruV248CsvDelimiter(text)) {
  const source = String(text || "").replace(/^\uFEFF/, "");
  const rows = [];
  let row = [];
  let cell = "";
  let quoted = false;
  for (let index = 0; index < source.length; index += 1) {
    const character = source[index];
    const next = source[index + 1];
    if (character === '"' && quoted && next === '"') {
      cell += '"';
      index += 1;
    } else if (character === '"') {
      quoted = !quoted;
    } else if (character === delimiter && !quoted) {
      row.push(cell);
      cell = "";
    } else if ((character === "\n" || character === "\r") && !quoted) {
      if (character === "\r" && next === "\n") index += 1;
      row.push(cell);
      if (row.some((value) => guruV185Text(value))) rows.push(row);
      row = [];
      cell = "";
    } else {
      cell += character;
    }
  }
  row.push(cell);
  if (row.some((value) => guruV185Text(value))) rows.push(row);
  return rows;
}

function guruV248ParseKeywordCsv(text) {
  const rows = guruV248ParseCsvRows(text);
  if (!rows.length) return { format: "external", entries: [] };
  const header = rows[0].map((value) => guruV185Text(value).toLocaleLowerCase("ru-RU"));
  const ownFormat = header[0] === "phrase" && header[1] === "source" && header[2] === "status";
  const commonExternalHeaders = new Set([
    "phrase", "keyword", "keywords", "query", "фраза", "запрос", "ключевая фраза", "ключевое слово",
  ]);
  const dataRows = ownFormat || commonExternalHeaders.has(header[0]) ? rows.slice(1) : rows;
  const seen = new Set();
  const entries = [];
  dataRows.forEach((row) => {
    const phrase = guruV185Text(row[0]);
    const key = guruV247KeywordNormalize(phrase);
    if (!key || seen.has(key)) return;
    seen.add(key);
    const source = ownFormat && ["manual", "generated", "imported"].includes(guruV185Text(row[1]))
      ? guruV185Text(row[1])
      : "imported";
    const status = ownFormat && ["draft", "confirmed"].includes(guruV185Text(row[2]))
      ? guruV185Text(row[2])
      : "draft";
    entries.push(guruV247KeywordEntry({ value: phrase, source, status }, { source, status }));
  });
  return { format: ownFormat ? "guru" : "external", entries };
}

function guruV248KeywordFileName(product) {
  const slug = guruV185Text(product?.name)
    .toLocaleLowerCase("ru-RU")
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/g, "") || guruV185Text(product?.id) || "product";
  return `keyword-foundation-${slug}.csv`;
}

function guruKeywordFoundationApplyImportV257(
  record,
  parsed,
  mode,
  fileName = "",
  blockedKeywords = [],
) {
  if (!record || !parsed?.entries || !["add", "replace"].includes(mode))
    return { parsed: 0, added: 0, total: 0 };
  const blocked = new Set(
    blockedKeywords
      .map(guruV247KeywordText)
      .map(guruV247KeywordNormalize)
      .filter(Boolean),
  );
  const incoming = parsed.entries
    .map((entry) => guruV247KeywordEntry(entry))
    .filter(
      (entry) =>
        !blocked.has(
          guruV247KeywordNormalize(guruV247KeywordText(entry)),
        ),
    );
  let added = incoming.length;
  if (mode === "add") {
    const existing = new Set(
      record.keywords.map(guruV247KeywordText).map(guruV247KeywordNormalize).filter(Boolean),
    );
    const unique = incoming.filter((entry) => {
      const key = guruV247KeywordNormalize(guruV247KeywordText(entry));
      if (!key || existing.has(key)) return false;
      existing.add(key);
      return true;
    });
    record.keywords.push(...unique);
    added = unique.length;
  } else {
    record.keywords = incoming;
    delete record.last_generation;
  }
  const now = new Date().toISOString();
  record.last_import = {
    at: now,
    mode,
    format: parsed.format === "guru" ? "phrase,source,status" : "external-first-column",
    file_name: guruV185Text(fileName),
    parsed: incoming.length,
    added,
  };
  record.updated_at = now;
  return { parsed: incoming.length, added, total: record.keywords.length };
}

function guruV248ApplyKeywordImport(product, parsed, mode, fileName = "", workspace = state) {
  if (!product?.id) return { parsed: 0, added: 0, total: 0 };
  return guruKeywordFoundationApplyImportV257(
    guruV247KeywordFoundationRecord(product, true, workspace),
    parsed,
    mode,
    fileName,
  );
}

function guruKeywordFoundationGenerateV257(
  record,
  snapshot,
  blockedKeywords = [],
  exactPhrases = [],
  options = {},
) {
  if (!record || !snapshot) return [];
  record.keywords = Array.isArray(record.keywords) ? record.keywords : [];
  const blocked = [
    ...record.keywords,
    ...blockedKeywords,
  ];
  const seen = new Set(
    blocked
      .map(guruV247KeywordText)
      .map(guruV247KeywordNormalize)
      .filter(Boolean),
  );
  const requestedLimit = options.limit === null || options.limit === Infinity
    ? null
    : Math.max(0, Number(options.limit ?? 15) || 0);
  const exact = [];
  exactPhrases.forEach((phrase) => {
    const value = guruV185Text(phrase);
    const key = guruV247KeywordNormalize(value);
    if (
      !key ||
      seen.has(key) ||
      (requestedLimit !== null && exact.length >= requestedLimit)
    )
      return;
    seen.add(key);
    exact.push(value);
  });
  const remaining = requestedLimit === null
    ? null
    : Math.max(0, requestedLimit - exact.length);
  const generated = guruV247KeywordCandidates(snapshot, [
    ...blocked,
    ...exact,
  ], remaining);
  const values = [...exact, ...generated];
  const now = new Date().toISOString();
  values.forEach((value) =>
    record.keywords.push(
      guruV247KeywordEntry({
        value,
        source: "generated",
        status: "draft",
        strategy_fingerprint: snapshot.fingerprint,
        generated_at: now,
      }),
    ),
  );
  record.last_generation = {
    at: now,
    added: values.length,
    strategy_fingerprint: snapshot.fingerprint,
  };
  record.updated_at = now;
  return values;
}

