/* Keyword-foundation controls used array indexes as their primary identity.
   After a row refresh an index can already point at another candidate, and
   replacing the focused list can also send the document viewport to the top.
   Resolve mutations by the stable row id and restore the user's viewport and
   keyboard position after any targeted refresh. The numeric attributes remain
   only as a compatibility fallback for old string-only entries. */
function guruKeywordFoundationEntryIndexV353(
  record,
  control,
  legacyDatasetKey,
) {
  const keywords = Array.isArray(record?.keywords) ? record.keywords : [];
  const rowId = guruV185Text(
    control?.closest?.("[data-keyword-foundation-row-v257]")
      ?.dataset?.keywordFoundationRowV257,
  );
  if (rowId) {
    const stableIndex = keywords.findIndex((entry) =>
      guruV185Text(entry?.id) === rowId);
    if (stableIndex >= 0) return stableIndex;
  }
  const legacyIndex = Number(control?.dataset?.[legacyDatasetKey]);
  return Number.isInteger(legacyIndex) && legacyIndex >= 0 && legacyIndex < keywords.length
    ? legacyIndex
    : -1;
}

function guruKeywordFoundationCaptureViewV353(control) {
  if (!control) return null;
  const row = control.closest?.("[data-keyword-foundation-row-v257]");
  const siblings = row
    ? [...row.parentElement.children].filter((entry) =>
        entry.matches?.("[data-keyword-foundation-row-v257]"))
    : [];
  const rowIndex = row ? siblings.indexOf(row) : -1;
  const scrollParents = [];
  for (
    let element = control.parentElement;
    element && element !== document.body;
    element = element.parentElement
  ) {
    if (
      element.scrollHeight > element.clientHeight + 1 ||
      element.scrollWidth > element.clientWidth + 1
    ) {
      scrollParents.push({
        element,
        top: element.scrollTop,
        left: element.scrollLeft,
      });
    }
  }
  const actionAttribute = control.getAttributeNames?.().find((name) =>
    /^data-.*keyword.*-(?:input|confirm|remove)$/.test(name)) || "";
  return {
    windowX: window.scrollX,
    windowY: window.scrollY,
    scrollParents,
    rowId: guruV185Text(row?.dataset?.keywordFoundationRowV257),
    nextRowId: guruV185Text(
      siblings[rowIndex + 1]?.dataset?.keywordFoundationRowV257,
    ),
    previousRowId: guruV185Text(
      siblings[rowIndex - 1]?.dataset?.keywordFoundationRowV257,
    ),
    actionAttribute,
    restoreFocus: document.activeElement === control,
  };
}

function guruKeywordFoundationRestoreViewV353(snapshot) {
  if (!snapshot) return;
  const restoreScroll = () => {
    snapshot.scrollParents.forEach(({ element, top, left }) => {
      if (!element.isConnected) return;
      element.scrollTop = top;
      element.scrollLeft = left;
    });
    window.scrollTo(snapshot.windowX, snapshot.windowY);
  };
  restoreScroll();
  if (snapshot.restoreFocus && snapshot.actionAttribute) {
    const rows = [...document.querySelectorAll(
      "[data-keyword-foundation-row-v257]",
    )];
    const targetRow = [
      snapshot.rowId,
      snapshot.nextRowId,
      snapshot.previousRowId,
    ].filter(Boolean).map((rowId) => rows.find((row) =>
      row.dataset.keywordFoundationRowV257 === rowId)).find(Boolean);
    targetRow?.querySelector(`[${snapshot.actionAttribute}]`)?.focus({
      preventScroll: true,
    });
    restoreScroll();
  }
  requestAnimationFrame(restoreScroll);
}

