function guruMigrateCompanySegmentUnifiedV352(workspace = state) {
  const initialRecord = guruV309ProjectSegmentRecord(workspace, false);
  if (!initialRecord) return { status: "not_applicable", removedDrafts: 0 };
  const previousMigration = initialRecord.company_segment_unified_migration_v352;
  if (["cleared_legacy_autotext", "reviewed_manual"].includes(previousMigration?.status))
    return { status: previousMigration.status, removedDrafts: 0 };

  const currentValue = guruCompanySegmentMigrationTextV352(initialRecord.value);
  if (!currentValue) return { status: "not_applicable", removedDrafts: 0 };
  const reconstructed = guruCompanySegmentMigrationTextV352(
    guruCompanyLegacySegmentAutotextV352(initialRecord),
  );
  const exactLegacyAutotext = Boolean(reconstructed) && currentValue === reconstructed;
  const markerCount = guruCompanyLegacySegmentMarkerCountV352(currentValue);
  if (!exactLegacyAutotext && markerCount < 2)
    return { status: "not_applicable", removedDrafts: 0 };

  const now = new Date().toISOString();
  if (!exactLegacyAutotext) {
    initialRecord.company_segment_unified_migration_v352 = {
      id: GURU_GATE0_COMPANY_SEGMENT_UNIFIED_MIGRATION_V352,
      status: "needs_review",
      detected_at: now,
      marker_count: markerCount,
    };
    initialRecord.updated_at = now;
    return { status: "needs_review", removedDrafts: 0 };
  }

  const badFingerprint = guruCompanyKeywordSourceSnapshotV351(workspace).fingerprint;
  const record = guruV309ProjectSegmentRecord(workspace, false);
  record.company_segment_unified_migration_v352 = {
    id: GURU_GATE0_COMPANY_SEGMENT_UNIFIED_MIGRATION_V352,
    status: "cleared_legacy_autotext",
    migrated_at: now,
    archived_value: currentValue,
    bad_strategy_fingerprint: badFingerprint,
  };
  record.value = "";
  record.updated_at = now;

  const foundation = guruCompanyKeywordFoundationRecordV351(workspace, false);
  const keywords = Array.isArray(foundation?.keywords) ? foundation.keywords : [];
  const removed = [];
  const kept = [];
  keywords.forEach((keyword) => {
    const entry = guruV247KeywordEntry(keyword);
    if (
      entry.source === "generated" &&
      entry.status === "draft" &&
      guruV185Text(entry.strategy_fingerprint) === badFingerprint
    ) {
      removed.push(entry);
    } else {
      kept.push(entry);
    }
  });
  if (foundation && removed.length) {
    foundation.keywords = kept;
    foundation.keyword_draft_archive_v352 = [
      ...(Array.isArray(foundation.keyword_draft_archive_v352)
        ? foundation.keyword_draft_archive_v352
        : []),
      ...removed.map((entry) => ({
        ...entry,
        archived_at: now,
        archived_reason: "legacy_company_segment_autotext",
      })),
    ];
    foundation.updated_at = now;
  }

  const project = workspace?.project;
  if (project) {
    project._gate0CompanyMigrationLogV352 = Array.isArray(
      project._gate0CompanyMigrationLogV352,
    )
      ? project._gate0CompanyMigrationLogV352
      : [];
    if (!project._gate0CompanyMigrationLogV352.some(
      (entry) => entry.id === GURU_GATE0_COMPANY_SEGMENT_UNIFIED_MIGRATION_V352,
    )) {
      project._gate0CompanyMigrationLogV352.push({
        id: GURU_GATE0_COMPANY_SEGMENT_UNIFIED_MIGRATION_V352,
        at: now,
        status: "completed",
        segment_record_id: record.id,
        bad_strategy_fingerprint: badFingerprint,
        removed_company_drafts: removed.length,
      });
    }
  }
  return { status: "cleared_legacy_autotext", removedDrafts: removed.length };
}

function guruCompanyKeywordCandidatesBalancedV352(
  snapshot,
  existingKeywords = [],
  limit = 15,
  requestedMinimum = 2,
) {
  const existing = new Set(
    existingKeywords.map(guruV247KeywordText).map(guruV247KeywordNormalize).filter(Boolean),
  );
  const candidates = new Map();
  let order = 0;
  snapshot.fields.forEach(({ field, values }) => {
    values.forEach((text) => {
      const words = guruV247KeywordTokens(text);
      for (let size = 2; size <= 4; size += 1) {
        for (let index = 0; index <= words.length - size; index += 1) {
          const value = words.slice(index, index + size).join(" ");
          const key = guruV247KeywordNormalize(value);
          if (!key || existing.has(key)) continue;
          const current = candidates.get(key) || {
            key,
            value,
            size,
            order: order++,
            occurrences: 0,
            fields: new Set(),
          };
          current.occurrences += 1;
          current.fields.add(field);
          candidates.set(key, current);
        }
      }
    });
  });
  const ranked = [...candidates.values()].sort((left, right) =>
    right.fields.size - left.fields.size ||
    right.occurrences - left.occurrences ||
    Math.abs(left.size - 3) - Math.abs(right.size - 3) ||
    left.order - right.order);
  const boundedLimit = Math.max(0, Number(limit) || 0);
  const sourceFields = snapshot.fields
    .filter(({ field, values }) =>
      values.some((value) => guruV247KeywordTokens(value).length >= 2) &&
      ranked.some((candidate) => candidate.fields.has(field)))
    .map(({ field }) => field);
  const minimum = sourceFields.length
    ? Math.min(
        Math.max(0, Number(requestedMinimum) || 0),
        Math.floor(boundedLimit / sourceFields.length),
      )
    : 0;
  const selected = [];
  const selectedKeys = new Set();
  const select = (candidate, ownerField) => {
    if (!candidate || selectedKeys.has(candidate.key) || selected.length >= boundedLimit)
      return false;
    selectedKeys.add(candidate.key);
    selected.push({
      value: candidate.value,
      ownerField,
      fields: [...candidate.fields],
    });
    return true;
  };
  for (let round = 0; round < minimum; round += 1) {
    sourceFields.forEach((field) => {
      const candidate = ranked.find((item) =>
        item.fields.has(field) && !selectedKeys.has(item.key));
      select(candidate, field);
    });
  }
  ranked.forEach((candidate) => {
    if (selected.length >= boundedLimit) return;
    select(candidate, [...candidate.fields][0] || "");
  });
  return selected;
}

function guruCompanyKeywordFoundationGenerateV352(
  record,
  snapshot,
  options = {},
) {
  if (
    !record ||
    !snapshot ||
    options.selectionMode !== "balanced_sources"
  )
    return [];
  record.keywords = Array.isArray(record.keywords) ? record.keywords : [];
  const selected = guruCompanyKeywordCandidatesBalancedV352(
    snapshot,
    record.keywords,
    options.limit ?? 15,
    options.minimumPerSource ?? 2,
  );
  const now = new Date().toISOString();
  selected.forEach(({ value, ownerField, fields }) => {
    record.keywords.push(
      guruV247KeywordEntry({
        value,
        source: "generated",
        status: "draft",
        strategy_fingerprint: snapshot.fingerprint,
        strategy_source_field: ownerField,
        strategy_source_fields: fields,
        generated_at: now,
      }),
    );
  });
  const sourceCoverage = Object.fromEntries(
    GURU_GATE0_COMPANY_KEYWORD_SOURCE_FIELDS_V351.map((field) => [
      field,
      selected.filter((candidate) => candidate.ownerField === field).length,
    ]),
  );
  record.last_generation = {
    at: now,
    added: selected.length,
    strategy_fingerprint: snapshot.fingerprint,
    selection_mode: options.selectionMode,
    source_coverage: sourceCoverage,
  };
  record.updated_at = now;
  return selected.map(({ value }) => value);
}

function guruCompanyKeywordFoundationStatsV351(workspace = state) {
  const record = guruCompanyKeywordFoundationRecordV351(workspace, false);
  const keywords = (record?.keywords || []).map((keyword) =>
    guruV247KeywordEntry(keyword));
  const filled = keywords.filter((keyword) => guruV247KeywordText(keyword));
  return {
    record,
    total: filled.length,
    confirmed: filled.filter((keyword) => keyword.status === "confirmed").length,
    draft: filled.filter((keyword) => keyword.status === "draft").length,
  };
}

function guruCompanyKeywordConfirmedModelV351(workspace = state) {
  const record = guruCompanyKeywordFoundationRecordV351(workspace, false);
  const seen = new Set();
  const entries = [];
  const duplicates = [];
  (record?.keywords || []).forEach((keyword, sourceIndex) => {
    const entry = guruV247KeywordEntry(keyword);
    const text = guruV247KeywordText(entry);
    const key = guruV247KeywordNormalize(text);
    if (entry.status !== "confirmed" || !key) return;
    const candidate = {
      id: entry.id,
      value: text,
      key,
      sourceIndex,
      source: entry.source,
    };
    if (seen.has(key)) {
      duplicates.push(candidate);
      return;
    }
    seen.add(key);
    entries.push(candidate);
  });
  return { entries, duplicates };
}

