function guruV247EnsureKeywordFoundationLog(workspace = state) {
  if (!workspace?.project) return;
  const log = (workspace.project._gate0ProductIdMigrationLog = Array.isArray(
    workspace.project._gate0ProductIdMigrationLog,
  ) ? workspace.project._gate0ProductIdMigrationLog : []);
  if (!log.some((entry) => entry.id === GURU_GATE0_KEYWORD_FOUNDATION_V247)) {
    log.push({
      id: GURU_GATE0_KEYWORD_FOUNDATION_V247,
      at: new Date().toISOString(),
      status: "completed",
      storage: "project.gate0ScopedValuesV194[field=keyword_foundation][product_id].keywords[]",
      sourceFields: [...GURU_GATE0_KEYWORD_SOURCE_FIELDS_V247],
      generation: "manual button; 2–4 word n-grams; stop words removed; maximum 15 new unique candidates per run",
      note: "Фундамент ключевых слов изолирован от painV130/Gate 1; записи хранятся только по product_id.",
    });
  }
  if (!log.some((entry) => entry.id === GURU_GATE0_KEYWORD_CSV_V248)) {
    log.push({
      id: GURU_GATE0_KEYWORD_CSV_V248,
      at: new Date().toISOString(),
      status: "completed",
      storage: "project.gate0ScopedValuesV194[field=keyword_foundation][product_id].keywords[]",
      format: "CSV phrase,source,status",
      import: "add with case-insensitive deduplication or replace with confirmed-data warning",
      note: "Импорт и экспорт работают только с выбранным product_id; painV130/Gate 1 не изменяются.",
    });
  }
}

