function g3ProductJourneyPageSource(product) {
  const cards = (state?.gates || []).flatMap((gate) => gate.cards || []);
  const source = product?.source || {};
  const sourceCard = source.cardId ? cards.find((card) => card.id === source.cardId) : null;
  // A saved rowIndex can point at another product after rows are reordered.
  // The live product_id always wins; old row hints only recover unbound rows.
  for (const card of [sourceCard, ...cards].filter(Boolean)) {
    const row = (card.pageRows || []).find((item) =>
      guruV185Text(item.catalogItemIdV189) === guruV185Text(product?.id));
    if (row) return { card, row };
  }
  const sourceRows = sourceCard?.pageRows || [];
  const legacyById = source.rowId
    ? sourceRows.find((row) => guruV185Text(row.id) === guruV185Text(source.rowId) &&
      !guruV185Text(row.catalogItemIdV189))
    : null;
  if (legacyById) return { card: sourceCard, row: legacyById };
  const legacyIndex = Number(source.rowIndex);
  if (sourceCard && source.rowIndex !== undefined && Number.isInteger(legacyIndex) &&
      legacyIndex >= 0 && !guruV185Text(sourceRows[legacyIndex]?.catalogItemIdV189))
    return { card: sourceCard, row: sourceRows[legacyIndex] };
  return { card: null, row: null };
}

