    keywordFoundationItems: (keywordFoundation.record?.keywords || [])
      .map((keyword) => guruV247KeywordEntry(keyword))
      .filter((keyword) => guruV247KeywordText(keyword)),
    middleKeywordFoundation: middleKeywordFoundation.total
      ? `${middleKeywordFoundation.total} предложено, ${middleKeywordFoundation.confirmed} подтверждено`
      : "",
    middleKeywordFoundationItems: middleKeywordFoundation.keywords,
