  patch(
    "Реклама готова",
    campaigns.some((campaign) =>
      [campaign?.decision, campaign?.campaignName, campaign?.launchStatus].some(
        guruV185Text,
      ),
    ),
    "Gate 4 → Кампании выбранного product_id",
    "gate-4",
  );
  result.ready = result.checks.filter((item) => item.passed).length;
  result.total = result.checks.length;
