g8ApplyManualToProject = function () {
  const product = guruV194SelectedProduct(state);
  const data = ensureGate8Workspace();
  if (!product) {
    data.message = "Продукт не выбран.";
    saveState();
    renderGate();
    return;
  }
  const manual = data.manual || {};
  const production = (state.gate4Production = state.gate4Production || {});
  production.forecastAssumptionsByProduct =
    production.forecastAssumptionsByProduct || {};
  const plan = (production.forecastAssumptionsByProduct[product.id] = {
    ...(production.forecastAssumptionsByProduct[product.id] || {}),
    product_id: product.id,
    updatedAt: new Date().toISOString(),
  });
  const applied = [];
  [
    "budget",
    "cpl",
    "demandChange",
    "cpc",
    "ctr",
    "siteConversion",
    "saleConversion",
    "termDays",
    "taskReadiness",
  ].forEach((key) => {
    if (g8Text(manual[key]) === "") return;
    plan[key] = String(manual[key]);
    applied.push(`${key} → Gate 4 (${product.name})`);
  });
  const economics = gate8ExactEconomicsV230(product.id);
  if (economics.item) {
    economics.item.steps = economics.item.steps || {};
    economics.item.steps.revenue = economics.item.steps.revenue || {};
    economics.item.steps.margin = economics.item.steps.margin || {};
    if (g8Text(manual.averageCheck) !== "") {
      economics.item.steps.revenue.avgCheck = String(manual.averageCheck);
      applied.push(`средний чек → Gate 1 (${product.name})`);
    }
    if (g8Text(manual.margin) !== "") {
      economics.item.steps.margin.marginPct = String(manual.margin);
      applied.push(`маржинальность → Gate 1 (${product.name})`);
    }
  }
  data.message = applied.length
    ? `Применено: ${applied.join("; ")}. Фактические данные Gate 5 не изменялись.`
    : "Нет значений, для которых в исходных Gate есть редактируемое плановое поле.";
  saveState();
  renderGate();
};

g8CreateTask = function () {
  const product = guruV194SelectedProduct(state);
  if (!product) return;
  const analysis = g8Analysis();
  const g7 = ensureGate7State();
  const signature = `${analysis.action.title}|${analysis.action.where}|${analysis.goal.deadline}`;
  if (analysis.data.linkedTasks.some((item) => item.signature === signature))
    return;
  const task = {
    id: makeId("g7-task"),
    product_id: product.id,
    task: analysis.action.title,
    where: analysis.action.where,
    date: /^\d{4}-\d{2}-\d{2}$/.test(analysis.goal.deadline)
      ? analysis.goal.deadline
      : "",
    result: "",
    status: "not_started",
    sectionId: "new",
    order: typeof gate7InsertAtTop === "function" ? gate7InsertAtTop("new") : 0,
    createdAt: new Date().toISOString(),
    priority: "Высокий",
    readinessCriterion: analysis.action.criterion,
    sourceProblem: analysis.risks[0]?.title || analysis.action.title,
    forecastLink: {
      gate: "gate-8",
      product_id: product.id,
      forecastId: analysis.data.history.at(-1)?.id || "",
      scenario: "base",
      metric: analysis.metric,
    },
  };
  g7.tasks.push(task);
  analysis.data.linkedTasks.push({
    signature,
    taskId: task.id,
    product_id: product.id,
    createdAt: task.createdAt,
  });
  analysis.data.message = "Задача создана в Gate 7 и связана с прогнозом продукта.";
  saveState();
  renderGate();
};

