/* ================================================================
   v2.3.7 — Gate 1 / painV130: товарная семантика по product_id.

   Внешняя строка productMaps по-прежнему описывает направление и хранит
   его брендовую семантику. Единственный ключ ВНУТРИ row.items теперь —
   стабильный catalogItemsV189[].id. Старые page-* ключи используются
   только один раз для точного сопоставления через source.rowId, после
   чего их снимки остаются в legacyPageItemsV237 и не участвуют в runtime.
   Никакого fallback по странице, названию или количеству товаров нет. */
const GATE1_PAIN_PRODUCT_ID_STORAGE_V237 =
  "gate1-pain-product-id-storage-v237";
const GATE1_PAIN_SHIRT_PRODUCT_ID_V237 =
  "catalog-item-1786792591872-c8b1e9";
const GATE1_PAIN_SHIRT_MAIN_QUERY_V237 =
  "рубашка с кружевными вставками";

function gate1PainHasDataV237(value, ignoredKeys = new Set()) {
  if (Array.isArray(value))
    return value.some((item) => gate1PainHasDataV237(item, ignoredKeys));
  if (value && typeof value === "object")
    return Object.entries(value).some(
      ([key, item]) =>
        !ignoredKeys.has(key) && gate1PainHasDataV237(item, ignoredKeys),
    );
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return true;
  return value !== null && value !== undefined && String(value).trim() !== "";
}

function gate1PainIsBlankV237(value) {
  if (value === undefined || value === null) return true;
  if (typeof value === "string") return !value.trim();
  if (Array.isArray(value) || (value && typeof value === "object"))
    return !gate1PainHasDataV237(value, new Set(["product_id"]));
  return false;
}

function gate1PainMergePreferredV237(target, source, conflicts, path = "") {
  Object.entries(source || {}).forEach(([key, sourceValue]) => {
    if (key === "product_id") return;
    const fieldPath = path ? `${path}.${key}` : key;
    const targetValue = target[key];
    if (gate1PainIsBlankV237(targetValue)) {
      target[key] = structuredClone(sourceValue);
      return;
    }
    if (
      targetValue &&
      sourceValue &&
      typeof targetValue === "object" &&
      typeof sourceValue === "object" &&
      !Array.isArray(targetValue) &&
      !Array.isArray(sourceValue)
    ) {
      gate1PainMergePreferredV237(
        targetValue,
        sourceValue,
        conflicts,
        fieldPath,
      );
      return;
    }
    if (
      !gate1PainIsBlankV237(sourceValue) &&
      JSON.stringify(targetValue) !== JSON.stringify(sourceValue)
    )
      conflicts.push(fieldPath);
  });
  return target;
}

function gate1PainSyncQueryMirrorV237(itemData) {
  if (!itemData || !Array.isArray(itemData.semL3Groups)) return;
  itemData.semL3 = itemData.semL3Groups
    .flatMap((group) => [
      String(group?.mainQuery || "").trim(),
      ...(Array.isArray(group?.keywords) ? group.keywords : []).map((keyword) =>
        pv181KeywordText(keyword).trim(),
      ),
    ])
    .filter(Boolean);
  if (!itemData.semL3.length) itemData.semL3 = [""];
}

function gate1PainNormalizeShirtQueriesV237(itemData) {
  if (!itemData || !Array.isArray(itemData.semL3Groups))
    return { changed: false };
  const group = itemData.semL3Groups[0];
  if (!group) return { changed: false };
  const mainLines = String(group.mainQuery || "")
    .split(/\r?\n/)
    .map((value) => value.trim())
    .filter(Boolean);
  if (mainLines.length <= 1) return { changed: false };

  const preferredIndex = mainLines.findIndex(
    (value) =>
      value.toLocaleLowerCase("ru-RU") ===
      GATE1_PAIN_SHIRT_MAIN_QUERY_V237.toLocaleLowerCase("ru-RU"),
  );
  if (preferredIndex < 0) {
    return {
      changed: false,
      openQuestion:
        "Многострочный mainQuery найден, но согласованный центральный запрос отсутствует; значение сохранено без автоматического выбора.",
      queries: mainLines,
    };
  }

  const mainQuery = mainLines[preferredIndex];
  const ordered = [
    ...mainLines.filter((_, index) => index !== preferredIndex),
    ...(Array.isArray(group.keywords)
      ? group.keywords.map(pv181KeywordText)
      : []),
  ];
  const seen = new Set([mainQuery.toLocaleLowerCase("ru-RU")]);
  const keywords = ordered.filter((value) => {
    const text = String(value || "").trim();
    const key = text.toLocaleLowerCase("ru-RU");
    if (!text || seen.has(key)) return false;
    seen.add(key);
    return true;
  }).map((value) => String(value).trim());
  const before = {
    mainQuery: group.mainQuery,
    keywords: Array.isArray(group.keywords)
      ? structuredClone(group.keywords)
      : [],
  };
  group.mainQuery = mainQuery;
  group.keywords = keywords;
  gate1PainSyncQueryMirrorV237(itemData);
  return {
    changed: true,
    before,
    after: { mainQuery, keywords: structuredClone(keywords) },
    reason:
      "Выбран запрос без транзакционного и дизайнерского уточнения: он точнее всего выражает общее ядро всех десяти фраз.",
  };
}

function gate1PainCatalogMapsV237(workspace) {
  const products = guruV194Products(workspace);
  const byId = new Map(products.map((product) => [product.id, product]));
  const bySourceRowId = new Map();
  products.forEach((product) => {
    const sourceRowId = guruV185Text(product?.source?.rowId);
    if (sourceRowId) bySourceRowId.set(sourceRowId, product);
  });
  const pageRowsById = new Map();
  guruV188PositionRows(workspace).forEach(({ card, row, index }) => {
    const rowId = guruV185Text(row?.id);
    if (rowId) pageRowsById.set(rowId, { card, row, index });
  });
  return { products, byId, bySourceRowId, pageRowsById };
}

function gate1PainMappedProductV237(
  sourceKey,
  itemData,
  maps,
) {
  if (maps.byId.has(sourceKey)) return maps.byId.get(sourceKey);
  const explicitId = guruV185Text(itemData?.product_id);
  if (maps.byId.has(explicitId)) return maps.byId.get(explicitId);
  const bySource = maps.bySourceRowId.get(sourceKey);
  if (bySource) return bySource;
  const pageRow = maps.pageRowsById.get(sourceKey)?.row;
  const pageProductId = guruV185Text(pageRow?.catalogItemIdV189);
  return maps.byId.get(pageProductId) || null;
}

function gate1PainCategoryIdV237(row, workspace) {
  const linked = guruV185ProductById(guruV185Text(row?.product_id), workspace);
  if (linked) return linked.id;
  return guruV185ProductByName(guruV185Text(row?.product), workspace)?.id || "";
}

function gate1PainArchiveLegacyV237(
  row,
  sourceKey,
  itemData,
  productId,
  reason,
  workspace,
) {
  row.legacyPageItemsV237 =
    row.legacyPageItemsV237 &&
    typeof row.legacyPageItemsV237 === "object" &&
    !Array.isArray(row.legacyPageItemsV237)
      ? row.legacyPageItemsV237
      : {};
  let archiveKey = sourceKey;
  if (row.legacyPageItemsV237[archiveKey]) {
    if (reason !== "catalog_product_belongs_to_another_category")
      return false;
    let moveNumber = 2;
    while (row.legacyPageItemsV237[
      `${sourceKey}::category-move-${moveNumber}`
    ]) moveNumber += 1;
    archiveKey = `${sourceKey}::category-move-${moveNumber}`;
  }
  const previousSequence = Number(
    workspace?.project?._gate1PainArchiveSequenceV521,
  ) || 0;
  const archivedSequence = (workspace?.painV130?.productMaps || [])
    .flatMap((item) => Object.values(item?.legacyPageItemsV237 || {}))
    .reduce((max, item) => Math.max(max,
      Number(item?.archive_sequence_v521) || 0), previousSequence);
  const archiveSequence = archivedSequence + 1;
  if (workspace?.project)
    workspace.project._gate1PainArchiveSequenceV521 = archiveSequence;
  row.legacyPageItemsV237[archiveKey] = {
    source_key: sourceKey,
    mapped_product_id: productId || "",
    reason,
    archived_at: new Date().toISOString(),
    archive_sequence_v521: archiveSequence,
    data: structuredClone(itemData || {}),
  };
  return true;
}

function gate1PainMigrateWorkspaceV237(workspace) {
  if (!workspace?.project) return { changed: false, mappings: [] };
  const productMaps = Array.isArray(workspace?.painV130?.productMaps)
    ? workspace.painV130.productMaps
    : [];
  const maps = gate1PainCatalogMapsV237(workspace);
  const mappings = [];
  const canonicalCreated = [];
  const archivedUnmatched = [];
  const relocatedCategoryItems = [];
  const movedActiveProducts = new Set();
  const conflicts = [];
  const shirtNormalizations = [];
  let changed = false;

  productMaps.forEach((row, rowIndex) => {
    if (!row || typeof row !== "object") return;
    const categoryId = gate1PainCategoryIdV237(row, workspace);
    const sourceItems =
      row.items && typeof row.items === "object" && !Array.isArray(row.items)
        ? row.items
        : {};
    const nextItems = {};

    Object.entries(sourceItems).forEach(([sourceKey, sourceData]) => {
      const product = gate1PainMappedProductV237(
        guruV185Text(sourceKey),
        sourceData,
        maps,
      );
      if (!product || (categoryId && !megaPlatformProductCategoryIds(product, workspace)
        .includes(categoryId))) {
        if (product) movedActiveProducts.add(product.id);
        if (
          gate1PainArchiveLegacyV237(
            row,
            sourceKey,
            sourceData,
            product?.id || "",
            product
              ? "catalog_product_belongs_to_another_category"
              : "catalog_product_not_found",
            workspace,
          )
        )
          changed = true;
        archivedUnmatched.push({
          row: rowIndex,
          direction: guruV185Text(row.product),
          sourceKey,
          hasData: gate1PainHasDataV237(
            sourceData,
            new Set(["product_id"]),
          ),
        });
        return;
      }

      const productId = product.id;
      const incoming = structuredClone(sourceData || {});
      incoming.product_id = productId;
      if (!nextItems[productId]) nextItems[productId] = incoming;
      else {
        const itemConflicts = [];
        gate1PainMergePreferredV237(
          nextItems[productId],
          incoming,
          itemConflicts,
        );
        if (itemConflicts.length)
          conflicts.push({
            row: rowIndex,
            direction: guruV185Text(row.product),
            product_id: productId,
            sourceKey,
            fields: itemConflicts,
          });
      }
      nextItems[productId].product_id = productId;

      if (sourceKey !== productId) {
        if (
          gate1PainArchiveLegacyV237(
            row,
            sourceKey,
            sourceData,
            productId,
            "migrated_to_product_id",
            workspace,
          )
        )
          changed = true;
        mappings.push({
          row: rowIndex,
          direction: guruV185Text(row.product),
          sourceKey,
          product_id: productId,
          product: product.name,
        });
      }
    });

    maps.products
      .filter((product) => megaPlatformProductCategoryIds(product, workspace).includes(categoryId))
      .forEach((product) => {
        if (!nextItems[product.id]) {
          nextItems[product.id] = { product_id: product.id };
          canonicalCreated.push({
            row: rowIndex,
            direction: guruV185Text(row.product),
            product_id: product.id,
            product: product.name,
          });
        }
        nextItems[product.id].product_id = product.id;
      });

    const shirtData = nextItems[GATE1_PAIN_SHIRT_PRODUCT_ID_V237];
    if (shirtData) {
      const normalized = gate1PainNormalizeShirtQueriesV237(shirtData);
      if (normalized.changed || normalized.openQuestion)
        shirtNormalizations.push(normalized);
      if (normalized.changed) changed = true;
    }

    if (JSON.stringify(sourceItems) !== JSON.stringify(nextItems)) {
      row.items = nextItems;
      changed = true;
    }
  });

  // Reattach data after a category move. Older snapshots stay in the
  // archive; only the newest snapshot for a product is projected back into
  // its current category. A replay marker prevents an old snapshot from
  // refilling fields that a user intentionally clears later.
  const categoryMoveArchives = new Map();
  let archiveOrder = 0;
  productMaps.forEach((sourceRow, sourceRowIndex) => {
    Object.entries(sourceRow?.legacyPageItemsV237 || {}).forEach(
      ([archiveKey, archived]) => {
        if (archived?.reason !== "catalog_product_belongs_to_another_category")
          return;
        const product = maps.byId.get(guruV185Text(archived.mapped_product_id)) ||
          gate1PainMappedProductV237(
            guruV185Text(archived.source_key) || archiveKey,
            archived.data,
            maps,
          );
        if (!product) return;
        const candidates = categoryMoveArchives.get(product.id) || [];
        candidates.push({
          archived,
          archiveKey,
          sourceRowIndex,
          order: archiveOrder++,
        });
        categoryMoveArchives.set(product.id, candidates);
      },
    );
  });
  categoryMoveArchives.forEach((candidates, productId) => {
    const product = maps.byId.get(productId);
    if (!product) return;
    candidates.sort((left, right) =>
      (Number(right.archived.archive_sequence_v521) || 0) -
      (Number(left.archived.archive_sequence_v521) || 0) ||
      guruV185Text(right.archived.archived_at).localeCompare(
        guruV185Text(left.archived.archived_at),
      ) || right.order - left.order,
    );
    const latest = candidates[0];
    megaPlatformProductCategoryIds(product, workspace).forEach((categoryId) => {
      const unprocessed = candidates.filter(({ archived }) =>
        !archived.replayedCategoryIdsV521?.includes(categoryId),
      );
      if (!unprocessed.length) return;
      let targetRow = productMaps.find((candidate) =>
        gate1PainCategoryIdV237(candidate, workspace) === categoryId,
      );
      if (!targetRow) {
        const category = guruV185ProductById(categoryId, workspace);
        if (!category) return;
        targetRow = {
          ...pv140EmptyProductMap(""),
          product: category.name,
          product_id: categoryId,
          items: {},
        };
        productMaps.push(targetRow);
        changed = true;
      }
      targetRow.items = targetRow.items && typeof targetRow.items === "object" &&
        !Array.isArray(targetRow.items) ? targetRow.items : {};
      const current = targetRow.items[productId];
      const currentHasData = gate1PainHasDataV237(
        current, new Set(["product_id"]),
      );
      // Existing edits at the destination win over an old archived copy.
      // A freshly moved active record may still fill missing fields there.
      if (!currentHasData || movedActiveProducts.has(productId)) {
        const before = JSON.stringify(current);
        const incoming = structuredClone(latest.archived.data || {});
        incoming.product_id = productId;
        if (!current) targetRow.items[productId] = incoming;
        else {
          const itemConflicts = [];
          gate1PainMergePreferredV237(current, incoming, itemConflicts);
          if (itemConflicts.length) conflicts.push({
            row: productMaps.indexOf(targetRow),
            direction: guruV185Text(targetRow.product),
            product_id: productId,
            sourceKey: latest.archived.source_key || latest.archiveKey,
            fields: itemConflicts,
          });
        }
        targetRow.items[productId].product_id = productId;
        if (before !== JSON.stringify(targetRow.items[productId])) {
          changed = true;
          relocatedCategoryItems.push({
            sourceRow: latest.sourceRowIndex,
            targetRow: productMaps.indexOf(targetRow),
            sourceKey: latest.archived.source_key || latest.archiveKey,
            product_id: productId,
            category_id: categoryId,
          });
        }
      }
      unprocessed.forEach(({ archived }) => {
        archived.replayedCategoryIdsV521 = [
          ...new Set([...(archived.replayedCategoryIdsV521 || []), categoryId]),
        ];
        changed = true;
      });
    });
  });

  const log = (workspace.project._gate1ProductIdMigrationLog = Array.isArray(
    workspace.project._gate1ProductIdMigrationLog,
  )
    ? workspace.project._gate1ProductIdMigrationLog
    : []);
  let entry = log.find(
    (item) => item.id === GATE1_PAIN_PRODUCT_ID_STORAGE_V237,
  );
  if (!entry) {
    entry = {
      id: GATE1_PAIN_PRODUCT_ID_STORAGE_V237,
      at: new Date().toISOString(),
      status: "completed",
      runs: [],
    };
    log.push(entry);
  }
  if (changed || !entry.runs.length) {
    entry.updated_at = new Date().toISOString();
    entry.status = archivedUnmatched.some((item) => item.hasData) || conflicts.length
      ? "completed_with_warnings"
      : "completed";
    entry.runs.push({
      at: entry.updated_at,
      catalogProducts: maps.products.length,
      mappings,
      canonicalCreated,
      archivedUnmatched,
      relocatedCategoryItems,
      conflicts,
      shirtNormalizations,
      storage: "state.painV130.productMaps[].items[product_id]",
      archive: "state.painV130.productMaps[].legacyPageItemsV237[page_id]",
      note:
        "Активная товарная семантика переведена с page-id на catalogItemsV189 product_id. Исходные page-записи сохранены целиком в архиве и исключены из runtime; сопоставление по названию или категории не используется.",
    });
  }
  return {
    changed,
    mappings,
    canonicalCreated,
    archivedUnmatched,
    relocatedCategoryItems,
    conflicts,
    shirtNormalizations,
  };
}

/* Список товаров направления теперь строится из единого каталога, а
   row страницы нужен только для URL/подписи источника. item.id всегда
   равен catalog-item-* и именно им адресуется row.items. */
