/* ================================================================
   v2.3.17 — Карточка товара: семь секций в порядке реальной страницы.

   Старые 17 полей сначала целиком сохраняются в legacyPageItemsV253.
   Перенос выполняется один раз: объединённые черновики после миграции
   являются обычным ручным текстом и больше никогда не пересобираются.
   ================================================================ */
const PRODUCT_CARD_SEVEN_BLOCKS_V253 =
  "product-card-seven-blocks-v253";
const PRODUCT_CARD_HERO_SHORT_DESCRIPTION_V254 =
  "product-card-hero-short-description-v254";
const PRODUCT_CARD_DELIVERY_STRUCTURE_V255 =
  "product-card-delivery-structure-v255";
const PRODUCT_CARD_OLD_CONTEXT_KEYS_V253 = [
  "productGallery",
  "productRating",
  "productShortDescription",
  "productPrice",
  "productAvailability",
  "productButtons",
  "productTrustMini",
  "productTabs",
  "productDescription",
  "productCharacteristics",
  "productSet",
  "productCrossSell",
  "productUgc",
  "productClientResult",
  "productRecommendationReasons",
  "productDeliveryPayment",
  "productViewed",
];
const PRODUCT_CARD_TRANSFERRED_CONTEXT_KEYS_V253 = new Set([
  "productPrice",
  "productButtons",
]);

function productCardEffectiveValueV253(row, key) {
  const context = row?.contextFields || {};
  const source = key.startsWith("row_")
    ? row?.[key.slice(4)]
    : context[key];
  const note = context[`${key}__flagNote`];
  const status = guruCanonStatus(context[`${key}__flag`]);
  if ((status === "missing" || status === "broken") && String(note || "").trim())
    return String(note).trim();
  if (String(source || "").trim()) return String(source).trim();
  return String(note || "").trim();
}

function productCardMergedDraftV253(values) {
  const seen = new Set();
  return values
    .map((value) => String(value || "").trim())
    .filter((value) => {
      const normalized = value.toLocaleLowerCase("ru-RU");
      if (!normalized || seen.has(normalized)) return false;
      seen.add(normalized);
      return true;
    })
    .join("\n\n");
}

function productCardProductionDraftV253(value) {
  return String(value || "")
    .split(/\r?\n|;\s*|(?<=\.)\s+(?=[А-ЯA-ZЁ])/)
    .map((line) => line.trim())
    .filter(Boolean)
    .filter((line) =>
      /(?:изготовлен|производств|ручн(?:ая|ой|ую|ое)\s+работ|мастерск)/iu.test(
        line,
      ),
    )
    .join("\n");
}

function productCardAggregateFlagV253(row, keys) {
  const flags = keys
    .map((key) => guruCanonStatus(row?.contextFields?.[`${key}__flag`]))
    .filter(Boolean);
  if (!flags.length) return "";
  if (flags.includes("broken")) return "broken";
  if (flags.includes("missing")) return "missing";
  if (flags.includes("needs_improvement")) return "needs_improvement";
  if (flags.every((flag) => flag === "not_needed")) return "not_needed";
  if (flags.includes("works")) return "works";
  return flags[0] || "";
}

function productCardArchiveV253(row, productId) {
  if (
    row.legacyPageItemsV253 &&
    row.legacyPageItemsV253.id === PRODUCT_CARD_SEVEN_BLOCKS_V253
  )
    return false;
  const context = row.contextFields || {};
  const contextSnapshot = {};
  Object.entries(context).forEach(([key, value]) => {
    if (
      PRODUCT_CARD_OLD_CONTEXT_KEYS_V253.some(
        (oldKey) => key === oldKey || key.startsWith(`${oldKey}__`),
      ) ||
      /^(?:product_first_screen|product_content|product_tail)__/.test(key)
    )
      contextSnapshot[key] = structuredClone(value);
  });
  row.legacyPageItemsV253 = {
    id: PRODUCT_CARD_SEVEN_BLOCKS_V253,
    archived_at: new Date().toISOString(),
    product_id: productId || row.catalogItemIdV189 || "",
    source_sections: [
      "product_first_screen",
      "product_content",
      "product_tail",
    ],
    row_fields: {
      h1: row.h1 || "",
      finalCta: row.finalCta || "",
      ctaMode: row.ctaMode || "",
      productGalleryPhotos: structuredClone(row.productGalleryPhotos || []),
      productGalleryMainPhotoId: row.productGalleryMainPhotoId || "",
    },
    context_fields: contextSnapshot,
  };
  return true;
}

function productCardLegacyShortDescriptionV254(row) {
  const archived = row?.legacyPageItemsV253?.context_fields || {};
  const source = String(archived.productShortDescription || "").trim();
  const note = String(
    archived.productShortDescription__flagNote || "",
  ).trim();
  const status = guruCanonStatus(
    archived.productShortDescription__flag,
  );
  if ((status === "missing" || status === "broken") && note) return note;
  return source || note;
}

function productCardEnsureHeroShortDescriptionV254(row) {
  if (!row || typeof row !== "object") return "";
  if (
    row.productCardHeroShortDescriptionV254 ===
    PRODUCT_CARD_HERO_SHORT_DESCRIPTION_V254
  )
    return "";
  row.contextFields = row.contextFields || {};
  const context = row.contextFields;
  let result = "marked";
  if (!String(context.productHeroShortDescriptionV254 || "").trim()) {
    const restored = productCardLegacyShortDescriptionV254(row);
    if (restored) {
      context.productHeroShortDescriptionV254 = restored;
      result = "restored";
    }
  }
  row.productCardHeroShortDescriptionV254 =
    PRODUCT_CARD_HERO_SHORT_DESCRIPTION_V254;
  return result;
}

function productCardDeliveryCardV255() {
  return {
    id: makeId("product-delivery-card"),
    title: "",
    description: "",
  };
}

function productCardEnsureDeliveryStructureV255(row) {
  if (!row || typeof row !== "object") return false;
  if (
    row.productCardDeliveryStructureV255 ===
    PRODUCT_CARD_DELIVERY_STRUCTURE_V255
  )
    return false;
  row.contextFields = row.contextFields || {};
  const context = row.contextFields;
  if (!Array.isArray(context.productDeliveryGuaranteeCardsV255))
    context.productDeliveryGuaranteeCardsV255 = [
      productCardDeliveryCardV255(),
      productCardDeliveryCardV255(),
    ];
  context.productDeliveryGuaranteeCardsV255 =
    context.productDeliveryGuaranteeCardsV255.map((item) => ({
      id: String(item?.id || makeId("product-delivery-card")),
      title: String(item?.title || ""),
      description: String(item?.description || ""),
    }));
  row.productCardDeliveryStructureV255 =
    PRODUCT_CARD_DELIVERY_STRUCTURE_V255;
  return true;
}

function productCardMigrateRowV253(row, productId) {
  if (!row || typeof row !== "object") return false;
  row.contextFields = row.contextFields || {};
  const context = row.contextFields;
  if (row.productCardSchemaV253 === PRODUCT_CARD_SEVEN_BLOCKS_V253)
    return false;

  productCardArchiveV253(row, productId);

  const old = Object.fromEntries(
    ["row_h1", ...PRODUCT_CARD_OLD_CONTEXT_KEYS_V253].map((key) => [
      key,
      productCardEffectiveValueV253(row, key),
    ]),
  );
  const oldFlags = Object.fromEntries(
    ["row_h1", ...PRODUCT_CARD_OLD_CONTEXT_KEYS_V253].map((key) => [
      key,
      guruCanonStatus(context[`${key}__flag`]),
    ]),
  );

  if (!String(row.h1 || "").trim() && old.row_h1) row.h1 = old.row_h1;
  if (old.productPrice) context.productPrice = old.productPrice;
  if (old.productButtons) context.productButtons = old.productButtons;
  if (!String(context.productHeroShortDescriptionV254 || "").trim())
    context.productHeroShortDescriptionV254 = old.productShortDescription;

  if (!String(context.productMeaningV253 || "").trim())
    context.productMeaningV253 = productCardMergedDraftV253([
      old.productShortDescription,
      old.productDescription,
    ]);
  if (!String(context.productCreationV253 || "").trim())
    context.productCreationV253 = productCardProductionDraftV253(
      old.productCharacteristics,
    );
  if (!String(context.productDeliveryGuaranteeV253 || "").trim())
    context.productDeliveryGuaranteeV253 = productCardMergedDraftV253([
      old.productTrustMini,
      old.productDeliveryPayment,
    ]);

  if (!guruCanonStatus(context.productHeroV253__flag))
    context.productHeroV253__flag = productCardAggregateFlagV253(row, [
      "productGallery",
      "row_h1",
      "productPrice",
      "productButtons",
      "productShortDescription",
    ]);
  if (!guruCanonStatus(context.productGalleryV253__flag))
    context.productGalleryV253__flag = oldFlags.productGallery || "";
  if (!guruCanonStatus(context.productMeaningV253__flag))
    context.productMeaningV253__flag = productCardAggregateFlagV253(row, [
      "productShortDescription",
      "productDescription",
    ]);
  if (!guruCanonStatus(context.productCreationV253__flag))
    context.productCreationV253__flag = oldFlags.productCharacteristics || "";
  if (!guruCanonStatus(context.productDeliveryGuaranteeV253__flag))
    context.productDeliveryGuaranteeV253__flag = productCardAggregateFlagV253(
      row,
      ["productTrustMini", "productDeliveryPayment"],
    );
  if (context.productFinalCtaImplementedV253 === undefined)
    context.productFinalCtaImplementedV253 = String(row.finalCta || "").trim()
      ? "yes"
      : "";
  if (context.productRelatedImplementedV253 === undefined)
    context.productRelatedImplementedV253 =
      oldFlags.productCrossSell === "works" || oldFlags.productViewed === "works"
        ? "yes"
        : "";

  PRODUCT_CARD_OLD_CONTEXT_KEYS_V253.forEach((key) => {
    if (!PRODUCT_CARD_TRANSFERRED_CONTEXT_KEYS_V253.has(key)) delete context[key];
    delete context[`${key}__flag`];
    delete context[`${key}__flagNote`];
  });
  ["row_h1__flag", "row_h1__flagNote"].forEach((key) => delete context[key]);
  Object.keys(context).forEach((key) => {
    if (/^(?:product_first_screen|product_content|product_tail)__/.test(key))
      delete context[key];
  });
  row.productCardSchemaV253 = PRODUCT_CARD_SEVEN_BLOCKS_V253;
  return true;
}

function productCardMigrateWorkspaceV253(workspace) {
  if (!workspace?.project) return { changed: false, rows: [] };
  const rows = [];
  const restoredShortDescriptions = [];
  const deliveryStructureRows = [];
  let changed = false;
  (workspace.gates || []).forEach((gate) => {
    (gate.cards || []).forEach((card) => {
      if (pageTemplateContext(card) !== "product") return;
      if (!Array.isArray(card.pageRows)) return;
      (card.pageRows || []).forEach((row, rowIndex) => {
        const productId = String(row?.catalogItemIdV189 || "").trim();
        if (productCardMigrateRowV253(row, productId)) {
          changed = true;
          rows.push({
            card_id: card.id,
            row_index: rowIndex,
            page_id: row.id || "",
            product_id: productId,
            name: row.name || "",
            archive: "pageRow.legacyPageItemsV253",
          });
        }
        const shortDescriptionMigration =
          productCardEnsureHeroShortDescriptionV254(row);
        if (shortDescriptionMigration) {
          changed = true;
          if (
            shortDescriptionMigration === "restored" ||
            String(row.contextFields?.productHeroShortDescriptionV254 || "").trim()
          )
            restoredShortDescriptions.push({
              card_id: card.id,
              row_index: rowIndex,
              page_id: row.id || "",
              product_id: productId,
              name: row.name || "",
              source:
                "pageRow.legacyPageItemsV253.context_fields.productShortDescription",
            });
        }
        if (productCardEnsureDeliveryStructureV255(row)) {
          changed = true;
          deliveryStructureRows.push({
            card_id: card.id,
            row_index: rowIndex,
            page_id: row.id || "",
            product_id: productId,
            name: row.name || "",
            preserved_description:
              String(
                row.contextFields?.productDeliveryGuaranteeV253 || "",
              ).trim().length > 0,
            initial_cards:
              row.contextFields?.productDeliveryGuaranteeCardsV255?.length ||
              0,
          });
        }
      });
    });
  });

  const log = (workspace.project._productCardMigrationLog = Array.isArray(
    workspace.project._productCardMigrationLog,
  )
    ? workspace.project._productCardMigrationLog
    : []);
  let logEntry = log.find(
    (entry) => entry.id === PRODUCT_CARD_SEVEN_BLOCKS_V253,
  );
  if (!logEntry) {
    logEntry = {
      id: PRODUCT_CARD_SEVEN_BLOCKS_V253,
      at: new Date().toISOString(),
      status: "completed",
      migrated_rows: rows,
      before: {
        sections: 3,
        active_fields: 17,
      },
      after: {
        groups: 3,
        active_blocks: 7,
      },
      drafts: {
        productMeaningV253:
          "Краткое описание + Описание, разделённые абзацем; далее свободный ручной текст",
        productCreationV253:
          "Только строки про изготовление, производство, ручную работу и мастерскую",
        productDeliveryGuaranteeV253:
          "Мини-блок доверия + Доставка и оплата, разделённые абзацем; далее свободный ручной текст",
      },
      removed_from_active_ui: [
        "Рейтинг",
        "Наличие",
        "Вкладки",
        "Характеристики-таблица",
        "Комплектация",
        "Отзывы / UGC",
        "Результат клиента",
        "Основания рекомендовать",
        "текст Cross-sell",
        "текст Вы недавно смотрели",
      ],
      archive: "pageRows[].legacyPageItemsV253",
    };
    log.push(logEntry);
    changed = true;
  } else if (rows.length) {
    const known = new Set(
      (logEntry.migrated_rows || []).map(
        (item) => `${item.card_id}:${item.page_id}:${item.product_id}`,
      ),
    );
    rows.forEach((item) => {
      const key = `${item.card_id}:${item.page_id}:${item.product_id}`;
      if (known.has(key)) return;
      known.add(key);
      (logEntry.migrated_rows ||= []).push(item);
    });
    logEntry.updated_at = new Date().toISOString();
    logEntry.status = "completed";
  }
  let shortLogEntry = log.find(
    (entry) => entry.id === PRODUCT_CARD_HERO_SHORT_DESCRIPTION_V254,
  );
  if (!shortLogEntry) {
    shortLogEntry = {
      id: PRODUCT_CARD_HERO_SHORT_DESCRIPTION_V254,
      at: new Date().toISOString(),
      status: "completed",
      field: "contextFields.productHeroShortDescriptionV254",
      position: "Герой товара → после Кнопки",
      restored_rows: restoredShortDescriptions,
      source:
        "legacyPageItemsV253.context_fields.productShortDescription; без перезаписи ручного значения",
    };
    log.push(shortLogEntry);
    changed = true;
  } else if (restoredShortDescriptions.length) {
    const known = new Set(
      (shortLogEntry.restored_rows || []).map(
        (item) => `${item.card_id}:${item.page_id}:${item.product_id}`,
      ),
    );
    restoredShortDescriptions.forEach((item) => {
      const key = `${item.card_id}:${item.page_id}:${item.product_id}`;
      if (known.has(key)) return;
      known.add(key);
      (shortLogEntry.restored_rows ||= []).push(item);
    });
    shortLogEntry.updated_at = new Date().toISOString();
    shortLogEntry.status = "completed";
  }
  let deliveryLogEntry = log.find(
    (entry) => entry.id === PRODUCT_CARD_DELIVERY_STRUCTURE_V255,
  );
  if (!deliveryLogEntry) {
    deliveryLogEntry = {
      id: PRODUCT_CARD_DELIVERY_STRUCTURE_V255,
      at: new Date().toISOString(),
      status: "completed",
      position: 3,
      fields: {
        title: "contextFields.productDeliveryGuaranteeTitleV255",
        description: "contextFields.productDeliveryGuaranteeV253",
        cards: "contextFields.productDeliveryGuaranteeCardsV255[]",
      },
      migrated_rows: deliveryStructureRows,
      note:
        "Прежний текст сохранён как описание блока; для каждого товара созданы две стартовые карточки",
    };
    log.push(deliveryLogEntry);
    changed = true;
  } else if (deliveryStructureRows.length) {
    const known = new Set(
      (deliveryLogEntry.migrated_rows || []).map(
        (item) => `${item.card_id}:${item.page_id}:${item.product_id}`,
      ),
    );
    deliveryStructureRows.forEach((item) => {
      const key = `${item.card_id}:${item.page_id}:${item.product_id}`;
      if (known.has(key)) return;
      known.add(key);
      (deliveryLogEntry.migrated_rows ||= []).push(item);
    });
    deliveryLogEntry.updated_at = new Date().toISOString();
  }
  return {
    changed,
    rows,
    restoredShortDescriptions,
    deliveryStructureRows,
  };
}

function productCardBlockVisualStatusV253(flag) {
  const status = guruCanonStatus(flag);
  if (status === "works" || status === "not_needed") return "ready";
  if (status === "needs_improvement") return "in_progress";
  if (status === "broken" || status === "missing") return "problem";
  return "not_started";
}

