function guruGate1DemandPickerEntriesV264(itemData) {
  const byPhrase = new Map();
  (itemData?.demandRows || []).forEach((demandRow, order) => {
    if (demandRow?.originStage === "gate4") return;
    const value = guruV185Text(demandRow?.kw);
    const key = guruV247KeywordNormalize(value);
    if (!key) return;
    const queryCount = pv181DemandQueryNumberV262(demandRow?.queryCount);
    const current = byPhrase.get(key);
    if (!current) {
      byPhrase.set(key, { value, queryCount, order });
      return;
    }
    if (current.queryCount === null && queryCount !== null)
      byPhrase.set(key, { value, queryCount, order: current.order });
  });
  return [...byPhrase.values()].sort((left, right) => {
    if (left.queryCount === null && right.queryCount === null)
      return left.order - right.order;
    if (left.queryCount === null) return 1;
    if (right.queryCount === null) return -1;
    return right.queryCount - left.queryCount || left.order - right.order;
  });
}

