/* ================================================================
   v2.3.30 — Gate 1 / «Спрос, ценность, позиционирование».

   Брендовые фразы становятся одним company-полем на проект. Старые
   значения направлений переносятся построчно и сохраняются в архиве.
   Страничный уровень товара исключён из активной модели: заполненные
   значения остаются в legacySemanticLevelsV264 и не участвуют в UI.
   ================================================================ */
const GATE1_SEMANTIC_CLEANUP_V264 =
  "gate1-company-brand-page-level-cleanup-v264";

function gate1SemanticLinesV264(value) {
  const values = Array.isArray(value) ? value : [value];
  return values.flatMap((entry) => String(entry || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean));
}

function gate1CompanySemanticsV264(workspace = state) {
  if (!workspace) return { brandPhrases: "" };
  workspace.painV130 = workspace.painV130 || { openSteps: {}, steps: {} };
  const current = workspace.painV130.companySemanticsV264;
  const company = current && typeof current === "object" && !Array.isArray(current)
    ? current
    : (workspace.painV130.companySemanticsV264 = {});
  if (Array.isArray(company.brandPhrases))
    company.brandPhrases = gate1SemanticLinesV264(company.brandPhrases).join("\n");
  else company.brandPhrases = String(company.brandPhrases || "");
  return company;
}

/* Брендовый «Спрос» живёт на уровне проекта. Текст ключевого слова приходит
   только из confirmed-кандидатов компанийного keyword foundation; таблица
   редактирует лишь показатели. brandPhrases остаётся отдельным источником SMM. */
const GATE1_COMPANY_BRAND_DEMAND_EDITABLE_FIELDS_V345 = new Set(
  PV181_DEMAND_FIELDS_V272
    .map(([field]) => field)
    .filter((field) => field !== "kw"),
);
const gate1CompanyBrandDemandViewV345 = { sortQueryCount: "none" };

function gate1CompanyKeywordFoundationDemandSourceV351(workspace = state) {
  const model = guruCompanyKeywordConfirmedModelV351(workspace);
  return {
    lines: model.entries.map((entry) => ({
      text: entry.value,
      key: entry.key,
      sourceIndex: entry.sourceIndex,
      candidateId: entry.id,
    })),
    duplicates: model.duplicates.map((entry) => ({
      text: entry.value,
      key: entry.key,
      sourceIndex: entry.sourceIndex,
      candidateId: entry.id,
    })),
  };
}

function gate1CompanyBrandDemandDraftIdV345(phrase, index) {
  const source = `${guruV247KeywordNormalize(phrase)}:${index}`;
  let hash = 2166136261;
  for (let charIndex = 0; charIndex < source.length; charIndex += 1) {
    hash ^= source.charCodeAt(charIndex);
    hash = Math.imul(hash, 16777619);
  }
  return `brand-demand-${(hash >>> 0).toString(36)}`;
}

function gate1CompanyBrandDemandRowV345(row, candidate, index) {
  const next = row && typeof row === "object" && !Array.isArray(row)
    ? { ...row }
    : {};
  next.id = guruV185Text(next.id) ||
    gate1CompanyBrandDemandDraftIdV345(candidate.text, index);
  next.candidate_id = guruV185Text(candidate.candidateId);
  next.kw = guruV185Text(candidate.text);
  GATE1_COMPANY_BRAND_DEMAND_EDITABLE_FIELDS_V345.forEach((field) => {
    next[field] = String(next[field] ?? "");
  });
  delete next.archivedAt;
  delete next.archivedReason;
  delete next.sourceIndex;
  return next;
}

function gate1CompanyBrandDemandReconcileV345(
  workspace = state,
  { create = false } = {},
) {
  if (!workspace) return { rows: [], archivedRows: [], duplicates: [] };
  const company = gate1CompanySemanticsV264(workspace);
  const parsed = gate1CompanyKeywordFoundationDemandSourceV351(workspace);
  const current = Array.isArray(company.demandRows)
    ? company.demandRows.filter((row) => row && typeof row === "object")
    : [];
  const archived = Array.isArray(company.archivedDemandRows)
    ? company.archivedDemandRows.filter(
      (row) => row && typeof row === "object",
    )
    : [];
  const rows = new Array(parsed.lines.length);
  const usedCurrent = new Set();
  const usedArchived = new Set();

  const reserveCandidateId = (sources, used, line) => {
    if (!line.candidateId) return null;
    const matchIndex = sources.findIndex((row, index) =>
      !used.has(index) &&
      guruV185Text(row?.candidate_id) === line.candidateId,
    );
    if (matchIndex < 0) return null;
    used.add(matchIndex);
    return sources[matchIndex];
  };

  const reserveExact = (sources, used, line) => {
    const matchIndex = sources.findIndex((row, index) =>
      !used.has(index) &&
      guruV247KeywordNormalize(row?.kw) === line.key,
    );
    if (matchIndex < 0) return null;
    used.add(matchIndex);
    return sources[matchIndex];
  };

  // Уже связанные строки следуют за стабильным candidate_id. Для старых строк,
  // где candidate_id ещё нет, единственная миграционная эвристика — точное
  // совпадение нормализованного текста. Сопоставления по позиции нет.
  parsed.lines.forEach((line, index) => {
    const match = reserveCandidateId(current, usedCurrent, line);
    if (match) rows[index] = gate1CompanyBrandDemandRowV345(match, line, index);
  });
  parsed.lines.forEach((line, index) => {
    if (rows[index]) return;
    const match = reserveCandidateId(archived, usedArchived, line);
    if (match) rows[index] = gate1CompanyBrandDemandRowV345(match, line, index);
  });
  parsed.lines.forEach((line, index) => {
    if (rows[index]) return;
    const match = reserveExact(current, usedCurrent, line);
    if (match) rows[index] = gate1CompanyBrandDemandRowV345(match, line, index);
  });
  parsed.lines.forEach((line, index) => {
    if (rows[index]) return;
    const match = reserveExact(archived, usedArchived, line);
    if (match) rows[index] = gate1CompanyBrandDemandRowV345(match, line, index);
  });

  parsed.lines.forEach((line, index) => {
    if (rows[index]) return;
    rows[index] = gate1CompanyBrandDemandRowV345(null, line, index);
  });

  const archivedRows = archived
    .filter((row, index) => !usedArchived.has(index))
    .map((row) => ({ ...row }));
  current.forEach((row, index) => {
    if (usedCurrent.has(index)) return;
    const archivedRow = {
      ...row,
      id: guruV185Text(row.id) || gate1CompanyBrandDemandDraftIdV345(
        row.kw,
        index,
      ),
      kw: guruV185Text(row.kw),
      archivedAt: new Date().toISOString(),
      archivedReason: "removed_from_company_keyword_foundation",
      sourceIndex: index,
    };
    const archivedIndex = archivedRows.findIndex((entry) =>
      guruV185Text(entry.id) === archivedRow.id,
    );
    if (archivedIndex >= 0) archivedRows[archivedIndex] = archivedRow;
    else archivedRows.push(archivedRow);
  });

  if (create) {
    company.demandRows = rows;
    company.archivedDemandRows = archivedRows;
  }
  return { rows, archivedRows, duplicates: parsed.duplicates };
}

/* v2.3.156 — CSV с метриками для компанийного спроса переиспользует
   продуктовый формат и парсер, но имеет отдельную строгую границу записи:
   только текущие confirmed-кандидаты компании, без создания фраз из CSV.
   Связь строк demandRows с candidate_id остаётся ответственностью reconcile. */
const GATE1_COMPANY_BRAND_DEMAND_METRIC_COLUMNS_V356 = Object.freeze([
  Object.freeze({ field: "vol", parsedField: "volume", indexField: "volumeIndex" }),
  Object.freeze({ field: "queryCount", parsedField: "queryCount", indexField: "queryCountIndex" }),
  Object.freeze({ field: "forecastClicks", parsedField: "monthlyClicks", indexField: "monthlyClicksIndex" }),
  Object.freeze({ field: "clickPrice", parsedField: "clickPrice", indexField: "clickPriceIndex" }),
  Object.freeze({ field: "bid", parsedField: "bid", indexField: "bidIndex" }),
  Object.freeze({ field: "forecastBudget", parsedField: "budget", indexField: "budgetIndex" }),
]);

function gate1CompanyBrandDemandImportStateV356(
  workspace = state,
  create = false,
) {
  if (!workspace) return null;
  const company = gate1CompanySemanticsV264(workspace);
  let current = company.brandDemandMetricsImportV356;
  if ((!current || typeof current !== "object" || Array.isArray(current)) && create) {
    current = { unmatched: [], last_import: null };
    company.brandDemandMetricsImportV356 = current;
  }
  if (!current || typeof current !== "object" || Array.isArray(current))
    return null;
  current.unmatched = Array.isArray(current.unmatched)
    ? current.unmatched
    : [];
  return current;
}

function gate1CompanyBrandDemandExportEntriesV356(workspace = state) {
  return gate1CompanyBrandDemandReconcileV345(workspace).rows.map(
    (demandRow, index) => ({ demandRow, index }),
  );
}

/* v2.3.158 — Буфер обмена получает только актуальные подтверждённые
   компанийные фразы: одна фраза на строку, без заголовка и метрик. */
function gate1CompanyBrandDemandCopyKeywordsV358(workspace = state) {
  return gate1CompanyBrandDemandExportEntriesV356(workspace)
    .map(({ demandRow }) => guruV185Text(demandRow?.kw))
    .filter(Boolean);
}

function gate1CompanyBrandDemandFileNameV356(workspace = state) {
  return guruCompanyKeywordFoundationFileNameV351(workspace).replace(
    /^keyword-foundation-company-/,
    "brand-demand-company-",
  );
}

function gate1CompanyBrandDemandAssignMetricsV356(
  demandRow,
  parsed,
  imported,
) {
  GATE1_COMPANY_BRAND_DEMAND_METRIC_COLUMNS_V356.forEach((column) => {
    /* В отличие от продуктового apply, отсутствующий в файле столбец не
       очищает уже сохранённое значение компании. */
    const columnIndex = parsed?.[column.indexField];
    if (!Number.isInteger(columnIndex) || columnIndex < 0) return;
    demandRow[column.field] = guruV185Text(imported?.[column.parsedField]);
  });
  return demandRow;
}

function gate1CompanyBrandDemandUnmatchedV356(imported, reason) {
  return {
    phrase: guruV185Text(imported?.phrase),
    values: Array.isArray(imported?.values) ? [...imported.values] : [],
    row: Number(imported?.row) || null,
    reason,
  };
}

function gate1CompanyBrandDemandApplyParsedRowsV356(
  parsed,
  fileName = "",
  workspace = state,
) {
  if (!workspace)
    return { matched: 0, unmatched: [], unmatchedCount: 0, rows: [] };
  const source = gate1CompanyKeywordFoundationDemandSourceV351(workspace);
  const candidatesByKey = new Map(
    source.lines.map((candidate) => [candidate.key, candidate]),
  );
  const company = gate1CompanySemanticsV264(workspace);
  const model = gate1CompanyBrandDemandReconcileV345(workspace);
  const rowsByCandidateId = new Map(
    model.rows
      .map((row) => [guruV185Text(row?.candidate_id), row])
      .filter(([candidateId]) => candidateId),
  );
  const unmatched = (parsed?.serviceRows || []).map((row) => ({ ...row }));
  let matched = 0;

  (parsed?.rows || []).forEach((imported) => {
    if (imported?.hasValidMetrics === false) {
      unmatched.push(
        gate1CompanyBrandDemandUnmatchedV356(imported, "invalid_metrics"),
      );
      return;
    }
    const candidate = candidatesByKey.get(guruV185Text(imported?.key));
    if (!candidate) {
      unmatched.push(
        gate1CompanyBrandDemandUnmatchedV356(
          imported,
          "not_current_confirmed_company_candidate",
        ),
      );
      return;
    }
    const candidateId = guruV185Text(candidate.candidateId);
    const demandRow = candidateId
      ? rowsByCandidateId.get(candidateId)
      : null;
    if (!demandRow) {
      unmatched.push(
        gate1CompanyBrandDemandUnmatchedV356(
          imported,
          candidateId ? "company_demand_row_unavailable" : "candidate_id_missing",
        ),
      );
      return;
    }
    gate1CompanyBrandDemandAssignMetricsV356(demandRow, parsed, imported);
    matched += 1;
  });

  /* Неизвестный файл не материализует даже вычисляемые UI-строки. Запись
     активной модели нужна только когда действительно обновлена метрика
     текущего confirmed-кандидата. */
  if (matched > 0) {
    company.demandRows = model.rows;
    company.archivedDemandRows = model.archivedRows;
  }

  const importState = gate1CompanyBrandDemandImportStateV356(workspace, true);
  importState.unmatched = unmatched;
  importState.last_import = guruGate1FinalImportMetaV279(
    parsed,
    fileName,
    matched,
    unmatched.length,
    {
      scope: "company",
      project_id: guruV194ProjectId(workspace),
      created: 0,
      applied: matched,
    },
  );
  return {
    matched,
    unmatched,
    unmatchedCount: unmatched.length,
    rows: model.rows,
  };
}

function gate1CompanyBrandDemandRowsHtmlV345(entries) {
  return entries.map(({ demandRow: row, index }) => {
    const rowId = guruV185Text(row.id);
    const cells = PV181_DEMAND_FIELDS_V272.map(([field, label]) => {
      const value = guruV185Text(row[field]);
      const filledClass = value ? "is-filled" : "is-empty";
      const control = field === "kw"
        ? `<div class="g1-input ${filledClass} pv181-demand-imported-value-v261" role="textbox" aria-label="${escapeAttr(label)}" aria-readonly="true" data-pv181-company-demand-keyword-v345>${escapeHtml(value || label)}</div>`
        : `<textarea class="g1-input ${filledClass}" aria-label="${escapeAttr(label)}" data-pv181-company-demand-input-v345 data-pv181-company-demand-row-id-v345="${escapeAttr(rowId)}" data-pv181-company-demand-source-index-v345="${index}" data-pv181-company-demand-field-v345="${escapeAttr(field)}" rows="1" inputmode="decimal" placeholder="${escapeAttr(label)}">${escapeHtml(value)}</textarea>`;
      return `<label class="g1-field pv181-demand-cell-v263"><span class="pv181-demand-cell-label-v263">${escapeHtml(label)}</span>${control}</label>`;
    }).join("");
    return `<div class="pv181-demand-row" data-pv181-company-demand-row-v345="${escapeAttr(rowId)}">${cells}<span class="pv181-demand-row-action-spacer-v272" aria-hidden="true"></span></div>`;
  }).join("");
}

function gate1CompanyBrandDemandTotalsHtmlV345(entries) {
  const totals = pv181DemandTotalsV276(entries);
  const cells = PV181_DEMAND_FIELDS_V272.map(([field, label]) => {
    const isLabel = field === "kw";
    const isSummed = PV181_DEMAND_TOTAL_FIELDS_V276.has(field);
    const isWeighted = PV181_DEMAND_WEIGHTED_TOTAL_FIELDS_V276.has(field);
    const hasTotal = isSummed || (isWeighted && totals[field] !== null);
    const value = isLabel
      ? "Итого"
      : hasTotal
        ? pv181DemandTotalValueV276(field, totals[field])
        : "—";
    const attributes = hasTotal
      ? ` data-pv181-company-demand-total-field-v345="${escapeAttr(field)}" data-pv181-company-demand-total-value-v345="${escapeAttr(totals[field])}"`
      : "";
    return `<div class="g1-field pv181-demand-cell-v263"><span class="pv181-demand-cell-label-v263">${escapeHtml(isLabel ? "Итог" : label)}</span><div class="g1-input is-filled pv181-demand-total-value-v276${!isLabel && !hasTotal ? " is-not-summed-v276" : ""}" role="textbox" aria-label="${escapeAttr(isLabel ? "Итого" : `${label}: итог`)}" aria-readonly="true"${attributes}>${escapeHtml(value)}</div></div>`;
  }).join("");
  return `<div class="pv181-demand-row pv181-demand-totals-row-v276" data-pv181-company-demand-totals-v345>${cells}<span class="pv181-demand-row-action-spacer-v272" aria-hidden="true"></span></div>`;
}

