function gate1CompanyBrandDemandRefreshV345({ preserveOpen = false } = {}) {
  document.querySelectorAll("[data-pv181-company-demand-v345]").forEach((root) => {
    const wasOpen = preserveOpen && Boolean(
      root.querySelector("[data-pv181-company-demand-details-v345]")?.open,
    );
    const template = document.createElement("template");
    template.innerHTML = gate1CompanyBrandDemandHtmlV345(state).trim();
    const next = template.content.firstElementChild;
    if (!next) return;
    const details = next.querySelector(
      "[data-pv181-company-demand-details-v345]",
    );
    if (details) details.open = wasOpen;
    root.replaceWith(next);
  });
  if (typeof gate1CompanyDemandPositioningHeaderRefreshV357 === "function")
    gate1CompanyDemandPositioningHeaderRefreshV357(state);
}

