/* ================================================================
   v2.3.33 — Gate 1 / черновая смысловая группировка спроса.

   Предложения хранятся отдельно от semL3Groups и не попадают в
   служебное зеркало semL3. Только явное подтверждение добавляет новую
   обычную группу; существующие группы не переписываются.
   ================================================================ */
const GATE1_DEMAND_GROUPING_DRAFTS_V266 =
  "gate1-demand-grouping-drafts-v266";
const GATE1_GROUPING_MIN_PHRASES_V266 = 2;
const GATE1_GROUPING_MAX_SHARE_V266 = 0.45;
const GATE1_GROUPING_STOP_WORDS_V266 = new Set(
  `и или но а да не ни что чтобы как когда где кто это тот та те
   для при по на в во из от до к ко с со у о об обо за над под про
   через без между после перед уже ещё же бы ли мы вы они он она оно
   мой твой ваш наш их его её один одна одно два купить цена заказать
   года год лет товар товары услуга услуги`.split(/\s+/).filter(Boolean),
);
const GATE1_GROUPING_WIDE_CORES_V266 = new Set([
  "подарок",
  "подарк",
  "коза",
  "коз",
]);

function guruGate1GroupingStemV266(token) {
  const word = guruV185Text(token)
    .toLocaleLowerCase("ru-RU")
    .replace(/ё/g, "е");
  if (!word || /^\d+$/u.test(word) || word.length < 4) return "";
  const endings = [
    "иями", "ями", "ами", "ого", "ему", "ому", "ыми", "ими",
    "ая", "яя", "ое", "ее", "ые", "ие", "ый", "ий", "ой",
    "ую", "юю", "ов", "ев", "ом", "ем", "ам", "ям", "ах",
    "ях", "ы", "и", "а", "я", "у", "ю", "е", "о",
  ];
  const ending = endings.find(
    (candidate) => word.endsWith(candidate) && word.length - candidate.length >= 4,
  );
  return ending ? word.slice(0, -ending.length) : word;
}

function guruGate1GroupingTokensV266(phrase) {
  const rawTokens = guruV185Text(phrase)
    .toLocaleLowerCase("ru-RU")
    .replace(/ё/g, "е")
    .match(/[\p{L}\p{N}]+/gu) || [];
  const seen = new Set();
  return rawTokens.flatMap((surface, index) => {
    if (GATE1_GROUPING_STOP_WORDS_V266.has(surface)) return [];
    const core = guruGate1GroupingStemV266(surface);
    if (!core || GATE1_GROUPING_STOP_WORDS_V266.has(core) || seen.has(core))
      return [];
    seen.add(core);
    return [{ core, surface, index }];
  });
}

function guruGate1GroupingUsedKeysV266(itemData) {
  const used = new Set();
  (itemData?.semL3Groups || []).forEach((group) => {
    [group?.mainQuery, ...(Array.isArray(group?.keywords) ? group.keywords : [])]
      .forEach((entry) => {
        const key = guruV247KeywordNormalize(pv181KeywordText(entry));
        if (key) used.add(key);
      });
  });
  return used;
}

function guruGate1GroupingDemandV266(itemData, excludedKeys = new Set()) {
  const used = guruGate1GroupingUsedKeysV266(itemData);
  const candidates = new Map();
  (itemData?.demandRows || []).forEach((row, order) => {
    const value = guruV185Text(row?.kw);
    const key = guruV247KeywordNormalize(value);
    if (!key || used.has(key) || excludedKeys.has(key)) return;
    const candidate = {
      value,
      key,
      queryCount: pv181DemandQueryNumberV262(row?.queryCount),
      volume: pv181DemandQueryNumberV262(row?.vol),
      order,
      tokens: guruGate1GroupingTokensV266(value),
    };
    const previous = candidates.get(key);
    if (!previous ||
        (candidate.queryCount ?? -Infinity) > (previous.queryCount ?? -Infinity) ||
        ((candidate.queryCount ?? -Infinity) === (previous.queryCount ?? -Infinity) &&
          (candidate.volume ?? -Infinity) > (previous.volume ?? -Infinity)))
      candidates.set(key, candidate);
  });
  return [...candidates.values()].sort((left, right) => left.order - right.order);
}

function guruGate1GroupingMetricSortV266(left, right) {
  return (right.queryCount ?? -Infinity) - (left.queryCount ?? -Infinity) ||
    (right.volume ?? -Infinity) - (left.volume ?? -Infinity) ||
    left.order - right.order;
}

function guruGate1SuggestGroupingV266(itemData, itemId = "") {
  const primaryMatch = typeof guruGate1PrimaryJtbdMatchV267 === "function"
    ? guruGate1PrimaryJtbdMatchV267(itemId, itemData)
    : { phraseKeys: new Set(), concepts: [] };
  const candidates = guruGate1GroupingDemandV266(
    itemData,
    primaryMatch.phraseKeys,
  );
  const maxDocumentFrequency = Math.max(
    GATE1_GROUPING_MIN_PHRASES_V266,
    Math.floor(candidates.length * GATE1_GROUPING_MAX_SHARE_V266),
  );
  const cores = new Map();
  candidates.forEach((candidate) => {
    candidate.tokens.forEach(({ core, surface, index }) => {
      if (GATE1_GROUPING_WIDE_CORES_V266.has(core)) return;
      let record = cores.get(core);
      if (!record) {
        record = {
          core,
          phraseKeys: new Set(),
          surfaces: new Map(),
          firstOrder: candidate.order,
          firstToken: index,
        };
        cores.set(core, record);
      }
      record.phraseKeys.add(candidate.key);
      const surfaceRecord = record.surfaces.get(surface) || {
        count: 0,
        firstOrder: candidate.order,
      };
      surfaceRecord.count += 1;
      record.surfaces.set(surface, surfaceRecord);
    });
  });

  const eligibleCores = [...cores.values()]
    .map((record) => ({ ...record, frequency: record.phraseKeys.size }))
    .filter((record) =>
      record.frequency >= GATE1_GROUPING_MIN_PHRASES_V266 &&
      record.frequency <= maxDocumentFrequency,
    )
    .sort((left, right) =>
      right.frequency - left.frequency ||
      left.firstOrder - right.firstOrder ||
      left.firstToken - right.firstToken ||
      left.core.localeCompare(right.core, "ru"),
    );

  const assigned = new Set();
  const now = new Date().toISOString();
  const drafts = [];
  eligibleCores.forEach((record) => {
    const rows = candidates
      .filter((candidate) =>
        !assigned.has(candidate.key) &&
        candidate.tokens.some((token) => token.core === record.core),
      )
      .sort(guruGate1GroupingMetricSortV266);
    if (rows.length < GATE1_GROUPING_MIN_PHRASES_V266) return;
    rows.forEach((candidate) => assigned.add(candidate.key));
    const coreLabel = [...record.surfaces.entries()]
      .sort((left, right) =>
        right[1].count - left[1].count ||
        left[1].firstOrder - right[1].firstOrder,
      )[0]?.[0] || record.core;
    drafts.push({
      id: makeId("query-group-draft"),
      status: "draft",
      core: record.core,
      coreLabel,
      mainQuery: rows[0].value,
      phrases: rows.map((candidate) => ({
        value: candidate.value,
        queryCount: candidate.queryCount,
        volume: candidate.volume,
        demandOrder: candidate.order,
      })),
      created_at: now,
    });
  });

  const unclustered = candidates
    .filter((candidate) => !assigned.has(candidate.key))
    .map((candidate) => candidate.value);
  itemData.semL3GroupingDraftsV266 = drafts;
  itemData.semL3GroupingMetaV266 = {
    generated_at: now,
    source_phrases: candidates.length,
    eligible_cores: eligibleCores.length,
    max_document_frequency: maxDocumentFrequency,
    min_group_size: GATE1_GROUPING_MIN_PHRASES_V266,
    max_core_share: GATE1_GROUPING_MAX_SHARE_V266,
    ignored_wide_cores: [...GATE1_GROUPING_WIDE_CORES_V266],
    primary_jtbd_phrases: primaryMatch.phraseKeys.size,
    primary_jtbd_concepts: primaryMatch.concepts,
    unclustered,
  };
  return { drafts, unclustered, candidates, eligibleCores };
}

function guruGate1GroupingDraftsV266(itemData) {
  return Array.isArray(itemData?.semL3GroupingDraftsV266)
    ? itemData.semL3GroupingDraftsV266.filter((draft) =>
        draft && draft.status === "draft" && Array.isArray(draft.phrases),
      )
    : [];
}

function guruGate1GroupingDraftsHtmlV266(mapIndex, itemId, itemData) {
  const drafts = guruGate1GroupingDraftsV266(itemData);
  if (!drafts.length) return "";
  const meta = itemData.semL3GroupingMetaV266 || {};
  const noJtbdSlots = typeof guruGate1EnsureAdditionalJtbdsV268 === "function" &&
    guruGate1EnsureAdditionalJtbdsV268(itemData).length >= 3;
  return `<section class="pv181-grouping-drafts-v266" data-pv181-grouping-drafts-v266>
    <header class="pv181-grouping-drafts-head-v266">
      <div><strong>Предложенная группировка</strong><small>Черновики не входят в активные группы до подтверждения.</small></div>
      <button type="button" class="small-btn pv181-grouping-confirm-v266" data-pv181-grouping-confirm-all-v266 data-pv181-map-i="${mapIndex}" data-pv181-item-i="${escapeAttr(itemId)}" ${noJtbdSlots ? 'disabled title="Достигнут лимит: максимум 3 дополнительных JTBD"' : ""}>Подтвердить все</button>
    </header>
    <div class="pv181-grouping-draft-list-v266">
      ${drafts.map((draft) => {
        const phrases = draft.phrases.map((phrase) => guruV185Text(phrase?.value)).filter(Boolean);
        return `<article class="pv181-grouping-draft-v266" data-pv181-grouping-draft-v266="${escapeAttr(draft.id)}">
          <header><span>Ядро: ${escapeHtml(draft.coreLabel || draft.core)}</span><span class="pv181-keyword-draft-badge">Черновик группировки</span></header>
          <div class="g1-field"><span>Предлагаемый главный запрос</span><div class="g1-input is-filled" data-guru-field-neutral>${escapeHtml(draft.mainQuery)}</div></div>
          <div class="pv181-grouping-phrase-list-v266">${phrases.map((phrase) => `<span>${escapeHtml(phrase)}</span>`).join("")}</div>
          <footer><span>${phrases.length} фраз</span><button type="button" class="small-btn pv181-grouping-confirm-v266" data-pv181-grouping-confirm-v266="${escapeAttr(draft.id)}" data-pv181-map-i="${mapIndex}" data-pv181-item-i="${escapeAttr(itemId)}" ${noJtbdSlots ? 'disabled title="Достигнут лимит: максимум 3 дополнительных JTBD"' : ""}>Подтвердить группу</button></footer>
        </article>`;
      }).join("")}
    </div>
    ${Array.isArray(meta.unclustered) && meta.unclustered.length
      ? `<small class="pv181-grouping-unclustered-v266">Без устойчивого общего ядра: ${meta.unclustered.length}. Эти фразы остались нераспределёнными.</small>`
      : ""}
  </section>`;
}

function guruGate1ConfirmGroupingDraftV266(itemData, draft) {
  if (!draft) return false;
  guruGate1EnsureAdditionalJtbdsV268(itemData);
  const additional = itemData.semL4Model.additionalJtbds;
  if (additional.length >= 3) return false;
  const used = guruGate1GroupingUsedKeysV266(itemData);
  const available = (draft.phrases || [])
    .map((phrase) => ({
      ...phrase,
      value: guruV185Text(phrase?.value),
      key: guruV247KeywordNormalize(phrase?.value),
    }))
    .filter((phrase) => phrase.value && phrase.key && !used.has(phrase.key))
    .sort(guruGate1GroupingMetricSortV266);
  if (!available.length) return false;
  const main = available.find((phrase) =>
    phrase.key === guruV247KeywordNormalize(draft.mainQuery),
  ) || available[0];
  const linkedJtbd = guruGate1AdditionalJtbdEntryV268(null, {
    source: "confirmed-demand-group",
  });
  const groupId = makeId("query-group");
  linkedJtbd.linked_group_id = groupId;
  additional.push(linkedJtbd);
  itemData.semL3Groups.push({
    id: groupId,
    mainQuery: main.value,
    keywords: available
      .filter((phrase) => phrase.key !== main.key)
      .map((phrase) => pv181KeywordEntry(phrase.value, {
        source: "generated",
        status: "confirmed",
      })),
    additionalJtbdIdV268: linkedJtbd.id,
  });
  pv181SyncQueryGroups(itemData);
  pv181SyncJtbdModel(itemData);
  return true;
}

function guruGate1GroupingLogEntryV266(workspace = state) {
  if (!workspace?.project) return null;
  const log = (workspace.project._gate1ProductIdMigrationLog = Array.isArray(
    workspace.project._gate1ProductIdMigrationLog,
  ) ? workspace.project._gate1ProductIdMigrationLog : []);
  let entry = log.find((item) => item.id === GATE1_DEMAND_GROUPING_DRAFTS_V266);
  if (!entry) {
    entry = {
      id: GATE1_DEMAND_GROUPING_DRAFTS_V266,
      at: new Date().toISOString(),
      status: "completed",
      storage:
        "painV130.productMaps[].items[product_id].semL3GroupingDraftsV266[]",
      active_groups: "semL3Groups[] — unchanged until confirmation",
      algorithm: {
        source: "unique unassigned demandRows phrases",
        tokenization: "lowercase significant Unicode words; Russian endings normalized",
        minimum_group_size: GATE1_GROUPING_MIN_PHRASES_V266,
        maximum_core_share: GATE1_GROUPING_MAX_SHARE_V266,
        ignored_wide_cores: [...GATE1_GROUPING_WIDE_CORES_V266],
        assignment:
          "greedy by descending document frequency; each phrase enters at most one draft",
        main_query:
          "highest Примерное количество запросов, then Объём показов/мес, then source order",
      },
      runs: [],
    };
    log.push(entry);
  }
  return entry;
}

function guruGate1RecordGroupingRunV266(context, result) {
  const entry = guruGate1GroupingLogEntryV266(state);
  if (!entry) return;
  entry.updated_at = new Date().toISOString();
  entry.runs.push({
    at: entry.updated_at,
    product_id: context.itemId,
    source_phrases: result.candidates.length,
    proposed_groups: result.drafts.map((draft) => ({
      core: draft.coreLabel,
      mainQuery: draft.mainQuery,
      phrases: draft.phrases.length,
    })),
    unclustered: result.unclustered.length,
  });
}

