function guruGate1GroupJtbdPartsV267(group) {
  const raw = group?.additionalJtbdV267;
  if (!raw || typeof raw !== "object") return null;
  return {
    situation: guruV185Text(raw.situation),
    desired_action: guruV185Text(raw.desired_action),
    result: guruV185Text(raw.result),
  };
}

function guruGate1GroupJtbdsV267(itemData) {
  return (itemData?.semL3Groups || []).flatMap((group, groupIndex) => {
    const parts = guruGate1GroupJtbdPartsV267(group);
    return parts ? [{ group, groupIndex, parts }] : [];
  });
}

function guruGate1AdditionalDescriptorIdV274(descriptor) {
  return guruV185Text(
    descriptor?.entry?.id || descriptor?.group?.additionalJtbdIdV268,
  );
}

function guruGate1GroupPhraseKeysV274(group) {
  return new Set([
    group?.mainQuery,
    ...(Array.isArray(group?.keywords) ? group.keywords : []),
  ].map((value) => guruV247KeywordNormalize(pv181KeywordText(value))).filter(Boolean));
}

function guruGate1JtbdBucketV274(
  itemId,
  itemData,
  demandEntry,
  primary = guruGate1PrimaryJtbdMatchV267(itemId, itemData),
  forms = guruGate1GroupJtbdsV267(itemData),
) {
  const assignment = guruGate1JtbdAssignmentV274(itemData, demandEntry.key);
  if (assignment?.target === "primary") return "primary";
  if (assignment?.target === "pending") return "pending";
  if (assignment?.target === "additional") {
    const targetExists = forms.some((descriptor) =>
      guruGate1AdditionalDescriptorIdV274(descriptor) ===
        assignment.additional_jtbd_id,
    ) || guruGate1SavedAdditionalJtbdsV520(itemId, itemData).some((entry) =>
      entry.id === assignment.additional_jtbd_id);
    return targetExists
      ? `additional:${assignment.additional_jtbd_id}`
      : "pending";
  }
  const savedJtbd = guruV185Text(demandEntry.row?._gate4JtbdIdV519);
  if ((demandEntry.row?._gate4JtbdIdsV519 || []).length > 1)
    return "pending";
  if (savedJtbd === `primary:${guruV185Text(itemId)}`) return "primary";
  if (savedJtbd) {
    const savedGroup = forms.find((descriptor) =>
      guruGate1AdditionalDescriptorIdV274(descriptor) === savedJtbd);
    const recovered = guruGate1SavedAdditionalJtbdsV520(itemId, itemData)
      .some((entry) => entry.id === savedJtbd);
    return savedGroup || recovered ? `additional:${savedJtbd}` : "pending";
  }
  if (primary.phraseKeys.has(demandEntry.key)) return "primary";
  const linked = forms.find((descriptor) =>
    descriptor.group &&
    guruGate1GroupPhraseKeysV274(descriptor.group).has(demandEntry.key),
  );
  const linkedId = guruGate1AdditionalDescriptorIdV274(linked);
  return linkedId ? `additional:${linkedId}` : "pending";
}

/* Фраза перестаёт ждать распределения только после попадания в Основной
   JTBD либо в подтверждённую группу, у которой уже создан дополнительный
   JTBD. Черновики групп намеренно не считаются распределением. */
function guruGate1DistributedDemandKeysV273(
  itemId,
  itemData,
  demand = guruGate1UniqueDemandV267(itemData),
  primary = guruGate1PrimaryJtbdMatchV267(itemId, itemData),
) {
  const forms = guruGate1GroupJtbdsV267(itemData);
  return new Set(demand.filter((entry) =>
    guruGate1JtbdBucketV274(itemId, itemData, entry, primary, forms)
      .startsWith("additional:"),
  ).map((entry) => entry.key));
}

