document.addEventListener("change", async (event) => {
  const input = event.target?.closest?.("[data-gate1-group-final-file-v279]");
  if (!input) return;
  const root = input.closest("[data-gate1-group-final-foundation-v279]");
  const context = guruGate1GroupFinalContextV279(root);
  const file = input.files?.[0];
  if (!context || !file) return;
  try {
    const parsed = await guruGate1FinalReadMetricsFileV260(file);
    if (!parsed.rows.length && !parsed.serviceRows.length) {
      window.alert("В CSV / XLS / XLSX не найдено ни одной непустой строки.");
      return;
    }
    const result = guruGate1GroupApplyMetricsV279(
      context.itemId,
      context.itemData,
      context.entries,
      parsed,
      file.name,
      {
        scope: context.scope,
        groupId: context.groupId,
      },
    );
    flashSaving();
    saveState();
    renderGate();
  } catch (error) {
    console.error("Не удалось импортировать метрики финального фундамента группы", error);
    window.alert(error?.message || "Не удалось прочитать CSV / XLS / XLSX-файл.");
  } finally {
    input.value = "";
  }
}, true);

