/* ================================================================
   v2.3.35 — Gate 1 / точное ядро Основного JTBD и единая структура
   дополнительных JTBD.

   Слова категории исключаются из автосопоставления. Все ручные и
   связанные с группами дополнительные JTBD хранятся одним массивом
   трёхчастных объектов; прежняя строка переносится в desired_action.
   ================================================================ */
const GATE1_ADDITIONAL_JTBD_STRUCTURED_V268 =
  "gate1-additional-jtbd-structured-v268";

function guruGate1AdditionalJtbdEntryV268(value, defaults = {}) {
  const isObject = Boolean(
    value && typeof value === "object" && !Array.isArray(value),
  );
  const current = isObject ? value : {};
  const legacyText = isObject ? "" : guruV185Text(value);
  const now = new Date().toISOString();
  return {
    ...current,
    id: guruV185Text(current.id) || makeId("additional-jtbd"),
    situation: guruV185Text(current.situation),
    desired_action:
      guruV185Text(current.desired_action ?? current.desiredAction) ||
      legacyText,
    result: guruV185Text(current.result),
    source:
      guruV185Text(current.source) ||
      guruV185Text(defaults.source) ||
      "manual",
    linked_group_id:
      guruV185Text(current.linked_group_id) ||
      guruV185Text(defaults.linked_group_id),
    created_at: current.created_at || defaults.created_at || now,
    updated_at: current.updated_at || defaults.updated_at || now,
    migrated_from_flat:
      current.migrated_from_flat === true || Boolean(legacyText),
  };
}

function guruGate1AdditionalJtbdTextV268(value) {
  const entry = guruGate1AdditionalJtbdEntryV268(value);
  return [entry.situation, entry.desired_action, entry.result]
    .map(guruV185Text)
    .filter(Boolean)
    .join("\n");
}

function guruGate1EnsureAdditionalJtbdsV268(itemData, audit = null) {
  if (!itemData || typeof itemData !== "object") return [];
  itemData.semL4Model = itemData.semL4Model &&
    typeof itemData.semL4Model === "object"
    ? itemData.semL4Model
    : { mainJtbd: "", additionalJtbds: [] };
  const raw = Array.isArray(itemData.semL4Model.additionalJtbds)
    ? itemData.semL4Model.additionalJtbds
    : [];
  if (audit) {
    audit.flat += raw.filter((value) =>
      (typeof value !== "object" && Boolean(guruV185Text(value))) ||
      value?.migrated_from_flat === true,
    ).length;
  }
  const additional = raw.map((value) =>
    guruGate1AdditionalJtbdEntryV268(value),
  );

  (itemData.semL3Groups || []).forEach((group) => {
    if (!group || typeof group !== "object") return;
    const oldLinked = group.additionalJtbdV267;
    if (!oldLinked || typeof oldLinked !== "object") return;
    let entry = additional.find((candidate) =>
      candidate.id === guruV185Text(group.additionalJtbdIdV268) ||
      candidate.linked_group_id === guruV185Text(group.id),
    );
    if (!entry && additional.length < 3) {
      entry = guruGate1AdditionalJtbdEntryV268(oldLinked, {
        source: "confirmed-demand-group",
        linked_group_id: group.id,
      });
      entry.linked_group_id = guruV185Text(group.id);
      additional.push(entry);
      if (audit) audit.groupForms += 1;
    }
    group.additionalJtbdLegacyV267 = group.additionalJtbdLegacyV267 || {
      ...oldLinked,
    };
    group.additionalJtbdIdV268 = entry?.id || "";
    group.additionalJtbdLimitReachedV268 = !entry;
    // Keep the legacy source intact. A read or migration must never erase it.
  });

  itemData.semL4Model.additionalJtbds = additional;
  pv181SyncJtbdModel(itemData);
  return itemData.semL4Model.additionalJtbds;
}

function guruGate1AdditionalJtbdGroupV268(itemData, entry) {
  const groupId = guruV185Text(entry?.linked_group_id);
  const entryId = guruV185Text(entry?.id);
  return (itemData?.semL3Groups || []).find((group) =>
    (groupId && guruV185Text(group?.id) === groupId) ||
    (entryId && guruV185Text(group?.additionalJtbdIdV268) === entryId),
  ) || null;
}

