/* Структурные действия перехватываются до старого строкового обработчика:
   он больше не должен создавать плоские значения или рендерить старый DOM. */
document.addEventListener("click", (event) => {
  const button = event.target?.closest?.(
    "[data-pv181-jtbd-add], [data-pv181-jtbd-remove]",
  );
  if (!button) return;
  const context = pv181QueryGroupTarget(button);
  if (!context) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  const list = guruGate1EnsureAdditionalJtbdsV268(context.itemData);
  if (button.hasAttribute("data-pv181-jtbd-add")) {
    if (list.length >= 3) return;
    list.push(guruGate1AdditionalJtbdEntryV268(null, { source: "manual" }));
  } else {
    const requestedId = guruV185Text(button.dataset.pv181JtbdRemoveId);
    const fallbackIndex = Number(button.dataset.pv181JtbdRemove);
    const entry = requestedId
      ? list.find((candidate) => candidate.id === requestedId)
      : Number.isInteger(fallbackIndex)
        ? list[fallbackIndex]
        : null;
    if (entry) {
      const linkedGroup = guruGate1AdditionalJtbdGroupV268(
        context.itemData,
        entry,
      );
      guruGate1ReleaseAdditionalJtbdKeywordsV274(
        context.itemId,
        context.itemData,
        entry,
      );
      // releaseAdditionalJtbdKeywords пересчитывает формы и заменяет массив
      // нормализованной копией. Удаляем поэтому из заново полученного массива,
      // адресуя форму по стабильному id, а не по устаревшему индексу.
      const currentList = guruGate1EnsureAdditionalJtbdsV268(
        context.itemData,
      );
      const currentIndex = currentList.findIndex((candidate) =>
        candidate.id === entry.id,
      );
      if (currentIndex >= 0) currentList.splice(currentIndex, 1);
      if (
        linkedGroup &&
        guruV185Text(linkedGroup.additionalJtbdIdV268) === entry.id
      ) delete linkedGroup.additionalJtbdIdV268;
    }
  }
  pv181SyncJtbdModel(context.itemData);
  flashSaving();
  renderGate();
}, true);

function guruGate1AdditionalJtbdMigrationV268(workspace = state) {
  if (!workspace?.project) return null;
  const log = (workspace.project._gate1ProductIdMigrationLog = Array.isArray(
    workspace.project._gate1ProductIdMigrationLog,
  ) ? workspace.project._gate1ProductIdMigrationLog : []);
  let entry = log.find((item) =>
    item.id === GATE1_ADDITIONAL_JTBD_STRUCTURED_V268,
  );
  const audit = { items: 0, flat: 0, groupForms: 0, migrated: [] };
  (workspace.painV130?.productMaps || []).forEach((map) => {
    Object.entries(map?.items || {}).forEach(([itemId, itemData]) => {
      if (!itemData || typeof itemData !== "object") return;
      const raw = Array.isArray(itemData.semL4Model?.additionalJtbds)
        ? itemData.semL4Model.additionalJtbds
        : [];
      const flatValues = raw
        .filter((value) =>
          typeof value !== "object" || value?.migrated_from_flat === true,
        )
        .map((value) =>
          typeof value === "object"
            ? guruV185Text(value?.desired_action)
            : guruV185Text(value),
        )
        .filter(Boolean);
      const oldGroupForms = (itemData.semL3Groups || []).filter((group) =>
        group?.additionalJtbdV267 &&
        typeof group.additionalJtbdV267 === "object",
      ).length;
      audit.items += 1;
      guruGate1EnsureAdditionalJtbdsV268(itemData, audit);
      if (flatValues.length || oldGroupForms) {
        audit.migrated.push({
          product_id: itemId,
          flat_values_to_desired_action: flatValues.length,
          linked_group_forms: oldGroupForms,
        });
      }
    });
  });
  if (!entry) {
    entry = {
      id: GATE1_ADDITIONAL_JTBD_STRUCTURED_V268,
      at: new Date().toISOString(),
      status: "completed",
      storage:
        "painV130.productMaps[].items[product_id].semL4Model.additionalJtbds[]",
      schema:
        "{id, situation, desired_action, result, source, linked_group_id}",
      migration:
        "legacy string → desired_action; situation/result remain empty",
      maximum: 3,
      category_filter:
        "normalized words from selected product category are excluded from primary JTBD concepts",
      audit,
    };
    log.push(entry);
  }
  const previousLinkLog = log.find((item) =>
    item.id === GATE1_JTBD_DEMAND_LINK_V267,
  );
  if (previousLinkLog) {
    previousLinkLog.primary_match =
      "meaningful normalized word overlap from current Main JTBD plus selected product name; category words, JTBD structural words and stop words excluded";
    previousLinkLog.linked_jtbd =
      "semL4Model.additionalJtbds[] structured objects linked to semL3Groups by id; created empty only after group confirmation, maximum 3";
  }
  return entry;
}

