/* ================================================================
   v2.3.37 — восстановимая навигация через URL.

   Query-параметры являются только снимком текущего маршрута:
   project, gate, category, product. Переключение по-прежнему выполняют
   openProject / guruNavigateToGate / общий guruV194Ui-селектор.
   replaceState не перезагружает страницу и не засоряет историю браузера
   отдельной записью на каждое переключение выпадающего списка.
   ================================================================ */
function guruNavigationReadUrlV269() {
  const params = new URL(window.location.href).searchParams;
  const keys = GURU_NAVIGATION_URL_KEYS_V269;
  const route = {
    projectId: String(params.get(keys.project) || "").trim(),
    gateId: String(params.get(keys.gate) || "").trim(),
    categoryId: String(params.get(keys.category) || "").trim(),
    productId: String(params.get(keys.product) || "").trim(),
  };
  route.hasNavigationParams = Object.values(keys).some((key) => params.has(key));
  return route;
}

function guruNavigationCurrentSelectionV269(workspace = state) {
  if (!workspace?.project) return { categoryId: "", productId: "" };
  if (typeof guruV194Ui === "function") {
    const ui = guruV194Ui(workspace);
    return {
      categoryId: String(ui?.selectedCategoryId || "").trim(),
      productId: String(ui?.selectedProductId || "").trim(),
    };
  }
  const ui = workspace.project.gate0ScopeUiV194 || {};
  return {
    categoryId: String(ui.selectedCategoryId || "").trim(),
    productId: String(ui.selectedProductId || "").trim(),
  };
}

function guruNavigationSyncUrlV269(options = {}) {
  if (!guruNavigationUrlReadyV269 || guruNavigationUrlRestoringV269) return;
  const url = new URL(window.location.href);
  const keys = GURU_NAVIGATION_URL_KEYS_V269;
  Object.values(keys).forEach((key) => url.searchParams.delete(key));
  if (!options.clear && activeProjectId && state) {
    url.searchParams.set(keys.project, activeProjectId);
    if (activeView === "gate" && activeGateId)
      url.searchParams.set(keys.gate, activeGateId);
    const selection = guruNavigationCurrentSelectionV269(state);
    if (selection.categoryId)
      url.searchParams.set(keys.category, selection.categoryId);
    if (selection.productId)
      url.searchParams.set(keys.product, selection.productId);
  }
  const nextUrl = `${url.pathname}${url.search}${url.hash}`;
  const currentUrl = `${window.location.pathname}${window.location.search}${window.location.hash}`;
  if (nextUrl !== currentUrl)
    window.history.replaceState(
      { ...(window.history.state || {}), guruNavigationV269: true },
      "",
      nextUrl,
    );
}

function guruNavigationApplySelectionV269(route, workspace = state) {
  if (!route || !workspace?.project || typeof guruV194Ui !== "function") return;
  const products = typeof guruV194Products === "function"
    ? guruV194Products(workspace)
    : [];
  const categories = typeof guruV185Registry === "function"
    ? guruV185Registry(workspace)
    : [];
  const ui = guruV194Ui(workspace);
  const requestedProduct = products.find(
    (item) => String(item?.id || "") === route.productId,
  );
  if (requestedProduct) {
    ui.selectedProductId = requestedProduct.id;
    ui.selectedCategoryId = megaPlatformProductCategoryIds(requestedProduct, workspace)
      .includes(route.categoryId)
      ? route.categoryId : megaPlatformProductCategoryId(requestedProduct, workspace) || "__uncategorized__";
    return;
  }
  const categoryExists = categories.some(
    (item) => String(item?.id || "") === route.categoryId,
  );
  const uncategorizedExists =
    route.categoryId === "__uncategorized__" &&
    products.some((item) => !megaPlatformProductCategoryIds(item, workspace).length);
  if (!categoryExists && !uncategorizedExists) return;
  ui.selectedCategoryId = route.categoryId;
  const matchingProducts = products.filter((item) =>
    route.categoryId === "__uncategorized__"
      ? !megaPlatformProductCategoryIds(item, workspace).length
      : megaPlatformProductCategoryIds(item, workspace).includes(route.categoryId),
  );
  ui.selectedProductId = matchingProducts[0]?.id || "";
}

function guruNavigationApplyPendingSelectionV269(projectId) {
  const route = guruNavigationPendingRouteV269;
  if (!guruNavigationUrlReadyV269 || !route || route.projectId !== projectId) return;
  guruNavigationApplySelectionV269(route, state);
}

function guruNavigationFinishPendingRouteV269(projectId) {
  const route = guruNavigationPendingRouteV269;
  if (!route || route.projectId !== projectId) return;
  guruNavigationApplySelectionV269(route, state);
  guruNavigationPendingRouteV269 = null;
  guruNavigationSyncUrlV269();
}

function guruNavigationRestoreFromUrlV269() {
  if (!guruNavigationUrlReadyV269) return "none";
  const route = guruNavigationReadUrlV269();
  if (!route.hasNavigationParams) return "none";
  const project = projects.find((item) => String(item?.id || "") === route.projectId);
  if (!project) {
    guruNavigationPendingRouteV269 = null;
    guruNavigationSyncUrlV269({ clear: true });
    showLauncher();
    return "invalid";
  }
  guruNavigationPendingRouteV269 = route;
  guruNavigationUrlRestoringV269 = true;
  try {
    openProject(project.id);
    guruNavigationApplySelectionV269(route, state);
    const gateExists = state?.gates?.some(
      (gate) => String(gate?.id || "") === route.gateId,
    );
    if (route.gateId && gateExists) guruNavigateToGate(route.gateId);
  } finally {
    guruNavigationUrlRestoringV269 = false;
  }
  guruNavigationSyncUrlV269();
  return "restored";
}

