/* ================================================================
   v2.3.82 — системная ревизия дублей Gate 4.

   Старый мост Gate 3 → Gate 4 возвращал в Gate 4 каналы, которые
   продуктовая 5A уже прочитала из Gate 0/4. Дополнительный канал при
   этом записывался одновременно в channel и platform, поэтому его
   ключ становился name_name_N. Мост удалён выше. Аудит ниже больше не
   удаляет даже пустые исторические записи: все они остаются в хранилище
   и попадают в manualReview, пока пользователь не примет отдельное решение.
   ================================================================ */
const GATE4_DUPLICATE_CLEANUP_V283 = "gate4-duplicate-cleanup-v283";

const G4_READINESS_TITLE_FIXES_V283 = Object.freeze({
  "card-147": "Карта реализации — вводный раздел",
  "card-148": "Единая карта запуска",
});

function g4CampaignDuplicatePatternV283(stateKey, campaign, workspace = state) {
  const productId = guruV185Text(campaign?.product);
  const products = Array.isArray(workspace?.project?.catalogItemsV189)
    ? workspace.project.catalogItemsV189
    : [];
  if (!productId || !products.some((product) => product.id === productId))
    return null;
  const prefix = `${normalizeAspectKey(productId)}_`;
  if (!stateKey.startsWith(prefix)) return null;
  const body = stateKey
    .slice(prefix.length)
    .replace(/_\d+$/, "");
  const tokens = body.split("_").filter(Boolean);
  let best = null;
  for (let index = 1; index < tokens.length; index += 1) {
    const left = tokens.slice(0, index).join("_");
    const right = tokens.slice(index).join("_");
    if (Math.min(left.length, right.length) < 8) continue;
    const length = Math.max(left.length, right.length) || 1;
    const distance = g4ProductIdLevenshteinV224(left, right);
    const similarity = 1 - distance / length;
    if (!best || similarity > best.similarity)
      best = { left, right, similarity };
  }
  return best && best.similarity >= 0.86
    ? { ...best, productId, key: stateKey }
    : null;
}

function g4ReadinessTitleAuditV283(workspace = state) {
  const cards = g4ReadinessAllCardsV225(workspace);
  const groups = new Map();
  cards.forEach((card) => {
    const titleKey = normalizeAspectKey(card.title);
    if (!groups.has(titleKey)) groups.set(titleKey, []);
    groups.get(titleKey).push({ id: card.id, title: card.title });
  });
  return {
    count: cards.length,
    duplicates: [...groups.values()].filter((items) => items.length > 1),
    cards: cards.map((card) => ({ id: card.id, title: card.title })),
  };
}

function g4CampaignDuplicateAuditV283(workspace = state) {
  const campaigns = workspace?.gate4Production?.campaigns || {};
  const products = Array.isArray(workspace?.project?.catalogItemsV189)
    ? workspace.project.catalogItemsV189
    : [];
  const byProduct = products.map((product) => {
    const rows = Object.entries(campaigns).filter(
      ([, campaign]) => guruV185Text(campaign?.product) === product.id,
    );
    const duplicates = rows
      .map(([key, campaign]) => {
        const pattern = g4CampaignDuplicatePatternV283(
          key,
          campaign,
          workspace,
        );
        if (!pattern) return null;
        const hasData = g4ProductIdCampaignHasDataV224(campaign);
        return {
          key,
          status: g4CampaignStatus(campaign),
          hasData,
          similarity: Number(pattern.similarity.toFixed(4)),
          repeatedParts: [pattern.left, pattern.right],
        };
      })
      .filter(Boolean);
    return {
      productId: product.id,
      productName: product.name,
      count: rows.length,
      duplicateCount: duplicates.length,
      emptyDuplicateCount: duplicates.filter((row) => !row.hasData).length,
      nonEmptyDuplicateCount: duplicates.filter((row) => row.hasData).length,
      duplicates,
    };
  });
  return {
    count: Object.keys(campaigns).length,
    duplicateCount: byProduct.reduce(
      (sum, product) => sum + product.duplicateCount,
      0,
    ),
    byProduct,
  };
}

function gate4DuplicateCleanupV283(workspace = state) {
  if (!workspace?.project) return { changed: false, removed: [], preserved: [] };

  const titleBefore = g4ReadinessTitleAuditV283(workspace);
  const renamedCards = [];
  Object.entries(G4_READINESS_TITLE_FIXES_V283).forEach(([cardId, title]) => {
    const card = g4ReadinessCardV225(cardId, workspace);
    if (!card || card.title === title) return;
    renamedCards.push({ cardId, from: card.title || "", to: title });
    card.title = title;
  });

  const campaignBefore = g4CampaignDuplicateAuditV283(workspace);
  const removed = [];
  const preserved = [];
  campaignBefore.byProduct.forEach((product) => {
    product.duplicates.forEach((duplicate) => {
      preserved.push({
        productId: product.productId,
        productName: product.productName,
        ...duplicate,
        snapshot: structuredClone(
          workspace.gate4Production?.campaigns?.[duplicate.key] || {},
        ),
        reason: duplicate.hasData
          ? "contains_data_manual_review_required"
          : "preserved_by_gate4_funnel_no_delete_policy",
      });
    });
  });

  const campaignAfter = g4CampaignDuplicateAuditV283(workspace);
  const titleAfter = g4ReadinessTitleAuditV283(workspace);
  const changed = Boolean(renamedCards.length || removed.length);
  const logs = (workspace.project._gate4DuplicateCleanupLogV283 = Array.isArray(
    workspace.project._gate4DuplicateCleanupLogV283,
  )
    ? workspace.project._gate4DuplicateCleanupLogV283
    : []);
  let entry = logs.find((item) => item.id === GATE4_DUPLICATE_CLEANUP_V283);
  if (!entry) {
    entry = {
      id: GATE4_DUPLICATE_CLEANUP_V283,
      at: new Date().toISOString(),
      status: "completed",
      cause:
        "Gate 4 re-read derivative Gate 3 channels; extra rows copied the same name to channel and platform, producing name_name_N keys",
      fix:
        "Gate 4 reads primary Gate 0/1 channel sources; historical rows are audited and preserved without deletion",
      runs: [],
    };
    logs.push(entry);
  }
  const preservedSignature = preserved
    .map((item) => item.key)
    .sort()
    .join("|");
  const lastRun = entry.runs[entry.runs.length - 1];
  const loggedPreservedSignature = (lastRun?.campaigns?.manualReview || [])
    .map((item) => item.key)
    .sort()
    .join("|");
  if (
    changed ||
    !entry.runs.length ||
    preservedSignature !== loggedPreservedSignature
  ) {
    entry.updatedAt = new Date().toISOString();
    entry.runs.push({
      at: entry.updatedAt,
      readiness: {
        before: titleBefore,
        renamedCards,
        after: titleAfter,
      },
      campaigns: {
        before: campaignBefore,
        removed,
        manualReview: preserved,
        after: campaignAfter,
      },
    });
  }
  return {
    changed,
    renamedCards,
    removed,
    preserved,
    before: campaignBefore,
    after: campaignAfter,
    titleBefore,
    titleAfter,
  };
}

