/* ================================================================
   v2.3.220 — Gate 4 / РСЯ: фундамент группы читается по product_id.

   Восемь полей ниже раньше были редактируемыми снимками данных Gate 0/1
   и товарного селектора Gate 4. Миграция сначала сопоставляет каждый
   сохранённый текст с актуальными вариантами источника. Реальные ручные
   расхождения целиком сохраняются в журнале для решения Лукой, после чего
   дубли удаляются из группы. Повторный запуск ничего не меняет.
   ================================================================ */
const GATE4_RSYA_FOUNDATION_SOURCE_V455 =
  "gate4-rsya-foundation-source-v455";
const G4_RSYA_GROUP_FOUNDATION_FIELDS_V455 = Object.freeze([
  "jtbd",
  "offer",
  "benefit",
  "usp",
  "segment",
  "category",
  "landing",
  "targetAction",
]);

function g4RsyaFoundationComparableV455(value) {
  return String(value || "").trim().replace(/\s+/g, " ");
}

function g4RsyaFoundationMatchesV455(storedValue, sourceValue) {
  const stored = g4RsyaFoundationComparableV455(storedValue);
  const source = g4RsyaFoundationComparableV455(sourceValue);
  if (!stored || !source) return false;
  if (stored === source) return true;
  if (!stored.includes("\uFFFD")) return false;
  const pieces = stored.split(/\uFFFD+/).filter(Boolean);
  if (!pieces.length) return false;
  let cursor = 0;
  for (const piece of pieces) {
    const index = source.indexOf(piece, cursor);
    if (index < 0) return false;
    cursor = index + piece.length;
  }
  return source.startsWith(pieces[0]) && source.endsWith(pieces.at(-1));
}

function g4RsyaMigrationSourceCandidatesV455(
  workspace,
  branchKey,
  group,
  field,
) {
  const catalogProduct = g4RsyaCatalogProductV289(
    branchKey,
    group,
    workspace,
  );
  if (!catalogProduct || typeof guruV194Records !== "function") return [];
  const sourceField = ({
    jtbd: "jtbd",
    offer: "offers",
    benefit: "usp",
    usp: "usp",
    segment: "segments",
    targetAction: "cta",
  })[field];
  if (!sourceField) return [];
  const records = guruV194Records(workspace).filter((record) =>
    record?.field === sourceField &&
    (
      record.scope === "project" ||
      g4RsyaTextV289(record.category_id) ===
        g4RsyaTextV289(catalogProduct.categoryId) ||
      g4RsyaTextV289(record.product_id) ===
        g4RsyaTextV289(catalogProduct.id)
    ),
  );
  const values = records.map((record) =>
    field === "jtbd" && typeof guruStrategicRecordValueV286 === "function"
      ? guruStrategicRecordValueV286("jtbd", record)
      : g4RsyaTextV289(record.value),
  );
  if (field === "targetAction" && typeof guruV194OfferParts === "function") {
    guruV194Records(workspace)
      .filter((record) => record?.field === "offers" && records.some(
        (candidate) =>
          candidate.scope === record.scope &&
          candidate.category_id === record.category_id &&
          candidate.product_id === record.product_id,
      ))
      .forEach((record) => values.push(guruV194OfferParts(record).cta));
  }
  return values.map((value) => g4RsyaTextV289(value)).filter(Boolean);
}

function g4RsyaMigrateGroupFoundationV455(workspace) {
  if (!workspace?.project)
    return { changed: false, removed: [], manualReview: [], unresolved: [] };
  const logs = (workspace.project._gate4RsyaFoundationMigrationLog =
    Array.isArray(workspace.project._gate4RsyaFoundationMigrationLog)
      ? workspace.project._gate4RsyaFoundationMigrationLog
      : []);
  const existing = logs.find(
    (entry) => entry.id === GATE4_RSYA_FOUNDATION_SOURCE_V455,
  );
  if (existing) {
    return {
      changed: false,
      removed: existing.removed || [],
      manualReview: existing.manual_review || [],
      unresolved: existing.unresolved || [],
      alreadyMigrated: true,
    };
  }

  const removed = [];
  const matchedCopies = [];
  const manualReview = [];
  const unresolved = [];
  let groupCount = 0;
  Object.entries(workspace.gate4Rsya || {}).forEach(
    ([branchKey, branch]) => {
      const groups = Array.isArray(branch?.groups) ? branch.groups : [];
      groups.forEach((group, groupIndex) => {
        if (!group || typeof group !== "object") return;
        groupCount += 1;
        let sources = {};
        try {
          sources = g4RsyaProjectOptionsV289(
            branchKey,
            group,
            workspace,
          );
        } catch (error) {
          sources = {};
        }
        G4_RSYA_GROUP_FOUNDATION_FIELDS_V455.forEach((field) => {
          if (!Object.hasOwn(group, field)) return;
          const storedValue = String(group[field] || "").trim();
          const sourceKey = field === "category" ? "product" : field;
          const options = Array.isArray(sources[sourceKey])
            ? sources[sourceKey]
            : [];
          const selected = g4RsyaSourceOptionV289(
            group,
            sourceKey,
            options,
          );
          const candidates = [...new Set(options
            .map((option) => String(option?.value || "").trim())
            .filter(Boolean)
            .concat(g4RsyaMigrationSourceCandidatesV455(
              workspace,
              branchKey,
              group,
              field,
            )))];
          const matchesSource = candidates.some((value) =>
            g4RsyaFoundationMatchesV455(storedValue, value),
          );
          const record = {
            branch_key: branchKey,
            group_id: String(group.id || ""),
            group_index: groupIndex,
            product_id: String(group.product_id || ""),
            field,
            stored_value: storedValue,
            source_value: String(selected?.value || "").trim(),
            source: String(selected?.source || ""),
          };
          if (storedValue && matchesSource) matchedCopies.push(record);
          else if (storedValue && candidates.length) {
            manualReview.push({
              ...record,
              source_candidates: candidates,
              reason: "stored_value_differs_from_current_source",
            });
          } else if (storedValue) {
            unresolved.push({
              ...record,
              reason: "current_source_not_resolved",
            });
          }
          delete group[field];
          removed.push({ ...record, had_value: Boolean(storedValue) });
        });
      });
    },
  );

  if (!removed.length) {
    return {
      changed: false,
      removed,
      matchedCopies,
      manualReview,
      unresolved,
      noLegacyFields: true,
    };
  }

  const at = new Date().toISOString();
  const entry = {
    id: GATE4_RSYA_FOUNDATION_SOURCE_V455,
    at,
    status: manualReview.length || unresolved.length
      ? "completed_needs_manual_review"
      : "completed",
    storage: "workspace.gate4Rsya[catalog_item_id].groups[]",
    source:
      "groups[].product_id → Gate 0 · Стратегическая основа / Gate 1 · Целевая аудитория / Gate 4 · селектор товара",
    groups_scanned: groupCount,
    fields_removed: removed.length,
    matched_copies: matchedCopies,
    manual_review: manualReview,
    unresolved,
    removed,
    note:
      "Поля jtbd/offer/benefit/usp/segment/category/landing/targetAction удалены из групп РСЯ. Совпавшие копии отброшены; отличающиеся ручные значения сохранены в manual_review для решения Лукой и не потеряны молча.",
  };
  logs.push(entry);
  if (manualReview.length || unresolved.length) {
    console.warn(
      "[GURU gate4Rsya foundation migration] Лука: нужны ручные решения",
      { manualReview, unresolved },
    );
  }
  return {
    changed: removed.length > 0,
    removed,
    matchedCopies,
    manualReview,
    unresolved,
    entry,
  };
}

