document.addEventListener("change", (event) => {
  const select = event.target?.closest?.("[data-g4rsya-platform-page-ref]");
  if (!select) return;
  const encoded = select.value;
  const split = encoded.indexOf(":");
  const ref = split < 0 ? null : { group: encoded.slice(0, split), id: encoded.slice(split + 1) };
  const product = select.dataset.g4rsyaProduct;
  if (select.dataset.g4rsyaStore === "promotion") {
    const record = ensureGate4RsyaV289(product)?.campaign?.promotion;
    if (!record) return;
    record.pageRefV1 = ref;
  } else {
    const { ad } = g4RsyaFindV289(product,
      select.dataset.g4rsyaGroupId, select.dataset.g4rsyaAdId);
    const link = ad?.sitelinks?.find((item) => item.id === select.dataset.g4rsyaItemId);
    if (!link) return;
    link.pageRefV1 = ref;
  }
  flashSaving();
  renderGate();
});

function g4RsyaSelectFieldV289(options) {
  return `<label class="g4-rsya-field-v289"><span class="g4-rsya-field-label-v289"><b>${escapeHtml(options.label)}</b></span>${options.hint ? `<small class="g4-rsya-hint-v289">${escapeHtml(options.hint)}</small>` : ""}<select class="g1-input ${options.value ? "is-filled" : "is-empty"}" data-g4rsya-v289-bind data-g4rsya-v289-product="${escapeAttr(options.product)}" data-g4rsya-v289-channel="${escapeAttr(options.channel || "")}" data-g4rsya-v289-store="${escapeAttr(options.store)}" data-g4rsya-v289-field="${escapeAttr(options.field)}" data-g4rsya-v289-group-id="${escapeAttr(options.groupId || "")}" data-g4rsya-v289-ad-id="${escapeAttr(options.adId || "")}">${options.options.map(([value, label]) => `<option value="${escapeAttr(value)}" ${options.value === value ? "selected" : ""}>${escapeHtml(label)}</option>`).join("")}</select></label>`;
}

function g4RsyaSectionV289(number, title, copy, body, extra = "") {
  return `<section class="g4-rsya-section-v289" id="g4-rsya-section-${number}"><header><span>${number}</span><div><h4>${escapeHtml(title)}</h4><p>${escapeHtml(copy)}</p></div>${extra}</header><div class="g4-rsya-section-body-v289">${body}</div></section>`;
}

