function g4RsyaOpenGroupIdsV461(d) {
  d.ui = d.ui && typeof d.ui === "object" ? d.ui : {};
  d.ui.openGroupIdsV461 = Array.isArray(d.ui.openGroupIdsV461)
    ? d.ui.openGroupIdsV461.filter((id) => g4RsyaTextV289(id))
    : [];
  return d.ui.openGroupIdsV461;
}

function g4RsyaGroupIsOpenV461(d, groupId) {
  return g4RsyaOpenGroupIdsV461(d).includes(groupId);
}

function g4RsyaSetGroupOpenV461(d, groupId, open) {
  const ids = new Set(g4RsyaOpenGroupIdsV461(d));
  if (open) ids.add(groupId);
  else ids.delete(groupId);
  d.ui.openGroupIdsV461 = [...ids];
}

