function g4RsyaSearchForecastHtmlV363(product) {
  const build = state.gate4SearchBuild?.[normalizeAspectKey(product || "no_product")];
  const rows = Array.isArray(build?.groupRows) ? build.groupRows : [];
  const items = rows.map((row, index) => {
    try {
      const phraseCount = (Array.isArray(row.demandRows) ? row.demandRows : []).filter((item) => g4RsyaTextV289(item?.kw)).length;
      // Работаем с копией и не вызываем ensureGate4SearchBuild: он мигрирует состояние Поиска.
      const assessment = g4sbV140ForecastAssessment(structuredClone(row), phraseCount, structuredClone(build.settings || {}), "");
      const scenarios = assessment.conversionScenarios.filter((item) => Number.isFinite(item.cpa) && item.cpa > 0);
      if (!scenarios.length || assessment.errors.length) return "";
      return `<li><strong>${escapeHtml(row.col0 || `Группа ${index + 1}`)}</strong> · ${scenarios.map((item) => `${escapeHtml(item.label)} ${Math.round(item.cpa).toLocaleString("ru-RU")} ₽`).join(" · ")}</li>`;
    } catch (_error) { return ""; }
  }).filter(Boolean);
  return `<details class="g4-rsya-reference-v363"><summary>Прогноз CPA Поиска · только для справки</summary>
    ${g4RsyaGuideV363("searchForecast")}
    ${items.length ? `<ul>${items.join("")}</ul>` : '<p class="g4-rsya-note-v289">У выбранного товара нет заполненного прогноза CPA Поиска.</p>'}
  </details>`;
}

