function g4RsyaImageForFormatV465(images, format) {
  const available = (images || []).filter((image) => image?.dataUrl || image?.url);
  if (!available.length) return null;
  const sameFamily = available.filter((image) =>
    g4RsyaImageFamilyV465(image) === format.family,
  );
  return [...(sameFamily.length ? sameFamily : available)].sort((left, right) =>
    Math.abs(g4RsyaImageRatioV465(left) - format.value) -
      Math.abs(g4RsyaImageRatioV465(right) - format.value),
  )[0] || null;
}

function g4RsyaSelectedPreviewImageV470(ad) {
  const selectedId = g4RsyaTextV289(ad?.previewImageId);
  if (!selectedId) return null;
  return (Array.isArray(ad?.images) ? ad.images : []).find((image) =>
    image?.id === selectedId && (image?.dataUrl || image?.url),
  ) || null;
}

function g4RsyaImageIdentityV475(image) {
  const dataUrl = typeof image?.dataUrl === "string" ? image.dataUrl : "";
  if (dataUrl) return dataUrl;
  const rawUrl = g4RsyaTextV289(image?.url);
  if (!rawUrl) return "";
  try {
    const url = new URL(rawUrl);
    url.hash = "";
    return `url:${url.href}`;
  } catch (_error) {
    return `url:${rawUrl}`;
  }
}

function g4RsyaImageNameKeyV476(image) {
  let name = g4RsyaTextV289(image?.originalName || image?.name);
  if (!name && image?.url) {
    try {
      name = decodeURIComponent(new URL(image.url).pathname.split("/").pop() || "");
    } catch (_error) {
      name = String(image.url).split(/[?#]/)[0].split("/").pop() || "";
    }
  }
  return name
    .normalize("NFKC")
    .trim()
    .toLocaleLowerCase("ru-RU")
    .replace(/\.(?:jpe?g|png|gif|webp)$/i, "")
    .replace(/\s+/g, " ");
}

function g4RsyaImageDuplicateKeysV476(image) {
  const keys = [];
  const identity = g4RsyaImageIdentityV475(image);
  if (identity) keys.push(`source:${identity}`);
  const sourceId = g4RsyaTextV289(image?.sourceId);
  if (sourceId) keys.push(`project:${sourceId}`);
  const fingerprint = g4RsyaTextV289(image?.visualFingerprintV476);
  if (fingerprint) keys.push(`visual:${fingerprint}`);
  const name = g4RsyaImageNameKeyV476(image);
  const width = Number(image?.width) || 0;
  const height = Number(image?.height) || 0;
  if (name && width && height) keys.push(`file:${name}:${width}x${height}`);
  if (name && /^[0-9a-f]{8}(?:[-_][0-9a-f]{4}){3}[-_][0-9a-f]{12}$/i.test(name))
    keys.push(`uuid:${name.replace(/_/g, "-")}`);
  return [...new Set(keys)];
}

function g4RsyaVisualFingerprintV476(image) {
  try {
    const canvas = document.createElement("canvas");
    canvas.width = 9;
    canvas.height = 8;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    if (!context) return "";
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    const pixels = context.getImageData(0, 0, canvas.width, canvas.height).data;
    let bits = "";
    for (let y = 0; y < 8; y += 1) {
      for (let x = 0; x < 8; x += 1) {
        const left = (y * 9 + x) * 4;
        const right = left + 4;
        const leftLuma = pixels[left] * 3 + pixels[left + 1] * 6 + pixels[left + 2];
        const rightLuma = pixels[right] * 3 + pixels[right + 1] * 6 + pixels[right + 2];
        bits += leftLuma > rightLuma ? "1" : "0";
      }
    }
    return bits.match(/.{4}/g)
      .map((part) => Number.parseInt(part, 2).toString(16))
      .join("");
  } catch (_error) {
    return "";
  }
}

async function g4RsyaEnsureImageFingerprintV476(image) {
  if (g4RsyaTextV289(image?.visualFingerprintV476))
    return image.visualFingerprintV476;
  const src = image?.dataUrl || image?.url || "";
  if (!src) return "";
  const element = new Image();
  if (!image?.dataUrl) element.crossOrigin = "anonymous";
  const loaded = new Promise((resolve, reject) => {
    element.addEventListener("load", resolve, { once: true });
    element.addEventListener("error", reject, { once: true });
  });
  element.src = src;
  try {
    await loaded;
    image.visualFingerprintV476 = g4RsyaVisualFingerprintV476(element);
  } catch (_error) {
    image.visualFingerprintV476 = "";
  }
  return image.visualFingerprintV476;
}

function g4RsyaImageDuplicateV476(images, candidate, excludeId = "") {
  const candidateKeys = new Set(g4RsyaImageDuplicateKeysV476(candidate));
  return (images || []).find((image) =>
    image?.id !== excludeId &&
    g4RsyaImageDuplicateKeysV476(image).some((key) => candidateKeys.has(key)),
  ) || null;
}

function g4RsyaDeduplicateAdImagesV476(ad) {
  if (!Array.isArray(ad?.images) || ad.images.length < 2) return false;
  const kept = [];
  let changed = false;
  ad.images.forEach((image) => {
    const duplicate = g4RsyaImageDuplicateV476(kept, image);
    if (!duplicate) {
      kept.push(image);
      return;
    }
    if (ad.previewImageId === image.id) ad.previewImageId = duplicate.id;
    changed = true;
  });
  if (changed) ad.images = kept;
  return changed;
}

