function g4RsyaImagesGalleryHtmlV471(product, channel, group, ad, projectPhotos) {
  const images = Array.isArray(ad.images) ? ad.images : [];
  const imageLimitReached = images.length >= G4_RSYA_LIMITS_V289.images;
  const addedSourceIds = new Set(images
    .map((image) => g4RsyaTextV289(image?.sourceId))
    .filter(Boolean));
  const previewImageId = g4RsyaTextV289(ad.previewImageId);
  const availableProjectPhotos = projectPhotos.filter((photo) =>
    !addedSourceIds.has(g4RsyaTextV289(photo.id)),
  );
  const imageCards = images.map((image, index) =>
    g4RsyaImageCardHtmlV471(
      product,
      channel,
      group,
      ad,
      image,
      index,
      previewImageId,
      projectPhotos,
    ),
  );
  const projectCards = availableProjectPhotos.map((photo) => {
    const src = photo.dataUrl || photo.url || "";
    return `<div class="g4-rsya-project-photo-slot-v488"><button type="button" class="g4-rsya-project-photo-v465" data-g4rsya-v289-add-project-image="${escapeAttr(photo.id)}" data-g4rsya-v289-product="${escapeAttr(product)}" data-g4rsya-v289-group-id="${escapeAttr(group.id)}" data-g4rsya-v289-ad-id="${escapeAttr(ad.id)}" aria-label="Добавить ${escapeAttr(photo.name || "фото товара")} в объявление" ${imageLimitReached ? "disabled" : ""}>
      <span class="g4-rsya-project-photo-thumb-v465">${src ? `<img src="${escapeAttr(src)}" alt="" />` : "Фото"}</span>
      <span title="${escapeAttr(photo.name || "Фото товара")}">${escapeHtml(photo.name || "Фото товара")}</span>
      <small>Добавить</small>
    </button>${g4RsyaImageNameEditorV490({ name: photo.name || "Фото товара", originalName: photo.originalName || "", generated: photo.generatedNameV490, product, groupId: group.id, adId: ad.id, sourceId: photo.id })}<button type="button" class="g4-rsya-project-photo-delete-v488" data-g4rsya-v488-delete-project-photo="${escapeAttr(photo.id)}" data-g4rsya-v289-product="${escapeAttr(product)}" data-g4rsya-v289-group-id="${escapeAttr(group.id)}" data-g4rsya-v289-ad-id="${escapeAttr(ad.id)}" aria-label="Удалить ${escapeAttr(photo.name || "фото товара")} из проекта и всех объявлений">Удалить навсегда</button></div>`;
  });
  const cards = [...imageCards, ...projectCards];
  return `<section class="g4-rsya-project-files-v289 g4-rsya-project-files-v465 g4-rsya-image-gallery-v471" data-g4rsya-v465-project-photos data-g4rsya-v471-image-gallery>
    <header><strong>Фото товара из проекта · ${projectPhotos.length}</strong><small>Нажмите на миниатюру, чтобы показать изображение в предпросмотре</small></header>
    <div class="g4-rsya-project-photo-grid-v465 g4-rsya-image-gallery-grid-v471">${cards.join("") || '<p class="g4-rsya-empty-v289">Готовое изображение ещё не добавлено.</p>'}</div>
  </section>`;
}

