        <header class="g4-rsya-ad-preview-variant-head-v473"><strong>Вариант ${variant.index + 1}</strong><small>${variant.heading.number ? `Заголовок ${variant.heading.number}` : "Без заголовка"} + ${variant.text.number ? `Текст ${variant.text.number}` : "без текста"}</small></header>
