function g4RsyaRefreshPreviewImageSourceV470(target, image) {
  const choice = target?.closest?.("[data-g4rsya-v470-preview-image-row]")
    ?.querySelector("[data-g4rsya-v470-select-preview-image]");
  if (!choice || !image) return;
  const src = image.dataUrl || image.url || "";
  choice.disabled = !src;
  const current = choice.querySelector(":scope > img, :scope > .g4-rsya-file-placeholder-v289");
  if (src && current?.tagName !== "IMG") {
    const next = document.createElement("img");
    next.alt = "";
    next.src = src;
    current?.replaceWith(next);
  } else if (src && current) {
    current.src = src;
  } else if (!src && current?.tagName === "IMG") {
    const next = document.createElement("span");
    next.className = "g4-rsya-file-placeholder-v289";
    next.textContent = "URL";
    current.replaceWith(next);
  }
}

// Удаление фото не должно заново собирать весь Gate 4: в предпросмотре
