function g4RsyaRefreshDeletedImagePreviewV527(preview, previous, ad) {
  if (!preview) return;
  const before = g4RsyaPreviewFormatImagesV527(previous);
  const after = g4RsyaPreviewFormatImagesV527(ad);
  after.forEach(({ format, image }, index) => {
    if (before[index].image?.id === image?.id) return;
    const src = image?.dataUrl || image?.url || "";
    preview.querySelectorAll(
      `[data-g4rsya-v469-preview-format="${format.ratio}"]`,
    ).forEach((card) => {
      const frame = card.querySelector(".g4-rsya-ad-preview-media-v469");
      if (!frame) return;
      const current = frame.querySelector(":scope > img");
      const empty = frame.querySelector(":scope > .g4-rsya-ad-preview-image-empty-v469");
      if (src) {
        if (current) current.src = src;
        else {
          const next = document.createElement("img");
          next.src = src;
          next.alt = `Предпросмотр объявления ${format.ratio}`;
          frame.prepend(next);
        }
        empty?.remove();
      } else {
        current?.remove();
        if (!empty) {
          const next = document.createElement("span");
          next.className = "g4-rsya-ad-preview-image-empty-v469";
          next.textContent = "Добавьте изображение";
          frame.prepend(next);
        }
      }
      frame.classList.toggle("has-image", Boolean(src));
      frame.classList.toggle("is-empty", !src);
    });
  });
  preview.dataset.g4rsyaV470PreviewImageId =
    g4RsyaSelectedPreviewImageV470(ad)?.id || "";
}

function g4RsyaRefreshDeletedImageMediaV527(media, ad, projectPhotoId, projectPhotoCount) {
  const remaining = new Set((ad.images || []).map((image) => image.id));
  media.querySelectorAll("[data-g4rsya-v470-preview-image-row]").forEach((row) => {
    if (!remaining.has(row.dataset.g4rsyaV470PreviewImageRow)) row.remove();
  });
  if (projectPhotoId) {
    media.querySelectorAll(".g4-rsya-project-photo-slot-v488").forEach((slot) => {
      if (slot.querySelector(`[data-g4rsya-v289-add-project-image="${CSS.escape(projectPhotoId)}"], [data-g4rsya-v488-delete-project-photo="${CSS.escape(projectPhotoId)}"]`))
        slot.remove();
    });
    const projectCount = media.querySelector(".g4-rsya-project-files-v465 > header > strong");
    if (projectCount) projectCount.textContent = `Фото товара из проекта · ${projectPhotoCount}`;
  }
  const gallery = media.querySelector(".g4-rsya-image-gallery-grid-v471");
  if (gallery) {
    const hasCards = Boolean(gallery.querySelector(".g4-rsya-image-card-v471, .g4-rsya-project-photo-slot-v488"));
    gallery.querySelector(".g4-rsya-empty-v289")?.remove();
    if (!hasCards) {
      const empty = document.createElement("p");
      empty.className = "g4-rsya-empty-v289";
      empty.textContent = "Готовое изображение ещё не добавлено.";
      gallery.append(empty);
    }
  }
  const count = ad.images.length;
  const reached = count >= G4_RSYA_LIMITS_V289.images;
  const head = media.querySelector(".g4-rsya-media-head-v289");
  const counter = head?.querySelector(":scope > strong");
  if (counter) {
    counter.textContent = `Изображения · ${count}/${G4_RSYA_LIMITS_V289.images}`;
    counter.classList.toggle("g4-rsya-image-count-over-limit", count > G4_RSYA_LIMITS_V289.images);
  }
  const upload = head?.querySelector("[data-g4rsya-v289-image-input]");
  if (upload) {
    upload.disabled = reached;
    upload.parentElement?.classList.toggle("is-disabled", reached);
    if (reached) upload.parentElement?.setAttribute("aria-disabled", "true");
    else upload.parentElement?.removeAttribute("aria-disabled");
  }
  const link = head?.querySelector("[data-g4rsya-v289-add-image-link]");
  if (link) link.disabled = reached;
  media.querySelectorAll("[data-g4rsya-v289-add-project-image]").forEach((button) => {
    button.disabled = reached;
  });
  let warning = media.querySelector(".g4-rsya-image-limit-warning");
  if (count > G4_RSYA_LIMITS_V289.images) {
    if (!warning) {
      warning = document.createElement("p");
      warning.className = "g4-rsya-image-limit-warning";
      warning.setAttribute("role", "alert");
      head.after(warning);
    }
    warning.textContent = `Лимит ${G4_RSYA_LIMITS_V289.images}, сейчас ${count}. Удалите лишние: Директ примет только ${G4_RSYA_LIMITS_V289.images}.`;
  } else warning?.remove();
  g4RsyaRefreshPreviewImageControlsV470(media, ad);
}

function g4RsyaRefreshDeletedImagesV527(product, snapshots, projectPhotoId = "") {
  const parentCache = guruRenderReadCacheV470;
  if (!parentCache) {
    guruRenderReadCacheV470 = {
      ensured: new WeakMap(),
      ui: new WeakMap(),
      selectedProduct: new WeakMap(),
      gate2Sync: new WeakMap(),
      productJourney: new WeakMap(),
      rsyaProjectOptions: new WeakMap(),
      rsyaFoundation: new WeakMap(),
      rsyaDefaults: new WeakMap(),
    };
  }
  try {
    return g4RsyaRefreshDeletedImagesCachedV527(product, snapshots, projectPhotoId);
  } finally {
    if (!parentCache) guruRenderReadCacheV470 = null;
  }
}

function g4RsyaRefreshDeletedImagesCachedV527(product, snapshots, projectPhotoId) {
  const channelCard = document.querySelector(
    `.g4-rsya-v289[data-g4rsya-product="${CSS.escape(String(product || ""))}"]`,
  );
  if (!channelCard) return false;
  const d = ensureGate4RsyaV289(product);
  const groups = new Map(d.groups.map((group) => [group.id, group]));
  const projectCounts = new Map();
  channelCard.querySelectorAll("[data-g4rsya-v289-ad-card]").forEach((card) => {
    const media = card.querySelector('[data-g4rsya-v464-ad-section="images"]');
    const input = media?.querySelector("[data-g4rsya-v289-image-input]");
    const group = groups.get(input?.dataset.g4rsyaV289GroupId);
    const ad = group?.ads?.find((row) => row.id === card.dataset.g4rsyaV289AdCard);
    const previous = snapshots.get(`${group?.id}:${ad?.id}`);
    if (!media || !ad || !previous) return;
    const changed = previous.images.length !== ad.images.length ||
      previous.images.some((image, index) => image.id !== ad.images[index]?.id);
    if (!changed && !projectPhotoId) return;
    if (projectPhotoId && !projectCounts.has(group.id))
      projectCounts.set(group.id, g4RsyaProjectOptionsV289(product, group).projectPhotos.length);
    g4RsyaRefreshDeletedImageMediaV527(media, ad, projectPhotoId,
      projectCounts.get(group.id));
    if (changed) {
      g4RsyaRefreshDeletedImagePreviewV527(
        card.querySelector("[data-g4rsya-v469-ad-preview]"), previous, ad,
      );
      const pill = card.querySelector(":scope > .g4-rsya-ad-head-v289 > .status-pill");
      if (pill) {
        const issues = g4RsyaAdIssuesV289(ad, megaPlatformProductUrl(product, state));
        pill.className = `status-pill status-${issues.length ? "in_progress" : "ready"}`;
        pill.textContent = issues.length ? "В работе" : "Готово к переносу";
      }
    }
  });
  const channel = channelCard.dataset.g4rsyaChannel;
  const campaign = g4RsyaCampaignV289(product, channel);
  const status = g4RsyaCampaignStatusV289(campaign, d, product);
  const pill = channelCard.querySelector(":scope > .g1-card-header > .status-pill");
  if (pill) {
    pill.className = `status-pill status-${status}`;
    pill.textContent = status === "ready" ? "Готово" : status === "problem"
      ? "Проблема" : status === "in_progress" ? "В работе" : "Не начато";
  }
  g4RsyaRefreshGroupCardsV458(product);
  g4RsyaRefreshLaunchV454(product);
  const preparation = channelCard.querySelector(".g4-rsya-preparation-v289");
  if (preparation) preparation.outerHTML = g4RsyaPreparationHtmlV289(product, channel, campaign, d);
  guruInvalidateGateViewCache();
  return true;
}

const G4_RSYA_AD_PROMPT_REQUIRED_V451 = Object.freeze([
  ["jtbd", "JTBD"],
  ["offer", "оффер"],
  ["benefit", "выгоду"],
  ["segment", "сегмент аудитории"],
]);

function g4RsyaAdPromptDataV451(product, group) {
  const foundation = g4RsyaGroupFoundationV455(product, group);
  const values = Object.fromEntries(
    ["jtbd", "offer", "benefit", "segment", "landing", "targetAction"]
      .map((field) => [field, g4RsyaTextV289(foundation[field])]),
  );
  const missing = G4_RSYA_AD_PROMPT_REQUIRED_V451
    .filter(([field]) => !values[field])
    .map(([, label]) => label);
  if (missing.length) return { ready: false, missing, values, prompt: "" };
  const prompt = `Ты создаёшь варианты для ОДНОГО комбинаторного объявления Яндекс.Директ (РСЯ).

Исходные данные группы:
JTBD: ${values.jtbd}
Сегмент аудитории: ${values.segment}
Оффер: ${values.offer}
Выгода: ${values.benefit}
Целевое действие: ${values.targetAction || "[не заполнено]"}
Посадочная страница: ${values.landing || "[не заполнено]"}

Создай пул вариантов для одного комбинаторного объявления:

- до ${G4_RSYA_LIMITS_V289.headings} вариантов заголовков
- до ${G4_RSYA_LIMITS_V289.texts} вариантов текста объявления

Жёсткие ограничения, считая пробелы и знаки препинания:

- заголовок — до ${G4_RSYA_LIMITS_V289.headingChars} знаков, слово не более ${G4_RSYA_LIMITS_V289.headingWord} знаков
- текст объявления — до ${G4_RSYA_LIMITS_V289.textChars} знака, слово не более ${G4_RSYA_LIMITS_V289.textWord} знаков

Правила:

- Не используй ключевые фразы: для РСЯ ориентируйся на описанный сегмент аудитории, его задачу и предложение.
- Каждый вариант должен быть самостоятельным и понятным в любой комбинации заголовка и текста.
- Сохраняй смысл JTBD, оффера и выгоды; веди к указанному целевому действию и посадочной странице.
- Не выдумывай цены, скидки, сроки, гарантии, характеристики и факты, которых нет в исходных данных.
- Без ЗАГЛАВНЫХ БУКВ, необоснованных превосходных степеней и лишних восклицательных знаков.

Формат вывода, без пояснений сверху:

Заголовки:
1. ...
2. ...

Тексты объявления:
1. ...
2. ...`;
  return { ready: true, missing: [], values, prompt };
}

