  const attrs = `data-g4rsya-v452-product="${escapeAttr(product)}" data-g4rsya-v452-group-id="${escapeAttr(group?.id || "")}" data-g4rsya-v452-ad-id="${escapeAttr(ad?.id || "")}"`;
