// Старые значения сохраняются отдельно: месячный бюджет нельзя считать недельным.
function g4RsyaMigrateStrategyV531(campaign, d) {
  const settings = d.campaign;
  if (!settings.strategyMigrationV531) {
    settings.legacyStrategySettingsV531 = {
      strategy: settings.strategy,
      paymentModel: settings.paymentModel,
      budgetPeriod: settings.budgetPeriod,
      budget: campaign?.budget ?? "",
    };
    if (settings.weeklyBudgetRubV531 === undefined) {
      const previousWeekly = settings.budgetPeriod === "week" ? String(campaign?.budget ?? "") : "";
      const amountOnly = previousWeekly.trim().replace(/\s*(?:₽|руб\.?)\s*$/i, "");
      settings.weeklyBudgetRubV531 = g4RsyaPositiveNumberV363(amountOnly) === null
        ? previousWeekly : amountOnly.replace(/\s/g, "").replace(",", ".");
    }
    settings.paymentModel = "clicks";
    settings.budgetPeriod = "week";
    settings.strategyMigrationV531 = true;
  }
  const volume = g4RsyaVolumeAssessmentV363(settings);
  if (volume.complete) {
    const recommended = volume.count >= 10 ? "max_conversions" : "max_clicks";
    if (settings.strategy !== recommended) {
      if (!settings.strategyBeforeVolumeV531) settings.strategyBeforeVolumeV531 = settings.strategy;
      settings.strategy = recommended;
    }
  }
}

const G4_RSYA_VIDEO_V532 = "https://www.youtube.com/watch?v=XFzBwc0kVGQ";
const G4_RSYA_YANDEX_CPA_V532 = "https://yandex.ru/support/direct/ru/strategies/average-cpa-clicks";
const G4_RSYA_YANDEX_VOLUME_V532 = "https://yandex.ru/support/direct/ru/troubleshooting/conversions";
const G4_RSYA_YANDEX_GOALS_V532 = "https://b2b.yandex.ru/adv/news/personalnye-sovety-po-nastroyke-strategiy-uzhe-v-interfeyse-direkta";
const G4_RSYA_YANDEX_AFTER_V532 = "https://b2b.yandex.ru/adv/edu/materials/oplata-za-konversii";

function g4RsyaMoneyV532(value) {
  return String(Math.ceil((value - 1e-8) * 100) / 100);
}

function g4RsyaMigrateStartMethodV532(d) {
  d.ui = d.ui && typeof d.ui === "object" ? d.ui : {};
  const source = d.campaign.startMethodV532;
  if (!source || typeof source !== "object" || Array.isArray(source)) {
    if (source !== undefined) d.campaign.legacyStartMethodV532 = source;
    d.campaign.startMethodV532 = {};
  }
  for (const key of ["forecastCpcRub", "siteConversionPercent", "expectedCpaManualRub", "directBudgetFloorRub"])
    if (d.campaign.startMethodV532[key] === undefined) d.campaign.startMethodV532[key] = "";
  if (!d.ui.prelaunchChecksV532 || typeof d.ui.prelaunchChecksV532 !== "object" || Array.isArray(d.ui.prelaunchChecksV532)) {
    if (d.ui.prelaunchChecksV532 !== undefined) d.ui.legacyPrelaunchChecksV532 = d.ui.prelaunchChecksV532;
    d.ui.prelaunchChecksV532 = {};
  }
}

function g4RsyaStartMethodModelV532(d) {
  const method = d.campaign.startMethodV532 || {};
  const cpc = g4RsyaPositiveNumberV363(method.forecastCpcRub);
  const conversion = g4RsyaPositiveNumberV363(method.siteConversionPercent);
  const automatic = cpc !== null && conversion !== null && conversion <= 100;
  const expectedRaw = automatic ? cpc / (conversion / 100) : g4RsyaPositiveNumberV363(method.expectedCpaManualRub);
  const expected = expectedRaw === null ? null : Math.ceil((expectedRaw - 1e-8) * 100) / 100;
  const startCpa = expected === null ? null : Math.ceil((expected * 2 - 1e-8) * 100) / 100;
  const minimumBudget = startCpa === null ? null : Math.ceil((startCpa * 10 - 1e-8) * 100) / 100;
  const directFloorText = g4RsyaTextV289(method.directBudgetFloorRub);
  const directFloor = directFloorText ? g4RsyaPositiveNumberV363(directFloorText) : null;
  const complete = minimumBudget !== null && (!directFloorText || directFloor !== null);
  return { automatic, expected, startCpa, minimumBudget, directFloor, complete,
    requiredBudget: complete ? Math.max(300, minimumBudget, directFloor || 0) : null };
}

function g4RsyaDirectPanelModelV533(product, d) {
  // Читаем готовый Search-слепок по товару без ensureGate4SearchBuild: ensure мигрирует Search.
  const search = state.gate4SearchBuild?.[normalizeAspectKey(product || "no_product")];
  const entries = search && Array.isArray(search.groupRows) ? g4sbV405SummaryEntries(product, search) : [];
  const summary = entries.length ? g4sbV405LaunchSummaryData(
    product, search, g4sbV407SavedDuplicateCount(product, search),
  ) : null;
  const missing = [];
  if (!entries.length) missing.push("нет сохранённых групп Поиска для этого товара");
  let monthlyBaseLeads = 0;
  const groupBudgets = [];
  const groupBaseLeads = [];
  entries.forEach((entry, index) => {
    const forecast = g4sbV128Forecast(entry.rows);
    groupBudgets.push(forecast.budget);
    const name = `группа ${index + 1}`;
    if (!forecast.count) missing.push(`${name}: нет ключевых фраз с прогнозом`);
    if (forecast.coverage.budget < forecast.count)
      missing.push(`${name}: прогноз бюджета у ${forecast.coverage.budget} из ${forecast.count} фраз`);
    if (forecast.coverage.clicks < forecast.count)
      missing.push(`${name}: прогноз кликов у ${forecast.coverage.clicks} из ${forecast.count} фраз`);
    const base = g4sbV140ConversionScenarios(forecast.clicks, forecast.budget)
      .find((scenario) => scenario.key === "base");
    groupBaseLeads.push(base?.conversions ?? null);
    if (base?.conversions !== null && base?.conversions !== undefined)
      monthlyBaseLeads += base.conversions;
  });
  if (entries.length && !(summary?.budget > 0)) missing.push("сумма прогнозных бюджетов равна нулю");
  if (entries.length && !(monthlyBaseLeads > 0)) missing.push("заявки базового сценария равны нулю");
  const hasSearch = missing.length === 0;
  const manual = g4RsyaPositiveNumberV363(d.campaign.startMethodV532?.expectedCpaManualRub);
  const expectedRaw = hasSearch ? summary.budget / monthlyBaseLeads : manual;
  const expected = expectedRaw === null ? null : Number(g4RsyaMoneyV532(expectedRaw));
  const price = expected === null ? null : Number(g4RsyaMoneyV532(expected * 2));
  const budget = price === null ? null : Number(g4RsyaMoneyV532(price * 10));
  const expectedTen = expected === null ? null : Number(g4RsyaMoneyV532(expected * 10));
  const volume = g4RsyaVolumeAssessmentV363(d.campaign);
  return {
    hasSearch, missing, summary, groupCount: entries.length, groupBudgets, groupBaseLeads,
    jtbdIds: (search?.groupRows || []).map((row) => String(row.jtbdId || "")).filter(Boolean),
    monthlyBaseLeads: hasSearch ? monthlyBaseLeads : null,
    expected, price, budget, expectedTen,
    strategy: volume.complete && volume.count < 10 ? "Оптимизация кликов" : "Максимум конверсий",
  };
}

