function g4RsyaBoundRecordV289(target) {
  const { d, group, ad } = g4RsyaFindV289(target.dataset.g4rsyaV289Product, target.dataset.g4rsyaV289GroupId, target.dataset.g4rsyaV289AdId);
  const store = target.dataset.g4rsyaV289Store;
  if (store === "campaignCommon") return g4RsyaCampaignV289(target.dataset.g4rsyaV289Product, target.dataset.g4rsyaV289Channel);
  if (store === "campaign") return d.campaign;
  if (store === "promotion") return d.campaign.promotion;
  if (store === "strategyTarget") return d.campaign.strategyTarget;
  if (store === "startMethodV532") return d.campaign.startMethodV532;
  if (store === "conversionVolumeCheck") return d.campaign.conversionVolumeCheck;
  if (store === "excludedPlacement") return d.campaign.excludedPlacements.find((row) => row.id === target.dataset.g4rsyaV289ItemId) || null;
  if (store === "group") return group;
  if (store === "ad") return ad;
  const lists = { heading: "headings", text: "texts", image: "images", video: "videos", callout: "callouts", sitelink: "sitelinks" };
  const list = ad?.[lists[store]];
  let record = list?.find((row) => row.id === target.dataset.g4rsyaV289ItemId) || null;
  if (!record && target.dataset.g4rsyaV482Virtual === "1" &&
      (store === "callout" || store === "sitelink") && Array.isArray(list)) {
    record = store === "callout"
      ? { id: target.dataset.g4rsyaV289ItemId, value: "" }
      : { id: target.dataset.g4rsyaV289ItemId, title: "", url: "", description: "" };
    list.push(record);
    target.closest(".g4-rsya-ad-extras-v477")
      ?.querySelectorAll(`[data-g4rsya-v289-item-id="${CSS.escape(String(record.id))}"]`)
      .forEach((control) => delete control.dataset.g4rsyaV482Virtual);
  }
  return record;
}

function g4RsyaRefreshControlV289(target) {
  const value = target.value || "";
  const optionalEmpty = target.dataset.g4rsyaV482OptionalEmpty === "1";
  if (target.dataset.guruOptionalMode === "empty") {
    delete target.dataset.guruOptional;
    target.setAttribute(
      "aria-required",
      target.dataset.g4rsyaV289Required === "1" ? "true" : "false",
    );
  }
  target.classList.toggle("is-filled", Boolean(value.trim()));
  target.classList.toggle("is-empty", !value.trim() && !optionalEmpty);
  target.classList.toggle("is-optional", !value.trim() && optionalEmpty);
  const label = target.closest(".g4-rsya-field-v289");
  const kind = target.dataset.g4rsyaV289Kind;
  const issues = kind ? g4RsyaTextIssuesV289(value, kind, target.dataset.g4rsyaV289Required === "1") : (target.dataset.g4rsyaV289Required === "1" && !value.trim() ? ["Заполните поле"] : []);
  target.classList.toggle("has-error", issues.length > 0);
  const counter = label?.querySelector("[data-g4rsya-v289-counter]");
  if (counter) counter.textContent = g4RsyaCounterV289(value, kind);
  const error = label?.querySelector("[data-g4rsya-v289-error]");
  if (error) error.textContent = issues.join(" · ");
  const copy = label?.querySelector("[data-g4rsya-v289-copy]") ||
    target.closest(".g4-rsya-sitelink-field-v483")
      ?.querySelector("[data-g4rsya-v289-copy]") ||
    target.closest(".g4-rsya-variant-row-v289")
      ?.querySelector("[data-g4rsya-v289-copy]");
  if (copy) {
    copy.dataset.g4rsyaV289Copy = g4RsyaCopyValueV289(value, copy.dataset.g4rsyaV289CopyMode);
    copy.disabled = !value.trim();
  }
}

