const g4RsyaInputEffectTimersV472 = new Map();

function g4RsyaScheduleInputEffectsV472(
  product,
  group,
  ad,
  delay = 320,
  options = {},
) {
  if (!group?.id || !ad?.id) return;
  const key = `${product}:${group.id}:${ad.id}`;
  window.clearTimeout(g4RsyaInputEffectTimersV472.get(key));
  g4RsyaInputEffectTimersV472.set(key, window.setTimeout(() => {
    g4RsyaInputEffectTimersV472.delete(key);
    const current = g4RsyaFindV289(product, group.id, ad.id);
    if (!current.group || !current.ad) return;
    if (options.refreshPrompt !== false)
      g4RsyaRefreshAssetPromptsV452(product, current.group, current.ad);
    g4RsyaRefreshLaunchAdV472(product, current.group, current.ad);
    g4RsyaRefreshGroupCardsV458(product);
    if (options.save !== false) flashSaving();
  }, delay));
}

