async function g4RsyaCopyV289(text, button, fallbackTargetId = "") {
  const iconOnly = Boolean(button?.hasAttribute?.("data-g4rsya-v472-icon-copy"));
  const initial = iconOnly
    ? {
        title: button.title,
        ariaLabel: button.getAttribute("aria-label") || "Копировать",
      }
    : button?.textContent || "Копировать";
  try {
    await g4sbV141CopyText(String(text || ""));
    if (button && iconOnly) {
      button.classList.add("is-copied");
      button.title = "Скопировано";
      button.setAttribute("aria-label", "Скопировано");
    } else if (button) button.textContent = "Скопировано";
  } catch (_error) {
    const field = fallbackTargetId ? document.getElementById(fallbackTargetId) : null;
    field?.focus();
    field?.select?.();
    if (button && iconOnly) {
      button.classList.add("is-copy-error");
      button.title = "Выделите значение вручную";
      button.setAttribute("aria-label", button.title);
    } else if (button) button.textContent = "Выделите значение вручную";
  }
  window.setTimeout(() => {
    if (!button?.isConnected) return;
    if (iconOnly) {
      button.classList.remove("is-copied", "is-copy-error");
      button.title = initial.title;
      button.setAttribute("aria-label", initial.ariaLabel);
    } else button.textContent = initial;
  }, 1600);
}

