/* Финальная активация v2.3.90 после конструктора РСЯ и всех старых
   override. Gate 4 больше не может вернуть собственную сортировку. */
const __g3Gate4UltimateStagesV290 = g3ProductJourneyStages;
g3ProductJourneyStages = function (snapshot) {
  const rows = __g3Gate4UltimateStagesV290(snapshot);
  const model = g3Gate4StructureForProductV290(snapshot?.product?.id);
  const byKey = new Map(rows.map((stage) => [stage.key, stage]));
  return (model?.stageOrder || rows.map((stage) => stage.key))
    .map((stageKey) => byKey.get(stageKey))
    .filter(Boolean)
    .map((stage) => {
      const executionGroups = g3ExecutionGroupsV290(stage.key, snapshot);
      return {
        ...stage,
        executionGroups,
        executionItems: executionGroups.flatMap((group) => group.items),
      };
    });
};

