/* v2.3.204 — Директ принимает посадочную ссылку и параметры URL в двух
   разных полях. Источник посадочной остаётся прежним; удаляются только
   query-параметры и hash, путь конкретной посадочной сохраняется. */
function g4sbV434CleanLandingUrl(source) {
  if (!source) return "";
  try {
    const url = new URL(source);
    url.search = "";
    url.hash = "";
    return url.href;
  } catch (_error) {
    return "";
  }
}

