async function g4sbV446CopyWithFeedback(button, value) {
  if (!button || !value) return;
  const idleLabel = button.dataset.g4sbCopyLabel || "Копировать";
  button.disabled = true;
  button.dataset.g4sbCopyState = "pending";
  try {
    await g4sbV141CopyText(value);
    button.dataset.g4sbCopyState = "copied";
    button.setAttribute("aria-label", "Скопировано");
    button.title = "Скопировано";
  } catch (_error) {
    button.dataset.g4sbCopyState = "error";
    button.setAttribute("aria-label", "Не удалось скопировать");
    button.title = "Не удалось скопировать";
  }
  window.setTimeout(() => {
    if (!button.isConnected) return;
    delete button.dataset.g4sbCopyState;
    button.setAttribute("aria-label", idleLabel);
    button.title = idleLabel;
    button.disabled = false;
  }, 1600);
}

