/* v2.3.205 — цена цели выводится из того же округлённого недельного
   бюджета, который видит пользователь: бюджет = цена цели × 10. */
function g4sbV435TargetCpaModel(weeklyBudget) {
  const ready = Number.isFinite(weeklyBudget) && weeklyBudget > 0;
  const displayedWeeklyBudget = ready
    ? Math.round((weeklyBudget + Number.EPSILON) * 100) / 100 : null;
  const targetCpa = displayedWeeklyBudget === null ? null : displayedWeeklyBudget / 10;
  return {
    ready,
    weeklyBudget: displayedWeeklyBudget,
    targetCpa,
    value: ready
      ? `${g4sbV407FormatNumber(targetCpa, 3)} ₽`
      : "[Цена цели пока не рассчитана - нет рекомендованного недельного бюджета]",
  };
}

function g4sbV435TargetCpaHtml(model) {
  return `<div class="g4-v407-utm g4-v435-target-cpa ${model.ready ? "" : "is-empty"}" data-g4sb-target-cpa data-g4sb-weekly-budget="${model.weeklyBudget ?? ""}">
    <span class="g4-v435-target-cpa-label">Предложено системой:</span>
    <div class="g4-v446-copy-row ${model.ready ? "" : "is-single"}">
      ${model.ready ? g4sbV446CopyIconButton(
        "data-g4sb-copy-target-cpa", "Копировать предложенную цену целевого действия",
      ) : ""}
      <input type="text" readonly class="g4-v407-utm-result" data-guru-field-neutral data-g4sb-target-cpa-value value="${escapeAttr(model.value)}" aria-label="Предложенная цена целевого действия">
    </div>
  </div>`;
}

