  const p = `data-g4sb-product="${escapeAttr(product)}" data-g4sb-ad-pool-jtbd="${escapeAttr(draft.jtbdId || "")}" data-g4sb-ad-pool-group="${escapeAttr(draft.editingClusterId || "")}"`;
  const single = kind === "headlines" ? "заголовок" : "текст";
