/* Ссылка в карточке должна знать только фактический runtime-источник.
   Полный guruExportGate2CardDiagnosticV223 остаётся экспортной
   диагностикой и больше не строится по 30 раз ради одного href. */
g2ResolvedSourceV267 = function (card) {
  if (!card) return null;
  const rule = g2SyncRuleV226(card) || {};
  const sync = g2SyncInfo(card);
  const sources = [];

  if (sync.g0) {
    const source = guruExportGate2Gate0SourceV223(rule);
    if (source?.found) sources.push(source);
  }

  if (sync.source && rule.g1) {
    const sourceCard = g2FindGateCard("gate-1", rule.g1);
    if (sourceCard) {
      sources.push(guruExportDiagnosticSourceV223({
        key: "G1",
        sourceType: "gate1_card",
        gateId: "gate-1",
        cardId: sourceCard.id,
        path: `state.gates[gate-1].cards[${sourceCard.id}].status`,
        title: sourceCard.title,
        rawStatus: sync.source.status || sourceCard.status || "",
        found: true,
        lookup: {
          kind: "title_regex",
          value: rule.g1.source,
          flags: rule.g1.flags,
        },
      }));
    }
  }

  if (sync.g4) {
    const sourceCard = g4ReadinessCardV225(sync.g4.cardId, state) ||
      g2FindGateCard("gate-4", rule.g4);
    const isCompany = sync.g4.scope === "company" ||
      Boolean(G4_READINESS_GATE0_SOURCES_V225[sourceCard?.id]);
    const productId = isCompany ? "" : sync.g4.product_id || "";
    sources.push(guruExportDiagnosticSourceV223({
      key: "L",
      sourceType: isCompany
        ? "gate0_readonly_aggregate"
        : "gate4_product_readiness",
      gateId: "gate-4",
      cardId: sourceCard?.id || sync.g4.cardId || "",
      path: isCompany
        ? "state.gates[gate-0].cards[card-7].megaMarketing"
        : `state.gate4Production.readinessV225.byProduct[${productId || "not-selected"}][${sourceCard?.id || sync.g4.cardId || "not-found"}]`,
      title: sourceCard?.title || sync.g4.title || "",
      rawStatus: sync.g4.status || "",
      found: Boolean(sourceCard || sync.g4.cardId),
      lookup: rule.g4
        ? { kind: "title_regex", value: rule.g4.source, flags: rule.g4.flags }
        : { kind: "card_id", value: sync.g4.cardId || "" },
    }));
  }

  sources.forEach((source) => {
    source.result = guruGate2RuntimeSourceResultV470(source);
  });
  return sources.find((source) => source.result) ||
    sources.find((source) => source.found) ||
    null;
};

