document.addEventListener("click", (event) => {
  const pageToggle = event.target?.closest?.("[data-guru-category-page-toggle-v495]");
  if (pageToggle && !event.target?.closest?.("button, select, input[data-guru-category-page-name-v500]:not([readonly])")) {
    const page = pageToggle.closest(".page-structure-card");
    const content = page?.querySelector("[data-guru-category-page-content-v495]");
    if (content) {
      const expanded = content.hidden;
      content.hidden = !expanded;
      pageToggle.setAttribute("aria-expanded", String(expanded));
      const chevron = pageToggle.querySelector(".guru-category-page-chevron-v495");
      if (chevron) chevron.textContent = expanded ? "⌄" : "›";
      const rowId = page?.dataset?.guruCategoryPageRowIdV495;
      if (rowId) guruCategoryPageSetExpandedV495(rowId, expanded);
    }
  }
  const button = event.target?.closest?.("[data-guru-category-page-expand]");
  if (!button) return;
  const page = button.closest(".page-structure-card");
  const sections = [...(page?.querySelectorAll("details.v22-route-section") || [])];
  if (!sections.length) return;
  const expand = sections.some((section) => !section.open);
  sections.forEach((section) => { section.open = expand; });
  button.setAttribute("aria-expanded", String(expand));
  button.textContent = expand ? "Свернуть все секции" : "Развернуть все секции для заполнения";
});

