function guruCatalogAuditPageStatusV493(row, card) {
  if (row.pageNeeded === "not_needed") return "not_required";
  if (row.pageNeeded === "undecided") return "in_progress";
  const isHub = card?.id === GURU_CATALOG_HUB_CARD_ID_V496 ||
    state?.gates?.find((gate) => gate.id === "gate-1")?.cards
      ?.find((item) => item.id === GURU_CATALOG_HUB_CARD_ID_V496)
      ?.pageRows?.includes(row);
  const sections = v22TemplateForCard(isHub
    ? { id: GURU_CATALOG_HUB_CARD_ID_V496, title: "КАТАЛОГ (ХАБ)" }
    : { id: GURU_CATALOG_AUDIT_CARD_ID_V493, title: "КАТЕГОРИЯ" }).sections;
  const statuses = sections.map((section) => v22SectionStatus(row, section));
  const seoStatus = v22SectionStatus(row, {
    key: "seo_snippet",
    fields: [
      rowField("title", "Title", ""),
      rowField("description", "Description", ""),
      ctxField("seoKeywords", "Ключевые слова", ""),
    ],
  });
  const cwvStatus = cwvBlockStatus(row);
  if (cwvStatus === "problem" || cwvStatus === "needs_attention")
    return cwvStatus;
  if (v22IsFilled(megaPlatformAuditRowUrl(row)) &&
      statuses.every((status) => status === "ready" || status === "not_required") &&
      seoStatus === "ready" && cwvStatus === "ready")
    return "ready";
  const hasWork = [megaPlatformAuditRowUrl(row), row.h1, row.title, row.description]
    .some(v22IsFilled) || Object.values(row.contextFields || {}).some(v22IsFilled) ||
    statuses.some((status) => status !== "not_started");
  return hasWork ? "in_progress" : "not_started";
}

