const __guruCatalogPrevRecalculateCardV493 = recalculateStatusForCard;
recalculateStatusForCard = function (card, workspace = state) {
  const result = __guruCatalogPrevRecalculateCardV493.apply(this, arguments);
  if (!guruIsCatalogPageCardV496(card)) return result;
  const statuses = (card.pageRows || []).map((row) => guruCatalogAuditPageStatusV493(row, card));
  const active = statuses.filter((status) => status !== "not_required");
  card.status = statuses.includes("problem") ? "problem"
    : statuses.includes("needs_attention") ? "needs_attention"
      : !active.length && statuses.length ? "not_required"
        : !active.length || active.every((status) => status === "not_started")
          ? "not_started"
          : active.every((status) => status === "ready") ? "ready" : "in_progress";
  return result;
};

