function guruSiteChromeValidUrlV497(value) {
  const url = String(value || "").trim();
  if (url.startsWith("/")) return url.length > 1 && !url.startsWith("//");
  try {
    return ["http:", "https:"].includes(new URL(url).protocol);
  } catch (_) {
    return false;
  }
}

function guruSiteChromeLegalReadyV497(saved, workspace = state) {
  const contacts = guruSiteChromeContactsV497(workspace);
  const policy = guruSiteChromePolicyV497(workspace);
  return Boolean(contacts.legal && contacts.address && contacts.email &&
    policy.status === "ready" && guruSiteChromeValidUrlV497(policy.url) &&
    saved.offerStatus === "ready" && guruSiteChromeValidUrlV497(megaPlatformUrl("fixed", "offer", workspace)) &&
    saved.returnStatus === "ready" && guruSiteChromeValidUrlV497(megaPlatformUrl("fixed", "returns", workspace)));
}

function guruSiteChromeStatusV497(card, workspace = state) {
  const saved = card.siteChromeV497 || {};
  if (card.id === GURU_SITE_HEADER_ID_V497) {
    const checks = saved.headerChecksV499 || {};
    const required = guruSiteChromeProposalV499(workspace)
      .flatMap((entry) => [entry, ...(entry.children || [])]);
    return required.length && required.every((entry) => checks[entry.key] === true)
      ? "ready" : "not_started";
  }
  return guruSiteChromeLegalReadyV497(saved, workspace) && String(saved.contactSocial || "").trim()
    ? "ready" : "not_started";
}

