function guruHubRefreshPreviewV504() {
  const card = findCard(GURU_CATALOG_HUB_CARD_ID_V496);
  if (!card) return;
  document.querySelectorAll('[data-page-source-card="card-22-hub"]').forEach((page, index) => {
    const row = card.pageRows?.[index];
    if (!row) return;
    const parts = guruHubPreviewPartsV505(row);
    page.querySelectorAll("[data-guru-hub-inline-preview-v505]").forEach((preview) => {
      const part = parts.get(preview.dataset.guruHubInlinePreviewV505);
      if (part) preview.innerHTML = `<div class="guru-hub-preview-page-v504">${part}</div>`;
    });
    const categories = guruHubCategoryPreviewPartsV506(row);
    page.querySelectorAll("[data-guru-hub-category-preview-v506]").forEach((preview) => {
      const category = categories.get(preview.dataset.guruHubCategoryPreviewV506);
      if (category) preview.innerHTML = category;
    });
  });
}

