function guruHomeMediaContextV509(control) {
  const holder = control.closest("[data-guru-home-image-v509]");
  const card = findCard(GURU_HOME_CARD_ID_V509);
  const row = card?.pageRows?.[Number(holder?.dataset?.guruHomeImageIndexV509)];
  return holder && row ? { holder, card, row,
    kind: holder.dataset.guruHomeImageV509,
    categoryId: holder.dataset.guruHomeImageCategoryV509 || "" } : null;
}

function guruHomeMediaSetV509(context, image, imageName = "") {
  const { holder, card, row, kind, categoryId } = context;
  if (kind === "hero") {
    (row.contextFields ||= {}).homeHeroImageV509 = image;
    row.contextFields.homeHeroImageNameV509 = imageName;
  } else {
    (row.homeSegmentImagesV509 ||= {})[categoryId] = { image, imageName };
  }
  const preview = holder.querySelector("[data-guru-home-image-preview-v509]");
  if (preview) {
    preview.replaceChildren();
    const src = guruHubImageSrcV502(image);
    if (src) {
      const img = document.createElement("img");
      img.src = src;
      img.alt = kind === "hero" ? "Изображение главного экрана" : "Изображение категории";
      preview.append(img);
      if (imageName) {
        const small = document.createElement("small");
        small.textContent = imageName;
        preview.append(small);
      }
    } else {
      const empty = document.createElement("span");
      empty.textContent = "Нет изображения · нажмите для загрузки";
      preview.append(empty);
    }
  }
  guruHomeSaveV509(card);
}

document.addEventListener("input", (event) => {
  const url = event.target?.closest?.("[data-guru-home-image-url-v509]");
  const caseInput = event.target?.closest?.("[data-guru-home-case-field-v509]");
  const fact = event.target?.closest?.("[data-guru-home-fact-index-v509]");
  if (url) {
    const context = guruHomeMediaContextV509(url);
    if (context) guruHomeMediaSetV509(context, url.value);
  } else if (fact) {
    const card = findCard(GURU_HOME_CARD_ID_V509);
    const row = card?.pageRows?.[Number(fact.dataset.guruHomeFactPageIndexV509)];
    if (!row) return;
    const raw = String(row.contextFields?.aboutFacts ?? "");
    const separator = raw.includes("\r\n") ? "\r\n" : "\n";
    const values = raw ? raw.split(/\r?\n/) : ["", "", ""];
    if (values.length !== 3) return;
    values[Number(fact.dataset.guruHomeFactIndexV509)] = fact.value;
    (row.contextFields ||= {}).aboutFacts = values.join(separator);
    guruHomeSaveV509(card);
  } else if (caseInput) {
    const card = findCard(GURU_HOME_CARD_ID_V509);
    const row = card?.pageRows?.[Number(caseInput.dataset.guruHomeCaseIndexV509)];
    const item = row?.homeCaseCardsV509?.find((entry) => entry.id === caseInput.dataset.guruHomeCaseIdV509);
    if (!item) return;
    item[caseInput.dataset.guruHomeCaseFieldV509] = caseInput.value;
    guruHomeSaveV509(card);
  }
});

document.addEventListener("change", async (event) => {
  const upload = event.target?.closest?.("[data-guru-home-upload-v509]");
  if (!upload?.files?.length) return;
  const context = guruHomeMediaContextV509(upload);
  if (!context) return;
  const error = context.holder.querySelector("[data-guru-home-image-error-v509]");
  try {
    const image = await guruHubImageFromFileV502(upload.files[0]);
    guruHomeMediaSetV509(context, image, upload.files[0].name);
    const url = context.holder.querySelector("[data-guru-home-image-url-v509]");
    if (url) url.value = "";
    if (error) error.hidden = true;
  } catch (failure) {
    if (error) {
      error.textContent = failure?.message || "Не удалось загрузить изображение.";
      error.hidden = false;
    }
  } finally {
    upload.value = "";
  }
});

document.addEventListener("click", (event) => {
  const add = event.target?.closest?.("[data-guru-home-case-add-v509]");
  const remove = event.target?.closest?.("[data-guru-home-case-remove-v509]");
  const removeLegacy = event.target?.closest?.("[data-guru-home-case-remove-legacy-v509]");
  if (!add && !remove && !removeLegacy) return;
  const card = findCard(GURU_HOME_CARD_ID_V509);
  const index = Number(add?.dataset.guruHomeCaseAddV509 ??
    remove?.dataset.guruHomeCaseIndexV509 ??
    removeLegacy?.dataset.guruHomeCaseRemoveLegacyV509);
  const row = card?.pageRows?.[index];
  if (!row) return;
  const cases = (row.homeCaseCardsV509 ||= []);
  if (add) cases.push({ id: `home-case-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, title: "", category: "", result: "" });
  else if (remove) row.homeCaseCardsV509 = cases.filter((item) => item.id !== remove.dataset.guruHomeCaseRemoveV509);
  else (row.contextFields ||= {}).cases = "";
  guruHomeSaveV509(card);
  renderGate();
});

const __guruHomePrevSectionStatusV509 = v22SectionStatus;
v22SectionStatus = function (row, section) {
  if (!row || !["home_segments", "home_cases"].includes(section?.key))
    return __guruHomePrevSectionStatusV509.apply(this, arguments);
  if (v22SectionMode(row, section) === "not_needed") return "ready";
  const fields = row.contextFields || {};
  if (section.key === "home_segments") {
    const categories = guruHubShowcaseSourcesV502();
    const images = row.homeSegmentImagesV509 || {};
    const ready = v22IsFilled(fields.segmentTitle) && (categories.length
      ? categories.every((source) => v22IsFilled(source.url) &&
        v22IsFilled(images[source.categoryId]?.image))
      : v22IsFilled(fields.segmentCards));
    if (ready) return "ready";
    return v22IsFilled(fields.segmentTitle) || v22IsFilled(fields.segmentCards) ||
      Object.values(images).some((item) => v22IsFilled(item?.image))
      ? "in_progress" : "not_started";
  }
  const cards = Array.isArray(row.homeCaseCardsV509) ? row.homeCaseCardsV509 : [];
  const casesReady = v22IsFilled(fields.cases) ||
    (cards.length > 0 && cards.every((item) =>
      [item.title, item.category, item.result].every(v22IsFilled)));
  if (casesReady && v22IsFilled(fields.casesTitle) &&
      v22IsFilled(fields.portfolioButton)) return "ready";
  return v22IsFilled(fields.casesTitle) || v22IsFilled(fields.cases) ||
    v22IsFilled(fields.portfolioButton) || cards.length
    ? "in_progress" : "not_started";
};

