/* One disclosure state per project and block. Native details that already own
   their state keep using it; all other details and legacy Gate 1 cards share
   this default-closed registry. Keys use page/product ids or DOM structure,
   never the visible heading, so editing copy does not reset a block. */
const GURU_OWNED_DETAILS_V512 = [
  ".gate0-card",
  "[data-gate0-diagnostic-stage]",
  "[data-g6-event-detail]",
  "[data-guru-strategic-jtbd-v286]",
  "[data-guru-catalog-category-group]",
  ".g4-map-outside-v290",
  ".g4-v166-jtbd:not(.is-orphaned)",
].join(",");

function guruDisclosureKeyV512(node) {
  const root = els.contentArea;
  if (!root || !root.contains(node)) return "";
  const page = node.closest(".page-structure-card");
  const pageInput = page?.querySelector("[data-gate1-page-card-id][data-gate1-page-index]");
  const pageCard = pageInput && findCard(pageInput.dataset.gate1PageCardId);
  const pageRow = pageCard?.pageRows?.[Number(pageInput?.dataset.gate1PageIndex)];
  const pageId = page?.dataset.guruCategoryPageRowIdV495 || pageRow?.id || "";
  const scope = page || node.closest("[data-card], [data-card-row], [data-g4-map-product-v290]") || root;
  const scopeId = pageId || scope.getAttribute("data-card") ||
    scope.getAttribute("data-card-row") || scope.getAttribute("data-g4-map-product-v290") || "";
  const parts = [];
  for (let current = node; current && current !== scope.parentElement && current !== root; current = current.parentElement) {
    const marker = ["data-ui-keeper-key", "data-v22-site-section", "data-g4sb-jtbd-id",
      "data-g4-map-implementation-id-v290", "data-g1-collapse-key", "data-pv181-demand-product-v262"]
      .find((name) => current.hasAttribute(name) && current.getAttribute(name));
    if (marker) {
      parts.unshift(`${marker}:${current.getAttribute(marker)}`);
      break;
    }
    if (current.id) {
      parts.unshift(`id:${current.id}`);
      break;
    }
    const classes = [...current.classList].filter((name) =>
      !/^(status-|is-open$|is-collapsed$|is-empty$|is-filled$|is-covered$)/.test(name));
    const signature = `${current.tagName.toLowerCase()}.${classes.join(".")}`;
    const siblings = [...(current.parentElement?.children || [])].filter((sibling) =>
      sibling.tagName === current.tagName &&
      [...sibling.classList].filter((name) =>
        !/^(status-|is-open$|is-collapsed$|is-empty$|is-filled$|is-covered$)/.test(name)).join(".") === classes.join("."));
    parts.unshift(`${signature}:${siblings.indexOf(current)}`);
  }
  return `${activeGateId}|${scopeId}|${parts.join("/")}`;
}

function guruDisclosureOpenStateV512() {
  state.ui = state.ui || {};
  state.ui.disclosureOpenV512 = state.ui.disclosureOpenV512 || {};
  return state.ui.disclosureOpenV512;
}

function guruApplyDisclosureStateV512(container = els.contentArea) {
  if (!state || !container || !els.contentArea?.contains(container)) return;
  const nodes = [container, ...container.querySelectorAll("details, .g1-card-collapsible")];
  for (const node of nodes) {
    if (!node.matches?.("details, .g1-card-collapsible")) continue;
    if (node.matches("details") && node.matches(GURU_OWNED_DETAILS_V512)) continue;
    const key = guruDisclosureKeyV512(node);
    if (!key) continue;
    if (node.matches("details")) {
      const open = guruDisclosureOpenStateV512()[key] === true;
      node.dataset.guruDisclosureKeyV512 = key;
      node.dataset.guruDisclosureExpectedV512 = open ? "1" : "0";
      if (node.open !== open) node.open = open;
    } else {
      state.ui.g1DisclosureOpenV512 = state.ui.g1DisclosureOpenV512 || {};
      const open = state.ui.g1DisclosureOpenV512[key] === true;
      node.classList.toggle("is-collapsed", !open);
    }
  }
}

document.addEventListener("toggle", (event) => {
  const node = event.target;
  if (!(node instanceof HTMLDetailsElement) || !els.contentArea?.contains(node) ||
      node.matches(GURU_OWNED_DETAILS_V512)) return;
  const key = node.dataset.guruDisclosureKeyV512;
  if (!key || node.dataset.guruDisclosureExpectedV512 === (node.open ? "1" : "0")) return;
  node.dataset.guruDisclosureExpectedV512 = node.open ? "1" : "0";
  guruDisclosureOpenStateV512()[key] = node.open;
  guruScheduleUiPreferenceSave();
}, true);

const __guruDisclosurePrevRenderGateV512 = renderGate;
renderGate = function () {
  const result = __guruDisclosurePrevRenderGateV512.apply(this, arguments);
  guruApplyDisclosureStateV512();
  return result;
};

function guruWatchDisclosuresV512() {
  if (!els.contentArea) return;
  new MutationObserver((records) => {
    for (const record of records) {
      for (const added of record.addedNodes) {
        if (added.nodeType === Node.ELEMENT_NODE)
          guruApplyDisclosureStateV512(added);
      }
    }
  }).observe(els.contentArea, { childList: true, subtree: true });
  guruApplyDisclosureStateV512();
}
if (document.readyState === "loading")
  document.addEventListener("DOMContentLoaded", guruWatchDisclosuresV512, { once: true });
else guruWatchDisclosuresV512();

