const GOAT_PRODUCT_CARD_SCHEMA_V514 = "goat-product-unified-page-v514";
const GOAT_PRODUCT_CARD_STATUS_KEYS_V514 = {
  hero: "goat_page_status_hero_v514",
  gallery: "goat_page_status_gallery_v514",
  delivery: "goat_page_status_delivery_v514",
  meaning: "goat_page_status_meaning_v514",
  creation: "goat_page_status_creation_v514",
  reviews: "goat_page_status_reviews_v514",
  finalCta: "goat_page_status_final_cta_v514",
  related: "goat_page_status_related_v514",
  catalogLink: "goat_page_status_catalog_link_v514",
  productJsonLd: "goat_page_status_product_jsonld_v514",
};

function goatProductCardLegacyStatusV514(value) {
  const status = guruCanonStatus(value);
  if (status === "works") return "ready";
  if (status === "not_needed") return "not_needed";
  if (status === "broken" || status === "missing") return "problem";
  if (status === "needs_improvement") return "in_progress";
  return "not_started";
}

function goatProductCardMigrateRowV514(row) {
  if (!row || typeof row !== "object") return false;
  let changed = !row.contextFields || typeof row.contextFields !== "object";
  row.contextFields = changed ? {} : row.contextFields;
  const context = row.contextFields;

  const legacyStatusBySection = {
    hero: context.productHeroV253__flag,
    gallery: context.productGalleryV253__flag,
    delivery: context.productDeliveryGuaranteeV253__flag,
    meaning: context.productMeaningV253__flag,
    creation: context.productCreationV253__flag,
  };
  Object.entries(legacyStatusBySection).forEach(([section, legacy]) => {
    const key = GOAT_PRODUCT_CARD_STATUS_KEYS_V514[section];
    if (context[key] === undefined || context[key] === "") {
      context[key] = goatProductCardLegacyStatusV514(legacy);
      changed = true;
    }
  });
  if (context[GOAT_PRODUCT_CARD_STATUS_KEYS_V514.reviews] === undefined) {
    context[GOAT_PRODUCT_CARD_STATUS_KEYS_V514.reviews] = "not_started";
    changed = true;
  }
  // For the new CTA layout the section starts unimplemented; preserve the old
  // checkbox and its historical status in its original field.
  if (context[GOAT_PRODUCT_CARD_STATUS_KEYS_V514.finalCta] === undefined) {
    context[GOAT_PRODUCT_CARD_STATUS_KEYS_V514.finalCta] = "not_started";
    changed = true;
  }
  if (context[GOAT_PRODUCT_CARD_STATUS_KEYS_V514.related] === undefined) {
    context[GOAT_PRODUCT_CARD_STATUS_KEYS_V514.related] =
      context.productRelatedImplementedV253 === "yes" ? "ready" : "not_started";
    changed = true;
  }
  ["catalogLink", "productJsonLd"].forEach((section) => {
    const key = GOAT_PRODUCT_CARD_STATUS_KEYS_V514[section];
    if (context[key] === undefined) {
      context[key] = "not_started";
      changed = true;
    }
  });
  if (!Array.isArray(context.productReviewsV514)) {
    context.productReviewsV514 = [];
    changed = true;
  }
  while (context.productReviewsV514.length < 3) {
    context.productReviewsV514.push({
      id: makeId("product-review"), photo: null, name: "", caption: "", text: "",
    });
    changed = true;
  }
  context.productReviewsV514.forEach((review, index) => {
    if (review && typeof review === "object") return;
    context.productReviewsV514[index] = {
      id: makeId("product-review"), photo: null, name: "", caption: "", text: "",
    };
    changed = true;
  });
  if (context.productReviewsHasCasesV514 === undefined) {
    context.productReviewsHasCasesV514 = "";
    changed = true;
  }
  if (context.productFinalCtaButtonTextV514 === undefined) {
    context.productFinalCtaButtonTextV514 = "Задать вопрос";
    changed = true;
  }
  if (context.productFinalCtaDestinationV514 === undefined) {
    context.productFinalCtaDestinationV514 = "Попап BF502N с формой";
    changed = true;
  }

  if (row.goatProductCardSchemaV514 !== GOAT_PRODUCT_CARD_SCHEMA_V514) {
    row.goatProductCardSchemaV514 = GOAT_PRODUCT_CARD_SCHEMA_V514;
    changed = true;
  }
  return changed;
}

function goatProductCardMigrateWorkspaceV514(workspace) {
  let changed = false;
  (workspace?.gates || []).forEach((gate) => (gate.cards || []).forEach((card) => {
    if (pageTemplateContext(card) !== "product") return;
    (card.pageRows || []).forEach((row) => {
      if (goatProductCardMigrateRowV514(row)) changed = true;
    });
  }));
  return { changed };
}

function goatProductCardStatusV514(row, section) {
  const value = String(row?.contextFields?.[GOAT_PRODUCT_CARD_STATUS_KEYS_V514[section]] || "");
  return ["not_started", "in_progress", "ready", "problem", "not_needed"].includes(value)
    ? value
    : "not_started";
}

