document.addEventListener("change", async (event) => {
  const related = event.target?.closest?.("[data-goat-product-related-v514]");
  if (related) {
    const found = goatProductCardFindRowV514(related);
    if (!found) return;
    found.row.contextFields.productRelatedImplementedV253 = related.checked ? "yes" : "";
    found.row.contextFields[GOAT_PRODUCT_CARD_STATUS_KEYS_V514.related] = related.checked ? "ready" : "not_started";
    goatProductCardApplyStatusV514(related, related.checked ? "ready" : "not_started");
    flashSaving();
    return;
  }
  const status = event.target?.closest?.("[data-goat-product-status-v514]");
  if (status) {
    const found = goatProductCardFindRowV514(status);
    if (!found) return;
    found.row.contextFields[status.dataset.goatProductStatusKeyV514] = status.value;
    goatProductCardApplyStatusV514(status);
    flashSaving();
    return;
  }
  const input = event.target?.closest?.("[data-goat-review-photo-v514]");
  if (!input) return;
  const found = goatProductCardFindRowV514(input);
  const reviewIndex = Number(input.dataset.goatReviewIndexV514);
  const review = found?.row?.contextFields?.productReviewsV514?.[reviewIndex];
  const file = input.files?.[0];
  input.value = "";
  if (!review || !file) return;
  try {
    review.photo = await v22PrepareProductPhoto(file);
    const frame = input.closest(".goat-product-review-photo-field-v514")?.querySelector(".goat-product-review-photo-frame-v514");
    if (frame) frame.innerHTML = `<img src="${escapeAttr(review.photo.dataUrl)}" alt="Фото ${escapeAttr(review.name || "покупателя")}" />`;
    const photoField = input.closest(".goat-product-review-photo-field-v514");
    if (photoField) {
      const action = photoField.querySelector(".v22-product-photo-add span");
      if (action) action.textContent = "Заменить фото";
      if (!photoField.querySelector("[data-goat-review-photo-remove-v514]")) {
        const remove = document.createElement("button");
        remove.type = "button";
        remove.className = "small-btn danger-mini";
        remove.textContent = "Удалить фото";
        remove.dataset.goatReviewPhotoRemoveV514 = "";
        remove.dataset.goatProductCardIdV514 = input.dataset.goatProductCardIdV514;
        remove.dataset.goatProductPageIndexV514 = input.dataset.goatProductPageIndexV514;
        remove.dataset.goatReviewIndexV514 = input.dataset.goatReviewIndexV514;
        photoField.append(remove);
      }
    }
    flashSaving();
  } catch (error) {
    window.alert(`${file.name}: ${error?.message || "Не удалось загрузить фото"}`);
  }
});

document.addEventListener("click", (event) => {
  const toggle = event.target?.closest?.("[data-goat-product-yesno-v514]");
  if (toggle) {
    const found = goatProductCardFindRowV514(toggle);
    if (!found) return;
    const key = toggle.dataset.goatProductValueKeyV514;
    found.row.contextFields[key] = toggle.dataset.value;
    const group = toggle.closest(".goat-product-yesno-v514");
    group?.querySelectorAll("[data-goat-product-yesno-v514]").forEach((button) => {
      button.setAttribute("aria-pressed", button.dataset.value === toggle.dataset.value ? "true" : "false");
    });
    group?.querySelector(".goat-product-unset-v514")?.remove();
    flashSaving();
    return;
  }
  const removePhoto = event.target?.closest?.("[data-goat-review-photo-remove-v514]");
  if (!removePhoto) return;
  const found = goatProductCardFindRowV514(removePhoto);
  const reviewIndex = Number(removePhoto.dataset.goatReviewIndexV514);
  const review = found?.row?.contextFields?.productReviewsV514?.[reviewIndex];
  if (!review) return;
  review.photo = null;
  const card = removePhoto.closest(".goat-product-review-photo-field-v514");
  const frame = card?.querySelector(".goat-product-review-photo-frame-v514");
  if (frame) frame.innerHTML = "<span>Фото не заполнено</span>";
  removePhoto.remove();
  const addLabel = card?.querySelector(".v22-product-photo-add span");
  if (addLabel) addLabel.textContent = "+ Добавить фото";
  flashSaving();
});

