/* Shared Company / Product disclosure for Gates 1–8. Gate 0 keeps its
   existing card-specific state; these gates use the same heading control
   and save one visibility choice per project, gate and scope. */
function guruGateScopeOpenStateV526(gateId = activeGateId) {
  state.ui = state.ui || {};
  state.ui.gateScopeOpenV526 = state.ui.gateScopeOpenV526 || {};
  state.ui.gateScopeOpenV526[gateId] = state.ui.gateScopeOpenV526[gateId] || {};
  return state.ui.gateScopeOpenV526[gateId];
}

function guruGateScopeItemsV526(heading) {
  const items = [];
  let node = heading?.nextElementSibling;
  while (node && !node.matches("[data-gate0-section-heading]")) {
    items.push(node);
    node = node.nextElementSibling;
  }
  return items;
}

function guruGateScopeMatchesV526(items, selector) {
  return items.flatMap((item) => [
    ...(item.matches(selector) ? [item] : []),
    ...item.querySelectorAll(selector),
  ]);
}

function guruGateScopeSetInnerV526(gateId, scope, open, items) {
  if (gateId === "gate-1") {
    const gate = state.gates.find((item) => item.id === gateId);
    const acc = getGate1AccordionState();
    let owner = "";
    getGate1Sections(gate, gate.cards).forEach((section) => {
      if (section.type === "divider") {
        owner = section.key === "__g1_divider_company" ? "company" : "product";
        return;
      }
      if (owner !== scope) return;
      if (section.key && !section.bare) acc.subblocks[section.key] = open;
      (section.allInnerCards || []).forEach((card) => { acc.cards[card.id] = open; });
    });
    guruGateScopeMatchesV526(items, "[data-gate1-toggle-section]").forEach((button) => {
      acc.subblocks[button.dataset.gate1ToggleSection] = open;
    });
    guruGateScopeMatchesV526(items, "[data-gate1-toggle-card]").forEach((button) => {
      acc.cards[button.dataset.gate1ToggleCard] = open;
    });
    if (scope === "company") {
      if (guruGateScopeMatchesV526(items, "[data-target-audience-toggle]").length) {
        const audience = ensureTargetAudience();
        audience.open = open;
        audience.segments.forEach((segment) => { segment.open = open; });
      }
      if (guruGateScopeMatchesV526(items, "[data-project-comparison-toggle]").length)
        ensureProjectComparison().open = open;
    } else {
      const product = guruV194SelectedProduct(state);
      if (product && guruGateScopeMatchesV526(items, "[data-project-comparison-product-toggle]").length)
        ensureProjectComparisonProduct(product.id).open = open;
    }
  } else if (gateId === "gate-2") {
    const acc = getGate2AccordionState();
    guruGateScopeMatchesV526(items, "[data-g2-toggle-section]").forEach((button) => {
      acc.sections[button.dataset.g2ToggleSection] = open;
    });
    guruGateScopeMatchesV526(items, "[data-g2-toggle-card]").forEach((button) => {
      acc.cards[button.dataset.g2ToggleCard] = open;
    });
  } else if (gateId === "gate-3" && scope === "product") {
    const product = guruV194SelectedProduct(state);
    if (!product) return;
    const stages = g3ProductJourneyState(state).openStepsByProduct;
    const current = (stages[product.id] = stages[product.id] || {});
    guruGateScopeMatchesV526(items, "[data-g3-product-stage-toggle]").forEach((button) => {
      current[button.dataset.g3ProductStageToggle] = open;
    });
  } else if (gateId === "gate-4") {
    const disclosure = guruDisclosureOpenStateV512();
    guruGateScopeMatchesV526(items, "details").forEach((detail) => {
      if (detail.matches(".instruction-toggle, .guru-strategic-jtbd-v286") ||
          detail.parentElement?.closest("details")) return;
      const key = detail.dataset.guruDisclosureKeyV512 || guruDisclosureKeyV512(detail);
      if (key) disclosure[key] = open;
      detail.open = open;
    });
  } else if (gateId === "gate-5" && scope === "product") {
    const blocks = ensureGate5State().ui.openBlocks;
    guruGateScopeMatchesV526(items, "[data-gate5-open]").forEach((button) => {
      const key = button.dataset.gate5Open;
      if (open) blocks[key] = true;
      else delete blocks[key];
    });
  } else if (gateId === "gate-6" && scope === "product") {
    const calendar = ensureGate6State();
    guruGateScopeMatchesV526(items, "[data-g6-open-quarter]").forEach((button) => {
      calendar.openQuarters[button.dataset.g6OpenQuarter] = open;
    });
    guruGateScopeMatchesV526(items, "[data-g6-open]").forEach((button) => {
      calendar.openSeasons[button.dataset.g6Open] = open;
    });
  } else if (gateId === "gate-8") {
    const forecast = ensureGate8Workspace();
    guruGateScopeMatchesV526(items, "[data-g8-toggle-section]").forEach((button) => {
      forecast.openSections[button.dataset.g8ToggleSection] = open;
    });
  }
}

function guruSyncGateScopeV526() {
  if (activeView !== "gate" || !state || activeGateId === "gate-0" ||
      !/^gate-[1-8]$/.test(activeGateId)) return;
  const preferences = guruGateScopeOpenStateV526();
  ["company", "product"].forEach((scope) => {
    if (els.contentArea.querySelector(`[data-gate0-section-heading="${scope}"]`))
      gate0SetSectionOpen(scope, preferences[scope] !== false);
  });
}

const __guruPrevRenderGateScopeV526 = renderGate;
renderGate = function () {
  const result = __guruPrevRenderGateScopeV526.apply(this, arguments);
  guruSyncGateScopeV526();
  const workspace = state;
  const gateId = activeGateId;
  // Gate 4 Search inserts its read-only panel after this renderer returns.
  queueMicrotask(() => {
    if (state === workspace && activeGateId === gateId) guruSyncGateScopeV526();
  });
  return result;
};

document.addEventListener("click", (event) => {
  const button = event.target?.closest?.("[data-gate0-section-toggle]");
  if (!button || !els.contentArea.contains(button) || activeView !== "gate" ||
      activeGateId === "gate-0" || !/^gate-[1-8]$/.test(activeGateId)) return;
  event.preventDefault();
  event.stopPropagation();
  const heading = button.closest("[data-gate0-section-heading]");
  const scope = button.dataset.gate0SectionToggle;
  const open = button.getAttribute("aria-expanded") !== "true";
  guruGateScopeSetInnerV526(activeGateId, scope, open, guruGateScopeItemsV526(heading));
  guruGateScopeOpenStateV526()[scope] = open;
  guruInvalidateGateViewCache();
  renderGate();
  guruScheduleUiPreferenceSave();
}, true);
